/// Compile `func` whole, or `None` if it uses anything outside the v0 subset.
fn function_osr_site(statement: &Stmt) -> Option<usize> {
    match statement {
        Stmt::While { body, .. } | Stmt::DoWhile { body, .. } | Stmt::For { body, .. } => {
            Some(&body.site as *const _ as usize)
        }
        Stmt::Labeled { body, .. } => function_osr_site(body),
        _ => None,
    }
}

pub fn compile(func: &Function) -> Option<Rc<Chunk>> {
    let started = crate::jit::perf_stage_start();
    let result =
        compile_inner(func, &Default::default(), None, None, false, false, false).or_else(|| {
            (!func.is_async && !func.is_generator)
                .then(|| compile_inner(func, &Default::default(), None, None, false, true, false))
                .flatten()
        });
    crate::jit::perf_bytecode_compile_end(started, result.is_some());
    result
}

/// Compile a derived class constructor against a retained Function Environment Record.
///
/// Unlike an ordinary lean frame, that environment starts with an uninitialized `this` binding
/// and carries the active constructor and `new.target`; `super()` binds `this` and initializes the
/// derived class's instance elements through the shared ECMA-262 algorithm.
pub(crate) fn compile_derived_constructor(func: &Function) -> Option<Rc<Chunk>> {
    let started = crate::jit::perf_stage_start();
    let result = compile_inner(func, &Default::default(), None, None, true, false, false);
    crate::jit::perf_bytecode_compile_end(started, result.is_some());
    result
}

/// Compile a Source Text Module's already-instantiated body as a strict heap continuation.
/// `bindings` are the module environment's own, non-import bindings; unlike an ordinary async
/// function, the chunk must read and initialize those exact cells so exports stay live and TDZ
/// state established during ModuleDeclarationInstantiation remains authoritative.
pub(crate) fn compile_module(body: &[Stmt], bindings: &[(String, bool)]) -> Option<Rc<Chunk>> {
    let function = Function {
        name: None,
        params: Vec::new(),
        body: body.to_vec().into(),
        is_arrow: false,
        is_strict: true,
        expr_body: false,
        is_generator: false,
        is_async: true,
        is_method: false,
        is_fn_expr: false,
        default_ctor: false,
        self_hosted: false,
        run_once: false,
        source: None,
        script: None,
        start: 0,
        scan: std::cell::Cell::new(0),
        hoist: std::cell::OnceCell::new(),
        calls: std::cell::Cell::new(0),
        code: std::cell::OnceCell::new(),
        code2: std::cell::OnceCell::new(),
        fn_maps: std::cell::OnceCell::new(),
        env_layouts: std::cell::OnceCell::new(),
    };
    let started = crate::jit::perf_stage_start();
    let result = compile_inner(
        &function,
        &Default::default(),
        None,
        Some(bindings),
        false,
        false,
        false,
    );
    crate::jit::perf_bytecode_compile_end(started, result.is_some());
    result
}

/// Compile an already-instantiated Script Record without a Function execution context.
/// ECMA-262 ScriptEvaluation retains the realm's global lexical/variable environments and
/// returns the StatementList completion. The temporary AST container is analysis-only: no
/// function object, parameters, arguments object, or FunctionDeclarationInstantiation is made.
pub(crate) fn compile_script(body: &[Stmt], strict: bool) -> Option<Rc<Chunk>> {
    let source = Function {
        name: None,
        params: Vec::new(),
        body: body.to_vec().into(),
        // Capture analysis must not invent an `arguments` binding or Annex B parameter blocker.
        is_arrow: true,
        is_strict: strict,
        expr_body: false,
        is_generator: false,
        is_async: false,
        is_method: false,
        is_fn_expr: false,
        default_ctor: false,
        self_hosted: false,
        run_once: false,
        source: None,
        script: None,
        start: 0,
        scan: std::cell::Cell::new(0),
        hoist: std::cell::OnceCell::new(),
        calls: std::cell::Cell::new(0),
        code: std::cell::OnceCell::new(),
        code2: std::cell::OnceCell::new(),
        fn_maps: std::cell::OnceCell::new(),
        env_layouts: std::cell::OnceCell::new(),
    };
    let started = crate::jit::perf_stage_start();
    let result = compile_inner(&source, &Default::default(), None, None, false, false, true);
    crate::jit::perf_bytecode_compile_end(started, result.is_some());
    result
}

