/// Second-stage compile: same as [`compile`], with hot monomorphic callees from `plan` spliced
/// inline at their call sites (guarded; see [`plan_inlines`]).
pub(crate) fn compile_with_inlines(
    func: &Function,
    plan: &crate::fasthash::FastMap<u32, InlinePlanEntry>,
    hot: &Chunk,
) -> Option<Rc<Chunk>> {
    let seed = (!env_flag!("TRUST_JS_JIT_NO_CACHE_SEED")).then_some(hot);
    let started = crate::jit::perf_stage_start();
    // Recompilation retains the caller's established entry contract. A prepared caller
    // already owns its mapped arguments/eval/closure environment; only the eligible callee
    // body is remapped into fresh slots, never the caller's authoritative bindings.
    let result = compile_inner(func, plan, seed, None, false, hot.prepared_entry, false);
    crate::jit::perf_bytecode_compile_end(started, result.is_some());
    result
}

fn property_cache_seeds(chunk: &Chunk) -> Vec<(Rc<str>, [IcState; PROP_IC_WAYS])> {
    chunk
        .ops
        .iter()
        .filter_map(|op| {
            let (name, cache) = match *op {
                Op::GetProp(n, c)
                | Op::GetPropThis(n, c)
                | Op::SetProp(n, c)
                | Op::SetPropDrop(n, c)
                | Op::SetPropThisDrop(n, c)
                | Op::AppendProp(n, c)
                | Op::GetMethod(n, c) => (n, c),
                Op::GetPropLocal(_, n, c) | Op::SetPropLocalDrop(_, n, c) => (n, c),
                Op::UpdateProp(n, c, _) => (n, c),
                _ => return None,
            };
            let states = std::array::from_fn(|way| chunk.caches[cache as usize + way].get());
            Some((chunk.names[name as usize].clone(), states))
        })
        .collect()
}

type NamePin = Option<crate::interpreter::WeakEnv>;
type NameSeed = (Rc<str>, NameIc, NamePin, Option<u64>);
type CallPin = crate::value::WeakGc;

struct CallSeed {
    entries: [CallIc; CALL_IC_WAYS],
    func_pins: [std::rc::Weak<Function>; CALL_IC_WAYS],
    next: u8,
    pins: Vec<(usize, CallPin)>,
}

fn name_cache_seeds(chunk: &Chunk) -> Vec<NameSeed> {
    let pins = chunk.name_pins.borrow();
    chunk
        .ops
        .iter()
        .filter_map(|op| {
            let (name, cache) = match *op {
                Op::LoadName(n, c)
                | Op::LoadNameForCall(n, c)
                | Op::StoreNameCached(n, c)
                | Op::UpdateNameCached(n, c, _) => (n, c as usize),
                _ => return None,
            };
            let number = chunk.name_num_valid[cache]
                .get()
                .then(|| chunk.name_num_bits[cache].get());
            let mut state = chunk.name_caches[cache].get();
            if state.env == lexical_cache::DEEP_NAME_IC {
                // Descriptor ownership does not cross Chunk boundaries when seeding inline
                // recompilations. The new chunk builds its own chain on its first execution.
                state = NameIc::EMPTY;
            }
            Some((
                chunk.names[name as usize].clone(),
                state,
                pins[cache].clone(),
                number,
            ))
        })
        .collect()
}

fn call_cache_seeds(chunk: &Chunk) -> Vec<CallSeed> {
    let pins = chunk.call_pins.borrow();
    chunk
        .ops
        .iter()
        .filter_map(|op| {
            let cache = match *op {
                Op::Call(_, cache) | Op::CallWithThis(_, cache) => cache as usize,
                _ => return None,
            };
            let site = chunk.call_caches.get(cache)?;
            let entries = std::array::from_fn(|way| {
                let entry = site.entries[way].get();
                if entry.callee == 0 || pins.contains_key(&entry.callee) {
                    entry
                } else {
                    CallIc::EMPTY
                }
            });
            let mut seed_pins = Vec::new();
            for entry in entries {
                if entry.callee == 0 || seed_pins.iter().any(|(callee, _)| *callee == entry.callee)
                {
                    continue;
                }
                if let Some(pin) = pins.get(&entry.callee) {
                    seed_pins.push((entry.callee, pin.clone()));
                }
            }
            Some(CallSeed {
                entries,
                func_pins: std::array::from_fn(|way| {
                    if entries[way].callee == 0 {
                        std::rc::Weak::new()
                    } else {
                        site.func_pins.borrow()[way].clone()
                    }
                }),
                next: site.next.get(),
                pins: seed_pins,
            })
        })
        .collect()
}

/// Leading pure string expressions have a normal completion discarded by FunctionBody
/// evaluation. Str includes directives, substitution-free templates and parenthesized
/// strings; parser strictness and the original source text remain authoritative.
/// Script/eval/module completion values must never pass through this function-only view.
fn function_body_statements(body: &[Stmt]) -> &[Stmt] {
    let prefix = body
        .iter()
        .take_while(|statement| matches!(statement, Stmt::Expr(Expr::Str(_))))
        .count();
    &body[prefix..]
}

