#[path = "bytecode_function_directive_tests.rs"]
mod function_directive_tests;

fn compile_inner(
    func: &Function,
    plan: &crate::fasthash::FastMap<u32, InlinePlanEntry>,
    hot: Option<&Chunk>,
    module_bindings: Option<&[(String, bool)]>,
    derived_constructor: bool,
    prepared_entry: bool,
    script_body: bool,
) -> Option<Rc<Chunk>> {
    // Compilation reads the statements: decode a snapshot-encoded body once, up front.
    func.body.prepare_to_run();
    // Body facts the scanner already knows: `new.target` is an observation channel into the
    // activation that slots do not provide; `this` / `arguments` in an ordinary arrow are free
    // variables we do not model. Ordinary functions with unmapped arguments can materialize
    // the object into a dedicated slot, independently of their positional parameters.
    let scan = func.scan_flags();
    let is_coroutine = func.is_generator || func.is_async;
    // ECMA-262 §9.4.5 GetNewTarget reads the nearest this-binding Function Environment Record.
    // Coroutine calls have already materialized that activation before this chunk is created and
    // retain it for every resumption, including as the lexical parent of async arrows. A compiled
    // derived constructor likewise runs under its required Function Environment Record. Other
    // lean ordinary frames still omit the activation, so keep their conservative exclusion.
    let lean_new_target = scan & SCAN_NEW_TARGET != 0
        && !func.is_arrow
        && !is_coroutine
        && !derived_constructor
        && !prepared_entry;
    let uses_arguments = !script_body && scan & SCAN_ARGUMENTS != 0;
    // ECMA-262 §10.2.11: strict functions never map arguments indices to parameter
    // bindings. Simple parameters can therefore use the ordinary compiled entry;
    // defaults/destructuring retain their existing general instantiation path.
    let strict_simple_arguments = func.is_strict
        && func.params.iter().all(|param| {
            !param.rest && param.default.is_none() && matches!(param.pattern, Pattern::Ident(_))
        });
    // ECMA-262 §10.2.11 creates a mapped arguments object only for a non-strict, non-arrow
    // function with a simple parameter list. A nonempty mapped list must alias parameter writes;
    // the current coroutine slot projection cannot yet preserve that relationship.
    let has_mapped_parameter_aliases = uses_arguments
        && !func.is_arrow
        && !func.is_strict
        && !func.params.is_empty()
        && func.params.iter().all(|param| {
            !param.rest && param.default.is_none() && matches!(param.pattern, Pattern::Ident(_))
        })
        && !func
            .params
            .iter()
            .any(|param| matches!(&param.pattern, Pattern::Ident(name) if name == "arguments"));
    // A mapped object is observable only through its index properties. If the body reads
    // nothing but `arguments.length` (proven on the final operation stream by
    // `lazy_arguments_rewrite`, with no element read), neither parameter writes nor argument
    // writes can be observed, so the parameters keep ordinary slots and no object is created.
    // An unproven body fails this compilation and takes the prepared (exactly mapped) entry.
    let arguments_length_only = has_mapped_parameter_aliases && !is_coroutine && !prepared_entry;
    let has_mapped_parameter_aliases = has_mapped_parameter_aliases && !arguments_length_only;
    if uses_arguments
        && !func.is_arrow
        && !is_coroutine
        && !prepared_entry
        && !func.params.is_empty()
        && !strict_simple_arguments
        && !arguments_length_only
    {
        log_bail("fn", "arguments with arrow/async/parameters");
        return None;
    }
    // Arrows resolve `this` / `arguments` from their definition environment. Named function
    // expressions likewise retain their immutable self-name in [[Environment]] at creation.
    // Neither needs a general per-call prologue merely to observe those lexical bindings.
    // Capture analysis: which locals inner functions can name (they live in a real activation
    // env), and whether an inner arrow chain reads `this`. `None` = unanalyzable — bail.
    let Some((mut captured, env_this, mut block_lets, mut runtime_lexicals, direct_eval)) =
        CaptureScan::run(func, is_coroutine || prepared_entry || script_body)
    else {
        let head: String = func
            .source
            .as_deref()
            .unwrap_or("<no source>")
            .chars()
            .take(90)
            .collect();
        log_bail(
            "capture-scan",
            &format!(
                "unanalyzable body (eval/with/annexB/pattern) in: {}",
                head.replace('\n', " ")
            ),
        );
        return None;
    };

    if prepared_entry || script_body {
        // A general entry already instantiated every body-wide binding. Keep those bindings
        // authoritative, including references from parameter-created closures and direct eval.
        // Nested block captures get actual block environments instead of extra activation homes.
        if !script_body && !hoisted_vars(&func.body, true, func.is_strict, &mut captured) {
            return None;
        }
        for (name, _) in block_lets.drain(..) {
            runtime_lexicals.insert(name);
        }
    }
    let mut c = Compiler {
        self_hosted: func.self_hosted,
        lean_new_target,
        rest_slot: None,
        arguments_length_only,
        // A module already has its own `this` binding, initialized to undefined. Reuse that
        // environment for nested arrows instead of synthesizing a function activation.
        // A derived constructor already runs under its mandatory Function Environment Record;
        // arrows must close over that live, initially-uninitialized `this` binding instead of a
        // child activation seeded with the entry-time placeholder.
        env_this: env_this
            && module_bindings.is_none()
            && !derived_constructor
            && !prepared_entry
            && !script_body,
        lexical_this: func.is_arrow && !script_body,
        derived_constructor,
        strict: func.is_strict,
        borrowed_parameter_aliases: !func.is_strict
            && !func.is_arrow
            && !func.params.is_empty()
            && func.params.iter().all(|parameter| {
                !parameter.rest
                    && parameter.default.is_none()
                    && matches!(parameter.pattern, Pattern::Ident(_))
            }),
        is_coroutine,
        module_body: module_bindings.is_some(),
        script_body,
        direct_eval,
        runtime_lexicals,
        reuse_activation: has_mapped_parameter_aliases || prepared_entry,
        function_osr_sites: if !script_body && !is_coroutine && hot.is_none() {
            func.body.iter().filter_map(function_osr_site).collect()
        } else {
            Vec::new()
        },
        plan_stack: vec![(plan.clone(), 0)],
        cache_seed_stack: hot
            .map(|chunk| vec![(property_cache_seeds(chunk), 0)])
            .unwrap_or_default(),
        name_seed_stack: hot
            .map(|chunk| vec![(name_cache_seeds(chunk), 0)])
            .unwrap_or_default(),
        call_seed_stack: hot
            .map(|chunk| vec![(call_cache_seeds(chunk), 0)])
            .unwrap_or_default(),
        ..Compiler::default()
    };
    if script_body {
        c.push_compile_scope();
        for op in crate::interpreter::collect_hoist_ops(&func.body, func.is_strict, &[]) {
            match op {
                HoistOp::Var(name) | HoistOp::Fn(name, _) => {
                    c.script_vars.insert(name.clone());
                    c.lexical_env_bind(&name, false);
                }
                HoistOp::AnnexB(name, function) => {
                    c.script_vars.insert(name.clone());
                    c.lexical_env_bind(&name, false);
                    c.script_annexb.insert(Rc::as_ptr(&function) as usize);
                }
            }
        }
        for statement in &func.body {
            match statement {
                Stmt::VarDecl { kind, decls } if !matches!(kind, DeclKind::Var) => {
                    let mut names = crate::fasthash::FastSet::default();
                    for (pattern, _) in decls {
                        pat_idents(pattern, &mut names);
                    }
                    for name in names {
                        c.lexical_env_bind(&name, !matches!(kind, DeclKind::Let));
                    }
                }
                Stmt::ClassDecl(class) => {
                    c.lexical_env_bind(class.name.as_ref()?, false);
                }
                _ => {}
            }
        }
        // All global declaration cells/properties were created exactly once by the caller.
        c.reuse_activation = true;
        let completion = c.fresh_slot("%script-completion%");
        c.script_completion = Some(completion);
    } else {
        if let Some(bindings) = module_bindings {
            for (name, is_const) in bindings {
                c.env_bind(name, *is_const);
            }
            // Any compiler-homed block captures may safely use the once-only module environment.
            // More importantly, a fresh function activation would put pre-instantiated module cells
            // in the parent while `LoadCap`/`StoreCap` intentionally address the fixed home directly.
            c.reuse_activation = true;
        }
        // Captured once-per-call block `let`s home in the activation (TDZ from entry, initialized
        // by the declaring block's own StoreCapInit); CaptureScan proved no enclosing same-name
        // declaration and block-resolved references only, so the function-flat env map is
        // faithful (nested same-name declarations shadow it through their slots).
        for (name, is_const) in &block_lets {
            c.cap_inits
                .push(CapInit::Lexical(Rc::from(name.as_str()), *is_const));
            c.env_bind(name, *is_const);
            c.homed_lets.insert(name.clone());
            c.homed_pending.insert(name.clone());
        }
        // Ordinary compiled calls instantiate parameters in this chunk, so each formal needs its
        // positional slot and only the subset whose default initialization is safely lowerable can
        // compile. Coroutine calls have already completed FunctionDeclarationInstantiation in the
        // tree-walker before their resumable context is created. For them, flatten BoundNames into
        // slots and seed those slots from the live bindings; this admits rest/destructuring/default
        // parameter lists without replaying any binding or initializer operation.
        if prepared_entry {
            c.push_compile_scope();
            for name in crate::interpreter::param_bound_names(&func.params) {
                // Parameter-expression bindings may be in the body's parent, while a body var
                // shadows them. Resolve the live reference, never copy it to an independent slot.
                c.lexical_env_bind(&name, false);
            }
        } else if func.is_generator || func.is_async {
            let bound_names = crate::interpreter::param_bound_names(&func.params);
            for (k, name) in bound_names.iter().enumerate() {
                let slot = c.fresh_slot(name);
                if has_mapped_parameter_aliases {
                    // The arguments exotic object's ParameterMap already aliases this binding in the
                    // retained call activation. Keep all direct and captured accesses there too.
                    c.env_bind(name, false);
                } else if captured.contains(name) {
                    c.cap_inits
                        .push(CapInit::Param(k as u16, Rc::from(name.as_str())));
                    c.env_bind(name, false);
                } else {
                    c.scope_bind(name, slot, false);
                }
            }
            c.n_params = bound_names.len();
        } else {
            // ECMA-262 FunctionDeclarationInstantiation → IteratorBindingInitialization of the
            // formals, strictly left to right. Every frame entry seeds argument k into slot k, so
            // the first pass allocates exactly one slot per positional parameter (a hidden
            // argument slot for a destructuring pattern) and then the rest parameter's slot;
            // names bound inside patterns are allocated afterwards. Parameter expressions
            // (defaults, pattern defaults, computed keys) are admitted only when they cannot
            // observe this or a later parameter's binding and create no closure (see
            // `default_expr_safe`), which makes the specification's separate parameter scope
            // unobservable. A defaulted parameter that a closure captures lives in the
            // activation environment, seeded from its argument at entry; its initializer stores
            // there instead of the argument slot, before any later initializer or the body runs.
            enum ParamInit<'a> {
                Default(u16, &'a Expr),
                CapturedDefault(&'a str, &'a Expr),
                Pattern(u16, &'a Pattern, Option<&'a Expr>),
            }
            let bound: Vec<Vec<String>> = func
                .params
                .iter()
                .map(|param| {
                    let mut names = Vec::new();
                    crate::interpreter::pattern_idents(&param.pattern, &mut names);
                    names
                })
                .collect();
            let banned_from = |k: usize| -> crate::fasthash::FastSet<&str> {
                bound[k..].iter().flatten().map(String::as_str).collect()
            };
            let mut inits: Vec<ParamInit> = Vec::new();
            for (k, p) in func.params.iter().enumerate() {
                if p.rest {
                    // A trailing BindingRestElement binds CreateArrayFromList(the remaining
                    // arguments). An identifier target needs no iteration protocol: the frame
                    // entry builds the Array (see `rest_slot`).
                    let Pattern::Ident(name) = &p.pattern else {
                        log_bail("params", "destructuring rest parameter");
                        return None;
                    };
                    debug_assert_eq!(k + 1, func.params.len(), "rest is the final parameter");
                    let slot = c.fresh_slot(name);
                    if captured.contains(name) {
                        c.cap_inits
                            .push(CapInit::Rest(k as u16, Rc::from(name.as_str())));
                        c.env_bind(name, false);
                    } else {
                        c.scope_bind(name, slot, false);
                        c.rest_slot = Some(slot);
                    }
                    break;
                }
                match &p.pattern {
                    Pattern::Ident(name) => {
                        if let Some(d) = &p.default {
                            if !default_expr_safe(d, &banned_from(k)) {
                                log_bail("params", "unsafe default expression");
                                return None;
                            }
                        }
                        let slot = c.fresh_slot(name);
                        let is_captured = captured.contains(name);
                        if is_captured {
                            c.cap_inits
                                .push(CapInit::Param(k as u16, Rc::from(name.as_str())));
                            c.env_bind(name, false);
                        } else {
                            c.scope_bind(name, slot, false);
                        }
                        if let Some(d) = &p.default {
                            inits.push(if is_captured {
                                ParamInit::CapturedDefault(name, d)
                            } else {
                                ParamInit::Default(slot, d)
                            });
                        }
                    }
                    pattern @ (Pattern::Object(_) | Pattern::Array(_)) => {
                        let banned = banned_from(k);
                        if p.default
                            .as_ref()
                            .is_some_and(|d| !default_expr_safe(d, &banned))
                            || !pattern_exprs_safe(pattern, &banned)
                            || bound[k].iter().any(|name| name == "arguments")
                        {
                            log_bail("params", "destructuring parameter with unsafe expressions");
                            return None;
                        }
                        let slot = c.fresh_slot(&format!("\u{0}param{k}"));
                        inits.push(ParamInit::Pattern(slot, pattern, p.default.as_ref()));
                    }
                    Pattern::Member(_) => {
                        log_bail("params", "member parameter target");
                        return None;
                    }
                }
            }
            // Names bound by destructuring parameters, after every argument-seeded slot.
            for (k, p) in func.params.iter().enumerate() {
                if p.rest {
                    break;
                }
                if matches!(p.pattern, Pattern::Ident(_)) {
                    continue;
                }
                for name in &bound[k] {
                    if captured.contains(name) {
                        c.cap_inits.push(CapInit::Var(Rc::from(name.as_str())));
                        c.env_bind(name, false);
                    } else {
                        let slot = c.fresh_slot(name);
                        c.scope_bind(name, slot, false);
                    }
                }
            }
            c.n_params = func.params.iter().filter(|param| !param.rest).count();
            for init in inits {
                let (slot, default) = match init {
                    ParamInit::Default(slot, d) => (slot, Some(d)),
                    ParamInit::CapturedDefault(name, d) => {
                        let name = c.name_idx(name);
                        c.emit(Op::LoadCap(name));
                        c.emit(Op::Undef);
                        c.emit(Op::StrictEq);
                        let jf = c.emit(Op::JumpIfFalse(0));
                        c.expr(d).ok()?;
                        c.emit(Op::StoreCap(name));
                        c.patch(jf);
                        continue;
                    }
                    ParamInit::Pattern(slot, _, d) => (slot, d),
                };
                if let Some(d) = default {
                    c.emit(Op::LoadLocal(slot));
                    c.emit(Op::Undef);
                    c.emit(Op::StrictEq);
                    let jf = c.emit(Op::JumpIfFalse(0));
                    c.expr(d).ok()?;
                    c.emit(Op::StoreLocal(slot));
                    c.patch(jf);
                }
                if let ParamInit::Pattern(slot, pattern, _) = init {
                    c.emit(Op::LoadLocal(slot));
                    c.destructure_store(pattern, DeclKind::Var).ok()?;
                }
            }
        }
        if uses_arguments && !func.is_arrow && !prepared_entry {
            if has_mapped_parameter_aliases {
                c.env_bind("arguments", false);
            } else if !is_coroutine {
                if captured.contains("arguments") {
                    // ECMA-262 §15.3.4: an arrow has no own arguments binding. Materialize the
                    // enclosing function's one arguments object in its activation so both the outer
                    // body and every captured arrow resolve the same identity.
                    c.env_bind("arguments", false);
                    c.env_arguments = true;
                } else {
                    // Positional parameters must occupy the first n_params slots in every
                    // VM/JIT entry. Allocate the independent arguments slot only after them.
                    let slot = c.fresh_slot("arguments");
                    c.scope_bind("arguments", slot, false);
                    c.arguments_slot = Some(slot);
                }
            }
            // Other coroutines deliberately leave `arguments` unresolved in the chunk. The normal
            // name operation walks the retained activation installed by FunctionDeclarationInstantiation,
            // or its parents for an arrow, so direct reads and nested arrows observe one object.
        }
        // Function-scoped `var`s and hoisted function declarations from the shared hoist plan.
        let annexb_blocked = crate::interpreter::param_bound_names(&func.params);
        for op in crate::interpreter::collect_hoist_ops(&func.body, func.is_strict, &annexb_blocked)
        {
            match op {
                HoistOp::AnnexB(name, function) if name == "arguments" => {
                    // ECMA-262 §10.2.11 (web-compat insertion point) gives a block function named
                    // `arguments` no var binding: evaluating it sets the VariableEnvironment's
                    // `arguments` (normally the arguments object's) or creates that binding then,
                    // which slots cannot express in advance. The tree-walker runs such functions.
                    // A coroutine's activation already holds the arguments object when the body
                    // names it and has no parameter expressions, so the chunk resolves `arguments`
                    // there; other coroutines keep the function block-scoped.
                    if !is_coroutine {
                        log_bail("annexb-arguments", "block function named arguments");
                        return None;
                    }
                    if !func.is_arrow
                        && uses_arguments
                        && !crate::interpreter::params_have_expr(&func.params)
                    {
                        let target = match c.home(&name) {
                            Some(home) => home,
                            None => {
                                c.env_bind(&name, false);
                                Home::Env(false)
                            }
                        };
                        c.annexb_targets
                            .insert(Rc::as_ptr(&function) as usize, target);
                    }
                }
                HoistOp::Var(name) => {
                    if prepared_entry {
                        c.env_bind(&name, false);
                    } else if c.env_has(&name) {
                        // A `var` sharing a parameter's Function Environment binding is already
                        // instantiated. In particular, do not split mapped parameters into slots.
                    } else if captured.contains(&name) {
                        if !c.env_has(&name) {
                            c.cap_inits.push(CapInit::Var(Rc::from(name.as_str())));
                            c.env_bind(&name, false);
                        }
                    } else if c.lookup(&name).is_none() {
                        let slot = c.fresh_slot(&name);
                        c.scope_bind(&name, slot, false);
                    }
                }
                HoistOp::Fn(name, f) => {
                    if prepared_entry {
                        c.env_bind(&name, false);
                        continue;
                    }
                    if c.module_body && c.env_has(&name) {
                        // ModuleDeclarationInstantiation already created the closure in this exact
                        // environment. Replaying FunctionDeclarationInstantiation would replace the
                        // live export cell and, for cycles, expose the wrong function identity.
                        continue;
                    }
                    let fidx = c.funcs.len() as u16;
                    c.funcs.push(f.clone());
                    if c.env_has(&name) || captured.contains(&name) {
                        c.cap_inits.push(CapInit::Fn(fidx, Rc::from(name.as_str())));
                        c.env_bind(&name, false);
                    } else {
                        let slot = match c.lookup(&name) {
                            Some((s, _)) => s,
                            None => {
                                let s = c.fresh_slot(&name);
                                c.scope_bind(&name, s, false);
                                s
                            }
                        };
                        // Created at entry, in hoist order, closing over the activation.
                        c.emit(Op::MakeClosure(fidx as u32, u32::MAX));
                        c.emit(Op::StoreLocal(slot));
                    }
                }
                HoistOp::AnnexB(name, function) => {
                    // Annex B.3.2 FunctionDeclarationInstantiation creates/reuses a mutable var home
                    // initialized to undefined. The block's distinct lexical binding is instantiated
                    // later; evaluating its declaration copies that function object into this home.
                    let target = if prepared_entry {
                        c.env_bind(&name, false);
                        Home::Env(false)
                    } else if let Some(home) = c.home(&name) {
                        home
                    } else if captured.contains(&name) {
                        c.cap_inits.push(CapInit::Var(Rc::from(name.as_str())));
                        c.env_bind(&name, false);
                        Home::Env(false)
                    } else {
                        let slot = c.fresh_slot(&name);
                        c.scope_bind(&name, slot, false);
                        Home::Slot(slot, false)
                    };
                    c.annexb_targets
                        .insert(Rc::as_ptr(&function) as usize, target);
                }
            }
        }
        // Body-level lexicals: captured ones home in the activation (inserted in TDZ by
        // make_run_env), the rest get TDZ slots.
        if c.declare_body_lexicals(&func.body, &captured).is_err() {
            log_bail("body-lexicals", "unsupported declaration form");
            return None;
        }
    }
    let body = if script_body || module_bindings.is_some() {
        &func.body[..]
    } else {
        function_body_statements(&func.body)
    };
    let compile_body = |compiler: &mut Compiler| compiler.statement_list(body);
    let has_body_using = func.body.iter().any(|statement| {
        matches!(
            statement,
            Stmt::VarDecl {
                kind: DeclKind::Using | DeclKind::AwaitUsing,
                ..
            }
        )
    });
    let body_result = if has_body_using {
        c.disposal_scope(compile_body)
    } else {
        compile_body(&mut c)
    };
    if body_result.is_err() {
        return None;
    }
    if let Some(completion) = c.script_completion {
        c.emit(Op::LoadLocal(completion));
        c.emit(Op::Return);
    } else {
        c.emit(Op::ReturnUndef);
    }
    finish_chunk(c, hot, prepared_entry, is_coroutine, Some(func))
}

fn finish_chunk(
    mut c: Compiler,
    hot: Option<&Chunk>,
    prepared_entry: bool,
    is_coroutine: bool,
    source: Option<&Function>,
) -> Option<Rc<Chunk>> {
    // Constructors in OO workloads overwhelmingly initialize a short, straight-line list of
    // fields. Count distinct names only until control flow can make the estimate speculative,
    // and decline large reservations: this is an allocation/memory optimization, not metadata
    // proportional to object count.
    let mut instance_names = [u32::MAX; 16];
    let mut instance_capacity_hint = 0u8;
    for op in &c.ops {
        match op {
            Op::SetPropThisDrop(name, _) => {
                if !instance_names[..instance_capacity_hint as usize].contains(name) {
                    if instance_capacity_hint == instance_names.len() as u8 {
                        instance_capacity_hint = 0;
                        break;
                    }
                    instance_names[instance_capacity_hint as usize] = *name;
                    instance_capacity_hint += 1;
                }
            }
            Op::Jump(..)
            | Op::AbruptJump(..)
            | Op::JumpIfFalse(..)
            | Op::JumpIfFalsePeek(..)
            | Op::JumpIfTruePeek(..)
            | Op::JumpIfNotNullishPeek(..)
            | Op::InlineGuard(..)
            | Op::Throw
            | Op::Return
            | Op::ReturnBare
            | Op::ResumeReturn
            | Op::ResumeJump
            | Op::ReturnUndef
            | Op::Await
            | Op::Yield
            | Op::PushHandler(..)
            | Op::PushFinally(..)
            | Op::PushIterator(..) => break,
            Op::PushDisposeFrame
            | Op::AddDisposable(_)
            | Op::DisposeNormal
            | Op::DisposeThrow
            | Op::DisposeReturn
            | Op::DisposeBareReturn
            | Op::DisposeResumeReturn
            | Op::DisposeJump
            | Op::PushWith
            | Op::PushLex(_)
            | Op::PushCatchLex(_)
            | Op::CloneLex(_)
            | Op::InitLex(_)
            | Op::PopEnv
            | Op::ResolveNameRef(..)
            | Op::LoadRef(_)
            | Op::StoreRef(_) => break,
            _ => {}
        }
    }
    // A speculative inline can allocate child call-cache seeds and then roll its op/cache
    // vectors back. Keep only Weak pins referenced by the surviving fixed-size sites so failed
    // speculation neither retains dead Rc allocation blocks nor consumes the runtime pin budget.
    c.call_pins.retain(|callee, _| {
        c.call_caches.iter().any(|site| {
            site.entries
                .iter()
                .any(|entry| entry.get().callee == *callee)
        })
    });
    let cap_cache_len = c.names.len();
    let op_count = c.ops.len();
    let inline_sites = register_inline_sites(&mut c);
    c.positions.runs.shrink_to_fit();
    let mut call_positions = vec![NO_POSITION; c.call_caches.len()].into_boxed_slice();
    let mut construct_positions = vec![NO_POSITION; c.construct_caches.len()].into_boxed_slice();
    for (pc, op) in c.ops.iter().enumerate() {
        let slot = match *op {
            Op::Call(_, cache) | Op::CallWithThis(_, cache) => {
                call_positions.get_mut(cache as usize)
            }
            Op::New(_, cache) => construct_positions.get_mut(cache as usize),
            _ => None,
        };
        if let Some(slot) = slot {
            *slot = c.positions.at(pc);
        }
    }
    let feedback = if let Some(chunk) = hot {
        // The transformed/inlined bytecode has different PCs. Retain the baseline schema without
        // guessing new runtime bindings; the original chunk remains the current-shape adapter.
        crate::feedback::FeedbackVector::unbound(chunk.feedback.layout().clone())
    } else {
        let (layout, bindings) = feedback_layout_for_ops(&c.ops, &c.names);
        crate::feedback::FeedbackVector::new(layout, bindings)
    };
    if let Some(func) = source.filter(|_| {
        env_flag!("TRUST_JS_NULLISH_TRACE")
            && c.ops.len() == 179
            && c.ops
                .get(45)
                .is_some_and(|op| matches!(op, Op::GetElemLocal(0)))
    }) {
        let source: String = func
            .source
            .as_deref()
            .unwrap_or("<no source>")
            .chars()
            .take(4000)
            .collect();
        eprintln!(
            "TRust JS: nullish target compile params={:?} source={source:?}",
            func.params
                .iter()
                .map(|param| match &param.pattern {
                    Pattern::Ident(name) => name.as_str(),
                    _ => "<pattern>",
                })
                .collect::<Vec<_>>()
        );
    }
    let instance_layout = (instance_capacity_hint != 0).then(|| {
        crate::value::new_shared_indexed_property_layout(
            instance_names[..instance_capacity_hint as usize]
                .iter()
                .map(|&name| c.names[name as usize].clone())
                .collect(),
        )
    });
    // The final operation stream includes inlining, fragments and prepared/coroutine entries.
    // Cache only facts about that immutable stream, never runtime environments or IC state.
    // See `Chunk::lazy_arguments`: proven and applied on the final operation stream.
    let lazy = c
        .arguments_slot
        .and_then(|slot| lazy_arguments_rewrite(&mut c.ops, slot, &c.names));
    let lazy_arguments = lazy.is_some();
    let arguments_count = lazy == Some(LazyArguments::Count);
    if c.arguments_length_only
        && !(lazy_arguments && !c.ops.iter().any(|op| matches!(op, Op::ArgElem(_))))
    {
        log_bail("fn", "mapped arguments observed beyond length");
        return None;
    }
    let jit_needs_activation_state = c.ops.iter().any(jit_bridge_op);
    let has_tail_calls = c
        .ops
        .iter()
        .any(|op| matches!(op, Op::TailCall(..) | Op::TailEvalCallArgsArray));
    let inline_planning_genv = exclusive_inline_genv(&c.inline_targets);
    let chunk = Chunk {
        debug_origin: source.map_or((0, 0), |func| {
            (
                func.start,
                func.source.as_ref().map_or(0, |text| text.len() as u32),
            )
        }),
        prepared_entry,
        lean_new_target: c.lean_new_target,
        rest_slot: c.rest_slot,
        lazy_arguments,
        arguments_count,
        ops: c.ops,
        jit_needs_activation_state,
        has_tail_calls,
        consts: crate::rooting::RootedVec::from_vec(c.consts),
        names: c.names,
        n_slots: c.slot_names.len(),
        slot_names: c.slot_names,
        borrowed_parameter_aliases: c.borrowed_parameter_aliases,
        function_osr_entries: c.function_osr_entries,
        n_refs: c.n_refs,
        n_params: c.n_params,
        arguments_slot: c.arguments_slot,
        uses_this: c.uses_this,
        lexical_this: c.lexical_this,
        strict: c.strict,
        resumable: is_coroutine,
        instance_capacity_hint,
        instance_layout,
        forwarded_capacity_hint: std::cell::Cell::new(0),
        initializer_layout: std::cell::OnceCell::new(),
        funcs: c.funcs,
        templates: c.templates,
        eval_exprs: c.eval_exprs,
        class_plans: c.class_plans,
        assignment_targets: c.assignment_targets,
        lexical_scopes: c
            .lexical_scopes
            .into_iter()
            .map(LexicalScope::new)
            .collect(),
        cap_inits: c.cap_inits,
        activation_plan: std::cell::OnceCell::new(),
        binding_layout_id: crate::interpreter::new_binding_layout_id(),
        reuse_activation: c.reuse_activation,
        env_this: c.env_this,
        env_arguments: c.env_arguments,
        feedback,
        feedback_shapes: std::cell::RefCell::new(Vec::new()),
        obj_maps: (0..c.obj_maps)
            .map(|_| std::cell::OnceCell::new())
            .collect(),
        record_getter: std::cell::OnceCell::new(),
        caches: c.caches,
        name_pins: std::cell::RefCell::new(c.name_pins),
        name_caches: c.name_caches,
        deep_name_caches: std::cell::RefCell::new(Vec::new()),
        resolution_caches: std::cell::OnceCell::new(),
        name_num_bits: c.name_num_bits,
        name_num_valid: c.name_num_valid,
        cap_caches: vec![std::cell::Cell::new(NameIc::EMPTY); cap_cache_len],
        cap_pins: std::cell::RefCell::new(vec![None; cap_cache_len]),
        initializer_plan: std::cell::OnceCell::new(),
        simple_constructor_shapes: std::cell::Cell::new(InitializerShapes::default()),
        simple_constructor_plan: std::cell::OnceCell::new(),
        arguments_forwarder: std::cell::OnceCell::new(),
        arguments_forwarder_runtime: std::cell::RefCell::new(None),
        regexp_literals: (0..op_count).map(|_| std::cell::OnceCell::new()).collect(),
        call_caches: c.call_caches,
        call_names: c.call_names.into_table(),
        positions: c.positions,
        call_positions,
        construct_positions,
        inline_sites,
        construct_caches: c.construct_caches,
        private_sites: (0..c.private_sites).map(|_| PrivateSite::new()).collect(),
        call_pins: std::cell::RefCell::new(c.call_pins),
        inline_targets: c.inline_targets,
        inline_planning_genv,
        jit_runs: std::cell::Cell::new(0),
        vm_runs: std::cell::Cell::new(0),
        inline_attempted: std::cell::Cell::new(inline_recompile_at() == 0),
        inline_retry_at: std::cell::Cell::new(inline_recompile_at()),
        inline_checks: std::cell::Cell::new(0),
        inline_feedback: std::cell::Cell::new(0),
        jit: crate::jit::cache::NativeCodeSlot::new(),
        jit_budget_wait_bytes: std::cell::Cell::new(0),
        osr: std::cell::OnceCell::new(),
    };
    Some(Rc::new(chunk))
}

/// Machine-code runs before the first bounded, feedback-adaptive inline checkpoint.
pub(crate) fn inline_recompile_at() -> u32 {
    static AT: std::sync::OnceLock<u32> = std::sync::OnceLock::new();
    *AT.get_or_init(|| {
        std::env::var("TRUST_JS_INLINE_AT")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(100)
    })
}

/// A mixed or unrestricted graph may contain a useful way in another Realm. Only a
/// uniform nonzero dependency proves that every spliced way would miss there.
fn exclusive_inline_genv(targets: &[InlineTarget]) -> usize {
    targets.first().map_or(0, |first| {
        let genv = first.expected_genv;
        if genv != 0 && targets.iter().all(|target| target.expected_genv == genv) {
            genv
        } else {
            0
        }
    })
}

/// Whether the ARM64 JIT may enter another compiled function through the shared activation.
/// This is a diagnostic kill switch, not a tier choice: ordinary layered JIT calls remain active
/// when it is disabled.
pub(crate) fn direct_shared_context_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("TRUST_JS_JIT_NO_DIRECT_CALLS").is_none())
}

/// Build the speculative-inline plan for a hot chunk: for each monomorphic, filled call site,
/// the callee qualifies when it is a plain same-strictness, same-Realm function whose compiled
/// body is small, needs no activation environment, and hides no control-flow the splice can't
/// reproduce (handlers, closures). Its free-name reads resolve from its own [[Environment]]. The plan keys are the sites' `CallIc`
/// indices, which equal the second compile's caller-level site ordinals (same AST, same
/// emission order).
/// Register the inline sites a finished compile's positions name, and rewrite those positions
/// from the compiler's local site list to the registered ones. Sites of discarded or unused
/// splices are left out. Cache implicit positions by final PC only after that identity rewrite;
/// ordinary chunks allocate no lookup, and error/explicit-call positions retain the run table.
fn register_inline_sites(c: &mut Compiler) -> crate::stack_trace::InlineSites {
    use crate::stack_trace::{inline_index, inline_position, is_inline_position, InlineSite};
    let count = c.inline_sites.len();
    if count == 0 {
        return Default::default();
    }
    let mut used = vec![false; count];
    for &(_, position) in &c.positions.runs {
        if is_inline_position(position) {
            used[inline_index(position)] = true;
        }
    }
    // A site's caller position names an earlier site (a splice exists before its body's).
    for index in (0..count).rev() {
        let outer = c.inline_sites[index].2;
        if used[index] && is_inline_position(outer) {
            used[inline_index(outer)] = true;
        }
    }
    let mut listed = vec![u32::MAX; count];
    let mut sites = Vec::new();
    for index in (0..count).filter(|&index| used[index]) {
        let (target, inner, outer) = c.inline_sites[index];
        let outer = if is_inline_position(outer) {
            inline_position(listed[inline_index(outer)])
        } else {
            outer
        };
        listed[index] = sites.len() as u32;
        sites.push(InlineSite {
            callee: c.inline_targets[target as usize].pin.clone(),
            inner,
            outer,
        });
    }
    let (mut owned, registered) = crate::stack_trace::InlineSites::register(sites);
    for run in &mut c.positions.runs {
        if is_inline_position(run.1) {
            run.1 = registered[listed[inline_index(run.1)] as usize];
        }
    }
    if !owned.is_empty() {
        owned.set_implicit_positions(c.positions.implicit_positions(c.ops.len()));
    }
    owned
}

pub(crate) fn plan_inlines(
    chunk: &Chunk,
    caller: &Function,
    // The optimized function's [[Realm]] (`UserCallable::realm` identity): splices run in it.
    realm: usize,
    // That Realm's global environment, which every splice's guard requires at run time.
    genv: &Env,
) -> crate::fasthash::FastMap<u32, InlinePlanEntry> {
    // Bound the *whole* optimized body rather than stopping after one arbitrary nesting level.
    // OO hot loops tend to be call chains (dispatcher -> virtual method -> small scheduler
    // helper); a depth-one cap leaves the most valuable dispatch intact.  The shared source-op
    // budget prevents four-way polymorphic sites from growing exponentially.  It is deliberately
    // conservative: an inline property op can expand to substantially more machine code than a
    // simple arithmetic op.
    const INLINE_SOURCE_OP_BUDGET: usize = 320;
    let limit = env_value!("TRUST_JS_INLINE_BUDGET")
        .and_then(|v| v.parse().ok())
        .unwrap_or(INLINE_SOURCE_OP_BUDGET);
    let mut budget = InlineBudget {
        shared: limit.saturating_sub(chunk.ops.len()),
        small: env_value!("TRUST_JS_INLINE_SMALL_BUDGET")
            .and_then(|v| v.parse().ok())
            .unwrap_or(INLINE_SMALL_BUDGET),
    };
    plan_inlines_at(chunk, caller, realm, genv, 0, false, &mut budget)
}

/// Source operations a callee may have to splice from the small-callee budget.
const INLINE_SMALL_CALLEE_OPS: usize = 16;
/// Source operations of small callees spliced into one optimized body after the shared budget
/// is exhausted. Large obfuscated or generated callers (string-table accessors, operator
/// wrappers) exhaust the shared budget by their own size, yet their hottest calls are to
/// callees whose splice is no larger than the call sequence it replaces.
const INLINE_SMALL_BUDGET: usize = 384;

struct InlineBudget {
    /// Shared by every splice of the optimized body (see [`plan_inlines`]).
    shared: usize,
    /// Reserved for callees of at most [`INLINE_SMALL_CALLEE_OPS`] operations.
    small: usize,
}

impl InlineBudget {
    /// Charge a callee of `cost` source operations, preferring the shared budget. The small
    /// budget admits only splices that cannot grow straight-line code much: leaf callees (no
    /// call of their own, hence no nested generic-call fallback) or sites that repeat in a loop.
    /// Straight-line code in large run-few-times callers is instruction-fetch bound, and a
    /// non-leaf splice there is several times the size of the call it replaces.
    fn take(&mut self, cost: usize, leaf: bool, in_loop: bool) -> bool {
        if cost <= self.shared {
            self.shared -= cost;
        } else if cost <= INLINE_SMALL_CALLEE_OPS && cost <= self.small && (leaf || in_loop) {
            self.small -= cost;
        } else {
            return false;
        }
        true
    }

    fn remaining(&self) -> bool {
        self.shared > 0 || self.small > 0
    }
}

/// Whether `test` is a literal whose ToBoolean is false (ECMA-262 ToBoolean: `0`, `-0`, `NaN`,
/// `false`, `null`): evaluating it has no side effect.
fn is_literal_falsy(test: &Expr) -> bool {
    match test {
        Expr::Paren(inner) => is_literal_falsy(inner),
        Expr::Num(n) => *n == 0.0 || n.is_nan(),
        Expr::Bool(value) => !*value,
        Expr::Null => true,
        _ => false,
    }
}

/// For each call-cache site of `chunk`, whether its call lies inside a loop (between a backward
/// branch's target and the branch).
fn call_sites_in_loops(chunk: &Chunk) -> Vec<bool> {
    let mut in_loop = vec![false; chunk.call_caches.len()];
    let mut loops: Vec<(usize, usize)> = Vec::new();
    for (pc, op) in chunk.ops.iter().enumerate() {
        if let Op::Jump(t)
        | Op::JumpIfFalse(t)
        | Op::JumpIfFalsePeek(t)
        | Op::JumpIfTruePeek(t)
        | Op::JumpIfNotNullishPeek(t) = *op
        {
            if t as usize <= pc {
                loops.push((t as usize, pc));
            }
        }
    }
    if loops.is_empty() {
        return in_loop;
    }
    for (pc, op) in chunk.ops.iter().enumerate() {
        if let Op::Call(_, c) | Op::CallWithThis(_, c) = *op {
            if let Some(slot) = in_loop.get_mut(c as usize) {
                *slot |= loops.iter().any(|&(start, end)| start <= pc && pc <= end);
            }
        }
    }
    in_loop
}

/// What the AST splice can preserve without constructing the callee's execution context.
/// This is deliberately an allowlist: adding VM/native coverage must not silently authorize
/// inlining an operation that observes a different Function/Private Environment Record.
#[derive(Clone, Copy, PartialEq, Eq)]
enum InlineCapability {
    /// Operands, local slots, constants, and branch targets are regenerated in the caller.
    RemappedFrame,
    /// Free-name reads: the splice resolves them from the callee's [[Environment]].
    ClosureRead(u32),
    /// A real call is required until the splice explicitly remaps this context/state.
    RequiresCallContext,
}

fn inline_capability(op: &Op) -> InlineCapability {
    match *op {
        Op::LoadName(name, _) | Op::LoadNameForCall(name, _) | Op::TypeofName(name) => {
            InlineCapability::ClosureRead(name)
        }
        Op::Const(_)
        | Op::Undef
        | Op::Dup
        | Op::Pop
        | Op::Dup2
        | Op::LoadLocal(_)
        | Op::StoreLocal(_)
        | Op::UpdateLocal(..)
        | Op::Tdz(_)
        | Op::StoreConstLocal(..)
        | Op::UpdateConst(..)
        | Op::ResetSlots(..)
        | Op::LoadThis
        | Op::RequireObject
        | Op::RequireCallable
        | Op::GetProp(..)
        | Op::GetPropThis(..)
        | Op::GetPropLocal(..)
        | Op::SetProp(..)
        | Op::SetPropDrop(..)
        | Op::SetPropThisDrop(..)
        | Op::SetPropLocalDrop(..)
        | Op::AppendProp(..)
        | Op::UpdateProp(..)
        | Op::GetElem
        | Op::SetElem
        | Op::SetElemDrop
        | Op::GetElemLocal(_)
        | Op::SetElemLocal(_)
        | Op::SetElemLocalDrop(_)
        | Op::UpdateElem(_)
        | Op::GetMethod(..)
        | Op::GetMethodElem
        | Op::DeleteProp(..)
        | Op::DeleteElem(_)
        | Op::ToPropKey
        | Op::ToPropKeyLocal(_)
        | Op::ToStr
        | Op::Add
        | Op::Sub
        | Op::Mul
        | Op::Div
        | Op::Mod
        | Op::BitAnd
        | Op::BitOr
        | Op::BitXor
        | Op::Shl
        | Op::Shr
        | Op::UShr
        | Op::Lt
        | Op::Gt
        | Op::Le
        | Op::Ge
        | Op::EqEq
        | Op::NotEq
        | Op::StrictEq
        | Op::StrictNotEq
        | Op::InstanceOf(_)
        | Op::In
        | Op::GenBin(_)
        | Op::Abstract(_)
        | Op::Neg
        | Op::Plus
        | Op::Not
        | Op::BitNot
        | Op::Typeof
        | Op::TypeofIs(..)
        | Op::Void
        | Op::Jump(_)
        | Op::JumpIfFalse(_)
        | Op::JumpIfFalsePeek(_)
        | Op::JumpIfTruePeek(_)
        | Op::JumpIfNotNullishPeek(_)
        | Op::Call(..)
        | Op::CallWithThis(..)
        | Op::CallSpread(_)
        | Op::CallSpreadThis(_)
        | Op::CallArgsArray
        | Op::CallArgsArrayThis
        | Op::New(..)
        | Op::NewArgsArray
        | Op::MakeRegExp(..)
        | Op::MakeArray(_)
        | Op::NewArray
        | Op::ArrayPush
        | Op::ArrayHole
        | Op::ArraySpread
        | Op::MakeObject(..)
        | Op::NewObject
        | Op::ObjectData(_)
        | Op::ObjectDataName(..)
        | Op::ObjectSpread
        | Op::ObjectProto
        | Op::ObjectRest(_)
        | Op::GetIter
        | Op::ForInKeys
        | Op::ForInStepL(..)
        | Op::IterStepL(..)
        | Op::IterCloseL(_)
        | Op::DestructureGuard
        | Op::DestructureArr(_)
        | Op::DestructureStepL(..)
        | Op::DestructureRestL(..)
        | Op::IterCloseIfNotDoneL(..)
        | Op::Throw
        | Op::Return
        | Op::ReturnBare
        | Op::ReturnUndef => InlineCapability::RemappedFrame,
        // In particular, SuperThis/SuperBase need BOTH the callee receiver and its live
        // [[HomeObject]], not the caller's lexical environment. Private names, new.target,
        // direct eval, closure creation, prepared references, handlers, cleanup and suspension
        // likewise lack a complete remapping contract. Keep their normal native call intact.
        // ECMA-262 GetThisEnvironment, GetSuperBase and MakeSuperPropertyReference; local
        // official snapshot e28783d5fc9dc12b3de905961e2c71410b38a202.
        _ => InlineCapability::RequiresCallContext,
    }
}

fn plan_inlines_at(
    chunk: &Chunk,
    caller: &Function,
    realm: usize,
    genv: &Env,
    depth: u32,
    // The enclosing splice repeats in a loop of the optimized body.
    outer_in_loop: bool,
    budget: &mut InlineBudget,
) -> crate::fasthash::FastMap<u32, InlinePlanEntry> {
    const INLINE_MAX_DEPTH: u32 = 3;
    const INLINE_MAX_WAYS: usize = 4;
    let max_ops = env_value!("TRUST_JS_INLINE_MAX_OPS")
        .and_then(|v| v.parse().ok())
        .unwrap_or(96);
    let mut plan: crate::fasthash::FastMap<u32, InlinePlanEntry> = Default::default();
    let log = env_flag!("TRUST_JS_TIER_LOG");
    macro_rules! skip {
        ($idx:expr, $why:expr) => {{
            if log {
                eprintln!("[tier] inline skip site {}: {}", $idx, $why);
            }
            continue;
        }};
    }
    let pins = chunk.call_pins.borrow();
    let sites_in_loops = call_sites_in_loops(chunk);
    for (idx, site) in chunk.call_caches.iter().enumerate() {
        let in_loop = outer_in_loop || sites_in_loops[idx];
        let mut filled: Vec<CallIc> = site
            .entries
            .iter()
            .map(|e| e.get())
            .filter(|c| c.callee != 0)
            .collect();
        // Distinct callees (refills may duplicate one across ways).  Call ICs retain four ways,
        // so consume all four when the body budget permits: Richards' central task dispatcher is
        // exactly four-way polymorphic, and leaving half of it as real calls dominates runtime.
        filled.dedup_by_key(|c| c.callee);
        let mut ways: Vec<InlineWay> = Vec::new();
        for ic in filled.iter().take(INLINE_MAX_WAYS) {
            let Some(weak) = pins.get(&ic.callee) else {
                skip!(idx, "no pin")
            };
            let Some(obj) = weak.upgrade() else {
                skip!(idx, "dead callee")
            };
            let b = obj.borrow();
            let crate::value::Callable::User(user) = &b.call else {
                continue;
            };
            // A splice runs in the caller's Realm: its literals, intrinsics and global object
            // must be the callee's [[Realm]]'s. The callee's free names resolve from its own
            // [[Environment]] (`Op::LoadNameIn`, behind the identity guard), so any same-Realm
            // closure qualifies.
            if user.realm != realm {
                skip!(idx, "cross-realm callee");
            }
            let f = &user.func;
            if f.is_strict != caller.is_strict {
                skip!(idx, "strictness");
            }
            // Lexical observations must remain in the definition frame. Plain arrow helpers
            // need no such frame and share the ordinary parameter/free-name guarded splice.
            if f.is_arrow && f.scan_flags() & (SCAN_THIS | SCAN_ARGUMENTS | SCAN_NEW_TARGET) != 0 {
                skip!(idx, "arrow lexical observations");
            }
            if f.params.iter().any(|p| {
                p.rest || p.default.is_some() || !matches!(p.pattern, crate::ast::Pattern::Ident(_))
            }) {
                skip!(idx, "param shape");
            }
            let Some(Some(callee_chunk)) = f.code.get() else {
                skip!(idx, "callee not compiled");
            };
            if std::ptr::eq(&**callee_chunk, chunk) {
                skip!(idx, "self-recursion");
            }
            if callee_chunk.ops.len() > max_ops
                || callee_chunk.n_slots > 32
                || !callee_chunk.jit_no_activation()
                || callee_chunk.env_this
                || ic.n_params > 8
            {
                skip!(idx, "callee size/shape");
            }
            if callee_chunk
                .ops
                .iter()
                .any(|op| inline_capability(op) == InlineCapability::RequiresCallContext)
            {
                skip!(idx, "callee operation requires an unremapped call context");
            }
            // `typeof name` has no environment-redirected form (see `Compiler::inline_env_op`).
            if callee_chunk
                .ops
                .iter()
                .any(|op| matches!(op, Op::TypeofName(_)))
            {
                skip!(idx, "typeof of a free name");
            }
            // Legacy `f.caller` / `f.arguments` read an activation's frame, and a splice runs
            // without one: a callee that names either property keeps its frame (the reflection
            // still finds splices that call out through their call positions).
            if callee_chunk
                .names
                .iter()
                .any(|name| matches!(&**name, "caller" | "arguments"))
            {
                skip!(idx, "legacy caller/arguments reflection");
            }
            let mut free_names: Vec<Rc<str>> = Vec::new();
            for op in callee_chunk.ops.iter() {
                if let InlineCapability::ClosureRead(n) = inline_capability(op) {
                    let name = callee_chunk.names[n as usize].clone();
                    if !free_names.contains(&name) {
                        free_names.push(name);
                    }
                }
            }
            let inline_cost = callee_chunk.ops.len();
            let leaf = !callee_chunk.ops.iter().any(|op| {
                matches!(
                    op,
                    Op::Call(..)
                        | Op::CallWithThis(..)
                        | Op::CallSpread(_)
                        | Op::CallSpreadThis(_)
                        | Op::CallArgsArray
                        | Op::CallArgsArrayThis
                        | Op::New(..)
                        | Op::NewArgsArray
                )
            });
            if !budget.take(inline_cost, leaf, in_loop) {
                skip!(idx, "optimized-body budget");
            }
            let uses_this = callee_chunk.uses_this();
            // Follow small hot call chains under the shared body budget.  This reaches through a
            // dispatcher into its virtual target and then into leaf helpers without allowing
            // unbounded recursive expansion.
            let nested = if depth < INLINE_MAX_DEPTH && budget.remaining() {
                plan_inlines_at(callee_chunk, f, realm, genv, depth + 1, in_loop, budget)
            } else {
                Default::default()
            };
            let f = f.clone();
            drop(b);
            ways.push(InlineWay {
                check_this: uses_this && !f.is_strict,
                uses_this,
                f,
                obj,
                free_names,
                expected_env: 0,
                expected_genv: Env::as_ptr(genv) as usize,
                genv_pin: Env::downgrade(genv),
                nested,
            });
        }
        if ways.is_empty() {
            continue;
        }
        plan.insert(idx as u32, InlinePlanEntry { ways });
    }
    plan
}

#[cfg(test)]
mod compiler_name_tests {
    use super::Compiler;

    #[test]
    fn indexed_names_keep_first_occurrence_and_contiguous_literal_keys() {
        let mut compiler = Compiler::default();
        for index in 0..32 {
            assert_eq!(compiler.name_idx(&format!("field{index}")), index);
        }
        assert!(compiler.name_indexes.is_none());
        for index in 32..256 {
            assert_eq!(compiler.name_idx(&format!("field{index}")), index);
        }
        assert!(compiler.name_indexes.is_some());
        for index in (0..256).rev() {
            assert_eq!(compiler.name_idx(&format!("field{index}")), index);
        }
        // MakeObject deliberately appends duplicate keys in a consecutive operand range.
        for (offset, key) in ["field99", "new", "field1", "new", "é", "e\u{301}"]
            .into_iter()
            .enumerate()
        {
            assert_eq!(compiler.append_name(key), 256 + offset as u32);
        }
        assert_eq!(compiler.name_idx("field99"), 99);
        assert_eq!(compiler.name_idx("field1"), 1);
        assert_eq!(compiler.name_idx("new"), 257);
        assert_eq!(compiler.name_idx("é"), 260);
        assert_eq!(compiler.name_idx("e\u{301}"), 261);
        assert_eq!(compiler.names.len(), 262);
    }

    #[test]
    fn indexed_names_rollback_discards_only_the_spliced_suffix() {
        let mut compiler = Compiler::default();
        for index in 0..64 {
            compiler.append_name(&format!("field{index}"));
        }
        // Build lazily even when the entire initial pool came from literal-key ranges.
        assert_eq!(compiler.name_idx("field63"), 63);
        assert!(compiler.name_indexes.is_some());
        assert_eq!(compiler.append_name("field3"), 64);
        assert_eq!(compiler.name_idx("discarded"), 65);
        compiler.append_name("discarded");
        compiler.truncate_names(64);
        assert_eq!(compiler.name_idx("field3"), 3);
        assert_eq!(compiler.name_idx("replacement"), 64);
        assert_eq!(compiler.name_idx("discarded"), 65);
        compiler.truncate_names(2);
        assert_eq!(compiler.name_idx("field1"), 1);
        assert_eq!(compiler.name_idx("field63"), 2);
        compiler.truncate_names(0);
        assert_eq!(compiler.name_idx("discarded"), 0);
        assert_eq!(compiler.names.len(), 1);
    }

    #[test]
    fn indexed_names_match_linear_lookup_through_repeated_rollbacks() {
        let mut compiler = Compiler::default();
        let mut reference = Vec::<String>::new();
        let mut random = 7u64;
        for step in 0..10_000 {
            random = random.wrapping_mul(6364136223846793005).wrapping_add(1);
            let key = format!("name{}", random >> 32 & 511);
            match (step < 256, random & 15) {
                (false, 0) => {
                    let len = (random >> 16) as usize % (reference.len() + 1);
                    reference.truncate(len);
                    compiler.truncate_names(len);
                }
                (_, 1 | 2) => {
                    assert_eq!(compiler.append_name(&key) as usize, reference.len());
                    reference.push(key);
                }
                _ => {
                    let index = reference
                        .iter()
                        .position(|name| name == &key)
                        .unwrap_or_else(|| {
                            reference.push(key.clone());
                            reference.len() - 1
                        });
                    assert_eq!(compiler.name_idx(&key) as usize, index, "step {step}");
                }
            }
            assert_eq!(compiler.names.len(), reference.len());
        }
    }
}

/// A bounded selector set keeps pathological source from expanding compiler work. Unary signs
/// and parentheses over numeric literals are pure; identifiers and other expressions are not.
fn integer_switch_cases(cases: &[SwitchCase]) -> Option<Vec<(i32, usize)>> {
    fn literal(expr: &Expr) -> Option<f64> {
        match expr {
            Expr::Num(value) => Some(*value),
            Expr::Paren(inner) => literal(inner),
            Expr::Unary { op: "+", arg } => literal(arg),
            Expr::Unary { op: "-", arg } => literal(arg).map(|value| -value),
            _ => None,
        }
    }
    if cases.len() < 8 || cases.len() > 1024 {
        return None;
    }
    let mut values = std::collections::BTreeMap::new();
    for (index, case) in cases.iter().enumerate() {
        if let Some(test) = &case.test {
            let value = literal(test)?;
            if value < i32::MIN as f64 || value > i32::MAX as f64 || value.fract() != 0.0 {
                return None;
            }
            values.entry(value as i32).or_insert(index);
        }
    }
    (values.len() >= 8).then(|| values.into_iter().collect())
}

/// The position [`Compiler::emit`] records, [`NO_POSITION`] outside every position-bearing node.
struct CompilePosition(u32);

impl Default for CompilePosition {
    fn default() -> Self {
        CompilePosition(NO_POSITION)
    }
}

#[derive(Default)]
struct Compiler {
    /// Compiling a body of the engine's self-hosted built-in source (see `crate::self_hosted`):
    /// calls of its intrinsics' free names compile to operations (see `self_hosted_intrinsic`).
    /// Follows the function being compiled, including a callee spliced by the inliner.
    self_hosted: bool,
    /// ECMA-262 GetNewTarget in an ordinary function compiled without a Function Environment
    /// Record. Every call path installs the callee's [[NewTarget]] as the interpreter's current
    /// value and restores the caller's around nested calls, so the body reads it directly. An
    /// arrow that observes `new.target` would need that record as its lexical environment, so
    /// such an arrow makes the enclosing function ineligible (see `expr`).
    lean_new_target: bool,
    /// See [`Chunk::rest_slot`].
    rest_slot: Option<u16>,
    /// A sloppy function with simple parameters compiled without its mapped arguments object:
    /// valid only if the body reads nothing but `arguments.length` (see `finish_chunk`).
    arguments_length_only: bool,
    /// Borrow the already-instantiated AST environment and return exact source completions.
    fragment_entry: bool,
    borrowed_parameter_aliases: bool,
    fragment_async_generator: bool,
    fragment_tail_calls: bool,
    fragment_root: Option<loop_fragment::RootKind>,
    fragment_seed_slots: Vec<u16>,
    fragment_exits: Vec<(usize, FragmentExitKind)>,
    function_osr_sites: Vec<usize>,
    function_osr_entries: Vec<FunctionOsrEntry>,
    pending_function_osr_site: Option<usize>,
    function_osr_environment_handlers: Vec<usize>,
    /// The compiled function's strictness (carried into ops whose runtime behavior forks on it).
    strict: bool,
    /// Generator/async chunks use the VM as their resumable execution context, not merely as an
    /// optimization tier. Some completion-aware lowerings are intentionally coroutine-only.
    is_coroutine: bool,
    /// Source Text Module execution uses bindings instantiated by the link phase rather than a
    /// fresh FunctionDeclarationInstantiation environment.
    module_body: bool,
    /// An already-instantiated Script Record. Global bindings are never compiler-local slots.
    script_body: bool,
    script_vars: crate::fasthash::FastSet<String>,
    script_annexb: crate::fasthash::FastSet<usize>,
    /// StatementList's last nonempty completion, initialized to undefined at script entry.
    script_completion: Option<u16>,
    /// This coroutine contains direct eval and CaptureScan proved every dynamically visible
    /// depth-0 binding has an exact retained activation or runtime lexical-environment home.
    direct_eval: bool,
    /// Inner lexical names whose closure- or eval-visible bindings must live in the resumable
    /// environment chain. Every admitted source scope receives its own Environment Record even
    /// when several declarations reuse the same spelling.
    runtime_lexicals: crate::fasthash::FastSet<String>,
    /// Captured once-per-call block `let`s homed in the activation (see CaptureScan's
    /// `candidates`). `homed_pending` holds the ones whose declaring block hasn't been reached
    /// yet: the FIRST block-level declaration of the name consumes it (skipping slot creation);
    /// any later same-name declaration is a nested shadow and binds a slot normally.
    homed_lets: crate::fasthash::FastSet<String>,
    homed_pending: crate::fasthash::FastSet<String>,
    ops: Vec<Op>,
    consts: Vec<Value>,
    names: Vec<Rc<str>>,
    /// Compile-only index for larger name pools. `names` remains the authoritative ordered
    /// table: object-literal keys can be contiguous duplicates, so this maps to the FIRST entry.
    name_indexes: Option<crate::fasthash::FastMap<Rc<str>, u32>>,
    /// Lexical scopes for slot resolution: (name, slot, is_const), innermost last.
    scopes: Vec<Vec<(String, u16, bool)>>,
    /// Environment-backed bindings at each compiler scope, parallel to `scopes`. An entry blocks
    /// lookup of same-named outer slots and resolves through the VM's current environment cursor.
    lexical_env_names: Vec<crate::fasthash::FastMap<String, bool>>,
    /// Scope-vector length at entry to each compiled `with` body. Bindings declared in scopes
    /// added after the innermost boundary shadow the with object; all earlier slot/activation
    /// homes must instead use dynamic Environment Record resolution.
    with_scope_floors: Vec<usize>,
    slot_names: Vec<Rc<str>>,
    n_refs: usize,
    n_params: usize,
    arguments_slot: Option<u16>,
    loops: Vec<LoopCtx>,
    /// Labels collected from an enclosing `Stmt::Labeled` chain, waiting to be attached to the next
    /// loop's `LoopCtx` (drained when that loop pushes its context).
    pending_labels: Vec<String>,
    uses_this: bool,
    /// Count of object-literal template sites handed out (see `Chunk::obj_maps`).
    obj_maps: u32,
    caches: Vec<std::cell::Cell<IcState>>,
    /// Property-cache snapshots for the source frame currently being recompiled. The hot
    /// first-stage caller is the root; entering a speculative inline pushes that callee's own
    /// hot first-stage property-site vector. Cursors follow source property-op order, which is
    /// stable for a function's AST even when `this` becomes an inline local; each seed also
    /// carries its property name so a compiler-shape mismatch safely leaves the new site cold.
    cache_seed_stack: Vec<(Vec<(Rc<str>, [IcState; PROP_IC_WAYS])>, usize)>,
    name_caches: Vec<std::cell::Cell<NameIc>>,
    name_pins: Vec<NamePin>,
    name_num_bits: Vec<std::cell::Cell<u64>>,
    name_num_valid: Vec<std::cell::Cell<bool>>,
    name_seed_stack: Vec<(Vec<NameSeed>, usize)>,
    call_caches: Vec<CallSite>,
    /// See [`Chunk::call_name`]; rolled back with `ops`.
    call_names: CallNames,
    /// See [`Chunk::position`]; rolled back with `ops`.
    positions: SourcePositions,
    /// The position recorded for operations emitted now (see [`Compiler::at_position`]).
    position: CompilePosition,
    /// Spliced callees' operation positions, as (inline target, byte offset in the callee's
    /// source, position of the splice in its caller); [`Compiler::inline_position`] names them
    /// with local inline positions that the chunk registers when it is built
    /// (`crate::stack_trace::InlineSite`). Rolled back with `inline_targets`.
    inline_sites: Vec<(u32, u32, u32)>,
    inline_site_index: crate::fasthash::FastMap<(u32, u32, u32), u32>,
    /// The splices being compiled, innermost last: (inline target, position in its caller).
    inline_frames: Vec<(u32, u32)>,
    /// The target name [`Compiler::finish_call`] records for the call it emits.
    pending_call_name: Option<String>,
    construct_caches: Vec<std::cell::Cell<ConstructSite>>,
    /// Number of private-name operation sites (`Chunk::private_sites`).
    private_sites: u32,
    call_pins: crate::fasthash::FastMap<usize, CallPin>,
    /// Polymorphic call feedback for the source frame currently being recompiled. Like property
    /// seeds, this is a compile-time stack: speculative child splices consume their own original
    /// call-site order without disturbing the caller's cursor.
    call_seed_stack: Vec<(Vec<CallSeed>, usize)>,
    /// Number of `PushHandler` regions active at the current emission point. `break`/`continue`
    /// jumping out of a `try` block (or a for-of body, which wraps itself in a handler) must
    /// emit a `PopHandler` per region crossed, or the stale handler catches unrelated throws
    /// later in the frame.
    try_depth: u32,
    /// Source-level contexts that forbid tail transfer (try bodies, catch-before-finally,
    /// for-of bodies, and statements after a using declaration). Synthetic environment
    /// cleanup handlers do not forbid tail calls: they only restore the environment cursor.
    tail_blocked: u32,
    /// Keep the final call opcode available while lowering a tail expression. Nested calls
    /// still execute normally; no inline splice may hide the call being converted.
    lowering_tail: bool,
    /// The `Expr::Call` node of the tail call being lowered (its address), until its own call
    /// arm claims it; `tail_finish` then hands the claim to that node's `finish_call`.
    tail_call_node: usize,
    tail_finish: bool,
    /// `finish_call` emitted the tail call's complete depth-selected lowering.
    tail_lowered: bool,
    /// Active `finally` handler depths. A break/continue may discard ordinary catch/iterator
    /// handlers, but it must never jump across a finalizer without executing it.
    finally_depths: Vec<u32>,
    /// Slots that ever enter a temporal dead zone (an `Op::Tdz` was emitted for them). The fused
    /// element ops defer the base-slot read past key/value evaluation, which is only
    /// order-unobservable when the base can never TDZ-throw — params and `var`s qualify.
    tdz_slots: crate::fasthash::FastSet<u16>,
    /// Captured (env-homed) function-scope-wide names → is_const. Slot scopes shadow these.
    env_names: crate::fasthash::FastMap<String, bool>,
    /// Annex B block FunctionDeclaration AST identity → its distinct function-scope var home.
    /// The current lexical home has the same spelling when the declaration statement executes.
    annexb_targets: crate::fasthash::FastMap<usize, Home>,
    funcs: Vec<Rc<Function>>,
    templates: Vec<(u64, Vec<(Option<String>, String)>)>,
    eval_exprs: Vec<EvalExprPlan>,
    class_plans: Vec<ClassPlan>,
    assignment_targets: Vec<AssignmentTargetPlan>,
    lexical_scopes: Vec<Vec<LexicalBinding>>,
    cap_inits: Vec<CapInit>,
    reuse_activation: bool,
    env_this: bool,
    env_arguments: bool,
    lexical_this: bool,
    /// A derived constructor reads the live Function Environment Record: its `this` binding is
    /// uninitialized until `super()` and its `new.target` belongs to that same record.
    derived_constructor: bool,
    /// Speculative-inline plan stack (second-stage only): one frame per active splice, each
    /// mapping that frame's call-site ordinal (== the function's first-compile `CallIc` index —
    /// same AST, same emission order) to the callees to splice. See [`plan_inlines`].
    plan_stack: Vec<(crate::fasthash::FastMap<u32, InlinePlanEntry>, u32)>,
    /// > 0 while compiling a spliced callee body.
    inline_depth: u32,
    /// The slot holding the receiver while inlining a `this`-using callee.
    inline_this: Option<u16>,
    /// `return` jumps inside the current spliced body, patched to the join point.
    inline_returns: Vec<usize>,
    inline_targets: Vec<InlineTarget>,
    /// The inline target of each active splice, innermost last. Free-name reads emitted while
    /// one is active resolve against that callee's [[Environment]] (`Op::LoadNameIn`).
    inline_env_targets: Vec<u32>,
    /// A splice emitted an operation that observes the running Environment Record (other than
    /// the free-name reads `emit` redirects); the enclosing `try_emit_inline` bails.
    inline_env_violation: bool,
}

/// Whether a call occurs in a tail position of a return operand.
///
/// This is the expression part of ECMA-262 HasCallInTailPosition: only the
/// selected conditional arm, the final sequence element, and the right logical operand inherit
/// tail position.
fn has_tail_call(expr: &Expr) -> bool {
    if crate::interpreter::ast_stack_low() {
        return crate::interpreter::with_ast_stack(|| has_tail_call(expr));
    }
    match expr {
        Expr::Call { .. } | Expr::TaggedTemplate { .. } => true,
        Expr::Cond { cons, alt, .. } => has_tail_call(cons) || has_tail_call(alt),
        Expr::Seq(exprs) => exprs.last().is_some_and(has_tail_call),
        Expr::Logical { right, .. } | Expr::Paren(right) | Expr::OptionalChain(right) => {
            has_tail_call(right)
        }
        _ => false,
    }
}

/// One planned inline: the callee function (AST) and its pinned identity.
#[derive(Clone)]
pub struct InlinePlanEntry {
    /// Guarded ways, tried in order; a polymorphic site (DeltaBlue's constraint hierarchies)
    /// splices each hot callee behind its own identity guard, falling through to the next.
    pub ways: Vec<InlineWay>,
}

#[derive(Clone)]
pub struct InlineWay {
    pub f: Rc<Function>,
    pub obj: crate::value::Gc,
    pub check_this: bool,
    pub uses_this: bool,
    /// Free names the callee reads. The splice resolves them from the callee's own
    /// [[Environment]] (`Op::LoadNameIn`), so caller bindings never shadow them.
    pub free_names: Vec<Rc<str>>,
    /// Exact caller environment required by the guard (zero: none). Splices no longer depend
    /// on the caller's environment; retained for the guard's encoding.
    pub expected_env: usize,
    /// The planning Realm's global environment (see [`InlineTarget::expected_genv`]).
    pub expected_genv: usize,
    pub genv_pin: crate::interpreter::WeakEnv,
    /// The callee's OWN inline plan (depth-capped recursion): call sites inside the spliced
    /// body splice too, keyed by the callee-frame ordinal — its first-compile cache numbering,
    /// which the splice reproduces by walking the same AST in the same order.
    pub nested: crate::fasthash::FastMap<u32, InlinePlanEntry>,
}

/// Where a name resolves inside the compiled body.
#[derive(Clone, Copy)]
enum Home {
    Slot(u16, bool),
    /// Captured: lives in the activation env; bool = is_const.
    Env(bool),
}

/// A destructuring-assignment Reference whose observable base/key evaluation has already run.
/// Hidden slots retain member References across iterator steps and suspending defaults.
enum PreparedAssignmentRef {
    Local {
        slot: u16,
        is_const: bool,
        name: u32,
    },
    Captured {
        name: u32,
        is_const: bool,
    },
    Name(u32),
    Reference(u16),
    Property {
        base: u16,
        name: u32,
        cache: u32,
    },
    Element {
        base: u16,
        key: u16,
    },
    Private {
        base: u16,
        name: u32,
    },
    Super {
        receiver: u16,
        key: u16,
        base: u16,
    },
}

#[derive(Default)]
struct LoopCtx {
    breaks: Vec<usize>,
    continues: Vec<usize>,
    /// `Compiler::try_depth` when this context was entered — the reference point for how many
    /// handler regions a `break`/`continue` targeting this context crosses.
    entry_try_depth: u32,
    /// A for-of loop's iterator slot: crossing `break`s close it (`IterCloseL`); its own
    /// `continue`s don't (the loop keeps iterating).
    foreach_iter: Option<u16>,
    /// The async-from-sync flag slot for a `for await…of`; present means every abandonment uses
    /// suspending AsyncIteratorClose rather than synchronous IteratorClose.
    foreach_async_from_sync: Option<u16>,
    /// For a for-of context: `try_depth` just after its per-iteration body handler pushed —
    /// exits emitted inside the body pop down to here before touching the handler itself.
    body_try_depth: u32,
    /// Labels naming this loop (usually zero or one; `a: b: for(…)` stacks several). A labelled
    /// `break`/`continue` searches the loop stack for the ctx carrying its target label.
    labels: Vec<String>,
    /// A `switch` context: an unlabelled `break` targets it, but `continue` skips past it to the
    /// innermost enclosing loop.
    is_switch: bool,
    /// A labelled non-breakable statement accepts only a matching labelled `break`; unlabelled
    /// break/continue searches skip it.
    is_label_block: bool,
}

/// Debug (`TRUST_JS_TIER_LOG=1`): report the AST construct a compile bail came from.
fn log_bail(what: &str, detail: &str) {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    if *ON.get_or_init(|| std::env::var_os("TRUST_JS_TIER_LOG").is_some()) {
        eprintln!("[tier] unsupported {what}: {detail}");
    }
}

/// Compilation bail: the construct is outside the v0 subset.
struct Bail;
type CResult = Result<(), Bail>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CallArgsMode {
    Fixed(u16),
    FinalSpread(u16),
    Array,
}

/// Whether a parameter default is in the compiler's lowerable subset: no reference to any
/// *banned* name (this parameter itself or a later one — the spec's param-scope TDZ would throw
/// where slots would read a seeded `undefined`), and no nested function/class (whose capture
/// analysis of a *parameter expression* scope the slot model doesn't carry). Whitelist
/// recursion: unknown constructs answer false (the function stays on the tree-walker).
/// Whether `op` names local `slot` through any slot operand. Conservative: every operand that
/// may be a local slot index counts (a false positive only forgoes an optimization). Argument
/// and element counts of calls/array literals and the separate reference-slot namespace are not
/// local slots.
fn op_mentions_slot(op: &Op, slot: u16) -> bool {
    match *op {
        Op::LoadLocal(a)
        | Op::StoreLocal(a)
        | Op::UpdateLocal(a, _)
        | Op::Tdz(a)
        | Op::StoreConstLocal(a, _)
        | Op::GetPropLocal(a, ..)
        | Op::SetPropLocalDrop(a, ..)
        | Op::GetElemLocal(a)
        | Op::SetElemLocal(a)
        | Op::SetElemLocalDrop(a)
        | Op::ToPropKeyLocal(a)
        | Op::IterCloseL(a)
        | Op::IterAbortL(a)
        | Op::DestructureArr(a)
        | Op::ObjectRest(a)
        | Op::CallSpread(a)
        | Op::CallSpreadThis(a)
        | Op::ClassStart(_, a)
        | Op::ClassKey(_, a)
        | Op::ClassDecorator(_, a)
        | Op::ArgElem(a) => a == slot,
        Op::IterStepL(a, b)
        | Op::IterCloseIfNotDoneL(a, b)
        | Op::IterAbortIfNotDoneL(a, b)
        | Op::AsyncIterResumeL(a, b)
        | Op::AsyncIterCloseL(a, b, _) => a == slot || b == slot,
        Op::ForInStepL(a, b, c)
        | Op::DestructureStepL(a, b, c)
        | Op::DestructureRestL(a, b, c)
        | Op::TryArrayBinding(a, b, c)
        | Op::ArrayBindingStep(a, b, c) => a == slot || b == slot || c == slot,
        Op::AsyncIterStepL(a, b, c, d) => a == slot || b == slot || c == slot || d == slot,
        Op::ResetSlots(start, count) => (start..start.saturating_add(count)).contains(&slot),
        _ => false,
    }
}

/// How [`lazy_arguments_rewrite`] represents an unobservable arguments object.
#[derive(Clone, Copy, PartialEq, Eq)]
enum LazyArguments {
    /// A plain Array of the actual arguments (see [`Chunk::lazy_arguments`]).
    List,
    /// Their number alone (see [`Chunk::arguments_count`]).
    Count,
}

/// See [`Chunk::lazy_arguments`]. The arguments object of a body is unobservable when its slot
/// is read only as `arguments.length` and `arguments[key]`: it is never stored, passed, called,
/// captured, written or deleted, so no code other than those two reads can reach it. Rewrite
/// the element reads to [`Op::ArgElem`]; without any, only the length is observable
/// (CreateUnmappedArgumentsObject and CreateMappedArgumentsObject both define it as the number
/// of actual arguments, ECMA-262 §10.4.4.6–7), so rewrite its reads to slot loads of that
/// number. Otherwise leave `ops` unchanged and return `None`.
fn lazy_arguments_rewrite(ops: &mut [Op], slot: u16, names: &[Rc<str>]) -> Option<LazyArguments> {
    let only_reads = ops.iter().all(|op| match *op {
        Op::GetPropLocal(a, name, _) if a == slot => &*names[name as usize] == "length",
        Op::GetElemLocal(a) if a == slot => true,
        _ => !op_mentions_slot(op, slot),
    });
    if !only_reads {
        return None;
    }
    if !ops
        .iter()
        .any(|op| matches!(*op, Op::GetElemLocal(a) if a == slot))
    {
        for op in ops.iter_mut() {
            if matches!(*op, Op::GetPropLocal(a, ..) if a == slot) {
                *op = Op::LoadLocal(slot);
            }
        }
        return Some(LazyArguments::Count);
    }
    for op in ops.iter_mut() {
        if matches!(*op, Op::GetElemLocal(a) if a == slot) {
            *op = Op::ArgElem(slot);
        }
    }
    Some(LazyArguments::List)
}

/// The `arguments[key]` read of a lazily represented arguments object (see
/// [`Chunk::lazy_arguments`]). `list` is the plain Array of actual arguments: an in-range integer
/// index is exactly the corresponding own element of the arguments object. Any other key
/// materializes the arguments object this body would have created (unmapped, or sloppy without
/// parameters and thus without a ParameterMap) and performs the ordinary [[Get]] on it.
pub(crate) fn lazy_arguments_element(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    list: &Value,
    key: &Value,
    materialized: impl FnOnce(&Value),
) -> Result<Value, Abrupt> {
    let still_lazy = matches!(list, Value::Obj(object)
        if matches!(object.borrow().exotic, crate::value::Exotic::Array));
    if !still_lazy {
        // Already materialized by an earlier fallback: an ordinary arguments object.
        return get_computed_element(i, chunk, pc, list, key);
    }
    if let (Value::Obj(list), Value::Num(index)) = (list, key) {
        if let Some(value) = i.fast_get_elem(list, *index) {
            return Ok(value);
        }
    }
    // The [[Get]] may reach an inherited accessor that receives (and could keep or mutate) the
    // arguments object, so it replaces the list for every later read in this activation.
    let values = crate::builtins::dense_array_snapshot(i, list).unwrap_or_default();
    let scope = i.global_env.clone();
    let arguments = Value::Obj(i.make_compiled_arguments_object(&values, &scope));
    materialized(&arguments);
    get_computed_element(i, chunk, pc, &arguments, key)
}

/// [`default_expr_safe`] for every expression inside a binding pattern: nested defaults and
/// computed keys.
fn pattern_exprs_safe(pattern: &Pattern, banned: &crate::fasthash::FastSet<&str>) -> bool {
    match pattern {
        Pattern::Ident(_) => true,
        Pattern::Member(_) => false,
        Pattern::Object(object) => object.props.iter().all(|prop| {
            let key_safe = match &prop.key {
                PropKey::Computed(key) => default_expr_safe(key, banned),
                PropKey::Ident(_) | PropKey::Str(_) | PropKey::Num(_) => true,
            };
            key_safe
                && prop
                    .default
                    .as_ref()
                    .is_none_or(|default| default_expr_safe(default, banned))
                && pattern_exprs_safe(&prop.value, banned)
        }),
        Pattern::Array(elements) => elements.iter().all(|element| match element {
            ArrayPatElem::Hole => true,
            ArrayPatElem::Elem { pattern, default } => {
                default
                    .as_ref()
                    .is_none_or(|default| default_expr_safe(default, banned))
                    && pattern_exprs_safe(pattern, banned)
            }
            ArrayPatElem::Rest(pattern) => pattern_exprs_safe(pattern, banned),
        }),
    }
}

fn default_expr_safe(e: &Expr, banned: &crate::fasthash::FastSet<&str>) -> bool {
    if crate::interpreter::ast_stack_low() {
        return crate::interpreter::with_ast_stack(|| default_expr_safe(e, banned));
    }
    match e {
        Expr::Num(_)
        | Expr::BigInt(_)
        | Expr::Str(_)
        | Expr::Bool(_)
        | Expr::Null
        | Expr::Undefined
        | Expr::This
        | Expr::Regex { .. } => true,
        Expr::Ident(n, _) => !banned.contains(n.as_str()),
        Expr::Paren(x) | Expr::ToStr(x) | Expr::Unary { arg: x, .. } => {
            default_expr_safe(x, banned)
        }
        Expr::Update { arg, .. } => default_expr_safe(arg, banned),
        Expr::Binary { left, right, .. } | Expr::Logical { left, right, .. } => {
            default_expr_safe(left, banned) && default_expr_safe(right, banned)
        }
        Expr::Cond { test, cons, alt } => {
            default_expr_safe(test, banned)
                && default_expr_safe(cons, banned)
                && default_expr_safe(alt, banned)
        }
        Expr::Member { obj, .. } => default_expr_safe(obj, banned),
        Expr::Index { obj, index, .. } => {
            default_expr_safe(obj, banned) && default_expr_safe(index, banned)
        }
        Expr::Call { callee, args, .. } | Expr::New { callee, args, .. } => {
            default_expr_safe(callee, banned)
                && args.iter().all(|a| match a {
                    ArrayElem::Item(x) | ArrayElem::Spread(x) => default_expr_safe(x, banned),
                    ArrayElem::Hole => true,
                })
        }
        Expr::Array(elems) => elems.iter().all(|a| match a {
            ArrayElem::Item(x) | ArrayElem::Spread(x) => default_expr_safe(x, banned),
            ArrayElem::Hole => true,
        }),
        Expr::Object(props) => props.iter().all(|p| match p {
            PropDef::KeyValue { key, value } => {
                !matches!(key, PropKey::Computed(_)) && default_expr_safe(value, banned)
            }
            _ => false,
        }),
        _ => false,
    }
}

/// Whether `e` provably cannot reassign the local `name` (for fused element ops, which defer the
/// base-slot read past this expression's evaluation). Whitelist recursion: any variant not
/// explicitly handled answers `false` (don't fuse). Calls and nested functions are safe — a slot
/// local is unobservable outside its function (that is what makes slot storage sound), so only a
/// syntactic assignment/update in this very expression could touch it.
fn no_assign_to(e: &Expr, name: &str) -> bool {
    if crate::interpreter::ast_stack_low() {
        return crate::interpreter::with_ast_stack(|| no_assign_to(e, name));
    }
    match e {
        Expr::Num(_)
        | Expr::BigInt(_)
        | Expr::Str(_)
        | Expr::Bool(_)
        | Expr::Null
        | Expr::Undefined
        | Expr::Ident(_, _)
        | Expr::This
        | Expr::Regex { .. }
        | Expr::Func(_) => true,
        Expr::Paren(x) | Expr::ToStr(x) | Expr::Unary { arg: x, .. } => no_assign_to(x, name),
        Expr::Update { arg, .. } => match &**arg {
            Expr::Ident(n, _) => n != name,
            Expr::Member { obj, .. } => no_assign_to(obj, name),
            Expr::Index { obj, index, .. } => no_assign_to(obj, name) && no_assign_to(index, name),
            _ => false,
        },
        Expr::Assign { target, value, .. } => {
            let target_ok = match &**target {
                Expr::Ident(n, _) => n != name,
                Expr::Member { obj, .. } => no_assign_to(obj, name),
                Expr::Index { obj, index, .. } => {
                    no_assign_to(obj, name) && no_assign_to(index, name)
                }
                _ => false, // destructuring pattern — could bind `name`
            };
            target_ok && no_assign_to(value, name)
        }
        Expr::Binary { left, right, .. } | Expr::Logical { left, right, .. } => {
            no_assign_to(left, name) && no_assign_to(right, name)
        }
        Expr::Cond { test, cons, alt } => {
            no_assign_to(test, name) && no_assign_to(cons, name) && no_assign_to(alt, name)
        }
        Expr::Member { obj, .. } => no_assign_to(obj, name),
        Expr::Index { obj, index, .. } => no_assign_to(obj, name) && no_assign_to(index, name),
        Expr::Call { callee, args, .. } | Expr::New { callee, args, .. } => {
            no_assign_to(callee, name)
                && args.iter().all(|a| match a {
                    ArrayElem::Item(e) | ArrayElem::Spread(e) => no_assign_to(e, name),
                    ArrayElem::Hole => true,
                })
        }
        Expr::Array(elems) => elems.iter().all(|a| match a {
            ArrayElem::Item(e) | ArrayElem::Spread(e) => no_assign_to(e, name),
            ArrayElem::Hole => true,
        }),
        _ => false,
    }
}

impl Compiler {
    fn record_function_osr(&mut self, site: &LoopSite, pc: usize) {
        self.record_function_osr_address(site as *const _ as usize, pc);
    }

    fn record_function_osr_address(&mut self, site: usize, pc: usize) {
        // The enclosing AST frame is parked at a body-level loop, with no active cleanup or
        // runtime lexical cursor to reconstruct. Captured function homes can reuse the exact
        // parked Function Environment Record; mapped arguments retain the prepared entry.
        if self.inline_depth != 0
            || self.try_depth as usize != self.function_osr_environment_handlers.len()
            || self.env_arguments
            || self.arguments_slot.is_some()
            || !self.function_osr_sites.contains(&site)
        {
            return;
        }
        let mut bindings = Vec::new();
        let mut shadow_counts = crate::fasthash::FastMap::<&str, u16>::default();
        for (scope, environment) in self.scopes.iter().zip(&self.lexical_env_names).rev() {
            let mut seen = crate::fasthash::FastSet::default();
            for (name, slot, _) in scope.iter().rev() {
                if seen.insert(name.as_str()) {
                    let depth = shadow_counts.entry(name.as_str()).or_default();
                    bindings.push((Rc::from(name.as_str()), *slot, *depth));
                    *depth += 1;
                }
            }
            for name in environment.keys() {
                if seen.insert(name.as_str()) {
                    *shadow_counts.entry(name.as_str()).or_default() += 1;
                }
            }
        }
        self.function_osr_entries.push(FunctionOsrEntry {
            site,
            pc,
            bindings,
            environment_handlers: self.function_osr_environment_handlers.clone(),
        });
    }

    fn emit(&mut self, op: Op) -> usize {
        let op = match self.inline_env_targets.last() {
            Some(&target) => self.inline_env_op(op, target),
            None => op,
        };
        self.positions.record(self.ops.len(), self.position.0);
        self.ops.push(op);
        self.ops.len() - 1
    }

    /// Compile with the operations attributed to the AST node at source `position`, as the
    /// tree-walker attributes an error raised while it evaluates that node. A spliced callee's
    /// positions index its own source, so they are recorded as inline positions that also name
    /// the callee and the splice's position in its caller (see [`Compiler::inline_position`]).
    fn at_position<T>(&mut self, position: u32, compile: impl FnOnce(&mut Self) -> T) -> T {
        if position == NO_POSITION {
            return compile(self);
        }
        let position = match self.inline_frames.last() {
            Some(&(target, outer)) => self.inline_position(target, position, outer),
            None => position,
        };
        let saved = std::mem::replace(&mut self.position.0, position);
        let result = compile(self);
        self.position.0 = saved;
        result
    }
    /// The local inline position of an operation at byte `inner` of the callee spliced through
    /// inline target `target`, whose splice sits at `outer` in its caller.
    fn inline_position(&mut self, target: u32, inner: u32, outer: u32) -> u32 {
        let key = (target, inner, outer);
        let index = match self.inline_site_index.get(&key) {
            Some(&index) => index,
            None => {
                let index = self.inline_sites.len() as u32;
                self.inline_sites.push(key);
                self.inline_site_index.insert(key, index);
                index
            }
        };
        crate::stack_trace::inline_position(index)
    }

    /// Inside a splice, the callee's free-name reads resolve from its own [[Environment]], not
    /// the caller's running one. Anything else that observes the running environment has no
    /// remapping and makes the splice bail.
    fn inline_env_op(&mut self, op: Op, target: u32) -> Op {
        match op {
            Op::LoadName(name, cache) => Op::LoadNameIn(name, cache, target),
            Op::LoadNameForCall(name, cache) => Op::LoadNameForCallIn(name, cache, target),
            Op::InlineGuard(..) => op,
            _ => {
                if inline_capability(&op) == InlineCapability::RequiresCallContext
                    || matches!(op, Op::TypeofName(_))
                {
                    self.inline_env_violation = true;
                }
                op
            }
        }
    }
    /// Reserve a fresh inline-cache slot (starts empty) for a property-access op.
    fn new_cache(&mut self, name: u32) -> u32 {
        // PROP_IC_WAYS consecutive ways per site: consumers address way 1; probes reach the
        // others at `cache_ptr + k` (see `Interp::ic_way`). Keeps every existing call site
        // untouched.
        let idx = self.caches.len() as u32;
        let seed = self
            .cache_seed_stack
            .last_mut()
            .and_then(|(sites, cursor)| {
                let site = sites.get(*cursor);
                *cursor += 1;
                site.filter(|(hot_name, _)| hot_name.as_ref() == self.names[name as usize].as_ref())
                    .map(|(_, states)| *states)
            });
        for way in 0..PROP_IC_WAYS {
            self.caches.push(std::cell::Cell::new(
                seed.map(|states| states[way]).unwrap_or(IcState::EMPTY),
            ));
        }
        idx
    }
    /// Reserve one cache cell for an op whose generated template has a single stable shape.
    /// Unlike property sites, `instanceof` does not need four polymorphic ways; keeping this
    /// separate avoids paying 96 bytes per source occurrence.
    fn new_single_cache(&mut self) -> u32 {
        let idx = self.caches.len() as u32;
        self.caches.push(std::cell::Cell::new(IcState::EMPTY));
        idx
    }
    /// Reserve a fresh name-cache slot for a free-name op.
    fn new_name_cache(&mut self, name: u32) -> u32 {
        let seed = self.name_seed_stack.last_mut().and_then(|(sites, cursor)| {
            let site = sites.get(*cursor);
            *cursor += 1;
            site.filter(|(hot_name, ..)| hot_name.as_ref() == self.names[name as usize].as_ref())
                .cloned()
        });
        let (ic, pin, number) = match seed {
            Some((_, ic, pin, number)) => (ic, pin, number),
            None => (NameIc::EMPTY, None, None),
        };
        self.name_caches.push(std::cell::Cell::new(ic));
        self.name_pins.push(pin);
        self.name_num_bits
            .push(std::cell::Cell::new(number.unwrap_or(0)));
        self.name_num_valid
            .push(std::cell::Cell::new(number.is_some()));
        (self.name_caches.len() - 1) as u32
    }
    fn emit_store_name(&mut self, name: u32) {
        let cache = self.new_name_cache(name);
        self.emit(Op::StoreNameCached(name, cache));
    }

    /// ECMA-262 §13.15.2 evaluates a statically-resolved immutable identifier like every other
    /// Reference: simple assignment evaluates the RHS before PutValue, while compound assignment
    /// first performs GetValue and the binary operation. The final store distinguishes a slot TDZ
    /// from an initialized immutable binding instead of folding both failures into a TypeError.
    fn immutable_assignment(&mut self, home: Home, name: &str, op: &str, value: &Expr) -> CResult {
        let name_index = self.name_idx(name);
        if op == "=" {
            self.named_expr(value, name)?;
        } else {
            match home {
                Home::Slot(slot, true) => self.emit(Op::LoadLocal(slot)),
                Home::Env(true) => self.emit(Op::LoadCap(name_index)),
                _ => unreachable!("immutable assignment requires an immutable home"),
            };
            self.expr(value)?;
            self.emit_compound(op)?;
        }
        match home {
            Home::Slot(slot, true) => self.emit(Op::StoreConstLocal(slot, name_index)),
            Home::Env(true) => self.emit(Op::StoreConstCap(name_index)),
            _ => unreachable!("immutable assignment requires an immutable home"),
        };
        Ok(())
    }
    /// Reserve a fresh call-cache slot for a `Call`/`CallWithThis` site.
    fn new_call_cache(&mut self) -> u32 {
        // Every frame counts its own call-site ordinals (see `Compiler::plan_stack`).
        if let Some(top) = self.plan_stack.last_mut() {
            top.1 += 1;
        }
        let seed = self.call_seed_stack.last_mut().and_then(|(sites, cursor)| {
            let seed = sites.get(*cursor);
            *cursor += 1;
            seed.map(|seed| {
                (
                    seed.entries,
                    seed.func_pins.clone(),
                    seed.next,
                    seed.pins.clone(),
                )
            })
        });
        let site = if let Some((entries, func_pins, next, pins)) = seed {
            for (callee, pin) in pins {
                self.call_pins.entry(callee).or_insert(pin);
            }
            CallSite {
                entries: std::array::from_fn(|way| std::cell::Cell::new(entries[way])),
                func_pins: std::cell::RefCell::new(func_pins),
                next: std::cell::Cell::new(next),
            }
        } else {
            CallSite::empty()
        };
        self.call_caches.push(site);
        (self.call_caches.len() - 1) as u32
    }
    /// Reserve a [`PrivateSite`] for one private-name operation.
    fn new_private_site(&mut self) -> u32 {
        self.private_sites += 1;
        self.private_sites - 1
    }
    fn new_construct_cache(&mut self) -> u32 {
        let cache = self.construct_caches.len() as u32;
        self.construct_caches
            .push(std::cell::Cell::new(ConstructSite::EMPTY));
        cache
    }

    /// The current frame's plan entry for the NEXT call site (call before `new_call_cache`).
    fn plan_hit(&self) -> Option<InlinePlanEntry> {
        let (plan, ord) = self.plan_stack.last()?;
        plan.get(ord).cloned()
    }

    /// Emit a planned speculative inline for a method call site whose stack already holds
    /// `[this, method, args...]`; anything the splice can't express reverts to the plain call.
    fn emit_call_with_inline(
        &mut self,
        entry: InlinePlanEntry,
        argc: u16,
        cc: u32,
        has_this: bool,
    ) {
        let snap = (
            self.ops.len(),
            self.consts.len(),
            self.names.len(),
            self.caches.len(),
            self.name_caches.len(),
            self.call_caches.len(),
            self.inline_targets.len(),
            self.slot_names.len(),
            self.funcs.len(),
            self.templates.len(),
            self.eval_exprs.len(),
            self.class_plans.len(),
            self.assignment_targets.len(),
            self.private_sites,
            self.inline_sites.len(),
        );
        if self.try_emit_inline(&entry, argc, cc, has_this).is_err() {
            let sites = snap.14;
            self.inline_sites.truncate(sites);
            self.inline_site_index
                .retain(|_, index| (*index as usize) < sites);
            self.ops.truncate(snap.0);
            self.call_names.truncate(snap.0);
            self.positions.truncate(snap.0);
            self.consts.truncate(snap.1);
            self.truncate_names(snap.2);
            self.caches.truncate(snap.3);
            self.name_caches.truncate(snap.4);
            self.name_pins.truncate(snap.4);
            self.name_num_bits.truncate(snap.4);
            self.name_num_valid.truncate(snap.4);
            self.call_caches.truncate(snap.5);
            self.inline_targets.truncate(snap.6);
            self.slot_names.truncate(snap.7);
            self.tdz_slots.retain(|&slot| usize::from(slot) < snap.7);
            self.funcs.truncate(snap.8);
            self.templates.truncate(snap.9);
            self.eval_exprs.truncate(snap.10);
            self.class_plans.truncate(snap.11);
            self.assignment_targets.truncate(snap.12);
            self.private_sites = snap.13;
            if has_this {
                self.emit(Op::CallWithThis(argc, cc));
            } else {
                self.emit(Op::Call(argc, cc));
            }
        }
    }

    fn try_emit_inline(
        &mut self,
        entry: &InlinePlanEntry,
        argc: u16,
        cc: u32,
        has_this: bool,
    ) -> CResult {
        if argc > 8 {
            return Err(Bail); // the JIT guard peeks the callee with a ±256-byte unscaled load
        }
        // Per-way gates: a plain `Call` site has no `this` beneath the callee (a this-using
        // callee needs the generic binding, and the guard's receiver peek would read past the
        // operands); a caller binding (slot or captured) would shadow a global free name.
        // A spliced body's free names resolve from the callee's own [[Environment]]
        // (`Op::LoadNameIn`), so caller bindings of the same spelling never shadow them.
        let ways: Vec<&InlineWay> = entry
            .ways
            .iter()
            .filter(|w| has_this || !w.uses_this)
            .collect();
        if ways.is_empty() {
            return Err(Bail);
        }
        // Each way: identity guard → bind → spliced body → jump to the shared join; a guard
        // mismatch falls to the next way, the last one to the generic call.
        let mut end_jumps: Vec<usize> = Vec::new();
        let mut pending_guard: Option<usize> = None;
        let outer_violation = std::mem::replace(&mut self.inline_env_violation, false);
        for w in &ways {
            if let Some(g) = pending_guard.take() {
                self.patch(g); // previous way's mismatch lands on this way's guard
            }
            let guard = self.emit_inline_way(w, argc, has_this, &mut end_jumps);
            let guard = match guard {
                Ok(guard) if !self.inline_env_violation => guard,
                _ => {
                    self.inline_env_violation = outer_violation;
                    return Err(Bail);
                }
            };
            pending_guard = Some(guard);
        }
        self.inline_env_violation = outer_violation;
        // ---- join: every way's result jumps here; the last mismatch runs the generic call.
        self.patch(pending_guard.take().expect("at least one way"));
        if has_this {
            self.emit(Op::CallWithThis(argc, cc));
        } else {
            self.emit(Op::Call(argc, cc));
        }
        for j in end_jumps {
            self.patch(j);
        }
        Ok(())
    }

    /// One guarded splice: emits the identity guard (returned unpatched — the caller chains it
    /// to the next way or the generic call), the frame binds, and the body; the result-carrying
    /// exits are appended to `end_jumps`.
    fn emit_inline_way(
        &mut self,
        w: &InlineWay,
        argc: u16,
        has_this: bool,
        end_jumps: &mut Vec<usize>,
    ) -> Result<usize, Bail> {
        let f = &w.f;
        let t = self.inline_targets.len() as u32;
        self.inline_targets.push(InlineTarget {
            expected: crate::value::Gc::as_ptr(&w.obj) as usize,
            pin: crate::value::Gc::downgrade(&w.obj),
            expected_env: w.expected_env,
            expected_genv: w.expected_genv,
            genv_pin: w.genv_pin.clone(),
            argc,
            check_this: has_this && w.check_this,
        });
        let guard = self.emit(Op::InlineGuard(t, 0));

        // ---- bind the callee frame into fresh caller slots ----
        let n_params = f.params.len();
        for _ in n_params..argc as usize {
            self.emit(Op::Pop); // surplus arguments (evaluated; excess drops from the top)
        }
        for _ in argc as usize..n_params {
            self.emit(Op::Undef); // missing arguments
        }
        let mut param_slots: Vec<u16> = Vec::with_capacity(n_params);
        for p in &f.params {
            let Pattern::Ident(name) = &p.pattern else {
                return Err(Bail);
            };
            if p.default.is_some() || p.rest {
                return Err(Bail);
            }
            param_slots.push(self.fresh_slot(name));
        }
        for &s in param_slots.iter().rev() {
            self.emit(Op::StoreLocal(s));
        }
        // The method (identity proven) stays owned by a hidden slot until the way's exit: its
        // [[Environment]], which the body's `LoadNameIn` reads, lives exactly as long as the
        // function, and the body may drop every other reference to it (`holder.f = null`).
        let callee_slot = self.fresh_slot("(inline callee)");
        self.emit(Op::StoreLocal(callee_slot));
        let this_slot = if !has_this {
            None // a plain Call site: nothing beneath the callee
        } else if w.uses_this {
            let s = self.fresh_slot("(inline this)");
            self.emit(Op::StoreLocal(s));
            Some(s)
        } else {
            self.emit(Op::Pop);
            None
        };

        // ---- compile the body under the callee's (empty) namespace ----
        let saved_scopes = std::mem::take(&mut self.scopes);
        let saved_lexical_env_names = std::mem::take(&mut self.lexical_env_names);
        let saved_env_names = std::mem::take(&mut self.env_names);
        let saved_loops = std::mem::take(&mut self.loops);
        let saved_labels = std::mem::take(&mut self.pending_labels);
        let saved_try = std::mem::replace(&mut self.try_depth, 0);
        let saved_this = std::mem::replace(&mut self.inline_this, this_slot);
        let saved_returns = std::mem::take(&mut self.inline_returns);
        // The caller's own capture analysis must neither shadow nor be consumed by the callee's
        // declarations: a callee `let n` would otherwise take the caller's pending homed block
        // `let n` as its own declaration, and a failed splice cannot give it back. The callee
        // needs no activation, so its bindings are all fresh slots. Its body has no `with`.
        let saved_homed_lets = std::mem::take(&mut self.homed_lets);
        let saved_homed_pending = std::mem::take(&mut self.homed_pending);
        let saved_runtime_lexicals = std::mem::take(&mut self.runtime_lexicals);
        let saved_with_floors = std::mem::take(&mut self.with_scope_floors);
        // The body compiles as its own function would: a self-hosted callee's intrinsics are
        // operations, never free names of the caller (the plan found none in its chunk).
        let saved_self_hosted = std::mem::replace(&mut self.self_hosted, f.self_hosted);
        self.inline_depth += 1;
        self.plan_stack.push((w.nested.clone(), 0));
        let hot_chunk = f.code.get().and_then(Option::as_ref);
        self.cache_seed_stack.push((
            hot_chunk
                .map(|chunk| property_cache_seeds(chunk))
                .unwrap_or_default(),
            0,
        ));
        self.name_seed_stack.push((
            hot_chunk
                .map(|chunk| name_cache_seeds(chunk))
                .unwrap_or_default(),
            0,
        ));
        self.call_seed_stack.push((
            hot_chunk
                .map(|chunk| call_cache_seeds(chunk))
                .unwrap_or_default(),
            0,
        ));
        self.push_compile_scope();
        for (k, p) in f.params.iter().enumerate() {
            let Pattern::Ident(name) = &p.pattern else {
                unreachable!()
            };
            self.scope_bind(name, param_slots[k], false);
        }
        self.inline_env_targets.push(t);
        // The body's operations report the callee's frame: at their own nodes, or at the
        // callee's start for operations outside every positioned node.
        let outer = self.position.0;
        let body_position = self.inline_position(t, NO_POSITION, outer);
        self.inline_frames.push((t, outer));
        let saved_position = std::mem::replace(&mut self.position.0, body_position);
        let r = self.inline_body(f);
        self.position.0 = saved_position;
        self.inline_frames.pop();
        self.inline_env_targets.pop();
        self.call_seed_stack.pop();
        self.name_seed_stack.pop();
        self.cache_seed_stack.pop();
        self.plan_stack.pop();
        self.inline_depth -= 1;
        self.self_hosted = saved_self_hosted;
        let returns = std::mem::replace(&mut self.inline_returns, saved_returns);
        self.with_scope_floors = saved_with_floors;
        self.runtime_lexicals = saved_runtime_lexicals;
        self.homed_pending = saved_homed_pending;
        self.homed_lets = saved_homed_lets;
        self.inline_this = saved_this;
        self.try_depth = saved_try;
        self.pending_labels = saved_labels;
        self.loops = saved_loops;
        self.env_names = saved_env_names;
        self.lexical_env_names = saved_lexical_env_names;
        self.scopes = saved_scopes;
        r?;

        // Every completion of the body (its end and each `return`) releases the callee here.
        for j in returns {
            self.patch(j);
        }
        self.emit(Op::ResetSlots(callee_slot, 1));
        end_jumps.push(self.emit(Op::Jump(0)));
        Ok(guard)
    }

    /// Compile a spliced callee body: mirrors `compile_inner`'s hoist + lexical + statement
    /// sequence, with explicit per-execution resets replacing the fresh frame's zeroed slots.
    fn inline_body(&mut self, f: &Function) -> CResult {
        // Hoisted vars start undefined on EVERY pass through the site; fused-reset runs are
        // emitted per contiguous slot range (fresh slots are consecutive, so usually one op).
        let mut resets: Vec<u16> = Vec::new();
        for op in crate::interpreter::collect_hoist_ops(&f.body, f.is_strict, &[]) {
            match op {
                HoistOp::Var(name) => {
                    if self.lookup(&name).is_none() {
                        let slot = self.fresh_slot(&name);
                        self.scope_bind(&name, slot, false);
                        resets.push(slot);
                    }
                }
                HoistOp::Fn(..) | HoistOp::AnnexB(..) => return Err(Bail),
            }
        }
        resets.sort_unstable();
        let mut k = 0;
        while k < resets.len() {
            let start = resets[k];
            let mut count = 1u16;
            while k + (count as usize) < resets.len() && resets[k + count as usize] == start + count
            {
                count += 1;
            }
            self.emit(Op::ResetSlots(start, count));
            k += count as usize;
        }
        let empty = crate::fasthash::FastSet::default();
        self.declare_body_lexicals(&f.body, &empty)?;
        for stmt in function_body_statements(&f.body) {
            self.stmt(stmt)?;
        }
        self.emit(Op::Undef); // implicit return value
        Ok(())
    }
    /// Declare every binding a lexical declaration pattern introduces, in source order (slot +
    /// TDZ each, like the plain-identifier path). Defaults and computed keys are evaluations, not
    /// declarations; rest and nested patterns contribute their BoundNames recursively.
    fn declare_lexical_pattern(&mut self, pat: &Pattern, is_const: bool) -> CResult {
        match pat {
            Pattern::Ident(name) => {
                if self.current_lexical_env_has(name) {
                    return Ok(());
                }
                if self.homed_pending.remove(name) {
                    // The homed block `let`'s own declaration (see `Compiler::homed_lets`):
                    // in TDZ since entry, no slot, no per-entry Tdz (the block runs at most
                    // once per call by construction). Consumed so any LATER same-name
                    // declaration (a nested for-of head, a sibling block) slot-shadows.
                    return Ok(());
                }
                let slot = self.fresh_slot(name);
                self.scope_bind(name, slot, is_const);
                self.tdz_slots.insert(slot);
                self.emit(Op::Tdz(slot));
                Ok(())
            }
            Pattern::Object(o) => {
                for prop in &o.props {
                    self.declare_lexical_pattern(&prop.value, is_const)?;
                }
                if let Some(rest) = &o.rest {
                    self.declare_lexical_pattern(&Pattern::Ident(rest.clone()), is_const)?;
                }
                Ok(())
            }
            Pattern::Array(elems) => {
                for e in elems {
                    match e {
                        ArrayPatElem::Hole => {}
                        ArrayPatElem::Elem { pattern, .. } | ArrayPatElem::Rest(pattern) => {
                            self.declare_lexical_pattern(pattern, is_const)?
                        }
                    }
                }
                Ok(())
            }
            _ => Err(Bail),
        }
    }

    /// Lower a declaration destructuring against the value on the stack (consumed): the
    /// KeyedBindingInitialization subset with plain (non-computed) keys, no defaults, no rest —
    /// per property: Dup + GetProp (the oracle's GetV), recursing into nested object patterns.
    /// The nullish guard throws the oracle's exact TypeError before any read.
    fn destructure_store(&mut self, pat: &Pattern, kind: DeclKind) -> CResult {
        match pat {
            Pattern::Ident(name) => {
                if self.dynamic_declaration_binding(name, kind) {
                    let name = self.name_idx(name);
                    self.emit(if matches!(kind, DeclKind::Var) {
                        Op::StoreName(name)
                    } else {
                        Op::InitLex(name)
                    });
                    return Ok(());
                }
                let home = self.home(name).ok_or(Bail)?;
                match home {
                    Home::Slot(slot, _) => {
                        self.emit(Op::StoreLocal(slot));
                    }
                    Home::Env(_) => {
                        let n = self.name_idx(name);
                        if matches!(kind, DeclKind::Var) {
                            self.emit(Op::StoreCap(n));
                        } else {
                            self.emit(Op::StoreCapInit(n));
                        }
                    }
                }
                Ok(())
            }
            Pattern::Object(o) => {
                if o.rest.is_some()
                    || o.props.iter().any(|prop| {
                        prop.default.is_some()
                            || !matches!(&prop.key, PropKey::Ident(_) | PropKey::Str(_))
                    })
                {
                    return self.binding_object_pattern(o, kind);
                }
                self.emit(Op::DestructureGuard);
                for prop in &o.props {
                    if prop.default.is_some() {
                        return Err(Bail);
                    }
                    let key: String = match &prop.key {
                        PropKey::Ident(k) => k.clone(),
                        PropKey::Str(k) => k.to_string(),
                        _ => return Err(Bail),
                    };
                    let ki = self.property_name_idx(&key);
                    let reference = self.prepare_binding_reference(&prop.value, kind)?;
                    self.emit(Op::Dup);
                    let c = self.new_cache(ki);
                    self.emit(Op::GetProp(ki, c));
                    self.finish_binding_reference(reference, &prop.value, kind)?;
                }
                self.emit(Op::Pop);
                Ok(())
            }
            Pattern::Array(elems) => {
                // Batched iterator walk (Op::DestructureArr), then stores in reverse. Batching
                // is only order-unobservable when every leaf is an UNCAPTURED slot (an env-homed
                // leaf's initialization is visible to a later iterator step's next() per spec)
                // and elements are flat idents/holes (a nested pattern's own reads would
                // interleave with the steps), with no defaults (their evaluation interleaves).
                let batched = elems.iter().all(|e| {
                    match e {
                        ArrayPatElem::Hole => {}
                        ArrayPatElem::Elem {
                            pattern: Pattern::Ident(n),
                            default: None,
                        } if matches!(self.home(n), Some(Home::Slot(..))) => {}
                        _ => return false,
                    }
                    true
                });
                if !batched {
                    return self.binding_array_pattern(elems, kind);
                }
                self.emit(Op::DestructureArr(elems.len() as u16));
                for e in elems.iter().rev() {
                    match e {
                        ArrayPatElem::Hole => {
                            self.emit(Op::Pop);
                        }
                        ArrayPatElem::Elem { pattern, .. } => {
                            self.destructure_store(pattern, kind)?;
                        }
                        ArrayPatElem::Rest(_) => unreachable!("filtered above"),
                    }
                }
                Ok(())
            }
            _ => Err(Bail),
        }
    }

    /// ECMA-262 IteratorBindingInitialization / KeyedBindingInitialization: a var-mode
    /// SingleNameBinding resolves its Reference before IteratorStepValue/GetV and the
    /// initializer. A nested BindingPattern instead resolves its leaves when entered.
    /// Lexical initialization uses the already-instantiated declarative binding; local
    /// and captured var homes keep their allocation-free stores when statically proven.
    fn prepare_binding_reference(
        &mut self,
        pattern: &Pattern,
        kind: DeclKind,
    ) -> Result<Option<PreparedAssignmentRef>, Bail> {
        if let (DeclKind::Var, Pattern::Ident(name)) = (kind, pattern) {
            return self.prepare_identifier_reference(name).map(Some);
        }
        Ok(None)
    }

    fn finish_binding_reference(
        &mut self,
        reference: Option<PreparedAssignmentRef>,
        pattern: &Pattern,
        kind: DeclKind,
    ) -> CResult {
        if let Some(reference) = reference {
            self.put_assignment_reference(reference);
            Ok(())
        } else {
            self.destructure_store(pattern, kind)
        }
    }

    fn binding_default(&mut self, pattern: &Pattern, default: Option<&Expr>) -> CResult {
        let Some(default) = default else {
            return Ok(());
        };
        self.emit(Op::Dup);
        self.emit(Op::Undef);
        self.emit(Op::StrictEq);
        let present = self.emit(Op::JumpIfFalse(0));
        self.emit(Op::Pop);
        if let Pattern::Ident(name) = pattern {
            self.named_expr(default, name)?;
        } else {
            self.expr(default)?;
        }
        self.patch(present);
        Ok(())
    }

    fn binding_array_pattern(&mut self, elements: &[ArrayPatElem], kind: DeclKind) -> CResult {
        let iterator = self.fresh_slot("%binding-iterator%");
        let next = self.fresh_slot("%binding-next%");
        let done = self.fresh_slot("%binding-done%");
        let closed_prefix = matches!(kind, DeclKind::Let | DeclKind::Const)
            && elements.len() <= 8
            && elements.iter().all(|element| {
                matches!(
                    element,
                    ArrayPatElem::Hole
                        | ArrayPatElem::Elem {
                            pattern: Pattern::Ident(_),
                            default: None,
                        }
                )
            });
        let fast_exit = if closed_prefix {
            self.emit(Op::TryArrayBinding(iterator, next, elements.len() as u16));
            let slow = self.emit(Op::JumpIfFalse(0));
            self.emit(Op::Pop);
            for (index, element) in elements.iter().enumerate() {
                self.emit(Op::ArrayBindingStep(iterator, next, index as u16));
                match element {
                    ArrayPatElem::Hole => {
                        self.emit(Op::Pop);
                    }
                    ArrayPatElem::Elem { pattern, .. } => {
                        self.destructure_store(pattern, kind)?;
                    }
                    _ => unreachable!("closed binding prefix"),
                }
            }
            let exit = self.emit(Op::Jump(0));
            self.patch(slow);
            Some(exit)
        } else {
            None
        };
        self.emit(Op::GetIter);
        self.emit(Op::StoreLocal(next));
        self.emit(Op::StoreLocal(iterator));
        let false_value = self.const_idx(Value::Bool(false));
        self.emit(Op::Const(false_value));
        self.emit(Op::StoreLocal(done));

        let handler = self.emit(Op::PushIterator(0, 0, 0, 0));
        self.try_depth += 1;
        for element in elements {
            match element {
                ArrayPatElem::Hole => {
                    self.emit(Op::DestructureStepL(iterator, next, done));
                    self.emit(Op::Pop);
                }
                ArrayPatElem::Elem { pattern, default } => {
                    let reference = self.prepare_binding_reference(pattern, kind)?;
                    self.emit(Op::DestructureStepL(iterator, next, done));
                    self.binding_default(pattern, default.as_ref())?;
                    self.finish_binding_reference(reference, pattern, kind)?;
                }
                ArrayPatElem::Rest(pattern) => {
                    let reference = self.prepare_binding_reference(pattern, kind)?;
                    self.emit(Op::DestructureRestL(iterator, next, done));
                    self.finish_binding_reference(reference, pattern, kind)?;
                }
            }
        }
        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        let after_pads = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::IterAbortIfNotDoneL(iterator, done));
        let return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::Return);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::ReturnBare);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::ResumeReturn);
        match &mut self.ops[handler] {
            Op::PushIterator(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
            }
            _ => unreachable!(),
        }
        self.patch(after_pads);
        if let Some(exit) = fast_exit {
            self.patch(exit);
        }
        Ok(())
    }

    fn binding_object_pattern(
        &mut self,
        object: &crate::ast::ObjectPat,
        kind: DeclKind,
    ) -> CResult {
        self.emit(Op::DestructureGuard);
        let source = self.fresh_slot("%binding-object%");
        self.emit(Op::StoreLocal(source));
        let mut excluded = Vec::new();
        for property in &object.props {
            let key = self.assignment_object_key(source, &property.key)?;
            excluded.push(key);
            let reference = self.prepare_binding_reference(&property.value, kind)?;
            self.load_assignment_property(source, key);
            self.binding_default(&property.value, property.default.as_ref())?;
            self.finish_binding_reference(reference, &property.value, kind)?;
        }
        if let Some(rest) = &object.rest {
            let pattern = Pattern::Ident(rest.clone());
            let reference = self.prepare_binding_reference(&pattern, kind)?;
            self.emit(Op::LoadLocal(source));
            for key in &excluded {
                self.emit(Op::LoadLocal(*key));
            }
            self.emit(Op::ObjectRest(excluded.len() as u16));
            self.finish_binding_reference(reference, &pattern, kind)?;
        }
        Ok(())
    }

    /// Emit ArgumentListEvaluation from ECMA-262 §13.3.8.1. Plain calls retain their compact
    /// fixed-arity op and one final spread retains the allocation-free expansion path. Multiple
    /// or interleaved spreads build a private dense list incrementally, so each iterator is fully
    /// consumed before the following argument expression is evaluated.
    fn call_args(&mut self, args: &[ArrayElem]) -> Result<CallArgsMode, Bail> {
        let spreads: Vec<usize> = args
            .iter()
            .enumerate()
            .filter_map(|(index, arg)| matches!(arg, ArrayElem::Spread(_)).then_some(index))
            .collect();
        if args.iter().any(|arg| matches!(arg, ArrayElem::Hole)) {
            return Err(Bail);
        }
        if spreads.is_empty() {
            for arg in args {
                let ArrayElem::Item(expr) = arg else {
                    unreachable!("argument shape checked above")
                };
                self.expr(expr)?;
            }
            return Ok(CallArgsMode::Fixed(
                u16::try_from(args.len()).map_err(|_| Bail)?,
            ));
        }
        if spreads.as_slice() == [args.len() - 1] {
            for arg in args {
                match arg {
                    ArrayElem::Item(expr) | ArrayElem::Spread(expr) => self.expr(expr)?,
                    ArrayElem::Hole => unreachable!("argument shape checked above"),
                }
            }
            return Ok(CallArgsMode::FinalSpread(
                u16::try_from(args.len()).map_err(|_| Bail)?,
            ));
        }

        self.emit(Op::NewArray);
        for arg in args {
            match arg {
                ArrayElem::Item(expr) => {
                    self.expr(expr)?;
                    self.emit(Op::ArrayPush);
                }
                ArrayElem::Spread(expr) => {
                    self.expr(expr)?;
                    self.emit(Op::ArraySpread);
                }
                ArrayElem::Hole => unreachable!("argument shape checked above"),
            }
        }
        Ok(CallArgsMode::Array)
    }

    /// Compile a call of a self-hosted built-in's intrinsic (see `crate::self_hosted`) to the
    /// operation it names: `Call(F, V, ...args)` becomes the method-call sequence with V as the
    /// receiver, and every other intrinsic its [`AbstractOp`]. Only engine source compiles
    /// these, only while the name is free (it then resolves to the intrinsic's own binding,
    /// whose native form the tree-walking interpreter calls with identical semantics), and only
    /// with the intrinsic's exact arity and plain arguments; a message operand must be a string
    /// literal. Returns whether the call was compiled; any other shape is an ordinary call.
    fn self_hosted_intrinsic(&mut self, callee: &Expr, args: &[ArrayElem]) -> Result<bool, Bail> {
        if !self.self_hosted {
            return Ok(false);
        }
        let Expr::Ident(name, _) = callee else {
            return Ok(false);
        };
        if self.home(name).is_some() {
            return Ok(false);
        }
        let Some(items) = args
            .iter()
            .map(|argument| match argument {
                ArrayElem::Item(expr) => Some(expr),
                ArrayElem::Spread(_) | ArrayElem::Hole => None,
            })
            .collect::<Option<Vec<&Expr>>>()
        else {
            return Ok(false);
        };
        let message = |index: usize| match items.get(index) {
            Some(Expr::Str(text)) => Some(text.clone()),
            _ => None,
        };
        // (operation, value operands); a message operand is folded into the operation.
        let (op, operands) = match (name.as_str(), items.len()) {
            ("Call", argc) if argc >= 2 => {
                // The receiver sits beneath the callee, exactly as for `V.method(...args)`.
                self.expr(items[1])?;
                self.expr(items[0])?;
                self.finish_call(&args[2..], true, true)?;
                return Ok(true);
            }
            ("ToObject", 2) => {
                let Some(method) = message(1) else {
                    return Ok(false);
                };
                (AbstractOp::ToObject(self.name_idx(&method)), 1)
            }
            ("LengthOfArrayLike", 1) => (AbstractOp::LengthOfArrayLike, 1),
            ("IsCallable", 1) => (AbstractOp::IsCallable, 1),
            ("ArraySpeciesCreate", 2) => (AbstractOp::ArraySpeciesCreate, 2),
            ("CreateDataPropertyOrThrow", 3) => (AbstractOp::CreateDataPropertyOrThrow, 3),
            ("ThrowTypeError", 1) => {
                let Some(text) = message(0) else {
                    return Ok(false);
                };
                (AbstractOp::ThrowTypeError(self.name_idx(&text)), 0)
            }
            _ => return Ok(false),
        };
        for item in &items[..operands] {
            self.expr(item)?;
        }
        self.emit(Op::Abstract(op));
        Ok(true)
    }

    fn finish_call(&mut self, args: &[ArrayElem], with_this: bool, allow_inline: bool) -> CResult {
        // Taken before the arguments compile: their own calls record their own names.
        let name = self.pending_call_name.take();
        let tail = std::mem::take(&mut self.tail_finish) && ordinary_tail_call_depth() != 0;
        match self.call_args(args)? {
            CallArgsMode::Fixed(argc) => {
                // Other calls inside a tail expression stay plain calls, never splices; the
                // tail call itself is depth-selected below, so its ordinary form may splice.
                let plan_hit = (allow_inline && (tail || !self.lowering_tail))
                    .then(|| self.plan_hit())
                    .flatten();
                let cache = self.new_call_cache();
                // [operands] TailDeep; JumpIfFalse(ordinary); TailCall; Jump(join);
                // ordinary: <call or splice>; join: (see `Op::TailDeep`).
                let join = tail.then(|| {
                    self.emit(Op::TailDeep);
                    let shallow = self.emit(Op::JumpIfFalse(0));
                    let tail_call = self.emit(Op::TailCall(CallArgsMode::Fixed(argc), with_this));
                    self.name_call(tail_call, name.as_deref());
                    let join = self.emit(Op::Jump(0));
                    self.patch(shallow);
                    join
                });
                match plan_hit {
                    Some(entry) => {
                        self.emit_call_with_inline(entry, argc, cache, with_this);
                        // Every way's guard mismatch ends in this generic call, emitted last.
                        debug_assert!(matches!(
                            self.ops.last(),
                            Some(Op::Call(..) | Op::CallWithThis(..))
                        ));
                        self.name_call(self.ops.len() - 1, name.as_deref());
                    }
                    None if with_this => {
                        let call = self.emit(Op::CallWithThis(argc, cache));
                        self.name_call(call, name.as_deref());
                    }
                    None => {
                        let call = self.emit(Op::Call(argc, cache));
                        self.name_call(call, name.as_deref());
                    }
                }
                if let Some(join) = join {
                    self.patch(join);
                    self.tail_lowered = true;
                }
            }
            CallArgsMode::FinalSpread(argc) => {
                let call = self.emit(if with_this {
                    Op::CallSpreadThis(argc)
                } else {
                    Op::CallSpread(argc)
                });
                self.name_call(call, name.as_deref());
            }
            CallArgsMode::Array => {
                let call = self.emit(if with_this {
                    Op::CallArgsArrayThis
                } else {
                    Op::CallArgsArray
                });
                self.name_call(call, name.as_deref());
            }
        }
        Ok(())
    }

    /// Record the source name of the target of the call or `new` operation at `pc`.
    fn name_call(&mut self, pc: usize, name: Option<&str>) {
        if let Some(name) = name {
            self.call_names.record(pc, name);
        }
    }

    /// Evaluate a call's Reference, retaining its receiver alongside GetValue's result when
    /// needed. Grouping does not apply GetValue (ECMA-262 §13.2.9.3), including around an
    /// OptionalExpression. A grouped chain owns its short-circuit boundary: `(null?.m)(arg())`
    /// must evaluate arg before throwing, while `(null?.m)?.(arg())` skips it.
    fn callee_reference(&mut self, e: &Expr) -> Result<(bool, bool), Bail> {
        let mut shorts = Vec::new();
        let shape = self.call_reference(e, &mut shorts)?;
        if !shorts.is_empty() {
            let done = self.emit(Op::Jump(0));
            for short in shorts {
                self.patch(short);
            }
            if shape.0 {
                self.emit(Op::Undef); // a short-circuit is a value, not a property Reference
            }
            self.emit(Op::Undef);
            self.patch(done);
        }
        Ok(shape)
    }

    /// The open-chain form shares short-circuit exits with subsequent links. The returned
    /// booleans select [receiver, callee] versus [callee], and speculative inline eligibility.
    /// EvaluateCall (§13.3.6.2) also preserves WithBaseObject for Environment References;
    /// comma/conditional/call results instead pass through ordinary value evaluation.
    fn call_reference(&mut self, e: &Expr, shorts: &mut Vec<usize>) -> Result<(bool, bool), Bail> {
        match e {
            Expr::Paren(inner) => self.call_reference(inner, shorts),
            Expr::OptionalChain(inner) => self.callee_reference(inner),
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                self.emit(Op::SuperGetMethod);
                Ok((true, false))
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                self.emit(Op::SuperGetMethod);
                Ok((true, false))
            }
            Expr::Member {
                obj,
                prop,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.opt_chain(obj, shorts)?;
                if *optional {
                    self.opt_link(1, shorts);
                }
                let name = self.property_name_idx(prop);
                if prop.starts_with('#') {
                    let site = self.new_private_site();
                    self.emit(Op::GetPrivateMethod(name, site));
                    Ok((true, false))
                } else {
                    let cache = self.new_cache(name);
                    self.emit(Op::GetMethod(name, cache));
                    Ok((true, true))
                }
            }
            Expr::Index {
                obj,
                index,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.opt_chain(obj, shorts)?;
                if *optional {
                    self.opt_link(1, shorts);
                }
                self.expr(index)?;
                self.emit(Op::GetMethodElem);
                Ok((true, true))
            }
            Expr::Ident(name, _) if self.home(name).is_none() => {
                let name = self.name_idx(name);
                let cache = self.new_name_cache(name);
                self.emit(Op::LoadNameForCall(name, cache));
                Ok((true, true))
            }
            other => {
                self.opt_chain(other, shorts)?;
                Ok((false, true))
            }
        }
    }

    /// `delete obj.p` / `delete obj[k]` on plain (non-optional, non-super, public) references;
    /// a non-reference operand evaluates for its effects and deletes to `true`. Identifier
    /// deletes (env bindings) and optional chains stay in the oracle.
    fn delete_expr(&mut self, arg: &Expr) -> CResult {
        match arg {
            Expr::Paren(inner) => self.delete_expr(inner),
            Expr::OptionalChain(inner) => self.delete_optional_chain(inner),
            Expr::Ident(name, _) => {
                if self.home(name).is_some() {
                    // Function/lexical declarations represented by slots or activation bindings
                    // are never deletable. Only a free name needs the full environment/global
                    // DeleteBinding lookup.
                    let no = self.const_idx(Value::Bool(false));
                    self.emit(Op::Const(no));
                } else {
                    let name = self.name_idx(name);
                    self.emit(Op::DeleteName(name));
                }
                Ok(())
            }
            Expr::Member {
                obj,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                // Evaluation of `super.name` performs GetThisBinding before Delete observes that
                // this is a Super Reference and throws. It does not need GetSuperBase.
                self.emit_super_this();
                self.emit(Op::Pop);
                self.emit(Op::DeleteSuper);
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                // The computed expression evaluates, but Delete throws before ToPropertyKey.
                self.emit_super_this();
                self.emit(Op::Pop);
                self.expr(index)?;
                self.emit(Op::Pop);
                self.emit(Op::DeleteSuper);
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                let n = self.property_name_idx(prop);
                self.emit(Op::DeleteProp(n, self.strict));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.expr(obj)?;
                self.expr(index)?;
                self.emit(Op::DeleteElem(self.strict));
                Ok(())
            }
            other => {
                self.expr(other)?;
                self.emit(Op::Pop);
                let k = self.const_idx(Value::Bool(true));
                self.emit(Op::Const(k));
                Ok(())
            }
        }
    }

    /// OptionalChain evaluation for the delete operator. A short-circuited chain produces true,
    /// while a live final Member/Index remains a Reference and performs [[Delete]].
    fn delete_optional_chain(&mut self, inner: &Expr) -> CResult {
        let mut shorts = Vec::new();
        match inner {
            Expr::Member {
                obj,
                prop,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.opt_chain(obj, &mut shorts)?;
                if *optional {
                    self.opt_link(1, &mut shorts);
                }
                let name = self.property_name_idx(prop);
                self.emit(Op::DeleteProp(name, self.strict));
            }
            Expr::Index {
                obj,
                index,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.opt_chain(obj, &mut shorts)?;
                if *optional {
                    self.opt_link(1, &mut shorts);
                }
                self.expr(index)?;
                self.emit(Op::DeleteElem(self.strict));
            }
            other => {
                self.opt_chain(other, &mut shorts)?;
                self.emit(Op::Pop);
                let yes = self.const_idx(Value::Bool(true));
                self.emit(Op::Const(yes));
            }
        }
        if shorts.is_empty() {
            return Ok(());
        }
        let done = self.emit(Op::Jump(0));
        for short in shorts {
            self.patch(short);
        }
        let yes = self.const_idx(Value::Bool(true));
        self.emit(Op::Const(yes));
        self.patch(done);
        Ok(())
    }

    /// Does this expression continue an open optional chain? An OptionalChain wrapper closes
    /// its own chain; optional links in arguments/keys are separate expressions as well.
    fn has_open_optional_chain(e: &Expr) -> bool {
        if crate::interpreter::ast_stack_low() {
            return crate::interpreter::with_ast_stack(|| Self::has_open_optional_chain(e));
        }
        match e {
            Expr::Member { obj, optional, .. } | Expr::Index { obj, optional, .. } => {
                *optional || Self::has_open_optional_chain(obj)
            }
            Expr::Call {
                callee, optional, ..
            } => *optional || Self::has_open_optional_chain(callee),
            _ => false,
        }
    }

    /// Compile an optional chain (`a?.b.c`, `r?.m(args)`): each optional link peeks its base —
    /// nullish pops what the link would have consumed and jumps to a shared pad that pushes the
    /// chain's `undefined` result (skipping every later link, key expression, and argument, per
    /// spec). Non-optional links compile as usual. Public Member/Index method calls and plain
    /// optional callees preserve their distinct receiver rules, including private method
    /// receivers and super References. Optional `delete` retains its separate path.
    fn opt_chain(&mut self, e: &Expr, shorts: &mut Vec<usize>) -> CResult {
        match e.position() {
            Some(position) => self.at_position(position, |c| c.opt_chain_link(e, shorts)),
            None => self.opt_chain_link(e, shorts),
        }
    }

    fn opt_chain_link(&mut self, e: &Expr, shorts: &mut Vec<usize>) -> CResult {
        if crate::interpreter::ast_stack_low() {
            return crate::interpreter::with_ast_stack(|| self.opt_chain_link(e, shorts));
        }
        if !Self::has_open_optional_chain(e) {
            // Preserve ordinary expression specializations (GetPropThis/GetPropLocal,
            // element fusions, etc.) before the first optional link. Besides avoiding extra
            // dispatch, constructor forwarders use that canonical opcode shape as their proof.
            return self.expr(e);
        }
        match e {
            Expr::Member {
                obj,
                prop,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.opt_chain(obj, shorts)?;
                if *optional {
                    self.opt_link(1, shorts);
                }
                let i = self.property_name_idx(prop);
                let c = self.new_cache(i);
                self.emit(Op::GetProp(i, c));
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) && prop.starts_with('#') => {
                self.opt_chain(obj, shorts)?;
                if *optional {
                    self.opt_link(1, shorts);
                }
                let name = self.property_name_idx(prop);
                let site = self.new_private_site();
                self.emit(Op::GetPrivate(name, site));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.opt_chain(obj, shorts)?;
                if *optional {
                    self.opt_link(1, shorts);
                }
                self.expr(index)?;
                self.emit(Op::GetElem);
                Ok(())
            }
            Expr::Call {
                callee,
                args,
                optional: call_opt,
                ..
            } => {
                // A SuperCall may be the base of `super()?.x`. Evaluate it through the
                // constructor continuation, not as an ordinary call to an Expr::Super value.
                if matches!(&**callee, Expr::Super) && !call_opt {
                    return self.expr(e);
                }
                let (with_this, allow_inline) = self.call_reference(callee, shorts)?;
                if *call_opt {
                    self.opt_link(if with_this { 2 } else { 1 }, shorts);
                }
                self.pending_call_name = Some(crate::callee_name::callee_name(callee));
                self.finish_call(args, with_this, allow_inline)
            }
            // The chain's base (before any `?.` link): an ordinary expression.
            other => self.expr(other),
        }
    }

    /// One optional link: fall through when the top of stack isn't nullish; otherwise pop the
    /// `depth` values the rest of the link would consume and jump to the chain's undefined pad.
    fn opt_link(&mut self, depth: u16, shorts: &mut Vec<usize>) {
        let cont = self.emit(Op::JumpIfNotNullishPeek(0));
        for _ in 0..depth {
            self.emit(Op::Pop);
        }
        shorts.push(self.emit(Op::Jump(0)));
        self.patch(cont);
    }

    /// The local slot for a fused element access (`x[k]` → `GetElemLocal`), or `None` to use
    /// the generic ops. Fusing defers the base-local read past the key/value evaluation, so it
    /// requires: the base is an Ident homed in a slot that can never be in TDZ (a param or a
    /// `var` — no early throw to reorder; see `tdz_slots`), and no `deps` expression can
    /// reassign that local (calls can't — slot locals are unobservable outside the function;
    /// only an explicit assignment/update in the key/value expressions themselves could, and
    /// `no_assign_to` rejects those).
    fn fused_elem_slot(&self, obj: &Expr, deps: &[&Expr]) -> Option<u16> {
        let Expr::Ident(name, _) = obj else {
            return None;
        };
        let Some(Home::Slot(slot, _)) = self.home(name) else {
            return None;
        };
        if self.tdz_slots.contains(&slot) {
            return None;
        }
        if deps.iter().all(|d| no_assign_to(d, name)) {
            Some(slot)
        } else {
            None
        }
    }
    fn fresh_slot(&mut self, name: &str) -> u16 {
        let slot = self.slot_names.len() as u16;
        self.slot_names.push(Rc::from(name));
        slot
    }
    fn fresh_reference(&mut self) -> Result<u16, Bail> {
        let reference = u16::try_from(self.n_refs).map_err(|_| Bail)?;
        self.n_refs += 1;
        Ok(reference)
    }
    fn push_compile_scope(&mut self) {
        self.scopes.push(Vec::new());
        self.lexical_env_names.push(Default::default());
    }
    fn pop_compile_scope(&mut self) {
        self.scopes.pop().expect("compiler scope stack underflow");
        self.lexical_env_names
            .pop()
            .expect("compiler lexical-environment stack underflow");
    }
    fn scope_bind(&mut self, name: &str, slot: u16, is_const: bool) {
        if self.scopes.is_empty() {
            self.push_compile_scope();
        }
        let top = self.scopes.last_mut().unwrap();
        if let Some(e) = top.iter_mut().find(|(n, ..)| n == name) {
            *e = (name.to_string(), slot, is_const);
        } else {
            top.push((name.to_string(), slot, is_const));
        }
    }
    fn lookup(&self, name: &str) -> Option<(u16, bool)> {
        for (scope, environment) in self.scopes.iter().zip(&self.lexical_env_names).rev() {
            if let Some((_, slot, k)) = scope.iter().rev().find(|(n, ..)| n == name) {
                return Some((*slot, *k));
            }
            if environment.contains_key(name) {
                return None;
            }
        }
        None
    }
    fn lexical_env_bind(&mut self, name: &str, is_const: bool) {
        self.lexical_env_names
            .last_mut()
            .expect("lexical binding requires a compiler scope")
            .insert(name.to_string(), is_const);
    }
    fn current_lexical_env_has(&self, name: &str) -> bool {
        self.lexical_env_names
            .last()
            .is_some_and(|scope| scope.contains_key(name))
    }
    /// VariableDeclaration/BindingInitialization with an undefined environment uses ordinary
    /// ResolveBinding. In particular, Annex B catch-parameter redeclarations must write a nearer
    /// catch slot instead of the same-named global var. Lexical declarations initialize their
    /// own binding; they must not accidentally initialize an outer binding of the same name.
    fn dynamic_declaration_binding(&self, name: &str, kind: DeclKind) -> bool {
        if matches!(kind, DeclKind::Var) {
            self.home(name).is_none()
        } else {
            self.current_lexical_env_has(name)
        }
    }
    fn env_bind(&mut self, name: &str, is_const: bool) {
        self.env_names.insert(name.to_string(), is_const);
    }
    fn env_has(&self, name: &str) -> bool {
        self.env_names.contains_key(name)
    }
    /// Resolve a local: innermost slot scope first, then runtime lexical environments (reported
    /// as `None` so the emitter uses dynamic name resolution), then the function activation.
    fn home(&self, name: &str) -> Option<Home> {
        if let Some(floor) = self.with_scope_floors.last().copied() {
            for (scope, environment) in self.scopes[floor..]
                .iter()
                .zip(&self.lexical_env_names[floor..])
                .rev()
            {
                if let Some((_, slot, is_const)) =
                    scope.iter().rev().find(|(candidate, ..)| candidate == name)
                {
                    return Some(Home::Slot(*slot, *is_const));
                }
                if environment.contains_key(name) {
                    return None;
                }
            }
            return None;
        }
        for (scope, environment) in self.scopes.iter().zip(&self.lexical_env_names).rev() {
            if let Some((_, slot, is_const)) =
                scope.iter().rev().find(|(candidate, ..)| candidate == name)
            {
                return Some(Home::Slot(*slot, *is_const));
            }
            if environment.contains_key(name) {
                return None;
            }
        }
        self.env_names
            .get(name)
            .map(|is_const| Home::Env(*is_const))
    }
    fn name_reference_can_change(&self, name: &str) -> bool {
        self.home(name).is_none()
            && (self.script_body || self.direct_eval || !self.with_scope_floors.is_empty())
    }

    /// If/iteration/with/switch/try use UpdateEmpty(completion, undefined), unlike a plain
    /// Block/StatementList. Keeping that boundary explicit also preserves labelled abrupt values.
    fn reset_script_completion(&mut self) {
        if let Some(slot) = self.script_completion {
            self.emit(Op::Undef);
            self.emit(Op::StoreLocal(slot));
        }
    }
    fn const_idx(&mut self, v: Value) -> u32 {
        self.consts.push(v);
        (self.consts.len() - 1) as u32
    }
    fn property_name_idx(&mut self, name: &str) -> u32 {
        self.name_idx(&crate::value::encode_string_key(name))
    }
    fn name_idx(&mut self, name: &str) -> u32 {
        // Large bundles repeatedly searched the complete pool for every emitted name. Keep
        // small functions allocation-free, then use a compile-local index without changing
        // bytecode IDs, property-key order, feedback layout, or serialized chunk contents.
        if self.name_indexes.is_none() && self.names.len() >= 32 {
            let mut indexes = crate::fasthash::FastMap::default();
            for (index, name) in self.names.iter().enumerate() {
                indexes.entry(name.clone()).or_insert(index as u32);
            }
            self.name_indexes = Some(indexes);
        }
        if let Some(indexes) = &self.name_indexes {
            if let Some(&index) = indexes.get(name) {
                return index;
            }
        } else if let Some(index) = self.names.iter().position(|n| &**n == name) {
            return index as u32;
        }
        self.append_name(name)
    }
    /// Append even a duplicate when an opcode requires a contiguous key range.
    fn append_name(&mut self, name: &str) -> u32 {
        let index = self.names.len() as u32;
        let name: Rc<str> = Rc::from(name);
        if let Some(indexes) = &mut self.name_indexes {
            indexes.entry(name.clone()).or_insert(index);
        }
        self.names.push(name);
        index
    }
    /// Failed speculative inlining must remove only entries first introduced by that splice.
    /// Work is proportional to the rolled-back suffix, not to the entire retained name table.
    fn truncate_names(&mut self, len: usize) {
        if let Some(indexes) = &mut self.name_indexes {
            for (index, name) in self.names.iter().enumerate().skip(len) {
                if indexes.get(name.as_ref()) == Some(&(index as u32)) {
                    indexes.remove(name.as_ref());
                }
            }
        }
        self.names.truncate(len);
    }
    fn patch(&mut self, at: usize) {
        let target = self.ops.len() as u32;
        self.patch_to(at, target);
    }
    fn patch_to(&mut self, at: usize, target: u32) {
        match &mut self.ops[at] {
            Op::Jump(t)
            | Op::AbruptJump(t, _)
            | Op::JumpIfFalse(t)
            | Op::JumpIfFalsePeek(t)
            | Op::JumpIfTruePeek(t)
            | Op::JumpIfNotNullishPeek(t)
            | Op::InlineGuard(_, t) => *t = target,
            _ => unreachable!("patching a non-jump"),
        }
    }

    /// Declare the function body's top-level lexical bindings: captured ones home in the activation
    /// env (inserted in TDZ by `make_run_env`), the rest get TDZ slots. Function declarations
    /// were already handled by the hoist plan; classes and resource declarations follow the same
    /// lexical initialization split.
    fn declare_body_lexicals(
        &mut self,
        stmts: &[Stmt],
        captured: &crate::fasthash::FastSet<String>,
    ) -> CResult {
        for s in stmts {
            let s = match s {
                Stmt::ExportDecl(inner) => &**inner,
                Stmt::ExportDefault(inner)
                    if matches!(&**inner, Stmt::Expr(_))
                        || matches!(&**inner, Stmt::FuncDecl(function) if function.name.is_none())
                        || matches!(&**inner, Stmt::ClassDecl(class) if class.name.is_none()) =>
                {
                    continue;
                }
                Stmt::ExportDefault(inner) => &**inner,
                other => other,
            };
            match s {
                Stmt::VarDecl {
                    kind:
                        kind
                        @ (DeclKind::Let | DeclKind::Const | DeclKind::Using | DeclKind::AwaitUsing),
                    decls,
                } => {
                    let is_const = matches!(
                        kind,
                        DeclKind::Const | DeclKind::Using | DeclKind::AwaitUsing
                    );
                    for (pat, _) in decls {
                        self.declare_body_lexical_pattern(pat, is_const, captured)?;
                    }
                }
                Stmt::ClassDecl(class) => {
                    let name = class.name.as_ref().ok_or(Bail)?;
                    if self.module_body && self.env_has(name) {
                        // ModuleDeclarationInstantiation created the mutable TDZ binding.
                    } else if captured.contains(name) {
                        self.cap_inits
                            .push(CapInit::Lexical(Rc::from(name.as_str()), false));
                        self.env_bind(name, false);
                    } else {
                        let slot = self.fresh_slot(name);
                        self.scope_bind(name, slot, false);
                        self.tdz_slots.insert(slot);
                        self.emit(Op::Tdz(slot));
                    }
                }
                Stmt::FuncDecl(_) => {} // hoisted — created at entry
                _ => {}
            }
        }
        Ok(())
    }

    /// FunctionDeclarationInstantiation creates every top-level lexical binding before body
    /// evaluation. Split a binding pattern leaf-by-leaf: captured names live in the activation
    /// Environment Record, while unobserved names retain the cheaper slot representation. Both
    /// remain uninitialized until the declaration's BindingInitialization reaches that leaf.
    fn declare_body_lexical_pattern(
        &mut self,
        pattern: &Pattern,
        is_const: bool,
        captured: &crate::fasthash::FastSet<String>,
    ) -> CResult {
        match pattern {
            Pattern::Ident(name) if self.module_body && self.env_has(name) => Ok(()),
            Pattern::Ident(name) if captured.contains(name) => {
                self.cap_inits
                    .push(CapInit::Lexical(Rc::from(name.as_str()), is_const));
                self.env_bind(name, is_const);
                Ok(())
            }
            Pattern::Ident(_) => self.declare_lexical_pattern(pattern, is_const),
            Pattern::Object(object) => {
                for property in &object.props {
                    self.declare_body_lexical_pattern(&property.value, is_const, captured)?;
                }
                if let Some(rest) = &object.rest {
                    self.declare_body_lexical_pattern(
                        &Pattern::Ident(rest.clone()),
                        is_const,
                        captured,
                    )?;
                }
                Ok(())
            }
            Pattern::Array(elements) => {
                for element in elements {
                    match element {
                        ArrayPatElem::Hole => {}
                        ArrayPatElem::Elem { pattern, .. } | ArrayPatElem::Rest(pattern) => {
                            self.declare_body_lexical_pattern(pattern, is_const, captured)?;
                        }
                    }
                }
                Ok(())
            }
            Pattern::Member(_) => Err(Bail),
        }
    }

    fn declare_block_function_binding(&mut self, function: &Rc<Function>) -> CResult {
        let name = function.name.as_ref().ok_or(Bail)?;
        // Web-legacy duplicate functions share one mutable block binding. Every declaration
        // still instantiates in source order below, including across switch clauses.
        if !self
            .scopes
            .last()
            .is_some_and(|scope| scope.iter().any(|(binding, ..)| binding == name))
        {
            self.declare_lexical_pattern(&Pattern::Ident(name.clone()), false)?;
        }
        Ok(())
    }

    fn instantiate_block_function(&mut self, function: &Rc<Function>) -> CResult {
        let name = function.name.as_ref().ok_or(Bail)?;
        self.emit_closure(function, None)?;
        if self.current_lexical_env_has(name) {
            let name = self.name_idx(name);
            self.emit(Op::InitLex(name));
        } else {
            let Home::Slot(slot, false) = self.home(name).ok_or(Bail)? else {
                return Err(Bail);
            };
            self.emit(Op::StoreLocal(slot));
        }
        Ok(())
    }

    /// Instantiate a statement list's block-scoped declarations at block entry. Per ECMA-262
    /// BlockDeclarationInstantiation, every binding exists before statement evaluation and a
    /// block FunctionDeclaration is initialized immediately rather than when its statement is
    /// reached. CaptureScan keeps recursive/closure-captured block functions on the tree-walker;
    /// the slot path here is therefore the exact, allocation-light representation of the
    /// uncaptured subset.
    fn declare_block_lexicals(&mut self, stmts: &[Stmt]) -> CResult {
        for s in stmts {
            let s = lexical_declaration_statement(s);
            match s {
                Stmt::VarDecl {
                    kind: DeclKind::Let | DeclKind::Const | DeclKind::Using | DeclKind::AwaitUsing,
                    decls,
                } => {
                    let is_const = matches!(
                        s,
                        Stmt::VarDecl {
                            kind: DeclKind::Const | DeclKind::Using | DeclKind::AwaitUsing,
                            ..
                        }
                    );
                    for (pat, _) in decls {
                        self.declare_lexical_pattern(pat, is_const)?;
                    }
                }
                Stmt::FuncDecl(function) => {
                    self.declare_block_function_binding(function)?;
                }
                Stmt::ClassDecl(class) => {
                    let name = class.name.as_ref().ok_or(Bail)?;
                    self.declare_lexical_pattern(&Pattern::Ident(name.clone()), false)?;
                }
                _ => {}
            }
        }
        // InstantiateFunctionObject uses the current lexical environment and initializes the
        // mutable block binding before the first statement executes. Do this after reserving all
        // slots so source-order declarations resolve against the complete block scope.
        for s in stmts {
            if let Stmt::FuncDecl(function) = lexical_declaration_statement(s) {
                self.instantiate_block_function(function)?;
            }
        }
        Ok(())
    }

    /// ECMA-262 HasCallInTailPosition: a preceding using declaration in this statement list
    /// blocks transfer, even if its resource is null. Restore the enclosing list on exit.
    fn statement_list(&mut self, body: &[Stmt]) -> CResult {
        let saved = self.tail_blocked;
        let result = (|| {
            for statement in body {
                self.stmt(statement)?;
                if matches!(
                    statement,
                    Stmt::VarDecl {
                        kind: DeclKind::Using | DeclKind::AwaitUsing,
                        ..
                    }
                ) {
                    self.tail_blocked = saved + 1;
                }
            }
            Ok(())
        })();
        self.tail_blocked = saved;
        result
    }

    fn without_tail(&mut self, body: impl FnOnce(&mut Self) -> CResult) -> CResult {
        self.tail_blocked += 1;
        let result = body(self);
        self.tail_blocked -= 1;
        result
    }

    /// Lower only expression tail positions, leaving callee/key/argument evaluation on the
    /// ordinary path. The selected final call stages owned values for the existing trampoline.
    fn tail_expr(&mut self, expression: &Expr) -> CResult {
        match expression {
            Expr::Paren(inner) => self.tail_expr(inner),
            Expr::Cond { test, cons, alt } => {
                self.expr(test)?;
                let alternate = self.emit(Op::JumpIfFalse(0));
                self.tail_expr(cons)?;
                let done = self.emit(Op::Jump(0));
                self.patch(alternate);
                self.tail_expr(alt)?;
                self.patch(done);
                Ok(())
            }
            Expr::Seq(expressions) if !expressions.is_empty() => {
                for expression in &expressions[..expressions.len() - 1] {
                    self.expr_stmt(expression)?;
                }
                self.tail_expr(expressions.last().unwrap())
            }
            Expr::Logical { op, left, right } => {
                self.expr(left)?;
                let done = self.emit(match *op {
                    "&&" => Op::JumpIfFalsePeek(0),
                    "||" => Op::JumpIfTruePeek(0),
                    "??" => Op::JumpIfNotNullishPeek(0),
                    _ => return Err(Bail),
                });
                self.emit(Op::Pop);
                self.tail_expr(right)?;
                self.patch(done);
                Ok(())
            }
            Expr::OptionalChain(inner) if has_tail_call(inner) => {
                let mut shorts = Vec::new();
                let saved = std::mem::replace(&mut self.lowering_tail, true);
                let result = self.opt_chain(inner, &mut shorts);
                self.lowering_tail = saved;
                result?;
                self.transfer_last_call()?;
                if !shorts.is_empty() {
                    let done = self.emit(Op::Jump(0));
                    for short in shorts {
                        self.patch(short);
                    }
                    self.emit(Op::Undef);
                    self.patch(done);
                }
                Ok(())
            }
            Expr::Call { callee, .. } if matches!(&**callee, Expr::Super) => self.expr(expression),
            Expr::Call { .. } | Expr::TaggedTemplate { .. } => {
                let saved = std::mem::replace(&mut self.lowering_tail, true);
                let node =
                    std::mem::replace(&mut self.tail_call_node, expression as *const Expr as usize);
                self.tail_lowered = false;
                let result = self.expr(expression);
                self.lowering_tail = saved;
                self.tail_call_node = node;
                result?;
                if std::mem::take(&mut self.tail_lowered) {
                    return Ok(());
                }
                let position = expression.position().unwrap_or(NO_POSITION);
                self.at_position(position, Self::transfer_last_call)
            }
            other => self.expr(other),
        }
    }

    fn transfer_last_call(&mut self) -> CResult {
        let at = self.ops.len().checked_sub(1).ok_or(Bail)?;
        let call = self.ops[at];
        let tail = match call {
            Op::Call(argc, _) => Op::TailCall(CallArgsMode::Fixed(argc), false),
            Op::CallWithThis(argc, _) => Op::TailCall(CallArgsMode::Fixed(argc), true),
            Op::CallSpread(argc) => Op::TailCall(CallArgsMode::FinalSpread(argc), false),
            Op::CallSpreadThis(argc) => Op::TailCall(CallArgsMode::FinalSpread(argc), true),
            Op::CallArgsArray => Op::TailCall(CallArgsMode::Array, false),
            Op::CallArgsArrayThis => Op::TailCall(CallArgsMode::Array, true),
            Op::EvalCallArgsArray => {
                self.ops[at] = Op::TailEvalCallArgsArray;
                return Ok(());
            }
            _ => return Err(Bail),
        };
        if ordinary_tail_call_depth() == 0 {
            self.ops[at] = tail;
            return Ok(());
        }
        // The operands stay where the call left them on both paths; a jump to `at` (from the
        // argument list) lands on the depth test, ahead of either form.
        let name = self.call_names.take_last(at);
        self.ops[at] = Op::TailDeep;
        let shallow = self.emit(Op::JumpIfFalse(0));
        let tail_call = self.emit(tail);
        self.name_call(tail_call, name.as_deref());
        let join = self.emit(Op::Jump(0));
        self.patch(shallow);
        let ordinary = self.emit(call);
        self.name_call(ordinary, name.as_deref());
        self.patch(join);
        Ok(())
    }

    fn stmt(&mut self, s: &Stmt) -> CResult {
        if crate::interpreter::ast_stack_low() {
            return crate::interpreter::with_ast_stack(|| self.stmt(s));
        }
        if self.fragment_root.is_none()
            && matches!(
                s,
                Stmt::If { .. }
                    | Stmt::While { .. }
                    | Stmt::DoWhile { .. }
                    | Stmt::For { .. }
                    | Stmt::ForInOf { .. }
                    | Stmt::Switch { .. }
                    | Stmt::With { .. }
                    | Stmt::Try { .. }
            )
        {
            self.reset_script_completion();
        }
        match s {
            Stmt::Expr(e) => {
                if let Some(slot) = self.script_completion {
                    self.expr(e)?;
                    self.emit(Op::StoreLocal(slot));
                    Ok(())
                } else {
                    self.expr_stmt(e)
                }
            }
            Stmt::Empty | Stmt::Debugger => Ok(()),
            // Top-level function declarations were hoisted at function entry; block-level ones
            // were initialized by BlockDeclarationInstantiation at block entry. Annex B.3.2 adds
            // one declaration-time step: copy that lexical function object into its separate
            // function-scope var binding.
            Stmt::FuncDecl(function) => {
                if self.fragment_entry {
                    let index = self.funcs.len() as u32;
                    self.funcs.push(function.clone());
                    self.emit(Op::AnnexBSync(index));
                    return Ok(());
                }
                if self
                    .script_annexb
                    .contains(&(Rc::as_ptr(function) as usize))
                {
                    let name = function.name.as_ref().ok_or(Bail)?;
                    self.expr(&Expr::Ident(name.clone(), NO_POSITION))?;
                    let name = self.name_idx(name);
                    self.emit(Op::StoreGlobalName(name));
                    return Ok(());
                }
                let Some(target) = self
                    .annexb_targets
                    .get(&(Rc::as_ptr(function) as usize))
                    .copied()
                else {
                    return Ok(());
                };
                let name = function.name.as_ref().ok_or(Bail)?;
                self.expr(&Expr::Ident(name.clone(), NO_POSITION))?;
                match target {
                    Home::Slot(slot, false) => self.emit(Op::StoreLocal(slot)),
                    Home::Env(false) => {
                        let name = self.name_idx(name);
                        self.emit(Op::StoreCap(name))
                    }
                    Home::Slot(_, true) | Home::Env(true) => {
                        unreachable!("Annex B promotion target is mutable")
                    }
                };
                Ok(())
            }
            Stmt::ClassDecl(class) => {
                self.expr(&Expr::Class(class.clone()))?;
                let name = class.name.as_ref().ok_or(Bail)?;
                if self.current_lexical_env_has(name) {
                    let name = self.name_idx(name);
                    self.emit(Op::InitLex(name));
                    return Ok(());
                }
                match self.home(name).ok_or(Bail)? {
                    Home::Slot(slot, _) => self.emit(Op::StoreLocal(slot)),
                    Home::Env(_) => {
                        let name = self.name_idx(name);
                        self.emit(Op::StoreCapInit(name))
                    }
                };
                Ok(())
            }
            Stmt::VarDecl { kind, decls } => {
                for (pat, init) in decls {
                    let Pattern::Ident(name) = pat else {
                        if matches!(kind, DeclKind::Using | DeclKind::AwaitUsing) {
                            return Err(Bail);
                        }
                        // Destructuring declaration: evaluate the initializer, then lower the
                        // pattern against it (a pattern without an initializer is a parse error).
                        let Some(e) = init else { return Err(Bail) };
                        self.expr(e)?;
                        self.destructure_store(pat, *kind)?;
                        continue;
                    };
                    let dynamic_lexical = self.dynamic_declaration_binding(name, *kind);
                    let home = if dynamic_lexical {
                        None
                    } else {
                        Some(self.home(name).ok_or(Bail)?)
                    };
                    // VariableDeclaration resolves an identifier Reference before its RHS.
                    // A with object may delete/reconfigure the property while that RHS runs.
                    let reference = if matches!(kind, DeclKind::Var)
                        && init.is_some()
                        && self.name_reference_can_change(name)
                    {
                        let reference = self.fresh_reference()?;
                        let name = self.name_idx(name);
                        self.emit(Op::ResolveNameRef(name, reference));
                        Some(reference)
                    } else {
                        None
                    };
                    match init {
                        Some(e) => self.named_expr(e, name)?,
                        // `var x;` leaves an existing binding alone; `let x;` initializes.
                        None => {
                            if matches!(kind, DeclKind::Var) {
                                continue;
                            }
                            self.emit(Op::Undef);
                        }
                    }
                    if matches!(kind, DeclKind::Using | DeclKind::AwaitUsing) {
                        // UsingDeclaration Evaluation calls AddDisposableResource before
                        // InitializeBinding. AddDisposable peeks so the same value then initializes
                        // the immutable lexical home without a clone on the common primitive path.
                        self.emit(Op::AddDisposable(matches!(kind, DeclKind::AwaitUsing)));
                    }
                    if let Some(reference) = reference {
                        self.emit(Op::StoreRef(reference));
                        continue;
                    }
                    if dynamic_lexical {
                        let name = self.name_idx(name);
                        self.emit(if matches!(kind, DeclKind::Var) {
                            Op::StoreName(name)
                        } else {
                            Op::InitLex(name)
                        });
                        continue;
                    }
                    match home.expect("non-dynamic declaration has a static home") {
                        Home::Slot(slot, _) => {
                            self.emit(Op::StoreLocal(slot));
                        }
                        Home::Env(_) => {
                            let n = self.name_idx(name);
                            // A lexical declaration initializes (clearing TDZ); a `var` writes an
                            // already-initialized binding.
                            if matches!(kind, DeclKind::Var) {
                                self.emit(Op::StoreCap(n));
                            } else {
                                self.emit(Op::StoreCapInit(n));
                            }
                        }
                    }
                }
                Ok(())
            }
            Stmt::Return(arg) => {
                // Async-generator ReturnStatement awaits an expression before cleanup. That is
                // a real suspension boundary, unlike a nested async function declaration.
                if self.fragment_async_generator && arg.is_some() {
                    return Err(Bail);
                }
                // Inside a spliced callee body, `return v` is "leave v on the stack and jump to
                // the join point" (the plan guarantees no handlers/for-of regions to unwind:
                // the callee chunk contains no PushHandler).
                if self.inline_depth > 0 {
                    match arg {
                        Some(e) => self.expr(e)?,
                        None => {
                            self.emit(Op::Undef);
                        }
                    }
                    let j = self.emit(Op::Jump(0));
                    self.inline_returns.push(j);
                    return Ok(());
                }
                let explicit = if let Some(e) = arg {
                    if self.strict
                        && !self.is_coroutine
                        && (!self.fragment_entry || self.fragment_tail_calls)
                        && self.tail_blocked == 0
                    {
                        self.tail_expr(e)?;
                    } else {
                        self.expr(e)?;
                    }
                    true
                } else {
                    false
                };
                if !self.is_coroutine && !self.fragment_entry {
                    // Ordinary/JIT frames do not return through drive_vm. Preserve their direct
                    // cleanup lowering; coroutine frames use completion-aware iterator handlers
                    // so injected returns and suspending finalizers share the normative path.
                    let fors: Vec<(u16, u32)> = self
                        .loops
                        .iter()
                        .filter_map(|ctx| ctx.foreach_iter.map(|it| (it, ctx.body_try_depth)))
                        .collect();
                    if fors.len() > 1 {
                        return Err(Bail);
                    }
                    if let Some(&(iter_s, body_depth)) = fors.first() {
                        let crosses_finally = self
                            .finally_depths
                            .iter()
                            .any(|depth| *depth > body_depth && *depth <= self.try_depth);
                        if crosses_finally {
                            // Evaluate the return expression once, then let inner finalizers
                            // complete before IteratorClose (ForIn/OfBodyEvaluation). A finalizer
                            // may replace this completion with return/throw/break/continue. The
                            // saved value must survive its operand-stack restoration unchanged.
                            let saved = explicit.then(|| {
                                let slot = self.fresh_slot("%for-of-return%");
                                self.emit(Op::StoreLocal(slot));
                                slot
                            });
                            let to_cleanup = self.emit(Op::AbruptJump(0, body_depth - 1));
                            self.patch(to_cleanup);
                            self.emit(Op::IterCloseL(iter_s));
                            if let Some(slot) = saved {
                                self.emit(Op::LoadLocal(slot));
                            }
                        } else {
                            for _ in body_depth..self.try_depth {
                                self.emit(Op::PopHandler);
                            }
                            self.emit(Op::PopHandler);
                            self.emit(Op::IterCloseL(iter_s));
                        }
                    }
                }
                // ECMA-262 §14.10.1 distinguishes `return;` from `return Expression;` in an
                // async generator: only the expression form performs Await, even when that
                // expression evaluates to undefined. Both remain abrupt completions so active
                // finalizers and for-of IteratorClose handlers see them in normative order.
                if explicit {
                    self.emit(Op::Return);
                } else {
                    self.emit(Op::ReturnBare);
                }
                Ok(())
            }
            Stmt::Throw(e) => {
                self.expr(e)?;
                self.emit(Op::Throw);
                Ok(())
            }
            Stmt::If { test, cons, alt } => {
                self.expr(test)?;
                let jf = self.emit(Op::JumpIfFalse(0));
                self.stmt(cons)?;
                match alt {
                    Some(a) => {
                        let jend = self.emit(Op::Jump(0));
                        self.patch(jf);
                        self.stmt(a)?;
                        self.patch(jend);
                    }
                    None => self.patch(jf),
                }
                Ok(())
            }
            Stmt::Block(body) => {
                self.push_compile_scope();
                let r = self.block_body(body);
                self.pop_compile_scope();
                r
            }
            Stmt::While { test, body, .. } => {
                self.fragment_root.take();
                let labels = std::mem::take(&mut self.pending_labels);
                let start = self.ops.len();
                self.record_function_osr(&body.site, start);
                self.expr(test)?;
                let jf = self.emit(Op::JumpIfFalse(0));
                self.loops.push(LoopCtx {
                    labels,
                    entry_try_depth: self.try_depth,
                    ..LoopCtx::default()
                });
                let r = self.stmt(body);
                let ctx = self.loops.pop().unwrap();
                r?;
                for c in ctx.continues {
                    self.patch_to(c, start as u32);
                }
                self.emit(Op::Jump(start as u32));
                self.patch(jf);
                for b in ctx.breaks {
                    self.patch(b);
                }
                Ok(())
            }
            Stmt::DoWhile { body, test, .. } => {
                self.fragment_root.take();
                let labels = std::mem::take(&mut self.pending_labels);
                let start = self.ops.len();
                self.record_function_osr(&body.site, start);
                self.loops.push(LoopCtx {
                    labels,
                    entry_try_depth: self.try_depth,
                    ..LoopCtx::default()
                });
                let r = self.stmt(body);
                let ctx = self.loops.pop().unwrap();
                r?;
                let cont = self.ops.len();
                for c in ctx.continues {
                    self.patch_to(c, cont as u32);
                }
                // ECMA-262 §14.7.2.2 DoWhileStatement evaluation: a literal false test (the
                // `do { … } while (0)` block idiom of macro-expanded and compiled code) has no
                // side effect and always exits, so the body runs once and `continue` reaches the
                // end. Emitting no test and no back edge keeps a once-run block from being
                // classified as a loop (hot-loop code shapes, loop polls).
                if !is_literal_falsy(test) {
                    self.expr(test)?;
                    let jf = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::Jump(start as u32));
                    self.patch(jf);
                }
                for b in ctx.breaks {
                    self.patch(b);
                }
                Ok(())
            }
            Stmt::For {
                init,
                test,
                update,
                body,
                ..
            } => {
                let saved_site = self
                    .pending_function_osr_site
                    .replace(&body.site as *const _ as usize);
                self.push_compile_scope();
                let r = self.for_loop(init.as_deref(), test.as_ref(), update.as_ref(), body);
                self.pop_compile_scope();
                self.pending_function_osr_site = saved_site;
                r
            }
            Stmt::Break(None) => {
                let idx = self
                    .loops
                    .iter()
                    .rposition(|ctx| !ctx.is_label_block)
                    .ok_or(Bail)?;
                let j = self.emit_exit_jump(idx, false)?;
                self.loops[idx].breaks.push(j);
                Ok(())
            }
            Stmt::Continue(None) => {
                // `continue` skips switch contexts: it targets the innermost enclosing *loop*.
                let idx = self
                    .loops
                    .iter()
                    .rposition(|c| !c.is_switch && !c.is_label_block)
                    .ok_or(Bail)?;
                let j = self.emit_exit_jump(idx, true)?;
                self.loops[idx].continues.push(j);
                Ok(())
            }
            // Labelled break/continue: jump to the control context carrying the target label.
            Stmt::Break(Some(name)) => {
                let idx = self
                    .loops
                    .iter()
                    .rposition(|c| c.labels.iter().any(|l| l == name));
                let Some(idx) = idx else {
                    return self.fragment_external_exit(name, false);
                };
                let j = self.emit_exit_jump(idx, false)?;
                self.loops[idx].breaks.push(j);
                Ok(())
            }
            Stmt::Continue(Some(name)) => {
                // A labelled continue must target a loop — a label on a switch is only a break
                // target (the parser rejects `continue` to it; not-found bails to the oracle).
                let idx = self.loops.iter().rposition(|c| {
                    !c.is_switch && !c.is_label_block && c.labels.iter().any(|l| l == name)
                });
                let Some(idx) = idx else {
                    return self.fragment_external_exit(name, true);
                };
                let j = self.emit_exit_jump(idx, true)?;
                self.loops[idx].continues.push(j);
                Ok(())
            }
            // A label naming a loop or switch attaches to that context; stacked labels
            // (`a: b: for`) accumulate through the recursion. Any other labelled statement gets
            // a break-only context, matching ECMA-262 §14.13.4 LabelledEvaluation.
            Stmt::Labeled { label, body } => match &**body {
                Stmt::While { .. }
                | Stmt::DoWhile { .. }
                | Stmt::For { .. }
                | Stmt::ForInOf { .. }
                | Stmt::Switch { .. }
                | Stmt::Labeled { .. } => {
                    self.pending_labels.push(label.clone());
                    self.stmt(body)
                }
                _ => {
                    let mut labels = std::mem::take(&mut self.pending_labels);
                    labels.push(label.clone());
                    self.loops.push(LoopCtx {
                        labels,
                        entry_try_depth: self.try_depth,
                        is_label_block: true,
                        ..LoopCtx::default()
                    });
                    let result = self.stmt(body);
                    let ctx = self.loops.pop().expect("just pushed labelled context");
                    result?;
                    for jump in ctx.breaks {
                        self.patch(jump);
                    }
                    Ok(())
                }
            },
            // `switch`: evaluate the discriminant in the outer environment first, then perform
            // one BlockDeclarationInstantiation shared by every case before any case test
            // (ECMA-262 §14.12.4). Case tests run in source order and bodies remain contiguous,
            // so fall-through is just falling through.
            Stmt::Switch { disc, cases } => {
                self.expr(disc)?;
                let tmp = self.fresh_slot("%switch%");
                self.emit(Op::StoreLocal(tmp));
                self.push_compile_scope();
                let mut bindings = Vec::new();
                for case in cases {
                    for binding in self.runtime_block_bindings(&case.body) {
                        if !bindings.iter().any(|(name, _)| name == &binding.0) {
                            bindings.push(binding);
                        }
                    }
                }
                let result = if bindings.is_empty() {
                    self.switch_body(tmp, cases)
                } else {
                    let scope = self.push_runtime_lexical_scope(bindings);
                    self.environment_scope(|compiler| compiler.switch_body(tmp, cases), scope)
                };
                self.pop_compile_scope();
                result
            }
            // `try` completion handling follows ECMA-262 §14.15.3. Catch consumes only a throw.
            // A finally handler intercepts throw/return/break/continue, records that Completion
            // in hidden slots, runs the finalizer once, then re-issues the saved Completion unless
            // the finalizer itself completed abruptly. The same representation also survives a
            // coroutine finalizer's suspension.
            Stmt::Try {
                block,
                handler,
                finalizer,
            } => {
                if let Some(finalizer) = finalizer {
                    let completion_slot = self.fresh_slot("%finally-value%");
                    let completion_kind = self.fresh_slot("%finally-kind%");
                    let completion_target_depth = self.fresh_slot("%finally-target-depth%");
                    let push_finally = self.emit(Op::PushFinally(0, 0, 0, 0, 0));
                    self.try_depth += 1;
                    self.finally_depths.push(self.try_depth);

                    if let Some((param, catch_body)) = handler {
                        let push_catch = self.emit(Op::PushHandler(0));
                        self.try_depth += 1;
                        self.push_compile_scope();
                        let try_result = self.without_tail(|compiler| compiler.block_body(block));
                        self.pop_compile_scope();
                        try_result?;
                        self.emit(Op::PopHandler);
                        self.try_depth -= 1;
                        let after_catch = self.emit(Op::Jump(0));
                        let catch_pc = self.ops.len() as u32;
                        match &mut self.ops[push_catch] {
                            Op::PushHandler(target) => *target = catch_pc,
                            _ => unreachable!(),
                        }
                        self.without_tail(|compiler| {
                            compiler.catch_clause(param.as_ref(), catch_body)
                        })?;
                        self.patch(after_catch);
                    } else {
                        self.push_compile_scope();
                        let try_result = self.without_tail(|compiler| compiler.block_body(block));
                        self.pop_compile_scope();
                        try_result?;
                    }

                    // Normal completion: remove the handler and tag the saved completion as
                    // normal. Throw/return pads are entered only after drive_vm already popped it.
                    self.emit(Op::PopHandler);
                    self.try_depth -= 1;
                    self.finally_depths.pop();
                    let normal = self.const_idx(Value::Num(0.0));
                    self.emit(Op::Const(normal));
                    self.emit(Op::StoreLocal(completion_kind));
                    let normal_to_finally = self.emit(Op::Jump(0));

                    let throw_pc = self.ops.len() as u32;
                    self.emit(Op::StoreLocal(completion_slot));
                    let throwing = self.const_idx(Value::Num(1.0));
                    self.emit(Op::Const(throwing));
                    self.emit(Op::StoreLocal(completion_kind));
                    let throw_to_finally = self.emit(Op::Jump(0));

                    let return_pc = self.ops.len() as u32;
                    self.emit(Op::StoreLocal(completion_slot));
                    let returning = self.const_idx(Value::Num(2.0));
                    self.emit(Op::Const(returning));
                    self.emit(Op::StoreLocal(completion_kind));
                    let return_to_finally = self.emit(Op::Jump(0));

                    let bare_return_pc = self.ops.len() as u32;
                    let bare_returning = self.const_idx(Value::Num(5.0));
                    self.emit(Op::Const(bare_returning));
                    self.emit(Op::StoreLocal(completion_kind));
                    let bare_return_to_finally = self.emit(Op::Jump(0));

                    // AsyncGeneratorUnwrapYieldResumption and async-generator ReturnStatement
                    // have already awaited their values before creating the Return Completion.
                    // Keep those resumptions distinct so finalization cannot await them again.
                    let resume_return_pc = self.ops.len() as u32;
                    self.emit(Op::StoreLocal(completion_slot));
                    let resume_returning = self.const_idx(Value::Num(3.0));
                    self.emit(Op::Const(resume_returning));
                    self.emit(Op::StoreLocal(completion_kind));
                    let resume_return_to_finally = self.emit(Op::Jump(0));

                    // A break/continue pad receives its patched bytecode destination followed by
                    // the handler depth at that destination. Both are exact u32 integers in the
                    // Number representation and survive arbitrary finalizer suspension.
                    let jump_pc = self.ops.len() as u32;
                    self.emit(Op::StoreLocal(completion_target_depth));
                    self.emit(Op::StoreLocal(completion_slot));
                    let jumping = self.const_idx(Value::Num(4.0));
                    self.emit(Op::Const(jumping));
                    self.emit(Op::StoreLocal(completion_kind));

                    match &mut self.ops[push_finally] {
                        Op::PushFinally(
                            throw_target,
                            return_target,
                            bare_return_target,
                            resume_return_target,
                            jump_target,
                        ) => {
                            *throw_target = throw_pc;
                            *return_target = return_pc;
                            *bare_return_target = bare_return_pc;
                            *resume_return_target = resume_return_pc;
                            *jump_target = jump_pc;
                        }
                        _ => unreachable!(),
                    }
                    self.patch(normal_to_finally);
                    self.patch(throw_to_finally);
                    self.patch(return_to_finally);
                    self.patch(bare_return_to_finally);
                    self.patch(resume_return_to_finally);

                    // Finally's normal value is discarded; an abrupt finalizer replaces the
                    // incoming completion, including its StatementList value. Saving at this
                    // common landing point also covers break/continue routed through handlers.
                    let saved_script_completion = self.script_completion.map(|completion| {
                        let saved = self.fresh_slot("%finally-script-completion%");
                        self.emit(Op::LoadLocal(completion));
                        self.emit(Op::StoreLocal(saved));
                        self.reset_script_completion();
                        saved
                    });
                    self.push_compile_scope();
                    let finally_result = self.block_body(finalizer);
                    self.pop_compile_scope();
                    finally_result?;
                    if let Some(saved) = saved_script_completion {
                        self.emit(Op::LoadLocal(saved));
                        self.emit(Op::StoreLocal(
                            self.script_completion.expect("script completion"),
                        ));
                        self.emit(Op::Undef);
                        self.emit(Op::StoreLocal(saved));
                    }

                    self.emit(Op::LoadLocal(completion_kind));
                    self.emit(Op::Const(throwing));
                    self.emit(Op::StrictEq);
                    let not_throw = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::LoadLocal(completion_slot));
                    self.emit(Op::Throw);
                    self.patch(not_throw);
                    self.emit(Op::LoadLocal(completion_kind));
                    self.emit(Op::Const(returning));
                    self.emit(Op::StrictEq);
                    let not_return = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::LoadLocal(completion_slot));
                    self.emit(Op::Return);
                    self.patch(not_return);
                    self.emit(Op::LoadLocal(completion_kind));
                    self.emit(Op::Const(bare_returning));
                    self.emit(Op::StrictEq);
                    let not_bare_return = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::ReturnBare);
                    self.patch(not_bare_return);
                    self.emit(Op::LoadLocal(completion_kind));
                    self.emit(Op::Const(resume_returning));
                    self.emit(Op::StrictEq);
                    let not_resume_return = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::LoadLocal(completion_slot));
                    self.emit(Op::ResumeReturn);
                    self.patch(not_resume_return);
                    self.emit(Op::LoadLocal(completion_kind));
                    self.emit(Op::Const(jumping));
                    self.emit(Op::StrictEq);
                    let not_jump = self.emit(Op::JumpIfFalse(0));
                    self.emit(Op::LoadLocal(completion_slot));
                    self.emit(Op::LoadLocal(completion_target_depth));
                    self.emit(Op::ResumeJump);
                    self.patch(not_jump);
                    return Ok(());
                }

                let Some((param, catch_body)) = handler else {
                    return Err(Bail);
                };
                let push = self.emit(Op::PushHandler(0));
                self.try_depth += 1;
                self.push_compile_scope();
                let try_result = self.without_tail(|compiler| compiler.block_body(block));
                self.pop_compile_scope();
                try_result?;
                self.emit(Op::PopHandler);
                self.try_depth -= 1;
                let after_catch = self.emit(Op::Jump(0));
                let catch_pc = self.ops.len() as u32;
                match &mut self.ops[push] {
                    Op::PushHandler(target) => *target = catch_pc,
                    _ => unreachable!(),
                }
                self.catch_clause(param.as_ref(), catch_body)?;
                self.patch(after_catch);
                Ok(())
            }
            // For-in/of iteration keeps its iterator/enumeration record in hidden slots. Sync
            // and async bodies share completion-aware handlers; `for await` adds explicit Await
            // points for stepping and AsyncIteratorClose without reserving a native thread.
            Stmt::ForInOf {
                decl,
                left,
                right,
                of,
                is_await,
                body,
                ..
            } => {
                let labels = std::mem::take(&mut self.pending_labels);
                let fragment_root = self.fragment_root.take();
                if *is_await && (!*of || !self.is_coroutine) {
                    return Err(Bail);
                }
                // A lexical head is in TDZ while the iterable expression evaluates. Captured
                // leaves use a real head Environment Record and a fresh sibling record per
                // iteration; uncaptured leaves retain the allocation-free slot representation.
                self.push_compile_scope();
                let mut runtime_bindings = Vec::new();
                if let Some(
                    kind @ (DeclKind::Let
                    | DeclKind::Const
                    | DeclKind::Using
                    | DeclKind::AwaitUsing),
                ) = decl
                {
                    let mut names = crate::fasthash::FastSet::default();
                    pat_idents(left, &mut names);
                    let mut names: Vec<_> = names.into_iter().collect();
                    names.sort();
                    runtime_bindings.extend(
                        names
                            .into_iter()
                            .filter(|name| {
                                self.fragment_entry || self.runtime_lexicals.contains(name)
                            })
                            .map(|name| (name, !matches!(kind, DeclKind::Let))),
                    );
                }
                let runtime_scope = (!runtime_bindings.is_empty())
                    .then(|| self.push_runtime_lexical_scope(runtime_bindings));
                enum Bind {
                    Slot(u16),
                    AssignmentSlot(u16),
                    Cap(u32),
                    Name(u32),
                    Lex(u32),
                    Using {
                        slot: u16,
                        is_async: bool,
                    },
                    UsingLex {
                        name: u32,
                        is_async: bool,
                    },
                    AssignmentMember,
                    /// Destructuring lexical head: bound by `destructure_store` INSIDE the
                    /// body's handler region (a binding throw must IteratorClose in throw mode,
                    /// which is exactly what the body's abort pad does).
                    Pattern(DeclKind),
                }
                let bind = match (left, decl) {
                    (
                        Pattern::Ident(name),
                        Some(kind @ (DeclKind::Using | DeclKind::AwaitUsing)),
                    ) if *of => {
                        if self.current_lexical_env_has(name) {
                            Bind::UsingLex {
                                name: self.name_idx(name),
                                is_async: matches!(kind, DeclKind::AwaitUsing),
                            }
                        } else if self.env_names.contains_key(name) {
                            self.pop_compile_scope();
                            return Err(Bail);
                        } else {
                            let slot = self.fresh_slot(name);
                            self.scope_bind(name, slot, true);
                            self.tdz_slots.insert(slot);
                            self.emit(Op::Tdz(slot));
                            Bind::Using {
                                slot,
                                is_async: matches!(kind, DeclKind::AwaitUsing),
                            }
                        }
                    }
                    (_, Some(DeclKind::Using | DeclKind::AwaitUsing)) => {
                        self.pop_compile_scope();
                        return Err(Bail);
                    }
                    (Pattern::Ident(name), Some(kind @ (DeclKind::Let | DeclKind::Const))) => {
                        if self.current_lexical_env_has(name) {
                            Bind::Lex(self.name_idx(name))
                        } else {
                            // ECMA-262 §14.7.5.5/§14.7.5.8 creates the loop-head lexical in a
                            // fresh Environment Record. An outer activation/module binding with
                            // the same spelling is therefore shadowed, never a reason to reuse or
                            // reject the new slot.
                            let slot = self.fresh_slot(name);
                            self.scope_bind(name, slot, matches!(kind, DeclKind::Const));
                            if matches!(kind, DeclKind::Let | DeclKind::Const) {
                                self.tdz_slots.insert(slot);
                                self.emit(Op::Tdz(slot));
                            }
                            Bind::Slot(slot)
                        }
                    }
                    (pat, Some(kind @ (DeclKind::Let | DeclKind::Const))) => {
                        // A destructuring lexical head: fresh uncaptured slots for every leaf,
                        // declared (in TDZ) before `right` like the ident path. `var` patterns
                        // would have to write hoisted function-scope bindings — those stay in
                        // the oracle.
                        if self
                            .declare_lexical_pattern(pat, matches!(kind, DeclKind::Const))
                            .is_err()
                        {
                            self.pop_compile_scope();
                            return Err(Bail);
                        }
                        Bind::Pattern(*kind)
                    }
                    (Pattern::Ident(name), Some(DeclKind::Var)) => match self.home(name) {
                        // ECMA-262 §14.7.5.7 var-binding writes the already-instantiated
                        // VariableEnvironment binding; it does not create a per-iteration slot.
                        Some(Home::Slot(slot, false)) => Bind::Slot(slot),
                        Some(Home::Env(false)) => Bind::Cap(self.name_idx(name)),
                        None if self.fragment_entry
                            || self.script_vars.contains(name)
                            || !self.with_scope_floors.is_empty() =>
                        {
                            Bind::Name(self.name_idx(name))
                        }
                        _ => {
                            self.pop_compile_scope();
                            return Err(Bail);
                        }
                    },
                    (pat, Some(DeclKind::Var)) => {
                        // Hoisting created every leaf home at function entry. Pattern binding is
                        // inside the loop-body handler so an abrupt iterator/destructuring step
                        // follows the same IteratorClose path as lexical patterns.
                        let mut leaf_names = crate::fasthash::FastSet::default();
                        pat_idents(pat, &mut leaf_names);
                        if leaf_names.iter().any(|name| {
                            !self.fragment_entry
                                && self.home(name).is_none()
                                && !self.script_vars.contains(name)
                        }) {
                            self.pop_compile_scope();
                            return Err(Bail);
                        }
                        Bind::Pattern(DeclKind::Var)
                    }
                    (Pattern::Ident(name), None) => match self.home(name) {
                        Some(Home::Slot(slot, is_const)) => {
                            if is_const {
                                self.pop_compile_scope();
                                return Err(Bail);
                            }
                            Bind::AssignmentSlot(slot)
                        }
                        Some(Home::Env(is_const)) => {
                            if is_const {
                                self.pop_compile_scope();
                                return Err(Bail);
                            }
                            Bind::Cap(self.name_idx(name))
                        }
                        None => Bind::Name(self.name_idx(name)),
                    },
                    (Pattern::Member(_), None) => Bind::AssignmentMember,
                    // Destructuring *assignment* heads are represented by the original covered
                    // Array/ObjectLiteral in Pattern::Member. They lower through AssignTarget
                    // below, retaining exact Reference-before-read and inner IteratorClose order.
                    (_, None) => Bind::AssignmentMember,
                };
                let er = if let Some(scope) = runtime_scope {
                    self.environment_scope(|compiler| compiler.expr(right), scope)
                } else {
                    self.expr(right)
                };
                if er.is_err() {
                    self.pop_compile_scope();
                    return er;
                }
                if !of {
                    // ForIn/OfHeadEvaluation(enumerate): snapshot candidate keys once, then check
                    // whether each object property still exists immediately before visiting it.
                    // Null/undefined and non-string primitives naturally produce no candidates.
                    let source_s = self.fresh_slot("%for-in-source%");
                    let keys_s = self.fresh_slot("%for-in-keys%");
                    let index_s = self.fresh_slot("%for-in-index%");
                    self.emit(Op::Dup);
                    self.emit(Op::StoreLocal(source_s));
                    self.emit(Op::ForInKeys);
                    self.emit(Op::StoreLocal(keys_s));
                    let zero = self.const_idx(Value::Num(0.0));
                    self.emit(Op::Const(zero));
                    self.emit(Op::StoreLocal(index_s));
                    if matches!(fragment_root, Some(loop_fragment::RootKind::ForIn)) {
                        // Head evaluation already ran in the AST. Keep only its compile-time
                        // binding schema; transfer the exact source/backing/cursor owners.
                        self.ops.clear();
                        self.fragment_seed_slots = vec![source_s, keys_s, index_s];
                    }
                    self.loops.push(LoopCtx {
                        labels,
                        entry_try_depth: self.try_depth,
                        ..LoopCtx::default()
                    });
                    let loop_head = self.ops.len();
                    self.emit(Op::ForInStepL(keys_s, index_s, source_s));
                    let jexit = self.emit(Op::JumpIfFalse(0));
                    if let Some(scope) = runtime_scope {
                        self.emit(Op::PushLex(scope));
                    }
                    let compile_iteration = |compiler: &mut Compiler| match bind {
                        Bind::Slot(slot) => {
                            compiler.emit(Op::StoreLocal(slot));
                            compiler.stmt(body)
                        }
                        Bind::AssignmentSlot(slot) => {
                            compiler.check_assignment_local_initialized(slot);
                            compiler.emit(Op::StoreLocal(slot));
                            compiler.stmt(body)
                        }
                        Bind::Cap(name) => {
                            compiler.emit(Op::StoreCap(name));
                            compiler.stmt(body)
                        }
                        Bind::Name(name) => {
                            compiler.emit_store_name(name);
                            compiler.stmt(body)
                        }
                        Bind::Lex(name) => {
                            compiler.emit(Op::InitLex(name));
                            compiler.stmt(body)
                        }
                        Bind::Using { .. } | Bind::UsingLex { .. } => Err(Bail),
                        Bind::AssignmentMember => compiler
                            .for_head_member_store(left)
                            .and_then(|()| compiler.stmt(body)),
                        Bind::Pattern(kind) => compiler
                            .destructure_store(left, kind)
                            .and_then(|()| compiler.stmt(body)),
                    };
                    let result = if let Some(scope) = runtime_scope {
                        self.environment_scope(compile_iteration, scope)
                    } else {
                        compile_iteration(self)
                    };
                    let ctx = self.loops.pop().expect("just pushed");
                    self.pop_compile_scope();
                    result?;
                    for jump in ctx.continues {
                        self.patch_to(jump, loop_head as u32);
                    }
                    self.emit(Op::Jump(loop_head as u32));
                    self.patch(jexit);
                    self.emit(Op::Pop); // exhausted-step placeholder
                    for jump in ctx.breaks {
                        self.patch(jump);
                    }
                    return Ok(());
                }
                let iter_s = self.fresh_slot("%iter%");
                let next_s = self.fresh_slot("%next%");
                let async_from_sync_s = if *is_await {
                    let slot = self.fresh_slot("%async-from-sync%");
                    self.emit(Op::GetAsyncIter);
                    self.emit(Op::StoreLocal(slot));
                    self.emit(Op::StoreLocal(next_s));
                    self.emit(Op::StoreLocal(iter_s));
                    Some(slot)
                } else {
                    self.emit(Op::GetIter);
                    self.emit(Op::StoreLocal(next_s));
                    self.emit(Op::StoreLocal(iter_s));
                    None
                };
                self.loops.push(LoopCtx {
                    labels,
                    entry_try_depth: self.try_depth,
                    foreach_iter: Some(iter_s),
                    foreach_async_from_sync: async_from_sync_s,
                    ..Default::default()
                });
                if matches!(fragment_root, Some(loop_fragment::RootKind::ForOf)) {
                    self.ops.clear();
                    self.fragment_seed_slots = vec![iter_s, next_s];
                }
                let loop_head = self.ops.len();
                if let Some(from_sync_s) = async_from_sync_s {
                    let done_s = self.fresh_slot("%async-step-done%");
                    self.emit(Op::AsyncIterStepL(iter_s, next_s, from_sync_s, done_s));
                    self.emit(Op::AsyncIterResumeL(from_sync_s, done_s));
                } else {
                    self.emit(Op::IterStepL(iter_s, next_s));
                }
                let jexit = self.emit(Op::JumpIfFalse(0));
                // ForIn/OfBodyEvaluation includes every form of BindingInitialization and
                // assignment in the status whose abrupt completion closes the iterator. Push the
                // body handler before even the identifier stores: a strict unresolved assignment
                // or environment operation can be abrupt just like a member/pattern PutValue.
                let push = if self.is_coroutine || self.fragment_entry {
                    self.emit(Op::PushIterator(0, 0, 0, 0))
                } else {
                    self.emit(Op::PushHandler(0))
                };
                self.try_depth += 1;
                self.loops.last_mut().expect("just pushed").body_try_depth = self.try_depth;
                if let Some(scope) = runtime_scope {
                    self.emit(Op::PushLex(scope));
                }
                let compile_iteration = |compiler: &mut Compiler| match bind {
                    Bind::Slot(slot) => {
                        compiler.emit(Op::StoreLocal(slot));
                        compiler.stmt(body)
                    }
                    Bind::AssignmentSlot(slot) => {
                        compiler.check_assignment_local_initialized(slot);
                        compiler.emit(Op::StoreLocal(slot));
                        compiler.stmt(body)
                    }
                    Bind::Cap(name) => {
                        compiler.emit(Op::StoreCap(name));
                        compiler.stmt(body)
                    }
                    Bind::Name(name) => {
                        compiler.emit_store_name(name);
                        compiler.stmt(body)
                    }
                    Bind::Lex(name) => {
                        compiler.emit(Op::InitLex(name));
                        compiler.stmt(body)
                    }
                    Bind::Using { slot, is_async } => compiler.disposal_scope(|compiler| {
                        compiler.emit(Op::AddDisposable(is_async));
                        compiler.emit(Op::StoreLocal(slot));
                        compiler.stmt(body)
                    }),
                    Bind::UsingLex { name, is_async } => compiler.disposal_scope(|compiler| {
                        compiler.emit(Op::AddDisposable(is_async));
                        compiler.emit(Op::InitLex(name));
                        compiler.stmt(body)
                    }),
                    Bind::Pattern(kind) => compiler
                        .destructure_store(left, kind)
                        .and_then(|()| compiler.stmt(body)),
                    Bind::AssignmentMember => compiler
                        .for_head_member_store(left)
                        .and_then(|()| compiler.stmt(body)),
                };
                let r = self.without_tail(|compiler| {
                    if let Some(scope) = runtime_scope {
                        compiler.environment_scope(compile_iteration, scope)
                    } else {
                        compile_iteration(compiler)
                    }
                });
                let ctx = self.loops.pop().expect("just pushed");
                self.pop_compile_scope();
                r?;
                self.emit(Op::PopHandler);
                self.try_depth -= 1;
                // continues re-enter at the step (the loop head re-pushes the body handler —
                // their cleanup already popped it).
                for j in ctx.continues {
                    self.patch_to(j, loop_head as u32);
                }
                self.emit(Op::Jump(0));
                let jback = self.ops.len() - 1;
                match &mut self.ops[jback] {
                    Op::Jump(t) => *t = loop_head as u32,
                    _ => unreachable!(),
                }
                // The body's completion pads implement ForIn/OfBodyEvaluation step 13. Throw
                // closes in throw mode (preserving the original error); every return closes in
                // normal mode, where a close error replaces the saved completion.
                let abort_pc = self.ops.len() as u32;
                if let Some(from_sync_s) = async_from_sync_s {
                    self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, true));
                    self.emit(Op::Throw);
                } else {
                    self.emit(Op::IterAbortL(iter_s));
                }
                if self.is_coroutine || self.fragment_entry {
                    let return_pc = self.ops.len() as u32;
                    if let Some(from_sync_s) = async_from_sync_s {
                        self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, false));
                    } else {
                        self.emit(Op::IterCloseL(iter_s));
                    }
                    self.emit(Op::Return);
                    let bare_return_pc = self.ops.len() as u32;
                    if let Some(from_sync_s) = async_from_sync_s {
                        self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, false));
                    } else {
                        self.emit(Op::IterCloseL(iter_s));
                    }
                    self.emit(Op::ReturnBare);
                    let resume_return_pc = self.ops.len() as u32;
                    if let Some(from_sync_s) = async_from_sync_s {
                        self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, false));
                    } else {
                        self.emit(Op::IterCloseL(iter_s));
                    }
                    self.emit(Op::ResumeReturn);
                    match &mut self.ops[push] {
                        Op::PushIterator(
                            throw_target,
                            return_target,
                            bare_return_target,
                            resume_return_target,
                        ) => {
                            *throw_target = abort_pc;
                            *return_target = return_pc;
                            *bare_return_target = bare_return_pc;
                            *resume_return_target = resume_return_pc;
                        }
                        _ => unreachable!(),
                    }
                } else {
                    match &mut self.ops[push] {
                        Op::PushHandler(throw_target) => *throw_target = abort_pc,
                        _ => unreachable!(),
                    }
                }
                // Exhaustion lands here (the step's bool was false): drop the undefined
                // placeholder the step pushed; no close on a completed iterator.
                self.patch(jexit);
                self.emit(Op::Pop);
                // Breaks jump here too — their cleanup (pop handler + close) ran at the site.
                let after = self.ops.len() as u32;
                for j in ctx.breaks {
                    self.patch_to(j, after);
                }
                Ok(())
            }
            // Source Text Module declarations are link-time metadata. Exported declarations still
            // execute normally against the module environment; default expressions and anonymous
            // classes initialize the synthetic `*default*` live binding using NamedEvaluation.
            Stmt::Import(_) | Stmt::ExportNamed { .. } | Stmt::ExportAll { .. }
                if self.module_body =>
            {
                Ok(())
            }
            Stmt::ExportDecl(inner) if self.module_body => self.stmt(inner),
            Stmt::ExportDefault(inner) if self.module_body => match &**inner {
                Stmt::Expr(expression) => {
                    self.named_expr(expression, "default")?;
                    let name = self.name_idx("*default*");
                    self.emit(Op::StoreCapInit(name));
                    Ok(())
                }
                Stmt::FuncDecl(function) if function.name.is_none() => Ok(()),
                Stmt::ClassDecl(class) if class.name.is_none() => {
                    self.named_expr(&Expr::Class(class.clone()), "default")?;
                    let name = self.name_idx("*default*");
                    self.emit(Op::StoreCapInit(name));
                    Ok(())
                }
                declaration => self.stmt(declaration),
            },
            Stmt::With { obj, body }
                if self.is_coroutine || self.script_body || self.fragment_entry =>
            {
                self.with_scope(obj, body)
            }
            other => {
                log_bail("stmt", &format!("{:.60}", format!("{other:?}")));
                Err(Bail)
            }
        }
    }

    /// Store the iterator/enumeration value on top of the stack into a member-expression loop
    /// head. ForIn/OfBodyEvaluation obtains the value first, then evaluates the LHS Reference on
    /// every iteration; the hidden slot keeps that ordering while evaluating base and key once.
    fn for_head_member_store(&mut self, target: &Pattern) -> CResult {
        let Pattern::Member(target) = target else {
            return Err(Bail);
        };
        let value_slot = self.fresh_slot("%for-head-value%");
        self.emit(Op::StoreLocal(value_slot));
        match &**target {
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                self.emit(Op::LoadLocal(value_slot));
                let name = self.property_name_idx(prop);
                let cache = self.new_cache(name);
                self.emit(Op::SetPropDrop(name, cache));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.expr(obj)?;
                self.expr(index)?;
                self.emit(Op::LoadLocal(value_slot));
                self.emit(Op::SetElemDrop);
                Ok(())
            }
            target @ (Expr::Array(_) | Expr::Object(_)) => {
                // ForIn/OfBodyEvaluation uses the same AssignmentPattern algorithm as `=`.
                // Lower its references and iterator cleanup explicitly in every execution tier.
                self.emit(Op::LoadLocal(value_slot));
                self.assignment_pattern(target)
            }
            _ => Err(Bail),
        }
    }

    fn projected_locals(&self) -> Vec<AssignmentLocal> {
        let mut seen = crate::fasthash::FastSet::default();
        let mut locals = Vec::new();
        for scope in self.scopes.iter().rev() {
            for (name, slot, is_const) in scope.iter().rev() {
                if !name.starts_with('%') && seen.insert(name.clone()) {
                    locals.push(AssignmentLocal {
                        name: Rc::from(name.as_str()),
                        slot: *slot,
                        mutable: !*is_const,
                    });
                }
            }
        }
        locals
    }

    /// The slot locals a retained expression can observe, projected into its evaluation
    /// scope and written back afterwards. Only identifier references outside every nested
    /// function can reach a slot: CaptureScan homes any depth-0 binding that a function,
    /// arrow, method or field initializer names in the activation, never in a slot. Projecting
    /// only those references keeps every visible binding while avoiding a full copy of a
    /// large function's locals for each retained class (platform bootstraps evaluate hundreds).
    /// A direct eval can name any binding, so it keeps the complete projection.
    fn retained_expr_locals(&self, expr: &Expr) -> Vec<AssignmentLocal> {
        let locals = self.projected_locals();
        if self.direct_eval {
            return locals;
        }
        let mut names = crate::fasthash::FastSet::default();
        if !retained_expr_names(expr, &mut names) {
            return locals;
        }
        locals
            .into_iter()
            .filter(|local| names.contains(&*local.name))
            .collect()
    }

    fn retain_eval_expr(&mut self, expr: &Expr) -> CResult {
        self.retain_named_eval_expr(expr, None)
    }

    fn retain_named_eval_expr(&mut self, expr: &Expr, name: Option<&str>) -> CResult {
        // The projected evaluator answers GetNewTarget by searching the Environment Record chain.
        // A lean frame has no record of its own, so that search could find an enclosing
        // function's [[NewTarget]] (ECMA-262 §9.4.5). Such a frame needs the general activation.
        if self.lean_new_target && crate::ast::expr_scan_flags(expr) & SCAN_NEW_TARGET != 0 {
            log_bail(
                "expr",
                "retained expression observing an activation-less new.target",
            );
            return Err(Bail);
        }
        // The projected evaluator resolves `this` through an Environment Record. Keeping one in
        // an ordinary bridged frame also covers super-property helpers. A derived constructor
        // already has the live, initially-uninitialized record that SuperCall must bind; a new
        // activation-local `this` would shadow it and break both GetThisBinding and super().
        if !self.derived_constructor {
            self.env_this = true;
        }
        let plan = self.eval_exprs.len() as u32;
        self.eval_exprs.push(EvalExprPlan {
            expr: expr.clone(),
            locals: self.retained_expr_locals(expr),
            strict: self.strict,
            name: name.map(str::to_string),
        });
        self.emit(Op::EvalExpr(plan));
        Ok(())
    }

    fn prepare_identifier_reference(&mut self, name: &str) -> Result<PreparedAssignmentRef, Bail> {
        let name_index = self.name_idx(name);
        Ok(match self.home(name) {
            Some(Home::Slot(slot, is_const)) => PreparedAssignmentRef::Local {
                slot,
                is_const,
                name: name_index,
            },
            Some(Home::Env(is_const)) => PreparedAssignmentRef::Captured {
                name: name_index,
                is_const,
            },
            None if self.name_reference_can_change(name) => {
                let reference = self.fresh_reference()?;
                self.emit(Op::ResolveNameRef(name_index, reference));
                PreparedAssignmentRef::Reference(reference)
            }
            None => PreparedAssignmentRef::Name(name_index),
        })
    }

    fn prepare_assignment_reference(
        &mut self,
        target: &Expr,
    ) -> Result<PreparedAssignmentRef, Bail> {
        match target {
            Expr::Paren(inner) => self.prepare_assignment_reference(inner),
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                Ok(self.save_assignment_super_reference())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                Ok(self.save_assignment_super_reference())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if prop.starts_with('#') => {
                self.expr(obj)?;
                let base = self.fresh_slot("%assignment-private-base%");
                self.emit(Op::StoreLocal(base));
                let name = self.property_name_idx(prop);
                Ok(PreparedAssignmentRef::Private { base, name })
            }
            Expr::Ident(name, _) => self.prepare_identifier_reference(name),
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                let base = self.fresh_slot("%assignment-base%");
                self.emit(Op::StoreLocal(base));
                let name = self.property_name_idx(prop);
                let cache = self.new_cache(name);
                Ok(PreparedAssignmentRef::Property { base, name, cache })
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.expr(obj)?;
                self.expr(index)?;
                // EvaluatePropertyAccessWithExpressionKey retains the raw base/key in its
                // Reference. PutValue performs the nullish check and ToPropertyKey only after
                // the iterator step/default, including when either operation has side effects.
                let key = self.fresh_slot("%assignment-key%");
                let base = self.fresh_slot("%assignment-base%");
                self.emit(Op::StoreLocal(key));
                self.emit(Op::StoreLocal(base));
                Ok(PreparedAssignmentRef::Element { base, key })
            }
            _ => Err(Bail),
        }
    }

    fn save_assignment_super_reference(&mut self) -> PreparedAssignmentRef {
        // MakeSuperPropertyReference retains the uncoerced computed key: PutValue performs
        // ToPropertyKey only after the iterator/property read and initializer have completed.
        let base = self.fresh_slot("%assignment-super-base%");
        let key = self.fresh_slot("%assignment-super-key%");
        let receiver = self.fresh_slot("%assignment-super-this%");
        self.emit(Op::StoreLocal(base));
        self.emit(Op::StoreLocal(key));
        self.emit(Op::StoreLocal(receiver));
        PreparedAssignmentRef::Super {
            receiver,
            key,
            base,
        }
    }

    /// SetMutableBinding throws on an uninitialized lexical, unlike declaration
    /// initialization. Reuse LoadLocal's checked TDZ path after RHS evaluation;
    /// var/temporary slots need no guard. A previous compound-assignment read
    /// already performs this check, so only plain writes call this helper.
    fn check_assignment_local_initialized(&mut self, slot: u16) {
        if self.tdz_slots.contains(&slot) {
            self.emit(Op::LoadLocal(slot));
            self.emit(Op::Pop);
        }
    }

    fn put_assignment_reference(&mut self, reference: PreparedAssignmentRef) {
        match reference {
            PreparedAssignmentRef::Local {
                slot,
                is_const,
                name,
            } => {
                if !is_const {
                    self.check_assignment_local_initialized(slot);
                }
                self.emit(if is_const {
                    Op::StoreConstLocal(slot, name)
                } else {
                    Op::StoreLocal(slot)
                });
            }
            PreparedAssignmentRef::Captured { name, is_const } => {
                self.emit(if is_const {
                    Op::StoreConstCap(name)
                } else {
                    Op::StoreCap(name)
                });
            }
            PreparedAssignmentRef::Name(name) => {
                self.emit_store_name(name);
            }
            PreparedAssignmentRef::Reference(reference) => {
                self.emit(Op::StoreRef(reference));
            }
            PreparedAssignmentRef::Property { base, name, cache } => {
                let value = self.fresh_slot("%assignment-value%");
                self.emit(Op::StoreLocal(value));
                self.emit(Op::LoadLocal(base));
                self.emit(Op::LoadLocal(value));
                self.emit(Op::SetPropDrop(name, cache));
            }
            PreparedAssignmentRef::Element { base, key } => {
                let value = self.fresh_slot("%assignment-value%");
                self.emit(Op::StoreLocal(value));
                self.emit(Op::LoadLocal(base));
                self.emit(Op::LoadLocal(key));
                self.emit(Op::LoadLocal(value));
                self.emit(Op::SetElemDrop);
            }
            PreparedAssignmentRef::Private { base, name } => {
                let value = self.fresh_slot("%assignment-value%");
                self.emit(Op::StoreLocal(value));
                self.emit(Op::LoadLocal(base));
                self.emit(Op::LoadLocal(value));
                let site = self.new_private_site();
                self.emit(Op::SetPrivate(name, site));
                self.emit(Op::Pop);
            }
            PreparedAssignmentRef::Super {
                receiver,
                key,
                base,
            } => {
                let value = self.fresh_slot("%assignment-value%");
                self.emit(Op::StoreLocal(value));
                self.emit(Op::LoadLocal(receiver));
                self.emit(Op::LoadLocal(key));
                self.emit(Op::LoadLocal(base));
                self.emit(Op::LoadLocal(value));
                self.emit(Op::SuperSet);
                self.emit(Op::Pop);
            }
        }
    }

    fn assignment_default(&mut self, core: &Expr, default: Option<&Expr>) -> CResult {
        let Some(default) = default else {
            return Ok(());
        };
        self.emit(Op::Dup);
        self.emit(Op::Undef);
        self.emit(Op::StrictEq);
        let present = self.emit(Op::JumpIfFalse(0));
        self.emit(Op::Pop);
        if let Expr::Ident(name, _) = core {
            self.named_expr(default, name)?;
        } else {
            self.expr(default)?;
        }
        self.patch(present);
        Ok(())
    }

    fn assignment_object_key(&mut self, source: u16, key: &PropKey) -> Result<u16, Bail> {
        self.emit(Op::LoadLocal(source));
        match key {
            PropKey::Ident(key) => {
                let value = self.const_idx(Value::lstr(key.clone()));
                self.emit(Op::Const(value));
            }
            PropKey::Str(key) => {
                let value = self.const_idx(Value::Str(key.clone().into()));
                self.emit(Op::Const(value));
            }
            PropKey::Num(key) => {
                let value = self.const_idx(Value::Num(*key));
                self.emit(Op::Const(value));
            }
            PropKey::Computed(key) => self.expr(key)?,
        }
        self.emit(Op::ToPropKey);
        let key_slot = self.fresh_slot("%assignment-object-key%");
        self.emit(Op::StoreLocal(key_slot));
        self.emit(Op::Pop); // retained source base used only to enforce Reference key ordering
        Ok(key_slot)
    }

    fn load_assignment_property(&mut self, source: u16, key: u16) {
        self.emit(Op::LoadLocal(source));
        self.emit(Op::LoadLocal(key));
        self.emit(Op::GetElem);
    }

    fn assignment_pattern(&mut self, target: &Expr) -> CResult {
        match target {
            Expr::Paren(inner) => self.assignment_pattern(inner),
            Expr::Array(elements) => self.assignment_array_pattern(elements),
            Expr::Object(properties) => self.assignment_object_pattern(properties),
            _ => Err(Bail),
        }
    }

    fn assignment_array_pattern(&mut self, elements: &[ArrayElem]) -> CResult {
        let iterator = self.fresh_slot("%assignment-iterator%");
        let next = self.fresh_slot("%assignment-next%");
        let done = self.fresh_slot("%assignment-done%");
        self.emit(Op::GetIter);
        self.emit(Op::StoreLocal(next));
        self.emit(Op::StoreLocal(iterator));
        let false_value = self.const_idx(Value::Bool(false));
        self.emit(Op::Const(false_value));
        self.emit(Op::StoreLocal(done));

        let handler = self.emit(Op::PushIterator(0, 0, 0, 0));
        self.try_depth += 1;
        for element in elements {
            match element {
                ArrayElem::Hole => {
                    self.emit(Op::DestructureStepL(iterator, next, done));
                    self.emit(Op::Pop);
                }
                ArrayElem::Item(element) => {
                    let (core, default) = match element {
                        Expr::Assign {
                            op: "=",
                            target,
                            value,
                            ..
                        } => (&**target, Some(&**value)),
                        _ => (element, None),
                    };
                    if matches!(core, Expr::Array(_) | Expr::Object(_)) {
                        self.emit(Op::DestructureStepL(iterator, next, done));
                        self.assignment_default(core, default)?;
                        self.assignment_pattern(core)?;
                    } else {
                        let reference = self.prepare_assignment_reference(core)?;
                        self.emit(Op::DestructureStepL(iterator, next, done));
                        self.assignment_default(core, default)?;
                        self.put_assignment_reference(reference);
                    }
                }
                ArrayElem::Spread(target) => {
                    if matches!(target, Expr::Array(_) | Expr::Object(_)) {
                        self.emit(Op::DestructureRestL(iterator, next, done));
                        self.assignment_pattern(target)?;
                    } else {
                        let reference = self.prepare_assignment_reference(target)?;
                        self.emit(Op::DestructureRestL(iterator, next, done));
                        self.put_assignment_reference(reference);
                    }
                }
            }
        }
        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        let after_pads = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::IterAbortIfNotDoneL(iterator, done));
        let return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::Return);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::ReturnBare);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::IterCloseIfNotDoneL(iterator, done));
        self.emit(Op::ResumeReturn);
        match &mut self.ops[handler] {
            Op::PushIterator(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
            }
            _ => unreachable!(),
        }
        self.patch(after_pads);
        Ok(())
    }

    fn assignment_object_pattern(&mut self, properties: &[PropDef]) -> CResult {
        self.emit(Op::DestructureGuard);
        let source = self.fresh_slot("%assignment-object%");
        self.emit(Op::StoreLocal(source));
        let mut excluded = Vec::new();
        for property in properties {
            match property {
                PropDef::KeyValue { key, value } | PropDef::Cover { key, value } => {
                    let key = self.assignment_object_key(source, key)?;
                    excluded.push(key);
                    let (core, default) = match value {
                        Expr::Assign {
                            op: "=",
                            target,
                            value,
                            ..
                        } => (&**target, Some(&**value)),
                        _ => (value, None),
                    };
                    if matches!(core, Expr::Array(_) | Expr::Object(_)) {
                        self.load_assignment_property(source, key);
                        self.assignment_default(core, default)?;
                        self.assignment_pattern(core)?;
                    } else {
                        let reference = self.prepare_assignment_reference(core)?;
                        self.load_assignment_property(source, key);
                        self.assignment_default(core, default)?;
                        self.put_assignment_reference(reference);
                    }
                }
                PropDef::Proto(value) => {
                    let key = self
                        .assignment_object_key(source, &PropKey::Ident("__proto__".to_string()))?;
                    excluded.push(key);
                    if matches!(value, Expr::Array(_) | Expr::Object(_)) {
                        self.load_assignment_property(source, key);
                        self.assignment_pattern(value)?;
                    } else {
                        let reference = self.prepare_assignment_reference(value)?;
                        self.load_assignment_property(source, key);
                        self.put_assignment_reference(reference);
                    }
                }
                PropDef::Spread(target) => {
                    let reference = self.prepare_assignment_reference(target)?;
                    self.emit(Op::LoadLocal(source));
                    for key in &excluded {
                        self.emit(Op::LoadLocal(*key));
                    }
                    self.emit(Op::ObjectRest(excluded.len() as u16));
                    self.put_assignment_reference(reference);
                }
                PropDef::Method { .. } | PropDef::Getter { .. } | PropDef::Setter { .. } => {
                    return Err(Bail);
                }
            }
        }
        Ok(())
    }

    /// Emit the bookkeeping a `break`/`continue` targeting `self.loops[target]` must run before
    /// its jump: pop every `try`/for-of-body handler region opened since the target's entry (a
    /// stale handler would catch unrelated throws later in the frame), and IteratorClose each
    /// for-of iterator being abandoned — the target's own iterator too for a `break`, but not
    /// for a `continue` (the loop keeps iterating). Multiple levels use abrupt-jump cleanup pads
    /// so close errors cascade through the outer loops' existing throw-mode handlers.
    fn emit_exit_jump(&mut self, target: usize, is_continue: bool) -> Result<usize, Bail> {
        let floor = self.loops[target].entry_try_depth;
        let crosses_finally = self
            .finally_depths
            .iter()
            .any(|finally_depth| *finally_depth > floor && *finally_depth <= self.try_depth);
        // For-of levels whose iterator is abandoned by this jump.
        let closes: Vec<(usize, u16, Option<u16>, u32)> = self
            .loops
            .iter()
            .enumerate()
            .skip(if is_continue { target + 1 } else { target })
            .filter_map(|(k, c)| {
                c.foreach_iter
                    .map(|it| (k, it, c.foreach_async_from_sync, c.body_try_depth))
            })
            .collect();
        if crosses_finally || closes.len() > 1 {
            // ECMA-262 §14.15.3 preserves a break/continue Completion when the finalizer is
            // normal. Handler unwinding therefore owns the jump. Abandoned for-of iterators close
            // inside-out: unwind only to each loop's entry, close with the outer body handlers
            // still active, then resume. Consequently a close throw replaces the jump and is
            // fed through every outer iterator's throw-mode close by its existing catch pad.
            for &(_, iter_s, async_from_sync_s, body_depth) in closes.iter().rev() {
                let to_cleanup = self.emit(Op::AbruptJump(0, body_depth - 1));
                let cleanup_pc = self.ops.len() as u32;
                self.patch_to(to_cleanup, cleanup_pc);
                if let Some(from_sync_s) = async_from_sync_s {
                    self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, false));
                } else {
                    self.emit(Op::IterCloseL(iter_s));
                }
            }
            return Ok(self.emit(Op::AbruptJump(0, floor)));
        }
        let mut depth_now = self.try_depth;
        if let Some(&(_, iter_s, async_from_sync_s, body_depth)) = closes.last() {
            // Pop the regions inside the for-of body, then its own body handler, then close.
            for _ in body_depth..depth_now {
                self.emit(Op::PopHandler);
            }
            self.emit(Op::PopHandler);
            if let Some(from_sync_s) = async_from_sync_s {
                self.emit(Op::AsyncIterCloseL(iter_s, from_sync_s, false));
            } else {
                self.emit(Op::IterCloseL(iter_s));
            }
            depth_now = body_depth - 1;
        }
        // Remaining regions down to the target's entry (plain `try`s between the loops — and for
        // a continue to a for-of, its own body handler, which the loop head re-pushes).
        for _ in floor..depth_now {
            self.emit(Op::PopHandler);
        }
        Ok(self.emit(Op::Jump(0)))
    }

    fn switch_body(&mut self, discriminant: u16, cases: &[SwitchCase]) -> CResult {
        for case in cases {
            for statement in &case.body {
                let statement = lexical_declaration_statement(statement);
                match statement {
                    Stmt::VarDecl {
                        kind: kind @ (DeclKind::Let | DeclKind::Const),
                        decls,
                    } => {
                        let is_const = matches!(kind, DeclKind::Const);
                        for (pattern, _) in decls {
                            self.declare_lexical_pattern(pattern, is_const)?;
                        }
                    }
                    Stmt::ClassDecl(class) => {
                        let name = class.name.as_ref().ok_or(Bail)?;
                        self.declare_lexical_pattern(&Pattern::Ident(name.clone()), false)?;
                    }
                    Stmt::VarDecl {
                        kind: DeclKind::Using | DeclKind::AwaitUsing,
                        ..
                    } => return Err(Bail),
                    Stmt::FuncDecl(function) => {
                        self.declare_block_function_binding(function)?;
                    }
                    _ => {}
                }
            }
        }
        // CaseBlockEvaluation uses one shared lexical environment. Its block functions are
        // instantiated after the discriminant but before the first case test, and declarations in
        // later/default clauses are visible throughout the CaseBlock.
        for case in cases {
            for statement in &case.body {
                if let Stmt::FuncDecl(function) = lexical_declaration_statement(statement) {
                    self.instantiate_block_function(function)?;
                }
            }
        }

        // ECMA-262 CaseBlockEvaluation / CaseClauseIsSelected (snapshot e28783d5fc9d):
        // selectors use strict equality and the first duplicate wins. Literal integer selectors
        // have no observable evaluation, so a Number-only balanced tree can replace the linear
        // search. Bodies and their shared lexical environment remain in source order below.
        let mut body_jumps: Vec<(usize, usize)> = Vec::new();
        let integer_cases = integer_switch_cases(cases);
        if let Some(integer_cases) = integer_cases {
            // Relational comparison would coerce strings, objects and BigInts. Guard the type
            // once before entering the tree; none of those values can strictly match a Number.
            self.emit(Op::LoadLocal(discriminant));
            self.emit(Op::TypeofIs(crate::value::TypeofTest::Number, false));
            let mut misses = vec![self.emit(Op::JumpIfFalse(0))];
            self.integer_switch_tree(&integer_cases, discriminant, &mut body_jumps, &mut misses);
            for miss in misses {
                self.patch(miss);
            }
        } else {
            // Dynamic selectors retain their ordered evaluation and abrupt completions.
            for (case_index, case) in cases.iter().enumerate() {
                if let Some(test) = &case.test {
                    self.emit(Op::LoadLocal(discriminant));
                    self.expr(test)?;
                    self.emit(Op::StrictEq);
                    let no_match = self.emit(Op::JumpIfFalse(0));
                    let body = self.emit(Op::Jump(0));
                    body_jumps.push((case_index, body));
                    self.patch(no_match);
                }
            }
        }
        let default_jump = self.emit(Op::Jump(0));
        self.loops.push(LoopCtx {
            labels: std::mem::take(&mut self.pending_labels),
            entry_try_depth: self.try_depth,
            is_switch: true,
            ..LoopCtx::default()
        });

        // Phase 2: bodies, contiguous and in source order so normal fall-through is implicit.
        let mut body_starts = vec![0usize; cases.len()];
        let mut result = Ok(());
        'bodies: for (case_index, case) in cases.iter().enumerate() {
            body_starts[case_index] = self.ops.len();
            for statement in &case.body {
                result = self.stmt(statement);
                if result.is_err() {
                    break 'bodies;
                }
            }
        }
        let context = self.loops.pop().expect("switch context missing");
        result?;
        for (case_index, jump) in body_jumps {
            match &mut self.ops[jump] {
                Op::Jump(target) => *target = body_starts[case_index] as u32,
                _ => unreachable!(),
            }
        }
        match cases.iter().position(|case| case.test.is_none()) {
            Some(default_index) => match &mut self.ops[default_jump] {
                Op::Jump(target) => *target = body_starts[default_index] as u32,
                _ => unreachable!(),
            },
            None => self.patch(default_jump),
        }
        for jump in context.breaks {
            self.patch(jump);
        }
        Ok(())
    }

    fn integer_switch_tree(
        &mut self,
        cases: &[(i32, usize)],
        discriminant: u16,
        bodies: &mut Vec<(usize, usize)>,
        misses: &mut Vec<usize>,
    ) {
        if cases.len() <= 3 {
            for &(value, case_index) in cases {
                self.emit(Op::LoadLocal(discriminant));
                let constant = self.const_idx(Value::Num(value as f64));
                self.emit(Op::Const(constant));
                self.emit(Op::StrictEq);
                let next = self.emit(Op::JumpIfFalse(0));
                bodies.push((case_index, self.emit(Op::Jump(0))));
                self.patch(next);
            }
            misses.push(self.emit(Op::Jump(0)));
            return;
        }
        let middle = cases.len() / 2;
        self.emit(Op::LoadLocal(discriminant));
        let pivot = self.const_idx(Value::Num(cases[middle].0 as f64));
        self.emit(Op::Const(pivot));
        self.emit(Op::Lt);
        let right = self.emit(Op::JumpIfFalse(0));
        self.integer_switch_tree(&cases[..middle], discriminant, bodies, misses);
        self.patch(right);
        self.integer_switch_tree(&cases[middle..], discriminant, bodies, misses);
    }

    /// Lower CatchClauseEvaluation (ECMA-262 §14.15.2). A parameterized catch creates every
    /// mutable binding before BindingInitialization; the catch Block then has its own nested
    /// lexical scope. Binding-pattern defaults and iterator closing use the same suspension-aware
    /// machinery as declarations, while an omitted parameter simply discards the thrown value.
    fn catch_clause(&mut self, param: Option<&Pattern>, body: &[Stmt]) -> CResult {
        self.reset_script_completion();
        if let Some(pattern) = param {
            self.push_compile_scope();
            let mut names = crate::fasthash::FastSet::default();
            pat_idents(pattern, &mut names);
            let mut bindings: Vec<_> = names
                .into_iter()
                .filter(|name| self.fragment_entry || self.runtime_lexicals.contains(name))
                .map(|name| (name, false))
                .collect();
            bindings.sort_by(|left, right| left.0.cmp(&right.0));

            let result = if bindings.is_empty() {
                self.catch_clause_body(pattern, body)
            } else {
                // NewDeclarativeEnvironment precedes BindingInitialization, and the environment
                // remains current through evaluation of the nested Block. Keep the catch marker:
                // Annex B.3.4 exempts this one environment when sloppy eval checks whether a var
                // declaration may cross intervening lexical environments.
                let scope = self.push_runtime_catch_scope(bindings);
                self.environment_scope(|compiler| compiler.catch_clause_body(pattern, body), scope)
            };
            self.pop_compile_scope();
            return result;
        }

        self.emit(Op::Pop);
        self.push_compile_scope();
        let result = self.block_body(body);
        self.pop_compile_scope();
        result
    }

    fn catch_clause_body(&mut self, pattern: &Pattern, body: &[Stmt]) -> CResult {
        self.declare_lexical_pattern(pattern, false)?;
        self.destructure_store(pattern, DeclKind::Let)?;

        self.push_compile_scope();
        let result = self.block_body(body);
        self.pop_compile_scope();
        result
    }

    fn block_body(&mut self, body: &[Stmt]) -> CResult {
        let bindings = self.runtime_block_bindings(body);
        if !bindings.is_empty() {
            let scope = self.push_runtime_lexical_scope(bindings);
            return self.environment_scope(|compiler| compiler.block_body_slots(body), scope);
        }
        self.block_body_slots(body)
    }

    fn block_body_slots(&mut self, body: &[Stmt]) -> CResult {
        self.declare_block_lexicals(body)?;
        if body.iter().any(|statement| {
            matches!(
                statement,
                Stmt::VarDecl {
                    kind: DeclKind::Using | DeclKind::AwaitUsing,
                    ..
                }
            )
        }) {
            return self.disposal_scope(|compiler| compiler.statement_list(body));
        }
        self.statement_list(body)
    }

    /// The closure-visible subset of BlockDeclarationInstantiation. Keeping uncaptured names out
    /// of this list preserves the slot fast path while the selected bindings receive one fresh
    /// Declarative Environment Record per block evaluation.
    fn runtime_block_bindings(&self, body: &[Stmt]) -> Vec<(String, bool)> {
        let mut bindings = Vec::new();
        let mut add_pattern = |pattern: &Pattern, is_const: bool| {
            let mut names = crate::fasthash::FastSet::default();
            pat_idents(pattern, &mut names);
            let mut names: Vec<_> = names.into_iter().collect();
            names.sort();
            for name in names {
                if (self.fragment_entry || self.runtime_lexicals.contains(&name))
                    && !bindings.iter().any(|(existing, _)| existing == &name)
                {
                    bindings.push((name, is_const));
                }
            }
        };
        for statement in body {
            let statement = lexical_declaration_statement(statement);
            match statement {
                Stmt::VarDecl { kind, decls }
                    if matches!(
                        kind,
                        DeclKind::Let | DeclKind::Const | DeclKind::Using | DeclKind::AwaitUsing
                    ) =>
                {
                    let is_const = !matches!(kind, DeclKind::Let);
                    for (pattern, _) in decls {
                        add_pattern(pattern, is_const);
                    }
                }
                Stmt::ClassDecl(class) => {
                    if let Some(name) = &class.name {
                        add_pattern(&Pattern::Ident(name.clone()), false);
                    }
                }
                Stmt::FuncDecl(function) => {
                    if let Some(name) = &function.name {
                        add_pattern(&Pattern::Ident(name.clone()), false);
                    }
                }
                _ => {}
            }
        }
        bindings
    }

    fn push_runtime_lexical_scope(&mut self, bindings: Vec<(String, bool)>) -> u32 {
        self.push_runtime_scope(bindings, false)
    }

    fn push_runtime_catch_scope(&mut self, bindings: Vec<(String, bool)>) -> u32 {
        self.push_runtime_scope(bindings, true)
    }

    fn push_runtime_scope(&mut self, bindings: Vec<(String, bool)>, catch_param: bool) -> u32 {
        for (name, is_const) in &bindings {
            self.lexical_env_bind(name, *is_const);
        }
        let scope = self.lexical_scopes.len() as u32;
        self.lexical_scopes.push(
            bindings
                .into_iter()
                .map(|(name, is_const)| LexicalBinding {
                    name: Rc::from(name),
                    is_const,
                })
                .collect(),
        );
        self.emit(if catch_param {
            Op::PushCatchLex(scope)
        } else {
            Op::PushLex(scope)
        });
        scope
    }

    /// Restore one compiler-created lexical environment on every Completion. The handler is
    /// deliberately outside resource/iterator handlers compiled by `compile_body`, matching the
    /// spec's restoration of LexicalEnvironment after inner cleanup has completed.
    fn environment_scope(
        &mut self,
        compile_body: impl FnOnce(&mut Compiler) -> CResult,
        _scope: u32,
    ) -> CResult {
        let push = self.emit(Op::PushFinally(0, 0, 0, 0, 0));
        self.try_depth += 1;
        self.finally_depths.push(self.try_depth);
        self.function_osr_environment_handlers.push(push);

        compile_body(self)?;
        self.function_osr_environment_handlers.pop();

        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.finally_depths.pop();
        self.emit(Op::PopEnv);
        let normal_exit = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::Throw);
        let return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::Return);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ReturnBare);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ResumeReturn);
        let jump_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ResumeJump);

        match &mut self.ops[push] {
            Op::PushFinally(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
                jump_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
                *jump_target = jump_pc;
            }
            _ => unreachable!("lexical environment handler changed kind"),
        }
        self.patch(normal_exit);
        Ok(())
    }

    /// Compile WithStatement Evaluation with its Object Environment Record stored directly in
    /// the heap continuation. The `PushFinally` pads restore the previous environment for every
    /// ECMAScript completion, including a throw/rejection or generator return injected while the
    /// body is suspended.
    fn with_scope(&mut self, object: &Expr, body: &Stmt) -> CResult {
        self.expr(object)?;
        self.emit(Op::PushWith);
        let push = self.emit(Op::PushFinally(0, 0, 0, 0, 0));
        self.try_depth += 1;
        self.finally_depths.push(self.try_depth);

        self.with_scope_floors.push(self.scopes.len());
        let result = self.stmt(body);
        self.with_scope_floors.pop();
        result?;

        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.finally_depths.pop();
        self.emit(Op::PopEnv);
        let normal_exit = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::Throw);
        let return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::Return);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ReturnBare);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ResumeReturn);
        let jump_pc = self.ops.len() as u32;
        self.emit(Op::PopEnv);
        self.emit(Op::ResumeJump);

        match &mut self.ops[push] {
            Op::PushFinally(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
                jump_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
                *jump_target = jump_pc;
            }
            _ => unreachable!("with scope handler changed kind"),
        }
        self.patch(normal_exit);
        Ok(())
    }

    /// Compile one statement-list disposal boundary as a completion-aware `finally` region.
    /// Each pad consumes the exact Completion that caused scope exit, runs DisposeResources, and
    /// reissues the surviving completion so outer finalizers/iterators observe the right order.
    fn disposal_scope(&mut self, compile_body: impl FnOnce(&mut Compiler) -> CResult) -> CResult {
        self.emit(Op::PushDisposeFrame);
        let push = self.emit(Op::PushFinally(0, 0, 0, 0, 0));
        self.try_depth += 1;
        self.finally_depths.push(self.try_depth);

        compile_body(self)?;

        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.finally_depths.pop();
        self.emit(Op::DisposeNormal);
        let normal_exit = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::DisposeThrow);
        let return_pc = self.ops.len() as u32;
        self.emit(Op::DisposeReturn);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::DisposeBareReturn);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::DisposeResumeReturn);
        let jump_pc = self.ops.len() as u32;
        self.emit(Op::DisposeJump);

        match &mut self.ops[push] {
            Op::PushFinally(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
                jump_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
                *jump_target = jump_pc;
            }
            _ => unreachable!("disposal scope handler changed kind"),
        }
        self.patch(normal_exit);
        Ok(())
    }

    fn for_loop(
        &mut self,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
    ) -> CResult {
        if matches!(
            self.fragment_root.take(),
            Some(loop_fragment::RootKind::For)
        ) {
            return self.fragment_for_remainder(init, test, update, body);
        }
        // Claim any labels from an enclosing `Stmt::Labeled` before the head runs, so they land on
        // this loop's context (the head itself introduces no labelled break/continue targets).
        let labels = std::mem::take(&mut self.pending_labels);
        if self.fragment_entry {
            if let Some(ForInit::VarDecl {
                kind: kind @ (DeclKind::Using | DeclKind::AwaitUsing),
                decls,
            }) = init
            {
                return self.fragment_using_for(labels, *kind, decls, test, update, body);
            }
        }
        let mut runtime_bindings = Vec::new();
        if let Some(ForInit::VarDecl {
            kind: kind @ (DeclKind::Let | DeclKind::Const),
            decls,
        }) = init
        {
            for (pattern, _) in decls {
                let mut names = crate::fasthash::FastSet::default();
                pat_idents(pattern, &mut names);
                let mut names: Vec<_> = names.into_iter().collect();
                names.sort();
                runtime_bindings.extend(
                    names
                        .into_iter()
                        .filter(|name| self.fragment_entry || self.runtime_lexicals.contains(name))
                        .map(|name| (name, matches!(kind, DeclKind::Const))),
                );
            }
        }
        if !runtime_bindings.is_empty() {
            let scope = self.push_runtime_lexical_scope(runtime_bindings);
            let per_iteration = matches!(
                init,
                Some(ForInit::VarDecl {
                    kind: DeclKind::Let,
                    ..
                })
            )
            .then_some(scope);
            return self.environment_scope(
                |compiler| compiler.for_loop_core(labels, init, test, update, body, per_iteration),
                scope,
            );
        }
        if let Some(ForInit::VarDecl {
            kind: kind @ (DeclKind::Using | DeclKind::AwaitUsing),
            decls,
        }) = init
        {
            for (pattern, _) in decls {
                self.declare_lexical_pattern(pattern, true)?;
            }
            return self.disposal_scope(|compiler| {
                for (pattern, initializer) in decls {
                    let Pattern::Ident(name) = pattern else {
                        return Err(Bail);
                    };
                    let initializer = initializer.as_ref().ok_or(Bail)?;
                    compiler.named_expr(initializer, name)?;
                    compiler.emit(Op::AddDisposable(matches!(kind, DeclKind::AwaitUsing)));
                    match compiler.home(name).ok_or(Bail)? {
                        Home::Slot(slot, _) => compiler.emit(Op::StoreLocal(slot)),
                        Home::Env(_) => {
                            let name = compiler.name_idx(name);
                            compiler.emit(Op::StoreCapInit(name))
                        }
                    };
                }
                compiler.without_tail(|compiler| {
                    compiler.for_loop_core(labels, None, test, update, body, None)
                })
            });
        }
        self.for_loop_core(labels, init, test, update, body, None)
    }

    fn for_loop_core(
        &mut self,
        labels: Vec<String>,
        init: Option<&ForInit>,
        test: Option<&Expr>,
        update: Option<&Expr>,
        body: &Stmt,
        per_iteration_scope: Option<u32>,
    ) -> CResult {
        match init {
            Some(ForInit::VarDecl { kind, decls }) => {
                debug_assert!(!matches!(kind, DeclKind::Using | DeclKind::AwaitUsing));
                if matches!(kind, DeclKind::Let | DeclKind::Const) {
                    for (pat, _) in decls {
                        // ForLoopEvaluation creates every loopEnv binding before evaluating the
                        // LexicalDeclaration. Captured leaves are already present in the runtime
                        // record; uncaptured leaves retain TDZ slots and need no environment copy.
                        self.declare_lexical_pattern(pat, matches!(kind, DeclKind::Const))?;
                    }
                }
                for (pat, initv) in decls {
                    let Pattern::Ident(name) = pat else {
                        let Some(initializer) = initv else {
                            return Err(Bail);
                        };
                        self.expr(initializer)?;
                        self.destructure_store(pat, *kind)?;
                        continue;
                    };
                    let dynamic_lexical = self.dynamic_declaration_binding(name, *kind);
                    let home = if dynamic_lexical {
                        None
                    } else {
                        Some(self.home(name).ok_or(Bail)?)
                    };
                    let reference = if matches!(kind, DeclKind::Var)
                        && initv.is_some()
                        && self.name_reference_can_change(name)
                    {
                        let reference = self.fresh_reference()?;
                        let name = self.name_idx(name);
                        self.emit(Op::ResolveNameRef(name, reference));
                        Some(reference)
                    } else {
                        None
                    };
                    match initv {
                        Some(initializer) => self.named_expr(initializer, name)?,
                        None if matches!(kind, DeclKind::Var) => continue,
                        None => {
                            self.emit(Op::Undef);
                        }
                    }
                    if let Some(reference) = reference {
                        self.emit(Op::StoreRef(reference));
                        continue;
                    }
                    if dynamic_lexical {
                        let name = self.name_idx(name);
                        self.emit(if matches!(kind, DeclKind::Var) {
                            Op::StoreName(name)
                        } else {
                            Op::InitLex(name)
                        });
                        continue;
                    }
                    match home.expect("non-dynamic for declaration has a static home") {
                        Home::Slot(slot, _) => {
                            self.emit(Op::StoreLocal(slot));
                        }
                        Home::Env(_) => {
                            let name = self.name_idx(name);
                            self.emit(if matches!(kind, DeclKind::Var) {
                                Op::StoreCap(name)
                            } else {
                                Op::StoreCapInit(name)
                            });
                        }
                    }
                }
            }
            Some(ForInit::Expr(e)) => {
                self.expr_stmt(e)?;
            }
            None => {}
        }
        if let Some(scope) = per_iteration_scope {
            // ForBodyEvaluation calls CreatePerIterationEnvironment once before the first test.
            self.emit(Op::CloneLex(scope));
        }
        let start = self.ops.len();
        if let Some(site) = self.pending_function_osr_site.take() {
            self.record_function_osr_address(site, start);
        }
        let jf = match test {
            Some(t) => {
                self.expr(t)?;
                Some(self.emit(Op::JumpIfFalse(0)))
            }
            None => None,
        };
        self.loops.push(LoopCtx {
            labels,
            entry_try_depth: self.try_depth,
            ..LoopCtx::default()
        });
        let r = self.stmt(body);
        let ctx = self.loops.pop().unwrap();
        r?;
        let cont = self.ops.len();
        for c in ctx.continues {
            self.patch_to(c, cont as u32);
        }
        if let Some(scope) = per_iteration_scope {
            // The next iteration's record is created before evaluating the increment expression;
            // closures in the body therefore retain the record that the body actually observed.
            self.emit(Op::CloneLex(scope));
        }
        if let Some(u) = update {
            self.expr_stmt(u)?;
        }
        self.emit(Op::Jump(start as u32));
        if let Some(jf) = jf {
            self.patch(jf);
        }
        for b in ctx.breaks {
            self.patch(b);
        }
        Ok(())
    }

    /// Compile an expression whose value is discarded (an expression statement, or a `for`
    /// header's init / update). Assignments and `++`/`--` to a local drop their producing `Dup`
    /// (and the trailing `Pop`); everything else falls back to `expr` + `Pop`. Semantically
    /// identical to `self.expr(e)?; self.emit(Op::Pop)` — the only difference is the unobservable
    /// result value.
    fn expr_stmt(&mut self, e: &Expr) -> CResult {
        match e {
            Expr::Paren(inner) => return self.expr_stmt(inner),
            // A comma expression as a statement: every operand is evaluated for effect only.
            Expr::Seq(exprs) => {
                for ex in exprs {
                    self.expr_stmt(ex)?;
                }
                return Ok(());
            }
            Expr::Update { op, arg, .. } => {
                let kind = match *op {
                    "++" => UpdKind::IncDiscard,
                    "--" => UpdKind::DecDiscard,
                    _ => return Err(Bail),
                };
                return self.update_target(arg, kind);
            }
            Expr::Assign {
                op,
                target,
                value,
                pos,
            } => {
                return self.at_position(*pos, |c| c.assign_discard(op, target, value));
            }
            _ => {}
        }
        self.expr(e)?;
        self.emit(Op::Pop);
        Ok(())
    }

    /// Compile a discarded assignment: the fast `Dup`-free lowering when the target is a plain
    /// local / free name / `obj.x` / `obj[k]`, otherwise the generic value-producing `assign`
    /// followed by `Pop` (identical to `self.expr(assign)?; Pop`).
    fn assign_discard(&mut self, op: &str, target: &Expr, value: &Expr) -> CResult {
        if self.try_assign_discard(op, target, value)? {
            return Ok(());
        }
        self.assign(op, target, value)?;
        self.emit(Op::Pop);
        Ok(())
    }

    /// Fast lowering for a discarded assignment (no `Dup`, no trailing `Pop`). Returns `Ok(true)`
    /// when it emitted the assignment, `Ok(false)` to defer to the generic `assign` + `Pop` path
    /// (which handles — or itself bails on — the forms not covered here). Any `Bail` from a
    /// compiled sub-expression propagates: the generic path would bail identically.
    fn try_assign_discard(&mut self, op: &str, target: &Expr, value: &Expr) -> Result<bool, Bail> {
        // Logical-assignment short-circuits; leave it to the generic path (which bails).
        if matches!(op, "&&=" | "||=" | "??=") {
            return Ok(false);
        }
        match target {
            Expr::Ident(name, _) => match self.home(name) {
                Some(Home::Slot(slot, is_const)) => {
                    if is_const {
                        self.immutable_assignment(Home::Slot(slot, true), name, op, value)?;
                        return Ok(true);
                    }
                    if op == "=" {
                        self.named_expr(value, name)?;
                        self.check_assignment_local_initialized(slot);
                    } else {
                        self.emit(Op::LoadLocal(slot));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::StoreLocal(slot));
                    Ok(true)
                }
                Some(Home::Env(is_const)) => {
                    if is_const {
                        self.immutable_assignment(Home::Env(true), name, op, value)?;
                        return Ok(true);
                    }
                    let n = self.name_idx(name);
                    if op == "=" {
                        self.named_expr(value, name)?;
                    } else {
                        self.emit(Op::LoadCap(n));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::StoreCap(n));
                    Ok(true)
                }
                None => {
                    let i = self.name_idx(name);
                    let reference = if self.name_reference_can_change(name) {
                        let reference = self.fresh_reference()?;
                        self.emit(Op::ResolveNameRef(i, reference));
                        Some(reference)
                    } else {
                        None
                    };
                    if op == "=" {
                        // StoreName already consumes the value without re-pushing it.
                        self.named_expr(value, name)?;
                    } else {
                        if let Some(reference) = reference {
                            self.emit(Op::LoadRef(reference));
                        } else {
                            let c = self.new_name_cache(i);
                            self.emit(Op::LoadName(i, c));
                        }
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    if let Some(reference) = reference {
                        self.emit(Op::StoreRef(reference));
                    } else {
                        self.emit_store_name(i);
                    }
                    Ok(true)
                }
            },
            // Receiver-direct statement stores: `this.x = v` (always safe — `this` can't be
            // reassigned) and `slotlocal.x = v` when reading the local cannot throw and the RHS
            // provably can't reassign it (the receiver is read at set time, after the RHS).
            Expr::Member {
                obj: mobj,
                prop,
                optional: false,
                ..
            } if op == "="
                && !prop.starts_with('#')
                && match &**mobj {
                    Expr::This => !self.lexical_this && !self.derived_constructor,
                    Expr::Ident(name, _) => {
                        matches!(self.home(name), Some(Home::Slot(slot, _))
                            if !self.tdz_slots.contains(&slot))
                            && no_assign_to(value, name)
                    }
                    _ => false,
                } =>
            {
                self.expr(value)?;
                let i = self.property_name_idx(prop);
                let c = self.new_cache(i);
                match &**mobj {
                    Expr::This => {
                        if self.inline_depth > 0 {
                            match self.inline_this {
                                Some(slot) => {
                                    self.emit(Op::SetPropLocalDrop(slot, i, c));
                                }
                                None => return Err(Bail), // splice without a this binding
                            }
                        } else {
                            self.uses_this = true;
                            self.emit(Op::SetPropThisDrop(i, c));
                        }
                    }
                    Expr::Ident(name, _) => {
                        let Some(Home::Slot(slot, _)) = self.home(name) else {
                            unreachable!()
                        };
                        self.emit(Op::SetPropLocalDrop(slot, i, c));
                    }
                    _ => unreachable!(),
                }
                Ok(true)
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                let i = self.property_name_idx(prop);
                if op == "+=" {
                    // Fused append: same evaluation order (read before RHS), and the op itself
                    // falls back to the generic Add + store when anything isn't plain strings.
                    self.emit(Op::Dup);
                    let cg = self.new_cache(i);
                    self.emit(Op::GetProp(i, cg));
                    self.expr(value)?;
                    let c = self.new_cache(i);
                    self.emit(Op::AppendProp(i, c));
                    return Ok(true);
                }
                if op == "=" {
                    self.expr(value)?;
                } else {
                    self.emit(Op::Dup);
                    let cg = self.new_cache(i);
                    self.emit(Op::GetProp(i, cg));
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                let c = self.new_cache(i);
                self.emit(Op::SetPropDrop(i, c));
                Ok(true)
            }

            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                if let Some(slot) = self.fused_elem_slot(obj, &[index.as_ref(), value]) {
                    self.expr(index)?;
                    if op == "=" {
                        self.expr(value)?;
                    } else {
                        // Compound: coerce a side-effecting key once (Num keys pass raw), then
                        // read-modify-write against the slot base — one Dup, no receiver churn.
                        self.emit(Op::ToPropKeyLocal(slot));
                        self.emit(Op::Dup);
                        self.emit(Op::GetElemLocal(slot));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::SetElemLocalDrop(slot));
                    return Ok(true);
                }
                self.expr(obj)?;
                self.expr(index)?;
                if op == "=" {
                    self.expr(value)?;
                } else {
                    self.emit(Op::ToPropKey);
                    self.emit(Op::Dup2);
                    self.emit(Op::GetElem);
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                self.emit(Op::SetElemDrop);
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    /// Emit a closure over the current environment; `name` applies NamedEvaluation to an
    /// anonymous function expression (`var f = function(){}` → `f.name === "f"`).
    fn emit_closure(&mut self, f: &Rc<Function>, name: Option<&str>) -> CResult {
        // ECMA-262 §9.4.5 GetNewTarget: an arrow reads the enclosing function's [[NewTarget]]
        // when it runs, possibly after that activation returned. A lean frame keeps new.target
        // only in the interpreter register, so such an arrow needs the general activation.
        if self.lean_new_target && f.is_arrow && f.scan_flags() & SCAN_NEW_TARGET != 0 {
            log_bail("fn", "arrow observing an activation-less new.target");
            return Err(Bail);
        }
        let fidx = self.funcs.len() as u32;
        self.funcs.push(f.clone());
        let name_idx = match name {
            Some(n) if f.name.is_none() && !f.is_method => self.name_idx(n),
            _ => u32::MAX,
        };
        self.emit(Op::MakeClosure(fidx, name_idx));
        Ok(())
    }

    /// Compile a value expression in a naming position (declaration/assignment to `name`).
    fn named_expr(&mut self, e: &Expr, name: &str) -> CResult {
        if let Expr::Func(f) = e {
            return self.emit_closure(f, Some(name));
        }
        if let Expr::Class(class) = e {
            if class.name.is_none() {
                if crate::eval::expr_has_own_suspension(e) {
                    return self.staged_class(class, Some(name));
                }
                return self.retain_named_eval_expr(e, Some(name));
            }
        }
        self.expr(e)
    }

    /// Lower the suspendable prefix of ClassDefinitionEvaluation while retaining its lexical and
    /// private environments in the VM frame. The existing evaluator finishes the atomic suffix
    /// after heritage and every computed key have completed exactly once.
    fn staged_class(&mut self, class: &Rc<Class>, inferred_name: Option<&str>) -> CResult {
        if !self.is_coroutine
            || class.decorators.len() > u16::MAX as usize
            || class
                .members
                .iter()
                .any(|member| member.decorators.len() > u16::MAX as usize)
        {
            return Err(Bail);
        }
        if class.members.len() > u16::MAX as usize {
            return Err(Bail);
        }
        let plan = self.class_plans.len() as u32;
        self.class_plans.push(ClassPlan {
            class: class.clone(),
            inferred_name: inferred_name.map(str::to_string),
        });

        // TC39 decorators proposal, "Evaluating decorators": class decorator expressions run in
        // the surrounding environment before ClassDefinitionEvaluation opens the class-name TDZ.
        for decorator in &class.decorators {
            self.decorator_expression(decorator)?;
        }
        self.emit(Op::ClassStart(plan, class.decorators.len() as u16));

        let cleanup = self.emit(Op::PushFinally(0, 0, 0, 0, 0));
        self.try_depth += 1;
        self.finally_depths.push(self.try_depth);

        // ClassDefinitionEvaluation is strict code and resolves the class's self-name through the
        // newly created (TDZ) class environment rather than any outer declaration slot.
        let saved_strict = std::mem::replace(&mut self.strict, true);
        self.scopes.push(Vec::new());
        let mut class_names = crate::fasthash::FastMap::default();
        if let Some(name) = &class.name {
            class_names.insert(name.clone(), true);
        }
        self.lexical_env_names.push(class_names);
        let compile_result = (|| {
            if let Some(superclass) = &class.superclass {
                self.expr(superclass)?;
                self.emit(Op::ClassHeritage(plan, true));
            } else {
                self.emit(Op::ClassHeritage(plan, false));
            }
            for (index, member) in class.members.iter().enumerate() {
                for decorator in &member.decorators {
                    self.decorator_expression(decorator)?;
                    self.emit(Op::ClassDecorator(plan, index as u16));
                }
                if member.kind == MemberKind::Constructor {
                    continue;
                }
                if let PropKey::Computed(key) = &member.key {
                    self.expr(key)?;
                    self.emit(Op::ClassKey(plan, index as u16));
                }
            }
            Ok(())
        })();
        self.lexical_env_names.pop();
        self.scopes.pop();
        self.strict = saved_strict;
        compile_result?;

        self.emit(Op::ClassFinish(plan));
        self.emit(Op::PopHandler);
        self.try_depth -= 1;
        self.finally_depths.pop();
        let normal_exit = self.emit(Op::Jump(0));

        let throw_pc = self.ops.len() as u32;
        self.emit(Op::ClassAbort(plan));
        self.emit(Op::Throw);
        let return_pc = self.ops.len() as u32;
        self.emit(Op::ClassAbort(plan));
        self.emit(Op::Return);
        let bare_return_pc = self.ops.len() as u32;
        self.emit(Op::ClassAbort(plan));
        self.emit(Op::ReturnBare);
        let resume_return_pc = self.ops.len() as u32;
        self.emit(Op::ClassAbort(plan));
        self.emit(Op::ResumeReturn);
        let jump_pc = self.ops.len() as u32;
        self.emit(Op::ClassAbort(plan));
        self.emit(Op::ResumeJump);
        match &mut self.ops[cleanup] {
            Op::PushFinally(
                throw_target,
                return_target,
                bare_return_target,
                resume_return_target,
                jump_target,
            ) => {
                *throw_target = throw_pc;
                *return_target = return_pc;
                *bare_return_target = bare_return_pc;
                *resume_return_target = resume_return_pc;
                *jump_target = jump_pc;
            }
            _ => unreachable!("class environment handler changed kind"),
        }
        self.patch(normal_exit);
        Ok(())
    }

    /// Evaluate a proposal decorator to its retained (receiver, callback) pair. Ordinary
    /// expression evaluation performs GetValue and loses the Reference base; `GetMethod` keeps it
    /// so `@holder.decorator` has the proposal's natural `this` when application occurs later.
    fn decorator_expression(&mut self, expression: &Expr) -> CResult {
        match expression {
            Expr::Paren(inner) => self.decorator_expression(inner),
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.expr(obj)?;
                let name = self.property_name_idx(prop);
                if prop.starts_with('#') {
                    let site = self.new_private_site();
                    self.emit(Op::GetPrivateMethod(name, site));
                } else {
                    let cache = self.new_cache(name);
                    self.emit(Op::GetMethod(name, cache));
                }
                Ok(())
            }
            _ => {
                self.emit(Op::Undef);
                self.expr(expression)
            }
        }
    }

    /// Evaluate an ObjectLiteral property name while the fresh object remains immediately below
    /// it on the operand stack. `ToPropKey` performs the observable coercion now (before the
    /// property's value or method definition), as required by PropertyDefinitionEvaluation.
    /// Numeric and string keys may remain in their cheap raw representation because their later
    /// re-coercion is side-effect-free; object and symbol keys are normalized immediately.
    fn object_literal_key(&mut self, key: &PropKey) -> CResult {
        match key {
            PropKey::Ident(key) => {
                let value = self.const_idx(Value::lstr(key.clone()));
                self.emit(Op::Const(value));
            }
            PropKey::Str(key) => {
                let value = self.const_idx(Value::Str(key.clone().into()));
                self.emit(Op::Const(value));
            }
            PropKey::Num(key) => {
                let value = self.const_idx(Value::Num(*key));
                self.emit(Op::Const(value));
            }
            PropKey::Computed(key) => self.expr(key)?,
        }
        self.emit(Op::ToPropKey);
        Ok(())
    }

    fn super_named_reference(&mut self, name: &str) {
        self.emit_super_this();
        let key = self.const_idx(Value::lstr(name.to_string()));
        self.emit(Op::Const(key));
        self.emit(Op::SuperBase);
    }

    fn super_computed_reference(&mut self, key: &Expr) -> CResult {
        self.emit_super_this();
        self.expr(key)?;
        self.emit(Op::SuperBase);
        Ok(())
    }

    /// A Super Reference's `[[ThisValue]]` is the current function's actual this binding. Marking
    /// that dependency is as important as emitting the read: lean compiled calls otherwise omit
    /// OrdinaryCallBindThis and `SuperThis` could resolve an enclosing/global `this` instead.
    fn emit_super_this(&mut self) {
        self.uses_this = true;
        self.emit(if self.lexical_this || self.derived_constructor {
            Op::LoadLexicalThis
        } else {
            Op::SuperThis
        });
    }

    fn expr(&mut self, e: &Expr) -> CResult {
        if crate::interpreter::ast_stack_low() {
            return crate::interpreter::with_ast_stack(|| self.expr(e));
        }
        match e.position() {
            Some(position) if !self.cannot_fail(e) => {
                self.at_position(position, |c| c.expr_node(e))
            }
            _ => self.expr_node(e),
        }
    }

    /// A read of a frame slot outside its temporal dead zone can neither throw nor call: its
    /// position is never observed, so it need not split the chunk's position runs.
    fn cannot_fail(&self, e: &Expr) -> bool {
        matches!(e, Expr::Ident(name, _)
            if matches!(self.home(name), Some(Home::Slot(slot, _)) if !self.tdz_slots.contains(&slot)))
    }

    /// The operator of a binary expression.
    fn binary_operator(&mut self, op: &'static str) -> Op {
        match op {
            "+" => Op::Add,
            "-" => Op::Sub,
            "*" => Op::Mul,
            "/" => Op::Div,
            "%" => Op::Mod,
            "&" => Op::BitAnd,
            "|" => Op::BitOr,
            "^" => Op::BitXor,
            "<<" => Op::Shl,
            ">>" => Op::Shr,
            ">>>" => Op::UShr,
            "<" => Op::Lt,
            ">" => Op::Gt,
            "<=" => Op::Le,
            ">=" => Op::Ge,
            "==" => Op::EqEq,
            "!=" => Op::NotEq,
            "===" => Op::StrictEq,
            "!==" => Op::StrictNotEq,
            "instanceof" => Op::InstanceOf(self.new_single_cache()),
            "in" => Op::In,
            other => {
                let i = self.name_idx(other);
                Op::GenBin(i)
            }
        }
    }

    /// `typeof x === "literal"` (either way round), compiled to one TypeofIs test.
    fn typeof_comparison<'e>(
        op: &str,
        left: &'e Expr,
        right: &'e Expr,
    ) -> Option<(&'e Expr, &'e Rc<str>)> {
        if !matches!(op, "==" | "!=" | "===" | "!==") {
            return None;
        }
        match (left, right) {
            (Expr::Unary { op: "typeof", arg }, Expr::Str(literal))
            | (Expr::Str(literal), Expr::Unary { op: "typeof", arg }) => Some((arg, literal)),
            _ => None,
        }
    }

    /// A left-nested chain of binary and logical operators (`a + b + c`, `a && b || c`),
    /// compiled left to right in a loop rather than recursing once per link: generated and
    /// obfuscated code chains hundreds of thousands of operands. Each link emits exactly what
    /// the recursive lowering below does (none of these nodes carries a source position).
    fn operator_chain(&mut self, e: &Expr) -> CResult {
        let mut links = Vec::new();
        let mut node = e;
        loop {
            match node {
                Expr::Binary { op, left, right }
                    if Self::typeof_comparison(op, left, right).is_none() =>
                {
                    links.push((true, *op, &**right));
                    node = left;
                }
                Expr::Logical { op, left, right } => {
                    links.push((false, *op, &**right));
                    node = left;
                }
                _ => break,
            }
        }
        self.expr(node)?;
        for (binary, op, right) in links.into_iter().rev() {
            if binary {
                self.expr(right)?;
                let op = self.binary_operator(op);
                self.emit(op);
            } else {
                let jump = match op {
                    "&&" => self.emit(Op::JumpIfFalsePeek(0)),
                    "||" => self.emit(Op::JumpIfTruePeek(0)),
                    "??" => self.emit(Op::JumpIfNotNullishPeek(0)),
                    _ => return Err(Bail),
                };
                self.emit(Op::Pop);
                self.expr(right)?;
                self.patch(jump);
            }
        }
        Ok(())
    }

    /// A non-optional public property read `o.p` or `o[k]` on an ordinary base: one link of a
    /// member chain that [`Self::member_chain`] compiles in a loop.
    fn plain_member_link(e: &Expr) -> Option<&Expr> {
        match e {
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => Some(obj),
            Expr::Index {
                obj,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => Some(obj),
            _ => None,
        }
    }

    /// A chain of property reads (`a.b.c`, `a[0][1]`), compiled from its innermost read
    /// outwards in a loop rather than recursing once per link. The innermost read keeps its
    /// receiver-direct and fused forms; every outer read is a plain GetProp/GetElem on the
    /// value below it, at its own source position, exactly as the recursive lowering emits.
    fn member_chain(&mut self, e: &Expr) -> CResult {
        let mut links = Vec::new();
        let mut node = e;
        while let Some(obj) = Self::plain_member_link(node) {
            if Self::plain_member_link(obj).is_none() {
                break;
            }
            links.push(node);
            node = obj;
        }
        self.expr(node)?;
        for link in links.into_iter().rev() {
            let position = link.position().unwrap_or(NO_POSITION);
            self.at_position(position, |c| {
                match link {
                    Expr::Member { prop, .. } => {
                        let i = c.property_name_idx(prop);
                        let cache = c.new_cache(i);
                        c.emit(Op::GetProp(i, cache));
                    }
                    Expr::Index { index, .. } => {
                        c.expr(index)?;
                        c.emit(Op::GetElem);
                    }
                    _ => unreachable!("plain member links are reads"),
                }
                Ok(())
            })?;
        }
        Ok(())
    }

    /// A chain of calls (`f()()()`, `f().m().n()`), compiled from its innermost call outwards
    /// in a loop rather than recursing once per link. Each outer link calls the value the link
    /// below left on the stack, as a plain callee or through GetMethod/GetMethodElem, and
    /// emits exactly the call sequence of the recursive lowering at its own position.
    fn call_chain(&mut self, e: &Expr) -> CResult {
        let mut links = Vec::new();
        let mut node = e;
        while let Some(below) = node.call_chain_link() {
            links.push(node);
            node = below;
        }
        // Only the outermost call can be in tail position (see the Call lowering below).
        let tail = self.tail_call_node == e as *const Expr as usize;
        if tail {
            self.tail_call_node = 0;
        }
        self.expr(node)?;
        for link in links.into_iter().rev() {
            let Expr::Call {
                callee, args, pos, ..
            } = link
            else {
                unreachable!("call chain links are calls");
            };
            let outermost = std::ptr::eq(link, e);
            self.at_position(*pos, |c| {
                let (with_this, allow_inline) = match &**callee {
                    Expr::Member { prop, .. } => {
                        let name = c.property_name_idx(prop);
                        if prop.starts_with('#') {
                            let site = c.new_private_site();
                            c.emit(Op::GetPrivateMethod(name, site));
                            (true, false)
                        } else {
                            let cache = c.new_cache(name);
                            c.emit(Op::GetMethod(name, cache));
                            (true, true)
                        }
                    }
                    Expr::Index { index, .. } => {
                        c.expr(index)?;
                        c.emit(Op::GetMethodElem);
                        (true, true)
                    }
                    _ => (false, true),
                };
                c.tail_finish = tail && outermost;
                c.pending_call_name = Some(crate::callee_name::callee_name(callee));
                c.finish_call(args, with_this, allow_inline)
            })?;
        }
        Ok(())
    }

    fn expr_node(&mut self, e: &Expr) -> CResult {
        match e {
            _ if e
                .call_chain_link()
                .and_then(Expr::call_chain_link)
                .is_some() =>
            {
                self.call_chain(e)
            }
            _ if Self::plain_member_link(e)
                .and_then(Self::plain_member_link)
                .is_some() =>
            {
                self.member_chain(e)
            }
            Expr::Func(f) => self.emit_closure(f, None),
            Expr::Class(class) if crate::eval::expr_has_own_suspension(e) => {
                self.staged_class(class, None)
            }
            Expr::Num(n) => {
                let i = self.const_idx(Value::Num(*n));
                self.emit(Op::Const(i));
                Ok(())
            }
            Expr::Str(s) => {
                let i = self.const_idx(Value::Str(s.clone().into()));
                self.emit(Op::Const(i));
                Ok(())
            }
            Expr::Bool(b) => {
                let i = self.const_idx(Value::Bool(*b));
                self.emit(Op::Const(i));
                Ok(())
            }
            Expr::Null => {
                let i = self.const_idx(Value::Null);
                self.emit(Op::Const(i));
                Ok(())
            }
            Expr::Undefined => {
                self.emit(Op::Undef);
                Ok(())
            }
            Expr::BigInt(n) => {
                let i = self.const_idx(Value::BigInt(n.value()));
                self.emit(Op::Const(i));
                Ok(())
            }
            Expr::Ident(name, _) => {
                match self.home(name) {
                    Some(Home::Slot(slot, _)) => {
                        self.emit(Op::LoadLocal(slot));
                    }
                    Some(Home::Env(_)) => {
                        let i = self.name_idx(name);
                        self.emit(Op::LoadCap(i));
                    }
                    None => {
                        let i = self.name_idx(name);
                        let c = self.new_name_cache(i);
                        self.emit(Op::LoadName(i, c));
                    }
                };
                Ok(())
            }
            Expr::This => {
                // A spliced callee's `this` is the receiver, parked in a caller slot.
                if let Some(slot) = self.inline_this {
                    if self.inline_depth > 0 {
                        self.emit(Op::LoadLocal(slot));
                        return Ok(());
                    }
                }
                self.uses_this = true;
                if self.lexical_this && !self.is_coroutine && !self.fragment_entry {
                    // Resolve at the expression, not at entry: a derived constructor's `this`
                    // may still be in TDZ, and an untaken branch must not eagerly throw. The
                    // normal guarded name cache reads the captured binding live on every hit.
                    // Closures under `with` are excluded by the call-entry gates.
                    let name = self.name_idx("this");
                    let cache = self.new_name_cache(name);
                    self.emit(Op::LoadName(name, cache));
                    return Ok(());
                }
                self.emit(if self.lexical_this || self.derived_constructor {
                    Op::LoadLexicalThis
                } else {
                    Op::LoadThis
                });
                Ok(())
            }
            Expr::Paren(inner) => self.expr(inner),
            Expr::Seq(exprs) => {
                for (k, ex) in exprs.iter().enumerate() {
                    if k + 1 < exprs.len() {
                        // ECMA-262 comma evaluation still performs GetValue and all effects
                        // on each prefix. Its result is unused: reuse statement lowering so
                        // assignments/updates do not clone and immediately discard it.
                        self.expr_stmt(ex)?;
                    } else {
                        self.expr(ex)?;
                    }
                }
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                // Receiver-direct forms: `this.x` and `slotlocal.x` skip the operand-stack
                // round trip (push + refcount bump + drop) entirely.
                match &**obj {
                    // Inside a splice `this` is the receiver slot; otherwise the frame binding.
                    Expr::This if self.inline_depth > 0 => {
                        if let Some(slot) = self.inline_this {
                            let i = self.property_name_idx(prop);
                            let c = self.new_cache(i);
                            self.emit(Op::GetPropLocal(slot, i, c));
                            return Ok(());
                        }
                    }
                    Expr::This if !self.lexical_this && !self.derived_constructor => {
                        self.uses_this = true;
                        let i = self.property_name_idx(prop);
                        let c = self.new_cache(i);
                        self.emit(Op::GetPropThis(i, c));
                        return Ok(());
                    }
                    Expr::Ident(name, _) => {
                        if let Some(Home::Slot(slot, _)) = self.home(name) {
                            let i = self.property_name_idx(prop);
                            let c = self.new_cache(i);
                            self.emit(Op::GetPropLocal(slot, i, c));
                            return Ok(());
                        }
                    }
                    _ => {}
                }
                self.expr(obj)?;
                let i = self.property_name_idx(prop);
                let c = self.new_cache(i);
                self.emit(Op::GetProp(i, c));
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                self.emit(Op::SuperGet);
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if prop.starts_with('#') => {
                self.expr(obj)?;
                let name = self.property_name_idx(prop);
                let site = self.new_private_site();
                self.emit(Op::GetPrivate(name, site));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                if let Some(slot) = self.fused_elem_slot(obj, &[index.as_ref()]) {
                    self.expr(index)?;
                    self.emit(Op::GetElemLocal(slot));
                } else {
                    self.expr(obj)?;
                    self.expr(index)?;
                    self.emit(Op::GetElem);
                }
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                self.emit(Op::SuperGet);
                Ok(())
            }
            Expr::Binary { left, .. } | Expr::Logical { left, .. }
                if matches!(**left, Expr::Binary { .. } | Expr::Logical { .. }) =>
            {
                self.operator_chain(e)
            }
            Expr::Binary { op, left, right } => {
                if let Some((argument, literal)) = Self::typeof_comparison(op, left, right) {
                    // An unknown identifier needs typeof's unresolvable-reference
                    // exception. Its existing TypeofName operation remains authoritative.
                    if !matches!(argument, Expr::Ident(name, _) if self.home(name).is_none()) {
                        self.expr(argument)?;
                        self.emit(Op::TypeofIs(
                            crate::value::TypeofTest::from_literal(literal),
                            matches!(*op, "!=" | "!=="),
                        ));
                        return Ok(());
                    }
                }
                self.expr(left)?;
                self.expr(right)?;
                let bop = self.binary_operator(op);
                self.emit(bop);
                Ok(())
            }
            Expr::Logical { op, left, right } => {
                self.expr(left)?;
                let j = match *op {
                    "&&" => self.emit(Op::JumpIfFalsePeek(0)),
                    "||" => self.emit(Op::JumpIfTruePeek(0)),
                    "??" => self.emit(Op::JumpIfNotNullishPeek(0)),
                    _ => return Err(Bail),
                };
                self.emit(Op::Pop);
                self.expr(right)?;
                self.patch(j);
                Ok(())
            }
            Expr::Cond { test, cons, alt } => {
                self.expr(test)?;
                let jf = self.emit(Op::JumpIfFalse(0));
                self.expr(cons)?;
                let jend = self.emit(Op::Jump(0));
                self.patch(jf);
                self.expr(alt)?;
                self.patch(jend);
                Ok(())
            }
            Expr::Unary { op, arg } => {
                match *op {
                    "-" => {
                        // ECMA-262 §13.5.5 unary minus of a Number literal: the negated Number
                        // (`-0` is the negative zero), a constant.
                        if let Expr::Num(n) = &**arg {
                            let i = self.const_idx(Value::Num(-*n));
                            self.emit(Op::Const(i));
                        } else {
                            self.expr(arg)?;
                            self.emit(Op::Neg);
                        }
                    }
                    "+" => {
                        self.expr(arg)?;
                        self.emit(Op::Plus);
                    }
                    "!" => {
                        self.expr(arg)?;
                        self.emit(Op::Not);
                    }
                    "~" => {
                        self.expr(arg)?;
                        self.emit(Op::BitNot);
                    }
                    "void" => {
                        self.expr(arg)?;
                        self.emit(Op::Void);
                    }
                    "typeof" => {
                        if let Expr::Ident(n, _) = &**arg {
                            if self.home(n).is_none() {
                                let name = self.name_idx(n);
                                self.emit(Op::TypeofName(name));
                                return Ok(());
                            }
                        }
                        self.expr(arg)?;
                        self.emit(Op::Typeof);
                    }
                    "delete" => return self.delete_expr(arg),
                    _ => return Err(Bail),
                }
                Ok(())
            }
            Expr::Await(arg) => {
                self.expr(arg)?;
                self.emit(Op::Await);
                Ok(())
            }
            Expr::Yield { delegate, arg } => {
                if let Some(value) = arg {
                    self.expr(value)?;
                } else {
                    self.emit(Op::Undef);
                }
                self.emit(if *delegate { Op::YieldStar } else { Op::Yield });
                Ok(())
            }
            Expr::Update { op, prefix, arg } => {
                if !self.with_scope_floors.is_empty()
                    && matches!(&**arg, Expr::Ident(name, _) if self.home(name).is_none())
                {
                    // UpdateExpression retains one Environment Reference across GetValue,
                    // ToNumeric (which may run user code), and PutValue. Re-resolving a name
                    // through a mutable with object after ToNumeric would be observable.
                    return self.retain_eval_expr(e);
                }
                let kind = match (*op, *prefix) {
                    ("++", true) => UpdKind::PreInc,
                    ("--", true) => UpdKind::PreDec,
                    ("++", false) => UpdKind::PostInc,
                    ("--", false) => UpdKind::PostDec,
                    _ => return Err(Bail),
                };
                self.update_target(arg, kind)
            }
            Expr::Assign {
                op, target, value, ..
            } => self.assign(op, target, value),
            Expr::ToStr(inner) => {
                self.expr(inner)?;
                self.emit(Op::ToStr);
                Ok(())
            }
            Expr::ImportMeta => {
                self.emit(Op::ImportMeta);
                Ok(())
            }
            Expr::NewTarget => {
                self.emit(Op::NewTarget);
                Ok(())
            }
            Expr::ImportCall {
                spec,
                phase,
                options,
            } => {
                self.expr(spec)?;
                if let Some(options) = options {
                    self.expr(options)?;
                }
                self.emit(Op::DynamicImport(*phase, options.is_some()));
                Ok(())
            }
            Expr::PrivateIn { name, obj } => {
                self.expr(obj)?;
                let name = self.name_idx(name);
                let site = self.new_private_site();
                self.emit(Op::PrivateIn(name, site));
                Ok(())
            }
            Expr::TaggedTemplate {
                tag,
                site: site_id,
                quasis,
                subs,
                ..
            } => {
                // Evaluation retains the Reference receiver. EvaluateCall checks IsCallable
                // only after TemplateLiteral ArgumentListEvaluation, including substitutions.
                let (with_this, _) = self.callee_reference(tag)?;
                let site = self.templates.len() as u32;
                self.templates.push((*site_id, quasis.clone()));
                self.emit(Op::TemplateObject(site));
                for substitution in subs {
                    self.expr(substitution)?;
                }
                let argc = u16::try_from(subs.len() + 1).map_err(|_| Bail)?;
                let cache = self.new_call_cache();
                let call = self.emit(if with_this {
                    Op::CallWithThis(argc, cache)
                } else {
                    Op::Call(argc, cache)
                });
                self.name_call(call, Some(&crate::callee_name::callee_name(tag)));
                Ok(())
            }
            Expr::OptionalChain(inner) => {
                let mut shorts = Vec::new();
                self.opt_chain(inner, &mut shorts)?;
                if shorts.is_empty() {
                    return Ok(()); // no optional link actually taken a short path
                }
                let done = self.emit(Op::Jump(0));
                for j in shorts {
                    self.patch(j);
                }
                self.emit(Op::Undef);
                self.patch(done);
                Ok(())
            }
            Expr::Call {
                callee,
                args,
                optional: false,
                ..
            } => {
                if self.self_hosted_intrinsic(callee, args)? {
                    return Ok(());
                }
                if matches!(&**callee, Expr::Ident(n, _) if n == "eval") {
                    if !self.direct_eval {
                        return Err(Bail);
                    }

                    // ECMA-262 §13.3.6 evaluates the identifier Reference/GetValue before
                    // ArgumentListEvaluation, then recognizes direct eval only when that exact
                    // non-property Reference still names this Realm's %eval%. Retain the
                    // with-object receiver (if any) alongside the callee, stage every argument
                    // and spread in source order, and decide direct-vs-ordinary only after the
                    // complete list exists. PerformEval itself is atomic, but yield/await in its
                    // arguments stays visible to this heap continuation.
                    if self.home("eval").is_none() {
                        let name = self.name_idx("eval");
                        let cache = self.new_name_cache(name);
                        self.emit(Op::LoadNameForCall(name, cache));
                    } else {
                        self.emit(Op::Undef);
                        self.expr(callee)?;
                    }
                    self.emit(Op::NewArray);
                    for arg in args {
                        match arg {
                            ArrayElem::Item(expr) => {
                                self.expr(expr)?;
                                self.emit(Op::ArrayPush);
                            }
                            ArrayElem::Spread(expr) => {
                                self.expr(expr)?;
                                self.emit(Op::ArraySpread);
                            }
                            ArrayElem::Hole => return Err(Bail),
                        }
                    }
                    let call = self.emit(Op::EvalCallArgsArray);
                    self.name_call(call, Some("eval"));
                    return Ok(());
                }
                match &**callee {
                    Expr::Super => {
                        // ECMA-262 §13.3.7.1 obtains new.target and the live superclass before
                        // ArgumentListEvaluation. Keep both on the continuation stack while any
                        // argument or spread suspends, then perform Construct/BindThisValue/field
                        // initialization as one non-suspending completion step.
                        self.emit(Op::SuperCallStart);
                        self.emit(Op::NewArray);
                        for arg in args {
                            match arg {
                                ArrayElem::Item(expression) => {
                                    self.expr(expression)?;
                                    self.emit(Op::ArrayPush);
                                }
                                ArrayElem::Spread(expression) => {
                                    self.expr(expression)?;
                                    self.emit(Op::ArraySpread);
                                }
                                ArrayElem::Hole => return Err(Bail),
                            }
                        }
                        self.emit(Op::SuperCallArgsArray);
                    }
                    other => {
                        // Only this node's own call is in tail position: calls in its callee
                        // and arguments are not (ECMA-262 §15.10.2 HasCallInTailPosition).
                        let tail = self.tail_call_node == e as *const Expr as usize;
                        if tail {
                            self.tail_call_node = 0;
                        }
                        let (with_this, allow_inline) = self.callee_reference(other)?;
                        self.tail_finish = tail;
                        self.pending_call_name = Some(crate::callee_name::callee_name(other));
                        self.finish_call(args, with_this, allow_inline)?;
                    }
                }
                Ok(())
            }
            Expr::New { callee, args, .. } => {
                self.expr(callee)?;
                if args.iter().all(|arg| matches!(arg, ArrayElem::Item(_))) {
                    let argc = u16::try_from(args.len()).map_err(|_| Bail)?;
                    for arg in args {
                        let ArrayElem::Item(expr) = arg else {
                            unreachable!("plain constructor arguments checked above")
                        };
                        self.expr(expr)?;
                    }
                    let cache = self.new_construct_cache();
                    let construct = self.emit(Op::New(argc, cache));
                    self.name_call(construct, Some(&crate::callee_name::callee_name(callee)));
                    return Ok(());
                }

                // Evaluate/expand each argument in source order before IsConstructor, as required
                // by EvaluateNew and ArgumentListEvaluation. The private array does not escape.
                self.emit(Op::NewArray);
                for arg in args {
                    match arg {
                        ArrayElem::Item(expr) => {
                            self.expr(expr)?;
                            self.emit(Op::ArrayPush);
                        }
                        ArrayElem::Spread(expr) => {
                            self.expr(expr)?;
                            self.emit(Op::ArraySpread);
                        }
                        ArrayElem::Hole => return Err(Bail),
                    }
                }
                let construct = self.emit(Op::NewArgsArray);
                self.name_call(construct, Some(&crate::callee_name::callee_name(callee)));
                Ok(())
            }
            Expr::Regex { body, flags } => {
                let body = self.name_idx(body);
                let flags = self.name_idx(flags);
                self.emit(Op::MakeRegExp(body, flags));
                Ok(())
            }
            Expr::Array(elems) => {
                if elems
                    .iter()
                    .all(|element| matches!(element, ArrayElem::Item(_)))
                {
                    let count = u16::try_from(elems.len()).map_err(|_| Bail)?;
                    for element in elems {
                        let ArrayElem::Item(value) = element else {
                            unreachable!("plain array literal fast path checked above")
                        };
                        self.expr(value)?;
                    }
                    self.emit(Op::MakeArray(count));
                    return Ok(());
                }

                self.emit(Op::NewArray);
                for element in elems {
                    match element {
                        ArrayElem::Item(value) => {
                            self.expr(value)?;
                            self.emit(Op::ArrayPush);
                        }
                        ArrayElem::Spread(value) => {
                            self.expr(value)?;
                            self.emit(Op::ArraySpread);
                        }
                        ArrayElem::Hole => {
                            self.emit(Op::ArrayHole);
                        }
                    }
                }
                Ok(())
            }
            Expr::Object(props) => {
                // A static, ordinary own-property key: no ToPropertyKey effects, not the
                // `__proto__` setter form, not a private name.
                let static_key = |key: &PropKey| {
                    matches!(key, PropKey::Ident(key) if key != "__proto__" && !key.starts_with('#'))
                        || matches!(key, PropKey::Str(key) if &**key != "__proto__" && !key.starts_with('#'))
                };
                // Concise methods are ordinary enumerable data properties (ECMA-262
                // MethodDefinitionEvaluation: DefineMethod, SetFunctionName(closure, key),
                // DefineMethodProperty), so a literal of static data keys and methods has a
                // fixed final shape. A method that can observe its [[HomeObject]] (`super`,
                // direct eval) keeps the incremental builder, which binds the literal itself.
                let plain = props.iter().all(|property| match property {
                    PropDef::KeyValue { key, .. } => static_key(key),
                    PropDef::Method { key, func } => {
                        static_key(key) && !func.observes_home_object()
                    }
                    _ => false,
                });
                if !plain {
                    // An identifier or string property name is already a property key.
                    let static_name = |key: &PropKey| match key {
                        PropKey::Ident(key) => Some(key.clone()),
                        PropKey::Str(key) => Some(key.to_string()),
                        PropKey::Num(_) | PropKey::Computed(_) => None,
                    };
                    self.emit(Op::NewObject);
                    for property in props {
                        match property {
                            PropDef::KeyValue { key, value } | PropDef::Cover { key, value } => {
                                let anonymous = crate::eval::is_anonymous_fn(value);
                                if let Some(name) = static_name(key) {
                                    self.expr(value)?;
                                    let name = self.property_name_idx(&name);
                                    self.emit(Op::ObjectDataName(name, anonymous));
                                } else {
                                    self.object_literal_key(key)?;
                                    self.expr(value)?;
                                    self.emit(Op::ObjectData(anonymous));
                                }
                            }
                            PropDef::Method { key, func }
                            | PropDef::Getter { key, func }
                            | PropDef::Setter { key, func } => {
                                let kind = match property {
                                    PropDef::Method { .. } => 0,
                                    PropDef::Getter { .. } => 1,
                                    _ => 2,
                                };
                                let function = self.funcs.len() as u32;
                                self.funcs.push(func.clone());
                                if let Some(name) = static_name(key) {
                                    let name = self.property_name_idx(&name);
                                    self.emit(Op::ObjectMethodName(function, kind, name));
                                } else {
                                    self.object_literal_key(key)?;
                                    self.emit(Op::ObjectMethod(function, kind));
                                }
                            }
                            PropDef::Spread(value) => {
                                self.expr(value)?;
                                self.emit(Op::ObjectSpread);
                            }
                            PropDef::Proto(value) => {
                                self.expr(value)?;
                                self.emit(Op::ObjectProto);
                            }
                        }
                    }
                    return Ok(());
                }

                let count = u16::try_from(props.len()).map_err(|_| Bail)?;
                // Keys must land contiguously in `names`; values go on the stack in order.
                let mut keys: Vec<String> = Vec::new();
                for p in props {
                    let (PropDef::KeyValue { key, .. } | PropDef::Method { key, .. }) = p else {
                        unreachable!("plain object literal fast path checked above")
                    };
                    let k = match key {
                        PropKey::Ident(k) => k.clone(),
                        PropKey::Str(k) => k.to_string(),
                        _ => unreachable!("plain object literal key checked above"),
                    };
                    match p {
                        // NamedEvaluation: `{ m: function(){} }` names the anonymous function "m".
                        PropDef::KeyValue { value, .. } => self.named_expr(value, &k)?,
                        // The method closure, named by its key (SetFunctionName).
                        PropDef::Method { func, .. } => {
                            let function = self.funcs.len() as u32;
                            self.funcs.push(func.clone());
                            let name = self.name_idx(&k);
                            self.emit(Op::MakeClosure(function, name));
                        }
                        _ => unreachable!("plain object literal fast path checked above"),
                    }
                    keys.push(k);
                }
                // Keys go into `names` only after every value is compiled — value expressions
                // add names of their own, and the key range must stay contiguous.
                let start = self.names.len() as u32;
                for k in &keys {
                    self.append_name(&crate::value::encode_string_key(k));
                }
                // Distinct keys → a pre-shaped template site ({a:1, a:2} keeps the insert path:
                // the template's slot-indexed value writes assume one slot per key).
                let tidx = {
                    let mut sorted: Vec<&String> = keys.iter().collect();
                    sorted.sort();
                    if count > 0 && sorted.windows(2).all(|w| w[0] != w[1]) {
                        self.obj_maps += 1;
                        self.obj_maps - 1
                    } else {
                        u32::MAX
                    }
                };
                self.emit(Op::MakeObject(start, count, tidx));
                Ok(())
            }
            other => {
                if crate::eval::expr_has_own_suspension(other) {
                    log_bail("expr", &format!("{:.60}", format!("{other:?}")));
                    return Err(Bail);
                }
                self.retain_eval_expr(other)
            }
        }
    }

    /// `++`/`--` on a local slot, `obj.name`, or `obj[k]`; `kind` carries pre/post/discard.
    fn update_target(&mut self, arg: &Expr, kind: UpdKind) -> CResult {
        match arg {
            Expr::Paren(inner) => self.update_target(inner, kind),
            Expr::Ident(name, _) => match self.home(name) {
                Some(Home::Slot(slot, false)) => {
                    self.emit(Op::UpdateLocal(slot, kind));
                    Ok(())
                }
                Some(Home::Env(false)) => {
                    let n = self.name_idx(name);
                    self.emit(Op::UpdateCap(n, kind));
                    Ok(())
                }
                Some(home @ (Home::Slot(_, true) | Home::Env(true))) => {
                    let name = self.name_idx(name);
                    match home {
                        Home::Slot(slot, true) => self.emit(Op::LoadLocal(slot)),
                        Home::Env(true) => self.emit(Op::LoadCap(name)),
                        _ => unreachable!(),
                    };
                    self.emit(Op::UpdateConst(name, kind));
                    Ok(())
                }
                None => {
                    let n = self.name_idx(name);
                    let c = self.new_name_cache(n);
                    self.emit(Op::UpdateNameCached(n, c, kind));
                    Ok(())
                }
            },
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                self.emit(Op::SuperUpdate(kind));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                self.emit(Op::SuperUpdate(kind));
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if prop.starts_with('#') => {
                self.expr(obj)?;
                let name = self.property_name_idx(prop);
                self.emit(Op::UpdatePrivate(name, kind));
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                let i = self.property_name_idx(prop);
                let c = self.new_cache(i);
                self.emit(Op::UpdateProp(i, c, kind));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                self.expr(obj)?;
                self.expr(index)?;
                self.emit(Op::UpdateElem(kind));
                Ok(())
            }
            other => {
                log_bail("expr", &format!("{:.60}", format!("{other:?}")));
                Err(Bail)
            }
        }
    }

    fn assign(&mut self, op: &str, target: &Expr, value: &Expr) -> CResult {
        if matches!(op, "&&=" | "||=" | "??=") {
            return self.logical_assign(op, target, value);
        }
        if op == "=" && matches!(target, Expr::Array(_) | Expr::Object(_)) {
            // ECMA-262 DestructuringAssignmentEvaluation applies equally to ordinary and
            // resumable bodies. Preserve the exact RHS identity beneath the explicit pattern
            // lowering, including its prepared references and IteratorClose cleanup pads.
            self.expr(value)?;
            self.emit(Op::Dup);
            self.assignment_pattern(target)?;
            return Ok(());
        }
        match target {
            Expr::Ident(name, _) => match self.home(name) {
                Some(Home::Slot(slot, is_const)) => {
                    if is_const {
                        return self.immutable_assignment(Home::Slot(slot, true), name, op, value);
                    }
                    if op == "=" {
                        self.named_expr(value, name)?;
                        self.check_assignment_local_initialized(slot);
                    } else {
                        self.emit(Op::LoadLocal(slot));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::Dup);
                    self.emit(Op::StoreLocal(slot));
                    Ok(())
                }
                Some(Home::Env(is_const)) => {
                    if is_const {
                        return self.immutable_assignment(Home::Env(true), name, op, value);
                    }
                    let n = self.name_idx(name);
                    if op == "=" {
                        self.named_expr(value, name)?;
                    } else {
                        self.emit(Op::LoadCap(n));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::Dup);
                    self.emit(Op::StoreCap(n));
                    Ok(())
                }
                None => {
                    let i = self.name_idx(name);
                    let reference = if self.name_reference_can_change(name) {
                        let reference = self.fresh_reference()?;
                        self.emit(Op::ResolveNameRef(i, reference));
                        Some(reference)
                    } else {
                        None
                    };
                    if op == "=" {
                        self.named_expr(value, name)?;
                    } else {
                        if let Some(reference) = reference {
                            self.emit(Op::LoadRef(reference));
                        } else {
                            let c = self.new_name_cache(i);
                            self.emit(Op::LoadName(i, c));
                        }
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::Dup);
                    if let Some(reference) = reference {
                        self.emit(Op::StoreRef(reference));
                    } else {
                        self.emit_store_name(i);
                    }
                    Ok(())
                }
            },
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                if op == "=" {
                    self.expr(value)?;
                } else {
                    self.emit(Op::SuperGetKeep);
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                self.emit(Op::SuperSet);
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                if op == "=" {
                    self.expr(value)?;
                } else {
                    self.emit(Op::SuperGetKeep);
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                self.emit(Op::SuperSet);
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if prop.starts_with('#') => {
                self.expr(obj)?;
                let name = self.property_name_idx(prop);
                if op == "=" {
                    self.expr(value)?;
                } else {
                    let site = self.new_private_site();
                    self.emit(Op::GetPrivateKeep(name, site));
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                let site = self.new_private_site();
                self.emit(Op::SetPrivate(name, site));
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                self.expr(obj)?;
                let i = self.property_name_idx(prop);
                if op == "=" {
                    self.expr(value)?;
                } else {
                    // Compound: base evaluated once (Dup), get before the RHS — Reference order.
                    self.emit(Op::Dup);
                    let cg = self.new_cache(i);
                    self.emit(Op::GetProp(i, cg));
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                let c = self.new_cache(i);
                self.emit(Op::SetProp(i, c));
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                if let Some(slot) = self.fused_elem_slot(obj, &[index.as_ref(), value]) {
                    self.expr(index)?;
                    if op == "=" {
                        self.expr(value)?;
                    } else {
                        self.emit(Op::ToPropKeyLocal(slot));
                        self.emit(Op::Dup);
                        self.emit(Op::GetElemLocal(slot));
                        self.expr(value)?;
                        self.emit_compound(op)?;
                    }
                    self.emit(Op::SetElemLocal(slot));
                    return Ok(());
                }
                self.expr(obj)?;
                self.expr(index)?;
                if op == "=" {
                    self.expr(value)?;
                } else {
                    // Compound: coerce a side-effecting key once, then read-modify-write.
                    self.emit(Op::ToPropKey);
                    self.emit(Op::Dup2);
                    self.emit(Op::GetElem);
                    self.expr(value)?;
                    self.emit_compound(op)?;
                }
                self.emit(Op::SetElem);
                Ok(())
            }
            _ => Err(Bail),
        }
    }

    fn logical_super_assign(&mut self, op: &str, value: &Expr) -> CResult {
        self.emit(Op::SuperGetKeep);
        let current = self.fresh_slot("%logical-super-current%");
        let base = self.fresh_slot("%logical-super-base%");
        let key = self.fresh_slot("%logical-super-key%");
        let receiver = self.fresh_slot("%logical-super-receiver%");
        self.emit(Op::StoreLocal(current));
        self.emit(Op::StoreLocal(base));
        self.emit(Op::StoreLocal(key));
        self.emit(Op::StoreLocal(receiver));
        self.emit(Op::LoadLocal(current));
        let done = match op {
            "&&=" => self.emit(Op::JumpIfFalsePeek(0)),
            "||=" => self.emit(Op::JumpIfTruePeek(0)),
            "??=" => self.emit(Op::JumpIfNotNullishPeek(0)),
            _ => return Err(Bail),
        };
        self.emit(Op::Pop);
        self.emit(Op::LoadLocal(receiver));
        self.emit(Op::LoadLocal(key));
        self.emit(Op::LoadLocal(base));
        self.expr(value)?;
        self.emit(Op::SuperSet);
        self.patch(done);
        Ok(())
    }

    /// ECMA-262 §13.16.2 logical assignment: evaluate the left Reference exactly once, read it,
    /// and only evaluate/write the RHS when the operator's short-circuit test permits it. The
    /// old value remains the expression result on the short path; the stored RHS is the result on
    /// the write path. Hidden slots retain member bases/keys across a suspending RHS.
    fn logical_assign(&mut self, op: &str, target: &Expr, value: &Expr) -> CResult {
        fn short_jump(compiler: &mut Compiler, op: &str) -> Result<usize, Bail> {
            Ok(match op {
                "&&=" => compiler.emit(Op::JumpIfFalsePeek(0)),
                "||=" => compiler.emit(Op::JumpIfTruePeek(0)),
                "??=" => compiler.emit(Op::JumpIfNotNullishPeek(0)),
                _ => return Err(Bail),
            })
        }

        match target {
            Expr::Paren(inner) => self.logical_assign(op, inner, value),
            Expr::Ident(name, _) => match self.home(name) {
                Some(Home::Slot(slot, false)) => {
                    self.emit(Op::LoadLocal(slot));
                    let done = short_jump(self, op)?;
                    self.emit(Op::Pop);
                    self.named_expr(value, name)?;
                    self.emit(Op::Dup);
                    self.emit(Op::StoreLocal(slot));
                    self.patch(done);
                    Ok(())
                }
                Some(Home::Env(false)) => {
                    let name_index = self.name_idx(name);
                    self.emit(Op::LoadCap(name_index));
                    let done = short_jump(self, op)?;
                    self.emit(Op::Pop);
                    self.named_expr(value, name)?;
                    self.emit(Op::Dup);
                    self.emit(Op::StoreCap(name_index));
                    self.patch(done);
                    Ok(())
                }
                Some(home @ (Home::Slot(_, true) | Home::Env(true))) => {
                    let name_index = self.name_idx(name);
                    match home {
                        Home::Slot(slot, true) => self.emit(Op::LoadLocal(slot)),
                        Home::Env(true) => self.emit(Op::LoadCap(name_index)),
                        _ => unreachable!(),
                    };
                    let done = short_jump(self, op)?;
                    self.emit(Op::Pop);
                    self.named_expr(value, name)?;
                    match home {
                        Home::Slot(slot, true) => {
                            self.emit(Op::StoreConstLocal(slot, name_index));
                        }
                        Home::Env(true) => {
                            self.emit(Op::StoreConstCap(name_index));
                        }
                        _ => unreachable!(),
                    }
                    self.patch(done);
                    Ok(())
                }
                None => {
                    let name_index = self.name_idx(name);
                    let reference = if self.name_reference_can_change(name) {
                        let reference = self.fresh_reference()?;
                        self.emit(Op::ResolveNameRef(name_index, reference));
                        self.emit(Op::LoadRef(reference));
                        Some(reference)
                    } else {
                        let cache = self.new_name_cache(name_index);
                        self.emit(Op::LoadName(name_index, cache));
                        None
                    };
                    let done = short_jump(self, op)?;
                    self.emit(Op::Pop);
                    self.named_expr(value, name)?;
                    self.emit(Op::Dup);
                    if let Some(reference) = reference {
                        self.emit(Op::StoreRef(reference));
                    } else {
                        self.emit_store_name(name_index);
                    }
                    self.patch(done);
                    Ok(())
                }
            },
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_named_reference(prop);
                self.logical_super_assign(op, value)
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if matches!(**obj, Expr::Super) => {
                self.super_computed_reference(index)?;
                self.logical_super_assign(op, value)
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if prop.starts_with('#') => {
                let base = self.fresh_slot("%logical-private-base%");
                self.expr(obj)?;
                self.emit(Op::StoreLocal(base));
                let name = self.property_name_idx(prop);
                self.emit(Op::LoadLocal(base));
                let site = self.new_private_site();
                self.emit(Op::GetPrivate(name, site));
                let done = short_jump(self, op)?;
                self.emit(Op::Pop);
                self.emit(Op::LoadLocal(base));
                self.expr(value)?;
                let site = self.new_private_site();
                self.emit(Op::SetPrivate(name, site));
                self.patch(done);
                Ok(())
            }
            Expr::Member {
                obj,
                prop,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) && !prop.starts_with('#') => {
                let base_slot = self.fresh_slot("%logical-base%");
                self.expr(obj)?;
                self.emit(Op::StoreLocal(base_slot));
                let name_index = self.property_name_idx(prop);
                let get_cache = self.new_cache(name_index);
                self.emit(Op::GetPropLocal(base_slot, name_index, get_cache));
                let done = short_jump(self, op)?;
                self.emit(Op::Pop);
                self.emit(Op::LoadLocal(base_slot));
                self.expr(value)?;
                let set_cache = self.new_cache(name_index);
                self.emit(Op::SetProp(name_index, set_cache));
                self.patch(done);
                Ok(())
            }
            Expr::Index {
                obj,
                index,
                optional: false,
                ..
            } if !matches!(**obj, Expr::Super) => {
                let base_slot = self.fresh_slot("%logical-base%");
                let key_slot = self.fresh_slot("%logical-key%");
                self.expr(obj)?;
                self.expr(index)?;
                self.emit(Op::ToPropKey);
                self.emit(Op::StoreLocal(key_slot));
                self.emit(Op::StoreLocal(base_slot));
                self.emit(Op::LoadLocal(base_slot));
                self.emit(Op::LoadLocal(key_slot));
                self.emit(Op::GetElem);
                let done = short_jump(self, op)?;
                self.emit(Op::Pop);
                self.emit(Op::LoadLocal(base_slot));
                self.emit(Op::LoadLocal(key_slot));
                self.expr(value)?;
                self.emit(Op::SetElem);
                self.patch(done);
                Ok(())
            }
            _ => Err(Bail),
        }
    }

    fn emit_compound(&mut self, op: &str) -> CResult {
        let bop = match op {
            "+=" => Op::Add,
            "-=" => Op::Sub,
            "*=" => Op::Mul,
            "/=" => Op::Div,
            "%=" => Op::Mod,
            "&=" => Op::BitAnd,
            "|=" => Op::BitOr,
            "^=" => Op::BitXor,
            "<<=" => Op::Shl,
            ">>=" => Op::Shr,
            ">>>=" => Op::UShr,
            "**=" => {
                let i = self.name_idx("**");
                Op::GenBin(i)
            }
            _ => return Err(Bail),
        };
        self.emit(bop);
        Ok(())
    }
}

// ---------------------------------------------------------------------------------------------
// VM
// ---------------------------------------------------------------------------------------------

/// Completion carried through an asynchronous DisposeResources operation. Distinct return kinds
/// preserve async-generator Await rules and externally injected returns across nested handlers.
pub enum DisposeCompletion {
    Normal,
    Throw(Value),
    SourceReturn(Value),
    BareReturn,
    ResumeReturn(Value),
    Jump { target: usize, handler_depth: usize },
}

/// How one run of the VM ended: the body returned a value, suspended at an `await` (async bodies
/// only — see [`VmCoro`]), or — carried as `Err(Abrupt::Throw)` — threw.
pub enum VmStep {
    /// Terminal exit from a borrowed AST fragment, after every local cleanup pad.
    FragmentExit(FragmentExitKind, Value),
    Done(Value),
    /// An explicit `return expression`; async generators must Await its value before completion.
    Return(Value),
    /// An explicit source `return;`, kept distinct from both body fallthrough and expression
    /// returns so it unwinds resources without adding an async-generator Await.
    BareReturn,
    /// A generator `.return(value)` completion whose value was already awaited by
    /// AsyncGeneratorUnwrapYieldResumption before it entered a finalizer.
    ResumeReturn(Value),
    /// A `break`/`continue` Completion. `handler_depth` identifies the handler stack at the
    /// destination so only intervening regions are unwound.
    AbruptJump {
        target: usize,
        handler_depth: usize,
    },
    Await(Value),
    AsyncClose {
        iterator: Value,
        from_sync: bool,
        swallow_error: bool,
    },
    Dispose {
        frame: Vec<crate::interpreter::Disposable>,
        completion: DisposeCompletion,
    },
    Yield(Value),
    YieldStar(Value),
}

/// Execute a compiled function body. `env` is the root for free-name resolution — the *definition*
/// environment when called leanly (see `Interp::call_user_inner`), since a compiled body has no
/// observable activation. Parameters seed straight into slots; `this_val` is the already-bound
/// `this` (computed only when the body reads it). Synchronous bodies only — an async body runs
/// through [`VmCoro`], which drives [`run_vm`] and can suspend it.
///
/// The slot and operand-stack buffers come from a per-interpreter pool ([`Interp::vm_pool`]) so a
/// hot call tree does not allocate two `Vec`s per call.
pub fn run(
    i: &mut Interp,
    chunk: &Chunk,
    env: &Env,
    this_val: Value,
    args: &[Value],
) -> Result<Value, Abrupt> {
    run_inner(i, chunk, env, this_val, args, None)
}

/// Move a cold ordinary function's already-instantiated AST activation into its whole
/// bytecode continuation. Only body-level settled loops are admitted: their outer parameter
/// binding, hoisting, prefix effects and lexical initialization must never run a second time.
pub(crate) fn try_function_osr(
    i: &mut Interp,
    site: &LoopSite,
    live_env: &Env,
) -> Result<Option<crate::interpreter::Completion>, Abrupt> {
    let Some(frame) = i.fn_frames.last() else {
        return Ok(None);
    };
    let construct = frame.construct;
    let callee = frame.callee();
    let (function, closure) = match &callee.borrow().call {
        crate::value::Callable::User(user) => (user.func.clone(), user.env.clone()),
        _ => return Ok(None),
    };
    let address = site as *const _ as usize;
    if function.is_async
        || function.is_generator
        || (construct
            && i.class_info
                .get(&(crate::value::Gc::as_ptr(&callee) as usize))
                .is_some_and(|class| class.derived))
        || !function
            .body
            .iter()
            .any(|statement| function_osr_site(statement) == Some(address))
        || live_env.borrow().under_with
    {
        return Ok(None);
    }
    if function.code.get().is_none() {
        let _ = function.code.set(compile(&function));
    }
    let Some(baseline) = function.code.get().and_then(Option::as_ref) else {
        return Ok(None);
    };
    let legacy_mapped_parameters = !function.is_strict
        && !function.is_arrow
        && !function.params.is_empty()
        && function.params.iter().all(|parameter| {
            !parameter.rest
                && parameter.default.is_none()
                && matches!(parameter.pattern, Pattern::Ident(_))
        });
    let chunk = baseline;
    if construct && chunk.has_tail_calls() {
        return Ok(None);
    }
    let Some(entry) = chunk
        .function_osr_entries
        .iter()
        .find(|entry| entry.site == address)
    else {
        return Ok(None);
    };
    let activation = crate::interpreter::nearest_var_env(live_env);
    let aliased_homes = if legacy_mapped_parameters && !chunk.prepared_entry {
        let formals = crate::interpreter::param_bound_names(&function.params);
        entry
            .bindings
            .iter()
            .filter(|(name, slot, _)| {
                (*slot as usize) < chunk.n_params
                    && formals.iter().any(|formal| formal == name.as_ref())
            })
            .map(|(name, slot, _)| (activation.clone(), name.clone(), *slot))
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    // Retained AST expression/pattern evaluators copy local homes into a temporary record.
    // They cannot currently share a slot alias with legacy ParameterMap writes. Preserve the
    // established environment-backed loop fragment path for these uncommon projections.
    if chunk.eval_exprs.iter().any(|plan| {
        plan.locals
            .iter()
            .any(|local| aliased_homes.iter().any(|(_, _, slot)| *slot == local.slot))
    }) || chunk.assignment_targets.iter().any(|plan| {
        plan.locals
            .iter()
            .any(|local| aliased_homes.iter().any(|(_, _, slot)| *slot == local.slot))
    }) {
        return Ok(None);
    }
    if chunk.makes_env() {
        // Defaults can split parameter/body Environment Records. A capture that was homed
        // into a nested AST block likewise cannot be redirected into the function record.
        // Verify every compiled capture against this exact live record before transferring.
        if crate::interpreter::params_have_expr(&function.params) {
            return Ok(None);
        }
        let scope = activation.borrow();
        if chunk.cap_inits.iter().any(|init| {
            let name = match init {
                CapInit::Param(_, name)
                | CapInit::Rest(_, name)
                | CapInit::Var(name)
                | CapInit::Fn(_, name)
                | CapInit::Lexical(name, _) => name,
            };
            !scope.vars.contains_key(name)
        }) || (chunk.env_this && !scope.vars.contains_key("this"))
        {
            return Ok(None);
        }
    }
    // Seed by binding identity through the parked lexical chain, including TDZ cells. This
    // inspects only engine-owned bindings and performs no author property read or conversion.
    let mut initial = Vec::with_capacity(entry.bindings.len());
    let mut private_homes = Vec::with_capacity(entry.bindings.len());
    for (name, slot, shadow_depth) in &entry.bindings {
        let mut cursor = Some(live_env.clone());
        let mut value = None;
        let mut shadow_depth = *shadow_depth;
        while let Some(environment) = cursor {
            let scope = environment.borrow();
            if let Some(binding) = scope.vars.get(name) {
                if shadow_depth == 0 {
                    value = Some(if binding.initialized {
                        binding.value.clone()
                    } else {
                        Value::Empty
                    });
                    private_homes.push((environment.clone(), name.clone(), *slot));
                    break;
                }
                shadow_depth -= 1;
            }
            cursor = scope.parent.clone();
        }
        let Some(value) = value else { return Ok(None) };
        initial.push((*slot, value));
    }
    let this_val = if chunk.needs_frame_this() {
        i.get_var("this", live_env)?
    } else {
        Value::Undefined
    };
    let (mut slots, mut stack) = i.vm_pool.pop().unwrap_or_default();
    slots.resize_with(chunk.n_slots, || PackedValue::pack(Value::Undefined));
    for (slot, value) in initial {
        slots.write_value(slot as usize, value);
    }
    let cap_env = if chunk.makes_env() || chunk.prepared_entry {
        activation.clone()
    } else {
        closure.clone()
    };
    let mut env = if !entry.environment_handlers.is_empty() {
        live_env.clone()
    } else {
        cap_env.clone()
    };
    let mut pc = entry.pc;
    let mut handlers = entry
        .environment_handlers
        .iter()
        .map(|&pc| {
            let Op::PushFinally(throw_pc, return_pc, bare_return_pc, resume_return_pc, jump_pc) =
                chunk.ops[pc]
            else {
                unreachable!("function OSR environment handler must name its cleanup pad")
            };
            Handler {
                stack_depth: 0,
                target: HandlerTarget::Finally {
                    throw_pc: throw_pc as usize,
                    return_pc: return_pc as usize,
                    bare_return_pc: bare_return_pc as usize,
                    resume_return_pc: resume_return_pc as usize,
                    jump_pc: jump_pc as usize,
                },
            }
        })
        .collect::<Vec<_>>();
    let mut disposal_frames = Vec::new();
    let mut class_states = (0..chunk.class_plans.len())
        .map(|_| None)
        .collect::<Vec<_>>();
    let mut references = (0..chunk.n_refs)
        .map(|_| crate::eval::PreparedReferenceSlot::default())
        .collect::<Vec<_>>();
    let mut tiering = crate::tiering::VmTiering::hot();
    // Transfer all uncaptured binding owners, including non-formal locals, into canonical
    // shared slot Cells. Their parked records must not retain overwritten objects. Captured
    // homes remain in their original environments and are absent from entry.bindings.
    // The scope restores even on unwind and drops before recycling any slot owner.
    let aliases = if private_homes.is_empty() {
        None
    } else {
        let registry = i.borrowed_parameters.get_or_insert_with(Default::default);
        Some(unsafe { registry.enter(&private_homes, &slots) })
    };
    #[cfg(test)]
    TEST_FUNCTION_OSR_ENTRIES.with(|entries| entries.set(entries.get() + 1));
    let result = drive_vm(
        i,
        chunk,
        &mut env,
        &cap_env,
        &mut references,
        &slots,
        &mut stack,
        &mut pc,
        &this_val,
        &mut handlers,
        &mut disposal_frames,
        &mut class_states,
        None,
        false,
        (matches!(i.tier, Tier::Jit) && !function.run_once).then_some(&mut tiering),
    );
    drop(aliases);
    slots.clear();
    stack.clear();
    if i.vm_pool.len() < 64 {
        i.vm_pool.push((slots, stack));
    }
    let completion = match result {
        Ok(VmStep::Done(value) | VmStep::Return(value) | VmStep::ResumeReturn(value)) => {
            Err(Abrupt::Return(value))
        }
        Ok(VmStep::BareReturn) => Err(Abrupt::Return(Value::Undefined)),
        Err(error) => Err(error),
        _ => unreachable!("ordinary function OSR cannot suspend or escape a loop completion"),
    };
    Ok(Some(completion))
}

#[cfg(test)]
thread_local! {
    pub(crate) static TEST_FUNCTION_OSR_ENTRIES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// Enter baseline Script bytecode and tier only this already-live activation.
/// The caller pins the exact Chunk for the entire run; no Script/GDI replay occurs.
#[cfg(test)]
pub(crate) fn run_tiered_script(
    i: &mut Interp,
    chunk: &Rc<Chunk>,
    env: &Env,
    this_val: Value,
) -> Result<Value, Abrupt> {
    let mut tiering = crate::tiering::VmTiering::new();
    run_inner(i, chunk, env, this_val, &[], Some(&mut tiering))
}

fn run_inner(
    i: &mut Interp,
    chunk: &Chunk,
    env: &Env,
    this_val: Value,
    args: &[Value],
    tiering: Option<&mut crate::tiering::VmTiering>,
) -> Result<Value, Abrupt> {
    // Captured locals (and a lexically-read `this`) live in a per-call activation env; slots
    // hold everything else. No captures → the definition env is used directly.
    let mut env = chunk.make_run_env(i, env, &this_val, args);
    let cap_env = env.clone();
    let (mut slots, mut stack) = i.vm_pool.pop().unwrap_or_default();
    let seed = chunk.n_params.min(args.len());
    slots.extend(args[..seed].iter().cloned().map(PackedValue::pack));
    slots.resize_with(chunk.n_slots, || PackedValue::pack(Value::Undefined));
    if let Some(rest) = chunk.rest_slot {
        let rest_values = args.get(chunk.n_params..).unwrap_or(&[]).to_vec();
        slots.write_value(rest as usize, i.make_array(rest_values));
    }
    if let Some(s) = chunk.arguments_slot {
        slots.write_value(s as usize, chunk.arguments_slot_value(i, args, &env));
    }
    let mut pc = 0usize;
    let mut handlers: Vec<Handler> = Vec::new();
    let mut disposal_frames: Vec<Vec<crate::interpreter::Disposable>> = Vec::new();
    let mut class_states = (0..chunk.class_plans.len())
        .map(|_| None)
        .collect::<Vec<_>>();
    let mut references = (0..chunk.n_refs)
        .map(|_| crate::eval::PreparedReferenceSlot::default())
        .collect::<Vec<_>>();
    let r = drive_vm(
        i,
        chunk,
        &mut env,
        &cap_env,
        &mut references,
        &slots,
        &mut stack,
        &mut pc,
        &this_val,
        &mut handlers,
        &mut disposal_frames,
        &mut class_states,
        None,
        false,
        tiering,
    );
    slots.clear();
    stack.clear();
    if i.vm_pool.len() < 64 {
        i.vm_pool.push((slots, stack));
    }
    match r? {
        VmStep::Done(v) | VmStep::Return(v) | VmStep::ResumeReturn(v) => Ok(v),
        VmStep::BareReturn => Ok(Value::Undefined),
        VmStep::AbruptJump { .. } => unreachable!("drive_vm consumes loop completions"),
        VmStep::FragmentExit(..) => unreachable!("ordinary entry cannot run an AST fragment"),
        VmStep::Await(_)
        | VmStep::AsyncClose { .. }
        | VmStep::Dispose { .. }
        | VmStep::Yield(_)
        | VmStep::YieldStar(_) => {
            unreachable!("a synchronous bytecode function cannot suspend")
        }
    }
}

/// Drive the VM through abrupt completions. Catch handlers consume only throws; finally handlers
/// consume throws and returns, restore their saved operand depth, and jump to a completion-specific
/// pad with the completion value pushed. `pending` injects a completion before the first step (for
/// a rejected `await`, generator `.throw()`, or generator `.return()`).
#[allow(clippy::too_many_arguments)]
fn drive_vm(
    i: &mut Interp,
    chunk: &Chunk,
    env: &mut Env,
    cap_env: &Env,
    references: &mut [crate::eval::PreparedReferenceSlot],
    slots: &[PackedValue],
    stack: &mut ValueStack<PackedValue>,
    pc: &mut usize,
    this_val: &Value,
    handlers: &mut Vec<Handler>,
    disposal_frames: &mut Vec<Vec<crate::interpreter::Disposable>>,
    class_states: &mut [Option<crate::eval::PreparedClassEvaluation>],
    mut pending: Option<PendingCompletion>,
    defer_source_return: bool,
    mut tiering: Option<&mut crate::tiering::VmTiering>,
) -> Result<VmStep, Abrupt> {
    // I1: this activation's frame state lives on the Rust heap (or in a suspended coroutine);
    // the conservative stack scan sees only pointers to it, so register it for the call.
    #[cfg(feature = "gc-heap")]
    let _frame = crate::gc_trace::enter_vm_frame(crate::gc_trace::VmFrameRoots {
        env: std::ptr::from_ref(&*env),
        cap_env: std::ptr::from_ref(cap_env),
        slots: std::ptr::from_ref(slots),
        stack: std::ptr::from_ref(&*stack),
        references: std::ptr::from_ref(&*references),
        this_val: std::ptr::from_ref(this_val),
        disposal_frames: std::ptr::from_ref(&*disposal_frames),
        class_states: std::ptr::from_ref(&*class_states),
    });
    let mut native = if chunk.resumable && matches!(i.tier, Tier::Jit) {
        crate::jit::continuation_code(i, chunk)
    } else {
        None
    };
    let mut first_transfer = false;
    loop {
        let outcome = match pending.take() {
            Some(PendingCompletion::Throw(error)) => Err(Abrupt::Throw(error)),
            Some(PendingCompletion::ResumeReturn(value)) => Ok(VmStep::ResumeReturn(value)),
            Some(PendingCompletion::SourceReturn(value)) => Ok(VmStep::Return(value)),
            Some(PendingCompletion::BareReturn) => Ok(VmStep::BareReturn),
            Some(PendingCompletion::Jump {
                target,
                handler_depth,
            }) => Ok(VmStep::AbruptJump {
                target,
                handler_depth,
            }),
            None if native.is_some() => {
                let mut state = NativeContinuation {
                    chunk,
                    env,
                    cap_env,
                    references,
                    stack,
                    disposal_frames,
                    class_states,
                };
                // VmCoro owns these exact fields for the complete call. Native code borrows
                // them only until the next suspension/completion and retains no stack address.
                unsafe {
                    if chunk.resumable {
                        crate::jit::run_continuation(
                            i,
                            chunk,
                            native.as_ref().unwrap(),
                            &mut state,
                            slots,
                            pc,
                            this_val,
                            handlers,
                        )
                    } else {
                        let initial = std::mem::take(&mut first_transfer);
                        crate::jit::run_borrowed_frame(
                            i,
                            chunk,
                            native.as_ref().unwrap(),
                            &mut state,
                            slots,
                            pc,
                            this_val,
                            handlers,
                            initial,
                        )
                    }
                }
            }
            None => match run_vm(
                i,
                chunk,
                env,
                cap_env,
                references,
                slots,
                stack,
                pc,
                this_val,
                handlers,
                disposal_frames,
                class_states,
                None,
                tiering.as_deref_mut(),
            ) {
                Ok(VmRunExit::Step(step)) => Ok(step),
                Ok(VmRunExit::TierRequest) => {
                    match script_osr_code(i, chunk, *pc, stack.len(), tiering.as_deref_mut()) {
                        Ok(code) => {
                            native = code;
                            first_transfer = native.is_some();
                            continue;
                        }
                        Err(error) => Err(error),
                    }
                }
                Err(error) => Err(error),
            },
        };
        match outcome {
            Ok(VmStep::Return(value)) => {
                // In an async generator, ReturnStatement awaits its expression before creating
                // the Return Completion that enters surrounding finalizers/IteratorClose.
                if defer_source_return {
                    return Ok(VmStep::Return(value));
                }
                let mut value = Some(value);
                while let Some(handler) = handlers.pop() {
                    let return_pc = match handler.target {
                        HandlerTarget::Finally { return_pc, .. }
                        | HandlerTarget::Iterator { return_pc, .. } => return_pc,
                        HandlerTarget::Catch { .. } => continue,
                    };
                    stack.truncate(handler.stack_depth);
                    stack.push(value.take().expect("return completion consumed once"));
                    *pc = return_pc;
                    break;
                }
                if let Some(value) = value {
                    return Ok(VmStep::Return(value));
                }
            }
            Ok(VmStep::BareReturn) => {
                let mut handled = false;
                while let Some(handler) = handlers.pop() {
                    let bare_return_pc = match handler.target {
                        HandlerTarget::Finally { bare_return_pc, .. }
                        | HandlerTarget::Iterator { bare_return_pc, .. } => bare_return_pc,
                        HandlerTarget::Catch { .. } => continue,
                    };
                    stack.truncate(handler.stack_depth);
                    *pc = bare_return_pc;
                    handled = true;
                    break;
                }
                if !handled {
                    return Ok(VmStep::BareReturn);
                }
            }
            Ok(VmStep::ResumeReturn(value)) => {
                let mut value = Some(value);
                while let Some(handler) = handlers.pop() {
                    let resume_return_pc = match handler.target {
                        HandlerTarget::Finally {
                            resume_return_pc, ..
                        }
                        | HandlerTarget::Iterator {
                            resume_return_pc, ..
                        } => resume_return_pc,
                        HandlerTarget::Catch { .. } => continue,
                    };
                    stack.truncate(handler.stack_depth);
                    stack.push(
                        value
                            .take()
                            .expect("resumed return completion consumed once"),
                    );
                    *pc = resume_return_pc;
                    break;
                }
                if let Some(value) = value {
                    return Ok(VmStep::ResumeReturn(value));
                }
            }
            Ok(VmStep::AbruptJump {
                target,
                handler_depth,
            }) => {
                let mut completion = Some((target, handler_depth));
                while handlers.len() > handler_depth {
                    let handler = handlers.pop().expect("handler depth checked");
                    if let HandlerTarget::Finally { jump_pc, .. } = handler.target {
                        stack.truncate(handler.stack_depth);
                        stack.push(Value::Num(target as f64));
                        stack.push(Value::Num(handler_depth as f64));
                        *pc = jump_pc;
                        completion = None;
                        break;
                    }
                }
                if completion.is_some() {
                    debug_assert_eq!(handlers.len(), handler_depth);
                    if native.is_none() && target < *pc {
                        // LoopContinues applies only after every exited finalizer has
                        // completed. Its backward edge has the same safepoint as Jump;
                        // a resource throw still belongs to any enclosing handlers.
                        match i.interrupt_poll().and_then(|()| i.gc_check()) {
                            Ok(()) => {}
                            Err(Abrupt::Throw(error)) => {
                                pending = Some(PendingCompletion::Throw(error));
                                continue;
                            }
                            Err(error) => return Err(error),
                        }
                    }
                    let from = pc.saturating_sub(1);
                    *pc = target;
                    if native.is_none()
                        && tiering
                            .as_deref_mut()
                            .is_some_and(|tier| tier.backedge(from, target))
                    {
                        match script_osr_code(i, chunk, *pc, stack.len(), tiering.as_deref_mut()) {
                            Ok(code) => {
                                native = code;
                                first_transfer = native.is_some();
                            }
                            Err(Abrupt::Throw(error)) => {
                                pending = Some(PendingCompletion::Throw(error))
                            }
                            Err(error) => return Err(error),
                        }
                    }
                }
            }
            Ok(step) => return Ok(step),
            Err(Abrupt::Throw(error)) => {
                let mut error = Some(error);
                if let Some(handler) = handlers.pop() {
                    if matches!(handler.target, HandlerTarget::Catch { .. }) {
                        crate::jit::perf_error_caught();
                    }
                    let throw_pc = match handler.target {
                        HandlerTarget::Catch { throw_pc }
                        | HandlerTarget::Finally { throw_pc, .. }
                        | HandlerTarget::Iterator { throw_pc, .. } => throw_pc,
                    };
                    stack.truncate(handler.stack_depth);
                    let error = error.take().expect("throw completion consumed once");
                    i.settle_caught(&error);
                    stack.push(error);
                    *pc = throw_pc;
                }
                if let Some(error) = error {
                    return Err(Abrupt::Throw(error));
                }
            }
            // Return/Break/Continue never escape a compiled body as an Abrupt; propagate defensively.
            Err(other) => return Err(other),
        }
    }
}

/// Admission failure leaves every VM field untouched, including the already-published
/// target PC. Unsupported/budget-limited code stays baseline without replaying an edge.
fn script_osr_code(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    depth: usize,
    tiering: Option<&mut crate::tiering::VmTiering>,
) -> Result<Option<Rc<crate::jit::JitCode>>, Abrupt> {
    i.interrupt_poll_force()?;
    let state = chunk
        .osr
        .get_or_init(|| Box::new(crate::tiering::OsrCodeState::default()));
    let code = state.code(i, chunk);
    i.interrupt_poll_force()?;
    if state.unavailable() {
        if let Some(tiering) = tiering {
            tiering.disable();
        }
    }
    Ok(code.filter(|code| code.osr_entry_depth(pc) == Some(depth)))
}

fn for_in_step<S: StoredValue>(
    i: &mut Interp,
    slots: &[S],
    keys_slot: u16,
    index_slot: u16,
    source_slot: u16,
) -> Result<Option<Value>, Abrupt> {
    let keys = slots.read_value(keys_slot as usize);
    let source = slots.read_value(source_slot as usize);
    let mut cursor = slots.read_value(index_slot as usize);
    let result = for_in_next(i, &keys, &mut cursor, &source);
    // The cursor advances before the observable HasProperty, including abrupt completion.
    slots.write_value(index_slot as usize, cursor);
    result
}

fn for_in_next(
    i: &mut Interp,
    keys: &Value,
    cursor: &mut Value,
    source: &Value,
) -> Result<Option<Value>, Abrupt> {
    loop {
        let index = match *cursor {
            Value::Num(index) => index as u32,
            _ => unreachable!("for-in cursor is an internal integer"),
        };
        let key = match keys {
            Value::Obj(keys) => keys
                .borrow()
                .props
                .get_index(index)
                .map(|prop| prop.value()),
            _ => unreachable!("for-in keys are stored in a private immutable backing"),
        };
        let Some(key) = key else {
            return Ok(None);
        };
        *cursor = Value::Num(index as f64 + 1.0);
        if matches!(source, Value::Obj(_)) {
            let Value::Str(name) = &key else {
                unreachable!("for-in candidates are strings")
            };
            if !i.js_has_property(source, name)? {
                continue;
            }
        }
        // Reuse ordinary candidates: fresh strings would discard their computed-read cache
        // identity on every iteration. Only escaped leading-NUL keys need decoding.
        return Ok(Some(match key {
            Value::Str(name) if name.as_str().starts_with("\0\0") => {
                crate::value::string_key_value(name)
            }
            other => other,
        }));
    }
}

/// Run a retained AssignmentPattern against a slot-backed VM frame. The tree-walker operates on
/// Environment Records, so project the lexically visible slot bindings into one child record,
/// execute the normative algorithm, and copy bindings back even after an abrupt completion (an
/// earlier element/property assignment remains observable when a later one throws).
fn assign_target_with_slots<S: StoredValue>(
    i: &mut Interp,
    plan: &AssignmentTargetPlan,
    value: Value,
    env: &Env,
    slots: &[S],
) -> Result<(), Abrupt> {
    let projected = crate::interpreter::new_scope(Some(env.clone()));
    {
        let mut scope = projected.borrow_mut();
        for local in &plan.locals {
            let value = slots.read_value(local.slot as usize);
            let initialized = !matches!(value, Value::Empty);
            scope.vars.insert(
                local.name.clone(),
                crate::interpreter::Binding::data(value, local.mutable, initialized),
            );
        }
    }

    // The retained plan may describe a class/field expression within an otherwise sloppy
    // body, so assignment target semantics carry their lexical strictness explicitly.
    let old_strict = std::mem::replace(&mut i.strict, plan.strict);
    let result = i.assign_to_target(&plan.target, value, &projected);
    i.strict = old_strict;

    let scope = projected.borrow();
    for local in &plan.locals {
        let binding = scope
            .vars
            .get(&local.name)
            .expect("projected assignment binding remains present");
        slots.write_value(
            local.slot as usize,
            if binding.initialized {
                binding.value.clone()
            } else {
                Value::Empty
            },
        );
    }
    result
}

/// Execute one uncommon, non-suspending expression through the normative evaluator while the
/// surrounding function remains a heap VM continuation. Slot bindings are projected exactly like
/// AssignmentPattern's shared bridge and copied back after both normal and abrupt completion.
fn eval_expr_with_slots<S: StoredValue>(
    i: &mut Interp,
    plan: &EvalExprPlan,
    env: &Env,
    slots: &[S],
) -> Result<Value, Abrupt> {
    let projected = crate::interpreter::new_scope(Some(env.clone()));
    {
        let mut scope = projected.borrow_mut();
        for local in &plan.locals {
            let value = slots.read_value(local.slot as usize);
            let initialized = !matches!(value, Value::Empty);
            scope.vars.insert(
                local.name.clone(),
                crate::interpreter::Binding::data(value, local.mutable, initialized),
            );
        }
    }

    let old_strict = std::mem::replace(&mut i.strict, plan.strict);
    let old_name = std::mem::replace(&mut i.pending_fn_name, plan.name.clone());
    let result = i.eval(&plan.expr, &projected);
    i.pending_fn_name = old_name;
    i.strict = old_strict;

    let scope = projected.borrow();
    for local in &plan.locals {
        let binding = scope
            .vars
            .get(&local.name)
            .expect("projected expression binding remains present");
        slots.write_value(
            local.slot as usize,
            if binding.initialized {
                binding.value.clone()
            } else {
                Value::Empty
            },
        );
    }
    result
}

/// Collect the identifiers `e` references outside nested function bodies (see
/// `Compiler::retained_expr_locals`). Returns false for a direct `eval` call, which can name
/// any binding. Field initializers are scanned too although they run as methods; that only
/// over-approximates. The match is exhaustive so a new expression form must decide here.
fn retained_expr_names(e: &Expr, out: &mut crate::fasthash::FastSet<String>) -> bool {
    if crate::interpreter::ast_stack_low() {
        return crate::interpreter::with_ast_stack(|| retained_expr_names(e, out));
    }
    fn elems(items: &[crate::ast::ArrayElem], out: &mut crate::fasthash::FastSet<String>) -> bool {
        items.iter().all(|item| match item {
            crate::ast::ArrayElem::Item(e) | crate::ast::ArrayElem::Spread(e) => {
                retained_expr_names(e, out)
            }
            crate::ast::ArrayElem::Hole => true,
        })
    }
    fn key(k: &PropKey, out: &mut crate::fasthash::FastSet<String>) -> bool {
        match k {
            PropKey::Computed(e) => retained_expr_names(e, out),
            PropKey::Ident(_) | PropKey::Str(_) | PropKey::Num(_) => true,
        }
    }
    match e {
        Expr::Ident(name, _) => {
            out.insert(name.clone());
            true
        }
        Expr::Num(_)
        | Expr::BigInt(_)
        | Expr::Str(_)
        | Expr::Bool(_)
        | Expr::Null
        | Expr::Undefined
        | Expr::This
        | Expr::Super
        | Expr::Regex { .. }
        | Expr::ImportMeta
        | Expr::NewTarget
        // Function bodies (arrows included) reach outer locals only through captures.
        | Expr::Func(_) => true,
        Expr::Paren(inner) | Expr::ToStr(inner) | Expr::Await(inner) | Expr::OptionalChain(inner) => {
            retained_expr_names(inner, out)
        }
        Expr::Array(items) => elems(items, out),
        Expr::Object(props) => props.iter().all(|p| match p {
            PropDef::KeyValue { key: k, value } | PropDef::Cover { key: k, value } => {
                key(k, out) && retained_expr_names(value, out)
            }
            PropDef::Method { key: k, .. }
            | PropDef::Getter { key: k, .. }
            | PropDef::Setter { key: k, .. } => key(k, out),
            PropDef::Spread(e) | PropDef::Proto(e) => retained_expr_names(e, out),
        }),
        Expr::Class(class) => {
            if let Some(name) = &class.name {
                out.insert(name.clone());
            }
            class.decorators.iter().all(|d| retained_expr_names(d, out))
                && class
                    .superclass
                    .as_ref()
                    .is_none_or(|heritage| retained_expr_names(heritage, out))
                && class.members.iter().all(|member| {
                    key(&member.key, out)
                        && member.decorators.iter().all(|d| retained_expr_names(d, out))
                        && member
                            .value
                            .as_ref()
                            .is_none_or(|value| retained_expr_names(value, out))
                })
        }
        Expr::Yield { arg, .. } => arg.as_ref().is_none_or(|a| retained_expr_names(a, out)),
        Expr::Unary { arg, .. } | Expr::Update { arg, .. } => retained_expr_names(arg, out),
        Expr::Binary { left, right, .. } | Expr::Logical { left, right, .. } => {
            retained_expr_names(left, out) && retained_expr_names(right, out)
        }
        Expr::Assign { target, value, .. } => {
            retained_expr_names(target, out) && retained_expr_names(value, out)
        }
        Expr::Cond { test, cons, alt } => {
            retained_expr_names(test, out)
                && retained_expr_names(cons, out)
                && retained_expr_names(alt, out)
        }
        Expr::Call { callee, args, .. } => {
            !matches!(&**callee, Expr::Ident(name, _) if name == "eval")
                && retained_expr_names(callee, out)
                && elems(args, out)
        }
        Expr::New { callee, args, .. } => retained_expr_names(callee, out) && elems(args, out),
        Expr::Member { obj, .. } => retained_expr_names(obj, out),
        Expr::Index { obj, index, .. } => {
            retained_expr_names(obj, out) && retained_expr_names(index, out)
        }
        Expr::Seq(items) => items.iter().all(|e| retained_expr_names(e, out)),
        Expr::TaggedTemplate { tag, subs, .. } => {
            retained_expr_names(tag, out) && subs.iter().all(|e| retained_expr_names(e, out))
        }
        Expr::PrivateIn { obj, .. } => retained_expr_names(obj, out),
        Expr::ImportCall { spec, options, .. } => {
            retained_expr_names(spec, out)
                && options.as_ref().is_none_or(|o| retained_expr_names(o, out))
        }
    }
}

fn rejected_intrinsic_promise(i: &mut Interp, reason: Value) -> Value {
    let promise = i.new_promise();
    i.reject_promise(&promise, reason);
    promise
}

/// The rejection handler installed by AsyncFromSyncIteratorContinuation when a live sync
/// iterator value rejects. IteratorClose receives the throw completion, so its own failures are
/// discarded and the original rejection is propagated by throwing it from this reaction.
fn async_from_sync_close_rejection(
    i: &mut Interp,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    let iterator = args.first().cloned().unwrap_or(Value::Undefined);
    let error = args.get(1).cloned().unwrap_or(Value::Undefined);
    i.iterator_close(&iterator);
    Err(error)
}

fn async_from_sync_abrupt_promise(i: &mut Interp, completion: Abrupt) -> Result<Value, Abrupt> {
    match completion {
        Abrupt::Throw(error) => Ok(rejected_intrinsic_promise(i, error)),
        other => Err(other),
    }
}

fn array_literal_append(i: &mut Interp, array: &Value, value: Option<Value>) -> Result<(), Abrupt> {
    i.append_array_literal(array, value)
}

/// Consume the private dense array built by ArgumentListEvaluation lowering. No user code can
/// observe this object between creation and consumption, so every index is a plain own value.
fn argument_array_values(i: &Interp, array: Value) -> Vec<Value> {
    let Value::Obj(array) = array else {
        unreachable!("argument-list builder retains an Array")
    };
    let length = i.array_length(&array);
    let array = array.borrow();
    (0..length)
        .map(|index| {
            array
                .props
                .get_index(index as u32)
                .expect("argument-list builder creates no holes")
                .value()
        })
        .collect()
}

/// Run from `*pc` until the body returns (`Done`), suspends at an `await` (`Await`, async bodies
/// only), or throws (`Err(Abrupt::Throw)`, caught by [`drive_vm`]). Operates on borrowed state so an
/// async [`VmCoro`] can save it at a suspension and restore it on resume.
#[allow(clippy::too_many_arguments)]
fn run_vm<S: StoredValue>(
    i: &mut Interp,
    chunk: &Chunk,
    env: &mut Env,
    cap_env: &Env,
    references: &mut [crate::eval::PreparedReferenceSlot],
    slots: &[S],
    stack: &mut ValueStack<S>,
    pc: &mut usize,
    this_val: &Value,
    handlers: &mut Vec<Handler>,
    disposal_frames: &mut Vec<Vec<crate::interpreter::Disposable>>,
    class_states: &mut [Option<crate::eval::PreparedClassEvaluation>],
    stop_at: Option<usize>,
    tiering: Option<&mut crate::tiering::VmTiering>,
) -> Result<VmRunExit, Abrupt> {
    let mut requested = false;
    let step = match run_vm_inner(
        i,
        chunk,
        env,
        cap_env,
        references,
        slots,
        stack,
        pc,
        this_val,
        handlers,
        disposal_frames,
        class_states,
        stop_at,
        tiering,
        &mut requested,
    ) {
        Ok(step) => step,
        Err(error) => {
            place_vm_thrown(i, chunk, *pc, &error);
            return Err(error);
        }
    };
    Ok(if requested {
        VmRunExit::TierRequest
    } else {
        VmRunExit::Step(step)
    })
}

/// Place the error the VM operation before `pc` threw (see [`Interp::place_thrown`]). An
/// operation that throws has already advanced `pc` past itself: only jumps move it elsewhere,
/// and they do so after anything that can fail. Out of line, so the VM's entry stays small.
#[cold]
#[inline(never)]
fn place_vm_thrown(i: &Interp, chunk: &Chunk, pc: usize, error: &Abrupt) {
    i.place_thrown(error, chunk.position(pc.saturating_sub(1)));
}

/// Tier requests are driver events, never ECMAScript completions. The inner VM
/// publishes this private flag only after settling an edge, before any next op.
enum VmRunExit {
    Step(VmStep),
    TierRequest,
}

impl VmRunExit {
    fn single_operation(self) -> VmStep {
        match self {
            Self::Step(step) => step,
            Self::TierRequest => unreachable!("single-operation bridges never enable tiering"),
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn run_vm_inner<S: StoredValue>(
    interpreter: &mut Interp,
    chunk: &Chunk,
    env: &mut Env,
    cap_env: &Env,
    references: &mut [crate::eval::PreparedReferenceSlot],
    slots: &[S],
    stack: &mut ValueStack<S>,
    pc: &mut usize,
    this_val: &Value,
    handlers: &mut Vec<Handler>,
    disposal_frames: &mut Vec<Vec<crate::interpreter::Disposable>>,
    class_states: &mut [Option<crate::eval::PreparedClassEvaluation>],
    stop_at: Option<usize>,
    mut tiering: Option<&mut crate::tiering::VmTiering>,
    requested: &mut bool,
) -> Result<VmStep, Abrupt> {
    macro_rules! tier_backedge {
        ($from:expr, $to:expr) => {
            if tiering
                .as_deref_mut()
                .is_some_and(|tier| tier.backedge($from, $to))
            {
                *requested = true;
                return Ok(VmStep::Done(Value::Undefined));
            }
        };
    }
    macro_rules! pop {
        () => {
            stack.pop().expect("vm stack underflow")
        };
    }
    // Reborrow from this live activation pointer per operation. The position guard restores
    // its field only after the operation's mutable borrow has finished.
    let interpreter = interpreter as *mut Interp;
    loop {
        if stop_at == Some(*pc) {
            return Ok(VmStep::Done(Value::Undefined));
        }
        let op_pc = *pc;
        let op = chunk.ops[op_pc];
        *pc += 1;
        // A checked operation can enter author code implicitly (getter, coercion, trap).
        // Its logical spliced callers must remain visible throughout that callback.
        let _inline_position = unsafe { ImplicitCallPosition::enter(interpreter, chunk, op_pc) };
        let i = unsafe { &mut *interpreter };
        match op {
            Op::Const(k) => stack.push(chunk.consts[k as usize].clone()),
            Op::Undef => stack.push(Value::Undefined),
            Op::Dup => {
                let t = stack.last_stored().expect("vm stack underflow").clone();
                stack.push_stored(t);
            }
            Op::Pop => {
                stack.pop_stored().expect("vm stack underflow");
            }
            Op::LoadLocal(s) => {
                let v = &slots[s as usize];
                if v.is_empty() {
                    return Err(i.throw(
                        "ReferenceError",
                        format!(
                            "cannot access '{}' before initialization",
                            chunk.slot_names[s as usize]
                        ),
                    ));
                }
                stack.push_stored(v.clone());
            }
            Op::StoreLocal(s) => {
                slots[s as usize].replace_stored(stack.pop_stored().expect("vm stack underflow"))
            }
            Op::UpdateLocal(s, kind) => {
                let idx = s as usize;
                let current = slots.read_value(idx);
                match &current {
                    // Reading a slot still in its TDZ is the same ReferenceError as LoadLocal.
                    Value::Empty => {
                        return Err(i.throw(
                            "ReferenceError",
                            format!(
                                "cannot access '{}' before initialization",
                                chunk.slot_names[idx]
                            ),
                        ));
                    }
                    // Fast path: a numeric slot updates in place.
                    Value::Num(n) => {
                        let profiling =
                            observe_arithmetic_operand(&chunk.feedback, op_pc, &current);
                        let old = *n;
                        let new = match kind {
                            UpdKind::PreInc | UpdKind::PostInc | UpdKind::IncDiscard => old + 1.0,
                            UpdKind::PreDec | UpdKind::PostDec | UpdKind::DecDiscard => old - 1.0,
                        };
                        slots.write_value(idx, Value::Num(new));
                        observe_arithmetic_result(
                            &chunk.feedback,
                            op_pc,
                            profiling,
                            &Value::Num(new),
                        );
                        match kind {
                            UpdKind::PreInc | UpdKind::PreDec => stack.push(Value::Num(new)),
                            UpdKind::PostInc | UpdKind::PostDec => stack.push(Value::Num(old)),
                            UpdKind::IncDiscard | UpdKind::DecDiscard => {}
                        }
                    }
                    // BigInt updates stay BigInt (ToNumeric, not ToNumber) — never coerced to a
                    // Number and never thrown on like unary `+` would.
                    Value::BigInt(n) => {
                        let profiling =
                            observe_arithmetic_operand(&chunk.feedback, op_pc, &current);
                        let old = n.clone();
                        let one = crate::bigint::JsBigInt::from_u64(1);
                        let new = match kind {
                            UpdKind::PreInc | UpdKind::PostInc | UpdKind::IncDiscard => {
                                old.add(&one)
                            }
                            UpdKind::PreDec | UpdKind::PostDec | UpdKind::DecDiscard => {
                                old.sub(&one)
                            }
                        };
                        let value = Value::BigInt(new.clone());
                        observe_arithmetic_result(&chunk.feedback, op_pc, profiling, &value);
                        slots.write_value(idx, value);
                        match kind {
                            UpdKind::PreInc | UpdKind::PreDec => stack.push(Value::BigInt(new)),
                            UpdKind::PostInc | UpdKind::PostDec => stack.push(Value::BigInt(old)),
                            UpdKind::IncDiscard | UpdKind::DecDiscard => {}
                        }
                    }
                    // Anything else: the shared ToNumeric path may run user code and may produce
                    // either Number or BigInt. This is cold compared with the two direct tags.
                    _ => {
                        let old = current;
                        if let Some(value) =
                            step_value(i, &chunk.feedback, op_pc, kind, old, |_, value| {
                                slots.write_value(idx, value);
                                Ok(())
                            })?
                        {
                            stack.push(value);
                        }
                    }
                }
            }
            Op::Tdz(s) => slots.write_value(s as usize, Value::Empty),
            Op::LoadCap(n) => {
                stack.push(chunk.load_cap_ic(i, cap_env, n)?);
            }
            Op::StoreCap(n) => {
                let v = pop!();
                chunk.store_cap_ic(i, cap_env, n, v, false)?;
            }
            Op::StoreCapInit(n) => {
                let v = pop!();
                chunk.store_cap_ic(i, cap_env, n, v, true)?;
            }
            Op::UpdateCap(n, kind) => {
                let name = &chunk.names[n as usize];
                let mut reference =
                    crate::eval::PreparedReference::scope(name.clone(), cap_env.clone(), i.strict);
                let old = {
                    let b = cap_env.borrow();
                    let bd = b.vars.get(name).expect("captured binding missing");
                    if !bd.initialized {
                        let msg = format!("cannot access '{name}' before initialization");
                        drop(b);
                        return Err(i.throw("ReferenceError", msg));
                    }
                    bd.value.clone()
                };
                step_and_store(i, stack, &chunk.feedback, op_pc, kind, old, |i, v| {
                    i.write_prepared_reference(&mut reference, v)
                })?;
            }
            Op::UpdateName(n, kind) => {
                let mut reference = chunk.resolve_name_reference(i, env, n)?;
                let old = i.read_prepared_reference(&mut reference)?;
                step_and_store(i, stack, &chunk.feedback, op_pc, kind, old, |i, v| {
                    i.write_prepared_reference(&mut reference, v)
                })?;
            }
            Op::UpdateNameCached(n, c, kind) => {
                let mut reference = chunk.resolve_name_reference(i, env, n)?;
                let old = i.read_prepared_reference(&mut reference)?;
                let _ = chunk.name_ic_fill(i, env, n, c);
                step_and_store(i, stack, &chunk.feedback, op_pc, kind, old, |i, v| {
                    i.write_prepared_reference(&mut reference, v)
                })?;
            }
            Op::MakeClosure(fidx, name_n) => {
                let name = (name_n != u32::MAX).then(|| &chunk.names[name_n as usize]);
                let v =
                    i.make_function_named(chunk.funcs[fidx as usize].clone(), env.clone(), name);
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::Function,
                    0,
                );
                stack.push(v);
            }
            Op::LoadName(n, c) => {
                if let Some(end) =
                    string_accumulation::try_vm(chunk, i, env, slots, stack, op_pc, stop_at)
                {
                    *pc = end;
                    continue;
                }
                let v = chunk.load_name_ic(i, env, n, c)?;
                stack.push(v);
            }
            Op::LoadNameIn(n, c, t) => {
                let (_, v) = chunk.load_name_in(i, n, c, t, false)?;
                stack.push(v);
            }
            Op::LoadNameForCallIn(n, c, t) => {
                let (this, callee) = chunk.load_name_in(i, n, c, t, true)?;
                stack.push(this);
                stack.push(callee);
            }
            Op::StoreName(n) => {
                let v = pop!();
                i.assign_free_name(&chunk.names[n as usize], v, env)?;
            }
            Op::StoreGlobalName(n) => {
                let v = pop!();
                i.assign_free_name(&chunk.names[n as usize], v, &i.global_env.clone())?;
            }
            Op::StoreNameCached(n, c) => {
                let v = pop!();
                chunk.store_name_ic(i, env, n, c, v)?;
            }
            Op::ResolveNameRef(name, reference) => {
                references[reference as usize].set(chunk.resolve_name_reference(i, env, name)?);
            }
            Op::LoadRef(reference) => {
                let reference = references[reference as usize]
                    .as_mut()
                    .expect("prepared name reference was resolved before use");
                stack.push(i.read_prepared_reference(reference)?);
            }
            Op::StoreRef(reference) => {
                let value = pop!();
                let reference = references[reference as usize]
                    .as_mut()
                    .expect("prepared name reference was resolved before use");
                i.write_prepared_reference(reference, value)?;
            }
            Op::StoreConstLocal(s, n) => {
                pop!();
                if matches!(slots.read_value(s as usize), Value::Empty) {
                    return Err(i.throw(
                        "ReferenceError",
                        format!(
                            "cannot access '{}' before initialization",
                            chunk.slot_names[s as usize]
                        ),
                    ));
                }
                return Err(i.throw(
                    "TypeError",
                    format!(
                        "assignment to constant variable '{}'",
                        chunk.names[n as usize]
                    ),
                ));
            }
            Op::StoreConstCap(n) => {
                pop!();
                chunk.reject_const_cap_store(i, cap_env, n)?;
                unreachable!("immutable captured store always completes abruptly");
            }
            Op::UpdateConst(n, kind) => {
                let old = pop!();
                let name = chunk.names[n as usize].clone();
                step_value(i, &chunk.feedback, op_pc, kind, old, |i, _| {
                    Err(i.throw(
                        "TypeError",
                        format!("assignment to constant variable '{name}'"),
                    ))
                })?;
                unreachable!("immutable update always completes abruptly");
            }
            Op::LoadThis => stack.push(this_val.clone()),
            Op::LoadLexicalThis => stack.push(i.resolve_this_binding(env)?),
            Op::RequireObject => {
                if matches!(
                    stack.last().expect("vm stack underflow"),
                    Value::Undefined | Value::Null
                ) {
                    return Err(i.throw("TypeError", "cannot access property of null or undefined"));
                }
            }
            Op::GetProp(n, c) => {
                let obj = pop!();
                let v = get_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    &chunk.caches[c as usize],
                )?;
                stack.push(v);
            }
            Op::GetPropThis(n, c) => {
                let v = get_named_property(
                    i,
                    chunk,
                    op_pc,
                    this_val,
                    &chunk.names[n as usize],
                    &chunk.caches[c as usize],
                )?;
                stack.push(v);
            }
            Op::GetPropLocal(s, n, c) => {
                let obj = slots.read_value(s as usize);
                if matches!(obj, Value::Empty) {
                    return Err(i.throw(
                        "ReferenceError",
                        format!(
                            "cannot access '{}' before initialization",
                            chunk.slot_names[s as usize]
                        ),
                    ));
                }
                let v = get_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    &chunk.caches[c as usize],
                )?;
                stack.push(v);
            }
            Op::SetProp(n, c) => {
                let v = pop!();
                let obj = pop!();
                set_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    v.clone(),
                    &chunk.caches[c as usize],
                )?;
                stack.push(v);
            }
            Op::SetPropDrop(n, c) => {
                let v = pop!();
                let obj = pop!();
                set_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    v,
                    &chunk.caches[c as usize],
                )?;
            }
            Op::SetPropThisDrop(n, c) => {
                let v = pop!();
                set_named_property(
                    i,
                    chunk,
                    op_pc,
                    this_val,
                    &chunk.names[n as usize],
                    v,
                    &chunk.caches[c as usize],
                )?;
            }
            Op::SetPropLocalDrop(s, n, c) => {
                let v = pop!();
                let obj = slots.read_value(s as usize);
                if matches!(obj, Value::Empty) {
                    return Err(i.throw(
                        "ReferenceError",
                        format!(
                            "cannot access '{}' before initialization",
                            chunk.slot_names[s as usize]
                        ),
                    ));
                }
                set_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    v,
                    &chunk.caches[c as usize],
                )?;
            }
            Op::DestructureGuard => {
                if matches!(
                    stack.last().expect("vm stack underflow"),
                    Value::Undefined | Value::Null
                ) {
                    return Err(i.throw("TypeError", "cannot destructure null or undefined"));
                }
            }
            Op::DestructureArr(n) => {
                let v = pop!();
                if let Some(result) =
                    i.destructure_array_prefix(&v, n as usize, |value| stack.push(value))
                {
                    result?;
                    continue;
                }
                let (it, nx) = i.get_iterator(&v)?;
                let mut done = false;
                for _ in 0..n {
                    if !done {
                        match i.iterator_step(&it, &nx)? {
                            Some(x) => {
                                stack.push(x);
                                continue;
                            }
                            None => done = true,
                        }
                    }
                    stack.push(Value::Undefined);
                }
                if !done {
                    i.iterator_close_normal(&it)?;
                }
            }
            Op::TryArrayBinding(iterator, next, count) => {
                let source = stack.last().expect("binding source").clone();
                let matched = open_array_binding(i, slots, source, iterator, next, count)?;
                stack.push(Value::Bool(matched));
            }
            Op::ArrayBindingStep(iterator, _, index) => {
                let source = slots.read_value(iterator as usize);
                stack.push(i.array_binding_step(&source, index as usize)?);
            }
            Op::AssignTarget(target) => {
                let value = pop!();
                assign_target_with_slots(
                    i,
                    &chunk.assignment_targets[target as usize],
                    value,
                    env,
                    slots,
                )?;
            }
            Op::EvalExpr(plan) => {
                let value = eval_expr_with_slots(i, &chunk.eval_exprs[plan as usize], env, slots)?;
                stack.push(value);
            }
            Op::ClassStart(plan, decorator_count) => {
                let class_plan = &chunk.class_plans[plan as usize];
                let value_count = (decorator_count as usize)
                    .checked_mul(2)
                    .expect("class decorator count overflow");
                let split = stack
                    .len()
                    .checked_sub(value_count)
                    .expect("compiled class decorator stack underflow");
                let decorator_values = stack.split_off(split);
                let mut state = i.begin_class_evaluation(&class_plan.class, env);
                let mut decorator_values = decorator_values.into_iter();
                while let Some(this_value) = decorator_values.next() {
                    let callback = decorator_values
                        .next()
                        .expect("compiled class decorator record is complete");
                    i.prepare_class_decorator(&mut state, None, callback, this_value);
                }
                *env = state.outer_class_env.clone();
                assert!(
                    class_states[plan as usize].replace(state).is_none(),
                    "class plan re-entered before its previous evaluation completed"
                );
                i.strict = true;
            }
            Op::ClassHeritage(plan, present) => {
                let parent = present.then(|| pop!());
                let state = class_states[plan as usize]
                    .as_mut()
                    .expect("ClassStart precedes heritage evaluation");
                i.prepare_class_heritage(state, parent)?;
                *env = state.class_env.clone();
            }
            Op::ClassKey(plan, member) => {
                let value = pop!();
                let state = class_states[plan as usize]
                    .as_mut()
                    .expect("ClassStart precedes computed-name evaluation");
                i.prepare_class_key(
                    state,
                    &chunk.class_plans[plan as usize].class,
                    member as usize,
                    value,
                )?;
            }
            Op::ClassDecorator(plan, member) => {
                let callback = pop!();
                let this_value = pop!();
                let state = class_states[plan as usize]
                    .as_mut()
                    .expect("ClassStart precedes decorator evaluation");
                i.prepare_class_decorator(state, Some(member as usize), callback, this_value);
            }
            Op::ClassFinish(plan) => {
                let state = class_states[plan as usize]
                    .take()
                    .expect("ClassStart precedes class completion");
                *env = state
                    .outer_class_env
                    .borrow()
                    .parent
                    .clone()
                    .expect("class environment retains its outer environment");
                let class_plan = &chunk.class_plans[plan as usize];
                let saved_name =
                    std::mem::replace(&mut i.pending_fn_name, class_plan.inferred_name.clone());
                let result = i
                    .finish_class_evaluation(&class_plan.class, crate::rooting::Rooted::new(state));
                i.pending_fn_name = saved_name;
                i.strict = if class_states.iter().any(Option::is_some) {
                    true
                } else {
                    chunk.strict
                };
                stack.push(result?);
            }
            Op::ClassAbort(plan) => {
                if let Some(state) = class_states[plan as usize].take() {
                    *env = state
                        .outer_class_env
                        .borrow()
                        .parent
                        .clone()
                        .expect("class environment retains its outer environment");
                }
                i.strict = if class_states.iter().any(Option::is_some) {
                    true
                } else {
                    chunk.strict
                };
            }
            Op::PushWith => {
                let value = pop!();
                if matches!(value, Value::Undefined | Value::Null) {
                    return Err(i.throw("TypeError", "Cannot convert undefined or null to object"));
                }
                let object = crate::builtins::box_primitive_pub(i, value);
                *env = crate::interpreter::new_with_scope(env.clone(), object);
            }
            Op::PushLex(scope) => push_lexical_scope(chunk, env, scope, false),
            Op::PushCatchLex(scope) => push_lexical_scope(chunk, env, scope, true),
            Op::CloneLex(scope) => clone_lexical_scope(chunk, env, scope),
            Op::InitLex(name) => {
                let value = pop!();
                initialize_lexical_binding(chunk, env, name, value);
            }
            Op::PopEnv => pop_lexical_scope(env),
            Op::PushDisposeFrame => disposal_frames.push(Vec::new()),
            Op::AddDisposable(is_async) => {
                let value = stack.last().expect("vm stack underflow");
                if let Some(resource) = i.create_disposable(&value, is_async)? {
                    disposal_frames
                        .last_mut()
                        .expect("using declaration outside a disposal boundary")
                        .push(resource);
                }
            }
            Op::DisposeNormal => {
                let frame = disposal_frames
                    .pop()
                    .expect("normal disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::Normal,
                    });
                }
                i.dispose_frame(frame, Ok(Value::Undefined))?;
            }
            Op::DisposeThrow => {
                let error = pop!();
                let frame = disposal_frames
                    .pop()
                    .expect("throw disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::Throw(error),
                    });
                }
                return match i.dispose_frame(frame, Err(Abrupt::Throw(error))) {
                    Err(completion) => Err(completion),
                    Ok(_) => unreachable!("DisposeResources preserved a throw as normal"),
                };
            }
            Op::DisposeReturn => {
                let value = pop!();
                let frame = disposal_frames
                    .pop()
                    .expect("return disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::SourceReturn(value),
                    });
                }
                return match i.dispose_frame(frame, Err(Abrupt::Return(value))) {
                    Err(Abrupt::Return(value)) => Ok(VmStep::Return(value)),
                    Err(completion) => Err(completion),
                    Ok(_) => unreachable!("DisposeResources preserved a return as normal"),
                };
            }
            Op::DisposeBareReturn => {
                let frame = disposal_frames
                    .pop()
                    .expect("bare-return disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::BareReturn,
                    });
                }
                return match i.dispose_frame(frame, Err(Abrupt::Return(Value::Undefined))) {
                    Err(Abrupt::Return(_)) => Ok(VmStep::BareReturn),
                    Err(completion) => Err(completion),
                    Ok(_) => unreachable!("DisposeResources preserved a return as normal"),
                };
            }
            Op::DisposeResumeReturn => {
                let value = pop!();
                let frame = disposal_frames
                    .pop()
                    .expect("resumed-return disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::ResumeReturn(value),
                    });
                }
                return match i.dispose_frame(frame, Err(Abrupt::Return(value))) {
                    Err(Abrupt::Return(value)) => Ok(VmStep::ResumeReturn(value)),
                    Err(completion) => Err(completion),
                    Ok(_) => unreachable!("DisposeResources preserved a return as normal"),
                };
            }
            Op::DisposeJump => {
                let handler_depth = match pop!() {
                    Value::Num(value) => value as usize,
                    _ => unreachable!("disposal jump depth is an internal integer"),
                };
                let target = match pop!() {
                    Value::Num(value) => value as usize,
                    _ => unreachable!("disposal jump target is an internal integer"),
                };
                let frame = disposal_frames
                    .pop()
                    .expect("jump disposal without an active frame");
                if frame.iter().any(|resource| resource.kind_is_async) {
                    return Ok(VmStep::Dispose {
                        frame,
                        completion: DisposeCompletion::Jump {
                            target,
                            handler_depth,
                        },
                    });
                }
                return match i.dispose_frame(frame, Err(Abrupt::Break(None, Value::Empty))) {
                    Err(Abrupt::Break(..)) | Err(Abrupt::Continue(..)) => Ok(VmStep::AbruptJump {
                        target,
                        handler_depth,
                    }),
                    Err(completion) => Err(completion),
                    Ok(_) => unreachable!("DisposeResources preserved a jump as normal"),
                };
            }
            Op::ObjectRest(count) => {
                let at = stack.len() - count as usize;
                let excluded_values = stack.split_off(at);
                let source = pop!();
                let mut excluded = Vec::with_capacity(excluded_values.len());
                for key in excluded_values {
                    match key {
                        Value::Str(key) => {
                            excluded.push(crate::value::encode_owned_string_key(key.to_string()))
                        }
                        other => excluded.push(i.to_property_key(&other)?.into_string()),
                    }
                }
                let rest = i.copy_data_properties(&source, &excluded)?;
                stack.push(Value::Obj(rest));
            }
            Op::DeleteProp(n, strict) => {
                let base = pop!();
                let prop = &chunk.names[n as usize];
                if matches!(base, Value::Undefined | Value::Null) {
                    return Err(i.throw(
                        "TypeError",
                        format!(
                            "cannot delete property '{}' of null or undefined",
                            crate::value::decode_string_key(prop)
                        ),
                    ));
                }
                let v = i.delete_prop_with(base, prop, strict)?;
                stack.push(v);
            }
            Op::DeleteElem(strict) => {
                let idx = pop!();
                let base = pop!();
                let key = i.to_property_key(&idx)?;
                if matches!(base, Value::Undefined | Value::Null) {
                    return Err(i.throw(
                        "TypeError",
                        format!(
                            "cannot delete property '{}' of null or undefined",
                            crate::value::decode_string_key(&key)
                        ),
                    ));
                }
                let v = i.delete_prop_with(base, &key, strict)?;
                stack.push(v);
            }
            Op::DeleteName(name) => {
                stack.push(i.delete_ident(&chunk.names[name as usize], env)?);
            }
            Op::DeleteSuper => {
                return Err(i.throw("ReferenceError", "cannot delete a super property"));
            }
            Op::TailDeep => stack.push(Value::Bool(i.depth >= ordinary_tail_call_depth())),
            Op::TailCall(mode, with_this) => {
                let args = match mode {
                    CallArgsMode::Fixed(argc) => stack.split_off(stack.len() - argc as usize),
                    CallArgsMode::FinalSpread(argc) => {
                        let spread = pop!();
                        let mut args = stack.split_off(stack.len() - (argc as usize - 1));
                        i.append_spread_arguments(&spread, &mut args)?;
                        args
                    }
                    CallArgsMode::Array => argument_array_values(i, pop!()),
                };
                let callee = pop!();
                let receiver = if with_this { pop!() } else { Value::Undefined };
                stage_tail_call(i, chunk, op_pc, callee, receiver, args)?;
                stack.push(Value::Undefined);
            }
            Op::CallSpread(argc) | Op::CallSpreadThis(argc) => {
                let spread = pop!();
                let at = stack.len() - (argc as usize - 1);
                let mut args: Vec<Value> = stack.split_off(at);
                i.append_spread_arguments(&spread, &mut args)?;
                let callee = pop!();
                let this = if matches!(op, Op::CallSpreadThis(_)) {
                    pop!()
                } else {
                    Value::Undefined
                };
                if !callee.is_callable() {
                    return Err(not_callable_error(i, chunk, op_pc, &callee, false));
                }
                let v = explicit_call(i, chunk.position(op_pc), |i| {
                    if chunk.feedback.detailed_enabled() {
                        call_profiled(i, chunk, op_pc, callee, this, &args)
                    } else {
                        i.call(callee, this, &args)
                    }
                })?;
                stack.push(v);
            }
            Op::CallArgsArray | Op::CallArgsArrayThis => {
                let args = argument_array_values(i, pop!());
                let callee = pop!();
                let this = if matches!(op, Op::CallArgsArrayThis) {
                    pop!()
                } else {
                    Value::Undefined
                };
                if !callee.is_callable() {
                    return Err(not_callable_error(i, chunk, op_pc, &callee, false));
                }
                let value = explicit_call(i, chunk.position(op_pc), |i| {
                    if chunk.feedback.detailed_enabled() {
                        call_profiled(i, chunk, op_pc, callee, this, &args)
                    } else {
                        i.call(callee, this, &args)
                    }
                })?;
                stack.push(value);
            }
            Op::EvalCallArgsArray | Op::TailEvalCallArgsArray => {
                let args = argument_array_values(i, pop!());
                let callee = pop!();
                let receiver = pop!();
                if !callee.is_callable() {
                    return Err(not_callable_error(i, chunk, op_pc, &callee, false));
                }
                // Only an identifier Reference named eval emits this opcode. A with
                // Environment Record can supply a receiver without making the
                // Reference a property Reference (ECMA-262 §13.3.6).
                let direct = matches!(
                    (&callee, &i.eval_fn),
                    (Value::Obj(function), Some(intrinsic))
                        if crate::value::Gc::ptr_eq(function, intrinsic)
                );
                let value = if !direct && matches!(op, Op::TailEvalCallArgsArray) {
                    stage_tail_call(i, chunk, op_pc, callee, receiver, args)?;
                    Value::Undefined
                } else if direct {
                    if chunk.feedback.detailed_enabled() {
                        let target = i.call_target_kind(&callee);
                        let environment = i.call_environment_kind(&callee);
                        chunk.feedback.observe_call(
                            op_pc,
                            target,
                            call_arity_kind(args.len()),
                            environment,
                        );
                    }
                    let value = explicit_call(i, chunk.position(op_pc), |i| {
                        i.direct_eval(args.first(), env)
                    })?;
                    if chunk.feedback.detailed_enabled() {
                        if let Some(class) = arithmetic_value_class(&value) {
                            chunk.feedback.observe_value_class(
                                op_pc,
                                crate::feedback::ObservationRole::Result,
                                class,
                            );
                        }
                    }
                    value
                } else {
                    explicit_call(i, chunk.position(op_pc), |i| {
                        if chunk.feedback.detailed_enabled() {
                            call_profiled(i, chunk, op_pc, callee, receiver, &args)
                        } else {
                            i.call(callee, receiver, &args)
                        }
                    })?
                };
                stack.push(value);
            }
            Op::AppendProp(n, c) => {
                let v = pop!();
                let lval = pop!();
                let obj = pop!();
                let name = &chunk.names[n as usize];
                let lval = if let (Value::Str(x), Value::Obj(o)) = (&v, &obj) {
                    match i.append_prop_fast(o, name, lval, x) {
                        Ok(()) => continue,
                        Err(l) => l,
                    }
                } else {
                    lval
                };
                let r = i.binary("+", lval, v)?;
                set_named_property(i, chunk, op_pc, &obj, name, r, &chunk.caches[c as usize])?;
            }
            Op::GetElem => {
                let key = pop!();
                let obj = pop!();
                let value = get_computed_element(i, chunk, op_pc, &obj, &key)?;
                stack.push(value);
            }
            Op::SetElem => {
                let v = pop!();
                let key = pop!();
                let obj = pop!();
                set_computed_element(i, chunk, op_pc, &obj, &key, v.clone())?;
                stack.push(v);
            }
            Op::SetElemDrop => {
                let v = pop!();
                let key = pop!();
                let obj = pop!();
                set_computed_element(i, chunk, op_pc, &obj, &key, v)?;
            }
            Op::GetElemLocal(s) => {
                let key = pop!();
                let obj = slots.read_value(s as usize);
                let value = get_computed_element(i, chunk, op_pc, &obj, &key)?;
                stack.push(value);
            }
            Op::ArgElem(s) => {
                let key = pop!();
                let list = slots.read_value(s as usize);
                let mut replacement = None;
                let value = lazy_arguments_element(i, chunk, op_pc, &list, &key, |object| {
                    replacement = Some(object.clone())
                });
                if let Some(object) = replacement {
                    slots.write_value(s as usize, object);
                }
                stack.push(value?);
            }
            Op::SetElemLocal(s) | Op::SetElemLocalDrop(s) => {
                let keep = matches!(op, Op::SetElemLocal(_));
                let v = pop!();
                let key = pop!();
                if keep {
                    stack.push(v.clone());
                }
                let obj = slots.read_value(s as usize);
                set_computed_element(i, chunk, op_pc, &obj, &key, v)?;
            }
            Op::UpdateProp(n, c, kind) => {
                let obj = pop!();
                let name = &chunk.names[n as usize];
                let cache = &chunk.caches[c as usize];
                let old = get_named_property(i, chunk, op_pc, &obj, name, cache)?;
                step_and_store(i, stack, &chunk.feedback, op_pc, kind, old, |i, v| {
                    set_named_property(i, chunk, op_pc, &obj, name, v, cache)
                })?;
            }
            Op::UpdateElem(kind) => {
                let key = pop!();
                let obj = pop!();
                // Dense-element fast path: numeric key on a plain array/object.
                // Detailed collection uses the exact-PC shared tail below; ordinary execution
                // retains this allocation-free numeric path.
                if !chunk.feedback.detailed_enabled() {
                    if let (Value::Obj(o), Value::Num(nk)) = (&obj, &key) {
                        if let Some(Value::Num(old)) = i.fast_get_elem(o, *nk) {
                            let new = match kind {
                                UpdKind::PreInc | UpdKind::PostInc | UpdKind::IncDiscard => {
                                    old + 1.0
                                }
                                UpdKind::PreDec | UpdKind::PostDec | UpdKind::DecDiscard => {
                                    old - 1.0
                                }
                            };
                            if i.fast_set_elem(o, *nk, Value::Num(new)).is_ok() {
                                match kind {
                                    UpdKind::PreInc | UpdKind::PreDec => {
                                        stack.push(Value::Num(new))
                                    }
                                    UpdKind::PostInc | UpdKind::PostDec => {
                                        stack.push(Value::Num(old))
                                    }
                                    UpdKind::IncDiscard | UpdKind::DecDiscard => {}
                                }
                                continue;
                            }
                        }
                    }
                }
                if chunk.feedback.detailed_enabled() {
                    let old = get_element_profiled(i, chunk, op_pc, &obj, &key)?;
                    if let Some(v) = step_value(i, &chunk.feedback, op_pc, kind, old, |i, v| {
                        set_element_profiled(i, chunk, op_pc, &obj, &key, v)
                    })? {
                        stack.push(v);
                    }
                    continue;
                }
                // General path: nullish check, one ToPropertyKey, [[Get]], ToNumeric, [[Set]] —
                // the oracle's Reference order exactly.
                if matches!(obj, Value::Undefined | Value::Null) {
                    crate::value::trace_nullish_property("bytecode-update-elem", &key);
                    return Err(i.throw("TypeError", "cannot read property of null or undefined"));
                }
                let k = i.to_property_key(&key)?;
                let old = i.get_member_key(&obj, &k)?;
                step_and_store(i, stack, &chunk.feedback, op_pc, kind, old, |i, v| {
                    i.set_member_key(&obj, &k, v)
                })?;
            }
            Op::ToPropKeyLocal(s) => {
                if matches!(slots.read_value(s as usize), Value::Undefined | Value::Null) {
                    return Err(i.throw("TypeError", "cannot access property of null or undefined"));
                }
                match stack.last().expect("vm stack underflow") {
                    Value::Num(_) | Value::Str(_) | Value::Sym(_) => {}
                    _ => {
                        let key = pop!();
                        let k = i.to_property_key(&key)?;
                        stack.push(k.into_value());
                    }
                }
            }
            Op::ToPropKey => {
                if matches!(
                    stack.get(stack.len().saturating_sub(2)),
                    Some(Value::Undefined | Value::Null)
                ) {
                    return Err(i.throw("TypeError", "cannot access property of null or undefined"));
                }
                match stack.last().expect("vm stack underflow") {
                    // Side-effect-free and deterministic to coerce later; numbers stay numeric
                    // so GetElem/SetElem keep their dense fast path.
                    Value::Num(_) | Value::Str(_) | Value::Sym(_) => {}
                    _ => {
                        let key = pop!();
                        let k = i.to_property_key(&key)?;
                        stack.push(k.into_value());
                    }
                }
            }
            Op::Dup2 => {
                let len = stack.len();
                let a = stack.raw_slice()[len - 2].clone();
                let b = stack.raw_slice()[len - 1].clone();
                stack.push_stored(a);
                stack.push_stored(b);
            }
            Op::GetMethod(n, c) => {
                let obj = pop!();
                let m = get_named_property(
                    i,
                    chunk,
                    op_pc,
                    &obj,
                    &chunk.names[n as usize],
                    &chunk.caches[c as usize],
                )?;
                stack.push(obj);
                stack.push(m);
            }
            Op::GetMethodElem => {
                let key = pop!();
                let obj = pop!();
                let m = get_computed_element(i, chunk, op_pc, &obj, &key)?;
                stack.push(obj);
                stack.push(m);
            }
            Op::Add => {
                // A following local store retires an owner of the old left string. Both
                // operands are already evaluated; only the non-coercing, non-throwing string
                // case may release that owner before addition. The existing Add/Store ops and
                // feedback remain intact, and real aliases still prevent in-place mutation.
                if let (Some(Value::Str(left)), Some(Value::Str(right))) =
                    (stack.get(stack.len().saturating_sub(2)), stack.last())
                {
                    if left.len().saturating_add(right.len()) <= crate::interpreter::MAX_STR_LEN {
                        match chunk.ops.get(op_pc + 1) {
                            Some(Op::StoreLocal(slot)) => {
                                if matches!(slots.read_value(*slot as usize), Value::Str(current)
                                    if crate::lstr::LStr::ptr_eq(&current, &left))
                                {
                                    slots.write_value(*slot as usize, Value::Undefined);
                                }
                            }
                            Some(Op::StoreCap(name)) => {
                                chunk.release_overwritten_captured_string(cap_env, *name, &left);
                            }
                            _ => {}
                        }
                    }
                }
                bin_num(i, stack, &chunk.feedback, op_pc, "+", |a, b| a + b)?;
            }
            Op::Sub => bin_num(i, stack, &chunk.feedback, op_pc, "-", |a, b| a - b)?,
            Op::Mul => bin_num(i, stack, &chunk.feedback, op_pc, "*", |a, b| a * b)?,
            Op::Div => bin_num(i, stack, &chunk.feedback, op_pc, "/", |a, b| a / b)?,
            Op::Mod => bin_num(i, stack, &chunk.feedback, op_pc, "%", crate::eval::js_mod)?,
            Op::BitAnd => bin_i32(i, stack, &chunk.feedback, op_pc, "&", |a, b| a & b)?,
            Op::BitOr => bin_i32(i, stack, &chunk.feedback, op_pc, "|", |a, b| a | b)?,
            Op::BitXor => bin_i32(i, stack, &chunk.feedback, op_pc, "^", |a, b| a ^ b)?,
            Op::Shl => bin_i32(i, stack, &chunk.feedback, op_pc, "<<", |a, b| {
                a.wrapping_shl(b as u32 & 31)
            })?,
            Op::Shr => bin_i32(i, stack, &chunk.feedback, op_pc, ">>", |a, b| {
                a >> (b as u32 & 31)
            })?,
            Op::UShr => bin_num(i, stack, &chunk.feedback, op_pc, ">>>", |a, b| {
                ((crate::eval::to_int32(a) as u32) >> (crate::eval::to_int32(b) as u32 & 31)) as f64
            })?,
            Op::Lt => bin_cmp(i, &mut *stack, "<", |a, b| a < b)?,
            Op::Gt => bin_cmp(i, &mut *stack, ">", |a, b| a > b)?,
            Op::Le => bin_cmp(i, &mut *stack, "<=", |a, b| a <= b)?,
            Op::Ge => bin_cmp(i, &mut *stack, ">=", |a, b| a >= b)?,
            Op::EqEq => bin_cmp(i, &mut *stack, "==", |a, b| a == b)?,
            Op::NotEq => bin_cmp(i, &mut *stack, "!=", |a, b| a != b)?,
            Op::StrictEq => bin_cmp(i, &mut *stack, "===", |a, b| a == b)?,
            Op::StrictNotEq => bin_cmp(i, &mut *stack, "!==", |a, b| a != b)?,
            Op::InstanceOf(c) => {
                let b = pop!();
                let a = pop!();
                let v = i.instanceof_ic(&a, &b, &chunk.caches[c as usize])?;
                stack.push(v);
            }
            Op::In => {
                let object = pop!();
                let key = pop!();
                stack.push(Value::Bool(i.in_operator(&key, &object)?));
            }
            Op::GenBin(n) => {
                let b = pop!();
                let a = pop!();
                let profiling = observe_arithmetic_operands(&chunk.feedback, op_pc, &a, &b);
                // Exponentiation keeps a dedicated dispatch so Number⊕Number never enters the
                // generic `binary` helper: same observable steps (no coercion for two Numbers),
                // same Number::exponentiate guard, one less indirect match per hot op. The
                // tagged slice rides the same path behind the opt-in switch.
                let v = if &*chunk.names[n as usize] == "**" {
                    match i
                        .tagged_arithmetic
                        .then(|| try_tagged_numeric_pow(&a, &b))
                        .flatten()
                    {
                        Some(value) => value,
                        None => match (&a, &b) {
                            (Value::Num(x), Value::Num(y)) => {
                                if y.is_nan() || (x.abs() == 1.0 && y.is_infinite()) {
                                    Value::Num(f64::NAN)
                                } else {
                                    Value::Num(x.powf(*y))
                                }
                            }
                            _ => i.binary(&chunk.names[n as usize], a, b)?,
                        },
                    }
                } else {
                    i.binary(&chunk.names[n as usize], a, b)?
                };
                observe_arithmetic_result(&chunk.feedback, op_pc, profiling, &v);
                stack.push(v);
            }
            Op::Neg => {
                let a = pop!();
                let profiling = observe_arithmetic_operand(&chunk.feedback, op_pc, &a);
                let v = match i
                    .tagged_arithmetic
                    .then(|| try_tagged_numeric_unary(&a, |n| -n))
                    .flatten()
                {
                    Some(value) => value,
                    None => match a {
                        Value::Num(n) => Value::Num(-n),
                        other => i.eval_unary_vm("-", other)?,
                    },
                };
                observe_arithmetic_result(&chunk.feedback, op_pc, profiling, &v);
                stack.push(v);
            }
            Op::Plus => {
                let a = pop!();
                let profiling = observe_arithmetic_operand(&chunk.feedback, op_pc, &a);
                let v = match i
                    .tagged_arithmetic
                    .then(|| try_tagged_numeric_unary(&a, |n| n))
                    .flatten()
                {
                    Some(value) => value,
                    None => match a {
                        Value::Num(n) => Value::Num(n),
                        other => i.eval_unary_vm("+", other)?,
                    },
                };
                observe_arithmetic_result(&chunk.feedback, op_pc, profiling, &v);
                stack.push(v);
            }
            Op::Not => {
                let a = pop!();
                stack.push(Value::Bool(!i.to_boolean(&a)));
            }
            Op::BitNot => {
                let a = pop!();
                let profiling = observe_arithmetic_operand(&chunk.feedback, op_pc, &a);
                let v = match i
                    .tagged_arithmetic
                    .then(|| try_tagged_numeric_unary(&a, |n| !crate::eval::to_int32(n) as f64))
                    .flatten()
                {
                    Some(value) => value,
                    None => match a {
                        Value::Num(n) => Value::Num(!crate::eval::to_int32(n) as f64),
                        other => i.eval_unary_vm("~", other)?,
                    },
                };
                observe_arithmetic_result(&chunk.feedback, op_pc, profiling, &v);
                stack.push(v);
            }
            Op::Typeof => {
                let a = pop!();
                let v = i.eval_unary_vm("typeof", a)?;
                stack.push(v);
            }
            Op::TypeofIs(test, negate) => {
                let value = pop!();
                stack.push(Value::Bool(i.typeof_matches(&value, test) ^ negate));
            }
            Op::TypeofName(n) => {
                stack.push(i.typeof_name_vm(&chunk.names[n as usize], env)?);
            }
            Op::Void => {
                pop!();
                stack.push(Value::Undefined);
            }
            Op::Jump(t) => {
                if t as usize <= *pc {
                    i.interrupt_poll()?;
                    i.gc_check()?;
                    if chunk.feedback.detailed_enabled() {
                        chunk.feedback.observe_loop_backedge(op_pc);
                    }
                }
                *pc = t as usize;
                tier_backedge!(op_pc, *pc);
            }
            Op::InlineGuard(t, target) => {
                let it = &chunk.inline_targets[t as usize];
                let d = it.argc as usize + 1;
                let callee_ok = matches!(
                    &stack.read_value(stack.len() - d),
                    Value::Obj(o) if crate::value::Gc::as_ptr(o) as usize == it.expected
                );
                let this_ok = !it.check_this
                    || matches!(stack.read_value(stack.len() - d - 1), Value::Obj(_));
                let env_ok = it.expected_env == 0 || Env::as_ptr(env) as usize == it.expected_env;
                let realm_ok = Env::as_ptr(&i.global_env) as usize == it.expected_genv;
                if !(callee_ok && this_ok && env_ok && realm_ok) {
                    *pc = target as usize;
                }
            }
            Op::ResetSlots(start, count) => {
                for k in start as usize..start as usize + count as usize {
                    slots.write_value(k, Value::Undefined);
                }
            }
            Op::JumpIfFalse(t) => {
                let a = pop!();
                let taken = !i.to_boolean(&a);
                if taken && t as usize <= *pc {
                    i.interrupt_poll()?;
                    i.gc_check()?;
                }
                if chunk.feedback.detailed_enabled() {
                    chunk.feedback.observe_branch(op_pc, taken);
                }
                if taken {
                    *pc = t as usize;
                    tier_backedge!(op_pc, *pc);
                }
            }
            Op::JumpIfFalsePeek(t) => {
                let taken = !i.to_boolean(&stack.last().expect("vm stack underflow"));
                if taken && t as usize <= *pc {
                    i.interrupt_poll()?;
                    i.gc_check()?;
                }
                if chunk.feedback.detailed_enabled() {
                    chunk.feedback.observe_branch(op_pc, taken);
                }
                if taken {
                    *pc = t as usize;
                    tier_backedge!(op_pc, *pc);
                }
            }
            Op::JumpIfTruePeek(t) => {
                let taken = i.to_boolean(&stack.last().expect("vm stack underflow"));
                if taken && t as usize <= *pc {
                    i.interrupt_poll()?;
                    i.gc_check()?;
                }
                if chunk.feedback.detailed_enabled() {
                    chunk.feedback.observe_branch(op_pc, taken);
                }
                if taken {
                    *pc = t as usize;
                    tier_backedge!(op_pc, *pc);
                }
            }
            Op::JumpIfNotNullishPeek(t) => {
                let taken = !matches!(
                    stack.last().expect("vm stack underflow"),
                    Value::Undefined | Value::Null
                );
                if taken && t as usize <= *pc {
                    i.interrupt_poll()?;
                    i.gc_check()?;
                }
                if chunk.feedback.detailed_enabled() {
                    chunk.feedback.observe_branch(op_pc, taken);
                }
                if taken {
                    *pc = t as usize;
                    tier_backedge!(op_pc, *pc);
                }
            }
            // Calls pass the argument window as a slice of the operand stack — no per-call `Vec`.
            // The callee/receiver slots below the window are cloned out first, then the whole
            // region is truncated away after the call. On a throw the stack is left long, which is
            // fine: the handler unwind (or function exit) truncates it.
            Op::Call(argc, cache) => {
                let at = stack.len() - argc as usize;
                let callee = stack.read_value(at - 1);
                let v = match explicit_call(i, chunk.call_position(cache), |i| {
                    stack.with_tail(at, |args| {
                        if chunk.feedback.detailed_enabled() {
                            call_profiled(i, chunk, op_pc, callee, Value::Undefined, args)
                        } else {
                            i.call(callee, Value::Undefined, args)
                        }
                    })
                }) {
                    Ok(value) => value,
                    Err(error) => {
                        let callee = stack.read_value(at - 1);
                        return Err(name_call_error(i, chunk, op_pc, &callee, false, error));
                    }
                };
                stack.truncate(at - 1);
                stack.push(v);
            }
            Op::LoadNameForCall(n, c) => {
                // A depth-0 cache hit/fill can't have come through a `with` object: `this` is
                // undefined. Only the full walk can produce a with-object receiver.
                if let Some(v) = chunk
                    .name_ic_hit(i, env, c)
                    .or_else(|| chunk.name_ic_fill(i, env, n, c))
                {
                    stack.push(Value::Undefined);
                    stack.push(v);
                } else {
                    let (callee, with_this) = i.get_var_with(&chunk.names[n as usize], env)?;
                    stack.push(with_this.unwrap_or(Value::Undefined));
                    stack.push(callee);
                }
            }
            Op::CallWithThis(argc, cache) => {
                let at = stack.len() - argc as usize;
                let m = stack.read_value(at - 1);
                let this = stack.read_value(at - 2);
                // `CallWithThis` immediately followed by `Op::Pop` proves the result is dead: the
                // JIT fuses this exact pattern into the allocation-free RegExp/string discard
                // intrinsics, and the bytecode tier routes it through the same guarded routines.
                // On a guard miss the fast path returns `None` without touching any state and the
                // generic call below runs unmodified, so this is observably invisible.
                if matches!(chunk.ops.get(*pc), Some(Op::Pop)) {
                    match stack.with_tail(at, |args| {
                        crate::builtins::vm_discard_call(i, &this, &m, args)
                    }) {
                        Ok(Some(_)) => {
                            stack.truncate(at - 2);
                            i.interrupt_poll_force()?;
                            // The trailing `Op::Pop` discards this placeholder instead of the
                            // call result; the discard routines already poll internally.
                            stack.push(Value::Undefined);
                            continue;
                        }
                        Ok(None) => {}
                        Err(error) => return Err(Abrupt::Throw(error)),
                    }
                }
                let v = match explicit_call(i, chunk.call_position(cache), |i| {
                    stack.with_tail(at, |args| {
                        if chunk.feedback.detailed_enabled() {
                            call_profiled(i, chunk, op_pc, m, this, args)
                        } else {
                            i.call(m, this, args)
                        }
                    })
                }) {
                    Ok(value) => value,
                    Err(error) => {
                        let method = stack.read_value(at - 1);
                        return Err(name_call_error(i, chunk, op_pc, &method, false, error));
                    }
                };
                stack.truncate(at - 2);
                stack.push(v);
            }
            Op::New(argc, cache) => {
                let at = stack.len() - argc as usize;
                let callee = stack.read_value(at - 1);
                let v = match explicit_call(i, chunk.construct_position(cache), |i| {
                    stack.with_tail(at, |args| {
                        if chunk.feedback.detailed_enabled() {
                            construct_profiled(i, chunk, op_pc, callee, args)
                        } else {
                            i.construct(callee, args)
                        }
                    })
                }) {
                    Ok(value) => value,
                    Err(error) => {
                        let callee = stack.read_value(at - 1);
                        return Err(name_call_error(i, chunk, op_pc, &callee, true, error));
                    }
                };
                stack.truncate(at - 1);
                stack.push(v);
            }
            Op::NewArgsArray => {
                let args = argument_array_values(i, pop!());
                let callee = pop!();
                if !i.value_is_constructor(&callee) {
                    return Err(not_callable_error(i, chunk, op_pc, &callee, true));
                }
                let value = explicit_call(i, chunk.position(op_pc), |i| {
                    if chunk.feedback.detailed_enabled() {
                        construct_profiled(i, chunk, op_pc, callee, &args)
                    } else {
                        i.construct(callee, &args)
                    }
                })?;
                stack.push(value);
            }
            Op::MakeRegExp(body, flags) => {
                let body = &chunk.names[body as usize];
                let flags = &chunk.names[flags as usize];
                let value = i.make_regexp(body, flags)?;
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::RegExp,
                    body.len().saturating_add(flags.len()),
                );
                stack.push(value);
            }
            Op::MakeArray(n) => {
                let at = stack.len() - n as usize;
                let items: Vec<Value> = stack.split_off(at);
                let value = i.make_array(items);
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::Array,
                    n as usize,
                );
                stack.push(value);
            }
            Op::NewArray => {
                let value = i.make_array(Vec::new());
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::Array,
                    0,
                );
                stack.push(value);
            }
            Op::ArrayPush => {
                let value = pop!();
                let array = stack.last().expect("array builder missing").clone();
                array_literal_append(i, &array, Some(value))?;
            }
            Op::ArrayHole => {
                let array = stack.last().expect("array builder missing").clone();
                array_literal_append(i, &array, None)?;
            }
            Op::ArraySpread => {
                let spread = pop!();
                let array = stack.last().expect("array builder missing").clone();
                let prefix = i.array_length(array.as_obj().expect("array builder"));
                i.expand_spread(&spread, prefix, |i, value| {
                    array_literal_append(i, &array, Some(value))
                })?;
            }
            Op::MakeObject(start, count, tidx) => {
                let at = stack.len() - count as usize;
                let values: Vec<Value> = stack.split_off(at);
                let keys = &chunk.names[start as usize..start as usize + count as usize];
                let v = if tidx != u32::MAX {
                    i.make_plain_object_templated(&chunk.obj_maps[tidx as usize], keys, values)
                } else {
                    i.make_plain_object_vm(keys, values)
                };
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::Object,
                    count as usize,
                );
                stack.push(v);
            }
            Op::NewObject => {
                let value = Value::Obj(i.new_object());
                observe_allocation(
                    &chunk.feedback,
                    op_pc,
                    crate::feedback::AllocationObjectKind::Object,
                    0,
                );
                stack.push(value);
            }
            Op::ObjectData(name_anonymous) => {
                let value = pop!();
                let key = pop!();
                // ToPropertyKey returns an owning String-or-Symbol. Keep that
                // owner until CreateDataProperty has retained the identity
                // (ECMA-262 e28783d5, sec-topropertykey).
                let key = i.to_property_key(&key)?;
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                literal_define_data(i, &object, key.as_str(), value, name_anonymous);
            }
            Op::ObjectDataName(name, name_anonymous) => {
                let value = pop!();
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                literal_define_data(
                    i,
                    &object,
                    chunk.names[name as usize].clone(),
                    value,
                    name_anonymous,
                );
            }
            Op::ObjectSpread => {
                let source = pop!();
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                i.copy_data_properties_into(&object, &source, &[])?;
            }
            Op::Abstract(operation) => match operation {
                AbstractOp::ToObject(method) => {
                    let value = pop!();
                    let method = &chunk.names[method as usize];
                    stack.push(crate::self_hosted::to_object(i, value, method)?);
                }
                AbstractOp::LengthOfArrayLike => {
                    let object = pop!();
                    let length = crate::self_hosted::length_of_array_like(i, &object)?;
                    stack.push(Value::Num(length));
                }
                AbstractOp::IsCallable => {
                    let value = pop!();
                    stack.push(Value::Bool(value.is_callable()));
                }
                AbstractOp::ArraySpeciesCreate => {
                    let length = pop!();
                    let original = pop!();
                    let array = crate::self_hosted::array_species_create(i, &original, &length)?;
                    stack.push(array);
                }
                AbstractOp::CreateDataPropertyOrThrow => {
                    let value = pop!();
                    let key = pop!();
                    let object = pop!();
                    crate::self_hosted::create_data_property_or_throw(
                        i,
                        &object,
                        &key,
                        PackedValue::pack(value),
                    )?;
                    stack.push(Value::Bool(true));
                }
                AbstractOp::ThrowTypeError(message) => {
                    let message = &chunk.names[message as usize];
                    return Err(crate::self_hosted::type_error(i, message));
                }
            },
            Op::ObjectProto => {
                let prototype = pop!();
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                match prototype {
                    Value::Obj(prototype) => object.borrow_mut().proto = Some(prototype),
                    Value::Null => object.borrow_mut().proto = None,
                    _ => {}
                }
            }
            Op::ObjectMethod(function, kind) => {
                let key = pop!();
                let key = i.to_property_key(&key)?;
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                let func = &chunk.funcs[function as usize];
                literal_define_method(i, &object, env, func, key.as_str(), kind);
            }
            Op::ObjectMethodName(function, kind, name) => {
                let Value::Obj(object) = stack.last().expect("object builder missing") else {
                    unreachable!("object literal builder retains an Object")
                };
                let func = &chunk.funcs[function as usize];
                literal_define_method(
                    i,
                    &object,
                    env,
                    func,
                    chunk.names[name as usize].clone(),
                    kind,
                );
            }
            Op::ImportMeta => stack.push(i.import_meta_vm(env)),
            Op::NewTarget => stack.push(if chunk.lean_new_target {
                i.new_target.clone()
            } else {
                i.new_target_vm(env)
            }),
            Op::DynamicImport(phase, has_options) => {
                let options = has_options.then(|| pop!());
                let specifier = pop!();
                stack.push(i.import_call_vm(specifier, options, phase, env)?);
            }
            Op::PrivateIn(name, site) => {
                let value = pop!();
                let site = &chunk.private_sites[site as usize];
                let name = &chunk.names[name as usize];
                stack.push(i.private_in_vm(name, value, env, Some(site))?);
            }
            Op::GetPrivate(name, site) => {
                let base = pop!();
                let site = &chunk.private_sites[site as usize];
                let name = &chunk.names[name as usize];
                stack.push(i.private_get_vm(name, &base, env, Some(site))?);
            }
            Op::GetPrivateKeep(name, site) | Op::GetPrivateMethod(name, site) => {
                let base = pop!();
                let site = &chunk.private_sites[site as usize];
                let name = &chunk.names[name as usize];
                let value = i.private_get_vm(name, &base, env, Some(site))?;
                stack.push(base);
                stack.push(value);
            }
            Op::SetPrivate(name, site) => {
                let value = pop!();
                let base = pop!();
                let site = &chunk.private_sites[site as usize];
                let name = &chunk.names[name as usize];
                i.private_set_vm(name, &base, value.clone(), env, Some(site))?;
                stack.push(value);
            }
            Op::UpdatePrivate(name, kind) => {
                let base = pop!();
                let old = i.private_get_vm(&chunk.names[name as usize], &base, env, None)?;
                if let Some(value) =
                    step_value(i, &chunk.feedback, op_pc, kind, old, |i, value| {
                        i.private_set_vm(&chunk.names[name as usize], &base, value, env, None)
                    })?
                {
                    stack.push(value);
                }
            }
            Op::SuperCallStart => {
                let (new_target, super_constructor) = i.prepare_super_call(env)?;
                stack.push(new_target);
                stack.push(super_constructor);
            }
            Op::SuperCallArgsArray => {
                let args = argument_array_values(i, pop!());
                let super_constructor = pop!();
                let new_target = pop!();
                let value = if chunk.feedback.detailed_enabled() {
                    let target = i.call_target_kind(&super_constructor);
                    let environment = i.call_environment_kind(&super_constructor);
                    chunk.feedback.observe_call(
                        op_pc,
                        target,
                        call_arity_kind(args.len()),
                        environment,
                    );
                    let value = i.finish_super_call(
                        new_target,
                        super_constructor,
                        &args,
                        chunk.position(op_pc),
                        env,
                    )?;
                    if let Some(class) = arithmetic_value_class(&value) {
                        chunk.feedback.observe_value_class(
                            op_pc,
                            crate::feedback::ObservationRole::Result,
                            class,
                        );
                    }
                    value
                } else {
                    i.finish_super_call(
                        new_target,
                        super_constructor,
                        &args,
                        chunk.position(op_pc),
                        env,
                    )?
                };
                stack.push(value);
            }
            // ECMA-262 §13.3.7.1 creates a Super Reference with the current function's actual
            // this binding as [[ThisValue]]. Compiled calls keep that binding in the VM frame
            // rather than materializing an activation environment, so use it directly here.
            Op::SuperThis => stack.push(this_val.clone()),
            Op::SuperBase => stack.push(i.super_base_vm(env)?),
            Op::SuperGet | Op::SuperGetMethod => {
                let keep_receiver = matches!(op, Op::SuperGetMethod);
                let base = pop!();
                let key = pop!();
                let receiver = pop!();
                let value = i.super_get_vm(&base, receiver.clone(), key)?;
                if keep_receiver {
                    stack.push(receiver);
                }
                stack.push(value);
            }
            Op::SuperGetKeep => {
                let base = pop!();
                let key = pop!();
                let receiver = pop!();
                if matches!(base, Value::Null | Value::Undefined) {
                    return Err(i.throw("TypeError", "cannot read property of null super base"));
                }
                let key = i.to_property_key(&key)?;
                let value = i.get_member_recv(&base, &key, receiver.clone())?;
                stack.push(receiver);
                stack.push(key.into_value());
                stack.push(base);
                stack.push(value);
            }
            Op::SuperSet => {
                let value = pop!();
                let base = pop!();
                let key = pop!();
                let receiver = pop!();
                i.super_set_vm(&base, receiver, key, value.clone())?;
                stack.push(value);
            }
            Op::SuperUpdate(kind) => {
                let base = pop!();
                let key = pop!();
                let receiver = pop!();
                if matches!(base, Value::Null | Value::Undefined) {
                    return Err(i.throw("TypeError", "cannot read property of null super base"));
                }
                let key = i.to_property_key(&key)?;
                let old = i.get_member_recv(&base, &key, receiver.clone())?;
                if let Some(value) =
                    step_value(i, &chunk.feedback, op_pc, kind, old, |i, value| {
                        i.set_member_recv(&base, &key, value, receiver.clone())
                            .map(|_| ())
                    })?
                {
                    stack.push(value);
                }
            }
            Op::TemplateObject(site) => {
                let (site_id, quasis) = &chunk.templates[site as usize];
                stack.push(i.template_object(*site_id, quasis)?);
            }
            Op::RequireCallable => {
                if !stack
                    .last()
                    .expect("tagged-template callee missing")
                    .is_callable()
                {
                    return Err(i.throw("TypeError", "tag is not a function"));
                }
            }
            Op::ToStr => {
                let v = pop!();
                let s = i.to_string(&v)?;
                stack.push(Value::Str(s));
            }
            Op::GetIter => {
                let v = pop!();
                let (it, nx) = i.get_iterator(&v)?;
                stack.push(it);
                stack.push(nx);
            }
            Op::GetAsyncIter => {
                let v = pop!();
                let opened = VmDelegate::open(i, v, true)?;
                stack.push(opened.iterator);
                stack.push(opened.next);
                stack.push(Value::Bool(opened.from_sync));
            }
            Op::ForInKeys => {
                let source = pop!();
                stack.push(i.for_in_keys(&source)?.into_value());
            }
            Op::ForInStepL(keys, index, source) => {
                if let Some(key) = for_in_step(i, slots, keys, index, source)? {
                    stack.push(key);
                    stack.push(Value::Bool(true));
                } else {
                    stack.push(Value::Undefined);
                    stack.push(Value::Bool(false));
                }
            }
            Op::IterStepL(is, ns) => {
                let it = slots.read_value(is as usize);
                let nx = slots.read_value(ns as usize);
                match i.iterator_step(&it, &nx)? {
                    Some(v) => {
                        stack.push(v);
                        stack.push(Value::Bool(true));
                    }
                    None => {
                        stack.push(Value::Undefined);
                        stack.push(Value::Bool(false));
                    }
                }
            }
            Op::IterCloseL(s) => {
                let it = slots.read_value(s as usize);
                i.iterator_close_normal(&it)?;
            }
            Op::IterAbortL(s) => {
                let exc = pop!();
                let it = slots.read_value(s as usize);
                i.iterator_close(&it);
                return Err(Abrupt::Throw(exc));
            }
            Op::DestructureStepL(iter_s, next_s, done_s) => {
                if matches!(slots.read_value(done_s as usize), Value::Bool(true)) {
                    stack.push(Value::Undefined);
                    continue;
                }
                // IteratorDestructuringAssignmentEvaluation sets [[Done]] before propagating an
                // abrupt IteratorStep. Restore false only after obtaining a live value.
                slots.write_value(done_s as usize, Value::Bool(true));
                let iterator = slots.read_value(iter_s as usize);
                let next = slots.read_value(next_s as usize);
                match i.iterator_step(&iterator, &next)? {
                    Some(value) => {
                        slots.write_value(done_s as usize, Value::Bool(false));
                        stack.push(value);
                    }
                    None => stack.push(Value::Undefined),
                }
            }
            Op::DestructureRestL(iter_s, next_s, done_s) => {
                let iterator = slots.read_value(iter_s as usize);
                let next = slots.read_value(next_s as usize);
                let mut done = matches!(slots.read_value(done_s as usize), Value::Bool(true));
                let result = i.drain_iterator_rest(&iterator, &next, &mut done);
                slots.write_value(done_s as usize, Value::Bool(done));
                let values = result?;
                stack.push(i.make_array(values));
            }
            Op::IterCloseIfNotDoneL(iter_s, done_s) => {
                if !matches!(slots.read_value(done_s as usize), Value::Bool(true)) {
                    slots.write_value(done_s as usize, Value::Bool(true));
                    let iterator = slots.read_value(iter_s as usize);
                    i.iterator_close_normal(&iterator)?;
                }
            }
            Op::IterAbortIfNotDoneL(iter_s, done_s) => {
                let error = pop!();
                if !matches!(slots.read_value(done_s as usize), Value::Bool(true)) {
                    slots.write_value(done_s as usize, Value::Bool(true));
                    let iterator = slots.read_value(iter_s as usize);
                    i.iterator_close(&iterator);
                }
                return Err(Abrupt::Throw(error));
            }
            Op::AsyncIterStepL(iter_s, next_s, from_sync_s, done_s) => {
                let iterator = slots.read_value(iter_s as usize);
                let next = slots.read_value(next_s as usize);
                let from_sync = matches!(slots.read_value(from_sync_s as usize), Value::Bool(true));
                let result = match i.call(next, iterator.clone(), &[]) {
                    Ok(result) => result,
                    Err(error) if from_sync => {
                        return Ok(VmStep::Await(async_from_sync_abrupt_promise(i, error)?));
                    }
                    Err(error) => return Err(error),
                };
                if !from_sync {
                    return Ok(VmStep::Await(result));
                }
                if !matches!(result, Value::Obj(_)) {
                    let error = i.make_error("TypeError", "iterator result is not an object");
                    return Ok(VmStep::Await(rejected_intrinsic_promise(i, error)));
                }
                let done = match i.get_member_key(&result, "done") {
                    Ok(done) => done,
                    Err(error) => {
                        return Ok(VmStep::Await(async_from_sync_abrupt_promise(i, error)?));
                    }
                };
                let done = i.to_boolean(&done);
                let value = match i.get_member_key(&result, "value") {
                    Ok(value) => value,
                    Err(error) => {
                        return Ok(VmStep::Await(async_from_sync_abrupt_promise(i, error)?));
                    }
                };
                slots.write_value(done_s as usize, Value::Bool(done));
                // AsyncFromSyncIteratorContinuation resolves and chains the value into the
                // adapter promise before the loop's Await. A live value rejection closes the
                // underlying sync iterator in that reaction job, not one Await job later.
                let wrapper = match i.promise_resolve_checked(value) {
                    Ok(promise) => {
                        let on_rejected = if done {
                            Value::Undefined
                        } else {
                            crate::builtins::make_bound_len(
                                i,
                                async_from_sync_close_rejection,
                                vec![iterator],
                                1.0,
                            )
                        };
                        i.promise_then(&promise, Value::Undefined, on_rejected)
                    }
                    Err(error) => {
                        if !done {
                            i.iterator_close(&iterator);
                        }
                        rejected_intrinsic_promise(i, error)
                    }
                };
                return Ok(VmStep::Await(wrapper));
            }
            Op::AsyncIterResumeL(from_sync_s, done_s) => {
                let settled = pop!();
                let from_sync = matches!(slots.read_value(from_sync_s as usize), Value::Bool(true));
                let (done, value) = if from_sync {
                    let done = matches!(slots.read_value(done_s as usize), Value::Bool(true));
                    (done, if done { Value::Undefined } else { settled })
                } else {
                    if !matches!(settled, Value::Obj(_)) {
                        return Err(i.throw("TypeError", "iterator result is not an object"));
                    }
                    let done = i.get_member_key(&settled, "done")?;
                    let done = i.to_boolean(&done);
                    let value = if done {
                        Value::Undefined
                    } else {
                        i.get_member_key(&settled, "value")?
                    };
                    (done, value)
                };
                stack.push(value);
                stack.push(Value::Bool(!done));
            }
            Op::AsyncIterCloseL(iter_s, from_sync_s, swallow_error) => {
                return Ok(VmStep::AsyncClose {
                    iterator: slots.read_value(iter_s as usize),
                    from_sync: matches!(slots.read_value(from_sync_s as usize), Value::Bool(true)),
                    swallow_error,
                });
            }
            Op::Throw => {
                let v = pop!();
                return Err(Abrupt::Throw(v));
            }
            Op::AbruptJump(target, handler_depth) => {
                return Ok(VmStep::AbruptJump {
                    target: target as usize,
                    handler_depth: handler_depth as usize,
                });
            }
            Op::Return => return Ok(VmStep::Return(pop!())),
            Op::ReturnBare => return Ok(VmStep::BareReturn),
            Op::ResumeReturn => return Ok(VmStep::ResumeReturn(pop!())),
            Op::ResumeJump => {
                let handler_depth = match pop!() {
                    Value::Num(value) => value as usize,
                    _ => unreachable!("finally jump depth is an internal integer"),
                };
                let target = match pop!() {
                    Value::Num(value) => value as usize,
                    _ => unreachable!("finally jump target is an internal integer"),
                };
                return Ok(VmStep::AbruptJump {
                    target,
                    handler_depth,
                });
            }
            Op::FragmentExit(kind) => {
                debug_assert!(
                    handlers.is_empty(),
                    "fragment cleanup must precede its terminal"
                );
                return Ok(VmStep::FragmentExit(kind, pop!()));
            }
            Op::AnnexBSync(function) => {
                let function = &chunk.funcs[function as usize];
                if let Some(name) = &function.name {
                    if i.annexb_fn_sync
                        .contains_key(&(Rc::as_ptr(function) as usize))
                    {
                        i.annexb_fn_sync_eval(name, function, env);
                    }
                }
            }
            Op::ReturnUndef => return Ok(VmStep::Done(Value::Undefined)),
            Op::Await => return Ok(VmStep::Await(pop!())),
            Op::Yield => return Ok(VmStep::Yield(pop!())),
            Op::YieldStar => return Ok(VmStep::YieldStar(pop!())),
            Op::PushHandler(throw_pc) => handlers.push(Handler {
                target: HandlerTarget::Catch {
                    throw_pc: throw_pc as usize,
                },
                stack_depth: stack.len(),
            }),
            Op::PushFinally(throw_pc, return_pc, bare_return_pc, resume_return_pc, jump_pc) => {
                handlers.push(Handler {
                    target: HandlerTarget::Finally {
                        throw_pc: throw_pc as usize,
                        return_pc: return_pc as usize,
                        bare_return_pc: bare_return_pc as usize,
                        resume_return_pc: resume_return_pc as usize,
                        jump_pc: jump_pc as usize,
                    },
                    stack_depth: stack.len(),
                })
            }
            Op::PushIterator(throw_pc, return_pc, bare_return_pc, resume_return_pc) => handlers
                .push(Handler {
                    target: HandlerTarget::Iterator {
                        throw_pc: throw_pc as usize,
                        return_pc: return_pc as usize,
                        bare_return_pc: bare_return_pc as usize,
                        resume_return_pc: resume_return_pc as usize,
                    },
                    stack_depth: stack.len(),
                }),
            Op::PopHandler => {
                handlers.pop();
            }
        }
    }
}

#[derive(Clone, Copy)]
enum DelegateCompletion {
    Normal,
    Return,
}

enum DelegateStage {
    /// Waiting for the completion produced by the outer generator's next/throw/return method.
    Ready,
    /// An async iterator method result is being awaited.
    AwaitResult(DelegateCompletion),
    /// An async-from-sync iterator result's value is being awaited.
    AwaitValue {
        completion: DelegateCompletion,
        done: bool,
    },
    /// AsyncIteratorClose after a missing delegated `throw` is awaiting `return()`.
    AwaitCloseResult,
    /// The async-from-sync close result's value is being awaited.
    AwaitCloseValue,
    /// A delegated async iterator has no `return`; YieldExpression performs its own Await of the
    /// already-unwrapped outer return value before propagating the return completion.
    AwaitMissingReturn,
}

struct VmDelegate {
    iterator: Value,
    next: Value,
    from_sync: bool,
    async_mode: bool,
    stage: DelegateStage,
}

enum DelegateAction {
    Suspend(crate::coroutine::Suspend),
    Continue(Value),
    Return(Value),
    Throw(Value),
    Terminate,
}

struct VmDispose {
    resources: Vec<crate::interpreter::Disposable>,
    output: DisposeCompletion,
    needs_await: bool,
    has_awaited: bool,
    /// A synchronous resource deferred until the await-only marker immediately above it has
    /// yielded one job turn.
    pending_resource: Option<crate::interpreter::Disposable>,
}

enum DisposeAction {
    Suspend(Value),
    Complete(DisposeCompletion),
    Terminate,
}

impl VmDispose {
    fn new(resources: Vec<crate::interpreter::Disposable>, output: DisposeCompletion) -> VmDispose {
        VmDispose {
            resources,
            output,
            needs_await: false,
            has_awaited: false,
            pending_resource: None,
        }
    }

    fn record_error(&mut self, i: &mut Interp, error: Value) {
        let previous = std::mem::replace(&mut self.output, DisposeCompletion::Normal);
        self.output = match previous {
            DisposeCompletion::Throw(suppressed) => {
                DisposeCompletion::Throw(i.make_suppressed(error, suppressed))
            }
            _ => DisposeCompletion::Throw(error),
        };
    }

    fn call_failure(&mut self, i: &mut Interp, error: Abrupt) -> Option<DisposeAction> {
        match error {
            Abrupt::Throw(error) => {
                self.record_error(i, error);
                None
            }
            Abrupt::Interrupt(_) => Some(DisposeAction::Terminate),
            // Call's function boundary consumes these completion kinds. Keep the defensive path
            // non-panicking if a host callable violates that contract.
            Abrupt::Return(value) | Abrupt::Break(_, value) | Abrupt::Continue(_, value) => {
                self.record_error(i, value);
                None
            }
        }
    }

    fn advance(&mut self, i: &mut Interp) -> DisposeAction {
        loop {
            let resource = match self
                .pending_resource
                .take()
                .or_else(|| self.resources.pop())
            {
                Some(resource) => resource,
                None => {
                    if self.needs_await && !self.has_awaited {
                        self.needs_await = false;
                        return DisposeAction::Suspend(Value::Undefined);
                    }
                    return DisposeAction::Complete(std::mem::replace(
                        &mut self.output,
                        DisposeCompletion::Normal,
                    ));
                }
            };

            if !resource.kind_is_async && self.needs_await && !self.has_awaited {
                self.needs_await = false;
                self.pending_resource = Some(resource);
                return DisposeAction::Suspend(Value::Undefined);
            }
            if !resource.method.is_callable() {
                debug_assert!(resource.kind_is_async);
                self.needs_await = true;
                continue;
            }

            let called = i.call(resource.method, resource.value, &[]);
            if !resource.kind_is_async {
                if let Err(error) = called {
                    if let Some(action) = self.call_failure(i, error) {
                        return action;
                    }
                }
                continue;
            }

            if resource.method_is_async {
                match called {
                    Ok(value) => {
                        self.has_awaited = true;
                        return DisposeAction::Suspend(value);
                    }
                    Err(error) => {
                        if let Some(action) = self.call_failure(i, error) {
                            return action;
                        }
                        continue;
                    }
                }
            }

            // The sync fallback is wrapped into an intrinsic async disposer. Its return value is
            // ignored; a synchronous throw rejects the wrapper promise before Await observes it.
            let promise = i.new_promise();
            match called {
                Ok(_) => i.resolve_promise(&promise, Value::Undefined),
                Err(Abrupt::Throw(error)) => i.reject_promise(&promise, error),
                Err(error) => {
                    if let Some(action) = self.call_failure(i, error) {
                        return action;
                    }
                    continue;
                }
            }
            self.has_awaited = true;
            return DisposeAction::Suspend(promise);
        }
    }

    fn resume(&mut self, i: &mut Interp, signal: crate::coroutine::Resume) -> DisposeAction {
        match signal {
            crate::coroutine::Resume::Next(_) => {}
            crate::coroutine::Resume::Throw(error) => self.record_error(i, error),
            crate::coroutine::Resume::Return(value) => {
                self.output = DisposeCompletion::ResumeReturn(value)
            }
            crate::coroutine::Resume::Terminate => return DisposeAction::Terminate,
        }
        self.advance(i)
    }
}

fn pending_dispose_completion(completion: DisposeCompletion) -> Option<PendingCompletion> {
    match completion {
        DisposeCompletion::Normal => None,
        DisposeCompletion::Throw(error) => Some(PendingCompletion::Throw(error)),
        DisposeCompletion::SourceReturn(value) => Some(PendingCompletion::SourceReturn(value)),
        DisposeCompletion::BareReturn => Some(PendingCompletion::BareReturn),
        DisposeCompletion::ResumeReturn(value) => Some(PendingCompletion::ResumeReturn(value)),
        DisposeCompletion::Jump {
            target,
            handler_depth,
        } => Some(PendingCompletion::Jump {
            target,
            handler_depth,
        }),
    }
}

enum AsyncCloseStage {
    AwaitResult,
    AwaitValue,
}

struct VmAsyncClose {
    /// Keep the iterator alive while an awaited close reaction is pending.
    _iterator: Value,
    swallow_error: bool,
    stage: AsyncCloseStage,
}

enum AsyncCloseAction {
    Suspend(crate::coroutine::Suspend),
    Continue,
    Throw(Value),
    Terminate,
}

impl VmAsyncClose {
    fn failure(swallow_error: bool, error: Abrupt) -> AsyncCloseAction {
        match error {
            Abrupt::Throw(_) if swallow_error => AsyncCloseAction::Continue,
            Abrupt::Throw(error) => AsyncCloseAction::Throw(error),
            Abrupt::Interrupt(_) => AsyncCloseAction::Terminate,
            Abrupt::Return(value) => AsyncCloseAction::Throw(value),
            Abrupt::Break(_, value) | Abrupt::Continue(_, value) => AsyncCloseAction::Throw(value),
        }
    }

    fn start(
        i: &mut Interp,
        iterator: Value,
        from_sync: bool,
        swallow_error: bool,
    ) -> (Option<VmAsyncClose>, AsyncCloseAction) {
        use crate::coroutine::Suspend;

        // CreateAsyncFromSyncIterator's `return` is an intrinsic method which always returns a
        // promise. Even an absent underlying `return`, or a getter/call/protocol error, therefore
        // reaches AsyncIteratorClose through Await. Preserve that mandatory job boundary instead
        // of directly invoking the sync close as though this were IteratorClose.
        if from_sync {
            return Self::start_from_sync(i, iterator, swallow_error);
        }

        let ret = match i.get_member_key(&iterator, "return") {
            Ok(ret) => ret,
            Err(error) => return (None, Self::failure(swallow_error, error)),
        };
        if matches!(ret, Value::Undefined | Value::Null) {
            return (None, AsyncCloseAction::Continue);
        }
        if !ret.is_callable() {
            let error = i.throw("TypeError", "iterator 'return' is not callable");
            return (None, Self::failure(swallow_error, error));
        }
        let result = match i.call(ret, iterator.clone(), &[]) {
            Ok(result) => result,
            Err(error) => return (None, Self::failure(swallow_error, error)),
        };
        (
            Some(VmAsyncClose {
                _iterator: iterator,
                swallow_error,
                stage: AsyncCloseStage::AwaitResult,
            }),
            AsyncCloseAction::Suspend(Suspend::Await(result)),
        )
    }

    fn suspend_from_sync(
        iterator: Value,
        swallow_error: bool,
        stage: AsyncCloseStage,
        promise: Value,
    ) -> (Option<VmAsyncClose>, AsyncCloseAction) {
        (
            Some(VmAsyncClose {
                _iterator: iterator,
                swallow_error,
                stage,
            }),
            AsyncCloseAction::Suspend(crate::coroutine::Suspend::Await(promise)),
        )
    }

    fn reject_from_sync(
        i: &mut Interp,
        iterator: Value,
        swallow_error: bool,
        error: Abrupt,
    ) -> (Option<VmAsyncClose>, AsyncCloseAction) {
        match error {
            Abrupt::Throw(error) => Self::suspend_from_sync(
                iterator,
                swallow_error,
                AsyncCloseStage::AwaitResult,
                rejected_intrinsic_promise(i, error),
            ),
            other => (None, Self::failure(swallow_error, other)),
        }
    }

    fn start_from_sync(
        i: &mut Interp,
        iterator: Value,
        swallow_error: bool,
    ) -> (Option<VmAsyncClose>, AsyncCloseAction) {
        let ret = match i.get_member_key(&iterator, "return") {
            Ok(ret) => ret,
            Err(error) => {
                return Self::reject_from_sync(i, iterator, swallow_error, error);
            }
        };
        if matches!(ret, Value::Undefined | Value::Null) {
            let promise = i.new_promise();
            let result = i.iter_result_obj(Value::Undefined, true);
            i.resolve_promise(&promise, result);
            return Self::suspend_from_sync(
                iterator,
                swallow_error,
                AsyncCloseStage::AwaitResult,
                promise,
            );
        }
        if !ret.is_callable() {
            let error =
                Abrupt::Throw(i.make_error("TypeError", "iterator 'return' is not callable"));
            return Self::reject_from_sync(i, iterator, swallow_error, error);
        }
        let result = match i.call(ret, iterator.clone(), &[]) {
            Ok(result) => result,
            Err(error) => {
                return Self::reject_from_sync(i, iterator, swallow_error, error);
            }
        };
        if !matches!(result, Value::Obj(_)) {
            let error =
                Abrupt::Throw(i.make_error("TypeError", "iterator result is not an object"));
            return Self::reject_from_sync(i, iterator, swallow_error, error);
        }
        // AsyncFromSyncIteratorContinuation observes `done` before `value`, even though
        // AsyncIteratorClose only uses the repackaged result's object-ness.
        if let Err(error) = i.get_member_key(&result, "done") {
            return Self::reject_from_sync(i, iterator, swallow_error, error);
        }
        let value = match i.get_member_key(&result, "value") {
            Ok(value) => value,
            Err(error) => {
                return Self::reject_from_sync(i, iterator, swallow_error, error);
            }
        };
        let wrapper = match i.promise_resolve_checked(value) {
            Ok(promise) => i.promise_then(&promise, Value::Undefined, Value::Undefined),
            Err(error) => rejected_intrinsic_promise(i, error),
        };
        Self::suspend_from_sync(
            iterator,
            swallow_error,
            AsyncCloseStage::AwaitValue,
            wrapper,
        )
    }

    fn resume(&mut self, i: &mut Interp, signal: crate::coroutine::Resume) -> AsyncCloseAction {
        use crate::coroutine::Resume;
        match signal {
            Resume::Next(result) => match self.stage {
                AsyncCloseStage::AwaitResult => {
                    if matches!(result, Value::Obj(_)) {
                        AsyncCloseAction::Continue
                    } else {
                        Self::failure(
                            self.swallow_error,
                            i.throw("TypeError", "iterator result is not an object"),
                        )
                    }
                }
                AsyncCloseStage::AwaitValue => AsyncCloseAction::Continue,
            },
            Resume::Throw(error) => Self::failure(self.swallow_error, Abrupt::Throw(error)),
            Resume::Return(error) => Self::failure(self.swallow_error, Abrupt::Throw(error)),
            Resume::Terminate => AsyncCloseAction::Terminate,
        }
    }
}

impl VmDelegate {
    /// GetIterator(value, generator kind). Async generators prefer @@asyncIterator and otherwise
    /// retain the sync iterator plus an explicit async-from-sync continuation state.
    fn open(i: &mut Interp, value: Value, async_mode: bool) -> Result<Self, Abrupt> {
        let (iterator, next, from_sync) = if async_mode {
            let key = crate::builtins::async_iterator_key(i);
            let method = match key {
                Some(key) => i.get_member_key(&value, &key)?,
                None => Value::Undefined,
            };
            if !matches!(method, Value::Undefined | Value::Null) && !method.is_callable() {
                return Err(i.throw("TypeError", "@@asyncIterator is not callable"));
            }
            if method.is_callable() {
                let iterator = i.call(method, value, &[])?;
                if !matches!(iterator, Value::Obj(_)) {
                    return Err(i.throw("TypeError", "@@asyncIterator did not return an object"));
                }
                let next = i.get_member_key(&iterator, "next")?;
                (iterator, next, false)
            } else {
                let (iterator, next) = i.get_iterator(&value)?;
                (iterator, next, true)
            }
        } else {
            let (iterator, next) = i.get_iterator(&value)?;
            (iterator, next, false)
        };
        Ok(Self {
            iterator,
            next,
            from_sync,
            async_mode,
            stage: DelegateStage::Ready,
        })
    }

    fn abrupt(error: Abrupt) -> DelegateAction {
        match error {
            Abrupt::Throw(value) => DelegateAction::Throw(value),
            Abrupt::Return(value) => DelegateAction::Return(value),
            Abrupt::Interrupt(_) => DelegateAction::Terminate,
            Abrupt::Break(_, _) | Abrupt::Continue(_, _) => DelegateAction::Terminate,
        }
    }

    fn type_error(i: &mut Interp, message: &str) -> DelegateAction {
        DelegateAction::Throw(i.make_error("TypeError", message))
    }

    /// Consume either an outer resumption completion or an internal async-await reaction.
    fn resume(&mut self, i: &mut Interp, signal: crate::coroutine::Resume) -> DelegateAction {
        use crate::coroutine::{Resume, Suspend};
        let stage = std::mem::replace(&mut self.stage, DelegateStage::Ready);
        match stage {
            DelegateStage::Ready => {
                let (method, argument, completion) = match signal {
                    Resume::Next(value) => (self.next.clone(), value, DelegateCompletion::Normal),
                    Resume::Throw(error) => {
                        let method = match i.get_member_key(&self.iterator, "throw") {
                            Ok(method) => method,
                            Err(error) => return Self::abrupt(error),
                        };
                        if matches!(method, Value::Undefined | Value::Null) {
                            if !self.async_mode {
                                if let Err(error) = i.iterator_close_normal(&self.iterator) {
                                    return Self::abrupt(error);
                                }
                                return Self::type_error(
                                    i,
                                    "the delegated iterator has no 'throw' method",
                                );
                            }
                            // AsyncIteratorClose(iteratorRecord, NormalCompletion(empty)) before
                            // the mandated protocol TypeError.
                            let ret = match i.get_member_key(&self.iterator, "return") {
                                Ok(ret) => ret,
                                Err(error) => return Self::abrupt(error),
                            };
                            if matches!(ret, Value::Undefined | Value::Null) {
                                return Self::type_error(
                                    i,
                                    "the delegated iterator has no 'throw' method",
                                );
                            }
                            if !ret.is_callable() {
                                return Self::type_error(i, "iterator 'return' is not callable");
                            }
                            let result = match i.call(ret, self.iterator.clone(), &[]) {
                                Ok(result) => result,
                                Err(error) => return Self::abrupt(error),
                            };
                            self.stage = DelegateStage::AwaitCloseResult;
                            return DelegateAction::Suspend(Suspend::Await(result));
                        }
                        if !method.is_callable() {
                            return Self::type_error(i, "iterator 'throw' is not callable");
                        }
                        (method, error, DelegateCompletion::Normal)
                    }
                    Resume::Return(value) => {
                        let method = match i.get_member_key(&self.iterator, "return") {
                            Ok(method) => method,
                            Err(error) => return Self::abrupt(error),
                        };
                        if matches!(method, Value::Undefined | Value::Null) {
                            if self.async_mode {
                                self.stage = DelegateStage::AwaitMissingReturn;
                                return DelegateAction::Suspend(Suspend::Await(value));
                            }
                            return DelegateAction::Return(value);
                        }
                        if !method.is_callable() {
                            return Self::type_error(i, "iterator 'return' is not callable");
                        }
                        (method, value, DelegateCompletion::Return)
                    }
                    Resume::Terminate => return DelegateAction::Terminate,
                };
                let result = match i.call(method, self.iterator.clone(), &[argument]) {
                    Ok(result) => result,
                    Err(error) => return Self::abrupt(error),
                };
                if self.async_mode {
                    self.stage = DelegateStage::AwaitResult(completion);
                    DelegateAction::Suspend(Suspend::Await(result))
                } else {
                    self.process_result(i, result, completion)
                }
            }
            DelegateStage::AwaitResult(completion) => match signal {
                Resume::Next(result) => self.process_result(i, result, completion),
                Resume::Throw(error) => DelegateAction::Throw(error),
                Resume::Return(value) => DelegateAction::Return(value),
                Resume::Terminate => DelegateAction::Terminate,
            },
            DelegateStage::AwaitValue { completion, done } => match signal {
                Resume::Next(value) => self.process_value(i, value, done, completion, None),
                Resume::Throw(error) => {
                    if !done {
                        i.iterator_close(&self.iterator);
                    }
                    DelegateAction::Throw(error)
                }
                Resume::Return(value) => DelegateAction::Return(value),
                Resume::Terminate => DelegateAction::Terminate,
            },
            DelegateStage::AwaitCloseResult => match signal {
                Resume::Next(result) => {
                    if !matches!(result, Value::Obj(_)) {
                        return Self::type_error(i, "iterator 'return' must return an object");
                    }
                    if self.from_sync {
                        let value = match i.get_member_key(&result, "value") {
                            Ok(value) => value,
                            Err(error) => return Self::abrupt(error),
                        };
                        self.stage = DelegateStage::AwaitCloseValue;
                        DelegateAction::Suspend(Suspend::Await(value))
                    } else {
                        Self::type_error(i, "the delegated iterator has no 'throw' method")
                    }
                }
                Resume::Throw(error) => DelegateAction::Throw(error),
                Resume::Return(value) => DelegateAction::Return(value),
                Resume::Terminate => DelegateAction::Terminate,
            },
            DelegateStage::AwaitCloseValue => match signal {
                Resume::Next(_) => {
                    Self::type_error(i, "the delegated iterator has no 'throw' method")
                }
                Resume::Throw(error) => DelegateAction::Throw(error),
                Resume::Return(value) => DelegateAction::Return(value),
                Resume::Terminate => DelegateAction::Terminate,
            },
            DelegateStage::AwaitMissingReturn => match signal {
                Resume::Next(value) => DelegateAction::Return(value),
                Resume::Throw(error) => DelegateAction::Throw(error),
                Resume::Return(value) => DelegateAction::Return(value),
                Resume::Terminate => DelegateAction::Terminate,
            },
        }
    }

    fn process_result(
        &mut self,
        i: &mut Interp,
        result: Value,
        completion: DelegateCompletion,
    ) -> DelegateAction {
        use crate::coroutine::Suspend;
        if !matches!(result, Value::Obj(_)) {
            return Self::type_error(i, "iterator result is not an object");
        }
        let done = match i.get_member_key(&result, "done") {
            Ok(done) => i.to_boolean(&done),
            Err(error) => return Self::abrupt(error),
        };
        if !self.async_mode && !done {
            // ECMA-262 YieldExpression : yield * AssignmentExpression passes the complete iterator
            // result to GeneratorYield here. In particular, it does not perform IteratorValue, so
            // an observable `value` getter must not run until the outer caller reads it.
            self.stage = DelegateStage::Ready;
            i.yield_raw_result = true;
            return DelegateAction::Suspend(Suspend::Yield(result));
        }
        let value = match i.get_member_key(&result, "value") {
            Ok(value) => value,
            Err(error) => return Self::abrupt(error),
        };
        if self.async_mode && self.from_sync {
            self.stage = DelegateStage::AwaitValue { completion, done };
            return DelegateAction::Suspend(Suspend::Await(value));
        }
        self.process_value(i, value, done, completion, Some(result))
    }

    fn process_value(
        &mut self,
        i: &mut Interp,
        value: Value,
        done: bool,
        completion: DelegateCompletion,
        result: Option<Value>,
    ) -> DelegateAction {
        use crate::coroutine::Suspend;
        if done {
            return match completion {
                DelegateCompletion::Normal => DelegateAction::Continue(value),
                DelegateCompletion::Return => DelegateAction::Return(value),
            };
        }
        self.stage = DelegateStage::Ready;
        if self.async_mode {
            // AsyncGeneratorYield receives IteratorValue(innerResult); unlike an ordinary async
            // `yield`, delegation does not await a value produced by a native async iterator.
            DelegateAction::Suspend(Suspend::Yield(value))
        } else {
            // GeneratorYield(innerResult) forwards the exact result object, including getters and
            // identity, instead of creating a fresh `{ value, done }` wrapper.
            i.yield_raw_result = true;
            DelegateAction::Suspend(Suspend::Yield(
                result.expect("a synchronous delegation retains its iterator result"),
            ))
        }
    }
}

/// An async function or generator body running as a heap-owned bytecode continuation. It presents
/// the shared `resume(&mut Interp, Resume) -> Suspend` interface used by the promise/generator
/// drivers and owns every suspension point explicitly.
pub struct VmCoro {
    chunk: Rc<Chunk>,
    /// Owning source execution context, not the Realm/settings of a native
    /// reaction or borrowed generator method that later resumes this body.
    realm: crate::value::Gc,
    host_job_context: u64,
    /// Fixed activation containing compiler-homed captures. `env` may temporarily point at a
    /// nested Object Environment Record while a suspending `with` body is active.
    cap_env: Env,
    env: Env,
    references: Vec<crate::eval::PreparedReferenceSlot>,
    this_val: Value,
    slots: Vec<PackedValue>,
    stack: ValueStack<PackedValue>,
    pc: usize,
    /// The `try` handler stack, saved across suspensions so a rejected `await` inside a `try` still
    /// lands in its `catch`.
    handlers: Vec<Handler>,
    /// One DisposableResource list per active `using` statement-list boundary. Unlike the
    /// tree-walker's ambient stack, this storage belongs to the suspended continuation.
    disposal_frames: Vec<Vec<crate::interpreter::Disposable>>,
    /// In-progress class definitions keyed by immutable class-plan site. A state exists only from
    /// ClassStart until ClassFinish or its abrupt-completion cleanup pad.
    class_states: Vec<Option<crate::eval::PreparedClassEvaluation>>,
    is_generator: bool,
    is_async_generator: bool,
    awaiting_yield_value: bool,
    awaiting_return_value: bool,
    awaiting_body_return: bool,
    delegation: Option<VmDelegate>,
    async_close: Option<VmAsyncClose>,
    disposal: Option<VmDispose>,
    pub done: bool,
    pub started: bool,
    /// What the body reports in stack traces while it runs after resuming.
    pub(crate) frame: Option<Box<crate::stack_trace::ResumedFrame>>,
}

impl VmCoro {
    pub(crate) fn trace_gc(&self, edges: &mut crate::gc_edges::DirectGcEdges<'_>) {
        fn disposable(
            resource: &crate::interpreter::Disposable,
            edges: &mut crate::gc_edges::DirectGcEdges<'_>,
        ) {
            let crate::interpreter::Disposable {
                value,
                method,
                kind_is_async: _,
                method_is_async: _,
            } = resource;
            edges.value(value);
            edges.value(method);
        }
        // These are *direct* owners, not a transitive traversal of the shared Chunk.
        // During execution the driver removes this continuation from the side table;
        // its temporarily stack-owned handles therefore remain external GC roots.
        let Self {
            chunk: _,
            realm,
            host_job_context: _,
            cap_env,
            env,
            references,
            this_val,
            slots,
            stack,
            pc: _,
            handlers: _,
            disposal_frames,
            class_states,
            is_generator: _,
            is_async_generator: _,
            awaiting_yield_value: _,
            awaiting_return_value: _,
            awaiting_body_return: _,
            delegation,
            async_close,
            disposal,
            done: _,
            started: _,
            frame: _,
        } = self;
        edges.object(realm);
        edges.scope(cap_env);
        edges.scope(env);
        edges.value(this_val);
        for value in slots.iter().chain(stack.raw_slice()) {
            edges.value(&value.unpack());
        }
        for reference in references.iter().flatten() {
            reference.trace_gc(edges);
        }
        for state in class_states.iter().flatten() {
            state.trace_gc(edges);
        }
        for resource in disposal_frames.iter().flatten() {
            disposable(resource, edges);
        }
        if let Some(VmDelegate {
            iterator,
            next,
            from_sync: _,
            async_mode: _,
            stage: _,
        }) = delegation
        {
            edges.value(iterator);
            edges.value(next);
        }
        if let Some(VmAsyncClose {
            _iterator,
            swallow_error: _,
            stage: _,
        }) = async_close
        {
            edges.value(_iterator);
        }
        if let Some(VmDispose {
            resources,
            output,
            needs_await: _,
            has_awaited: _,
            pending_resource,
        }) = disposal
        {
            for resource in resources {
                disposable(resource, edges);
            }
            if let Some(resource) = pending_resource {
                disposable(resource, edges);
            }
            match output {
                DisposeCompletion::Throw(value)
                | DisposeCompletion::SourceReturn(value)
                | DisposeCompletion::ResumeReturn(value) => edges.value(value),
                DisposeCompletion::Normal
                | DisposeCompletion::BareReturn
                | DisposeCompletion::Jump { .. } => {}
            }
        }
    }

    /// Scan allocations owned below this continuation. The caller credits the fixed `VmCoro`
    /// payload because it may be boxed directly or embedded in a module-coroutine box.
    pub(crate) fn scan_retained_memory(&self, visitor: &mut crate::memory::Visitor) -> usize {
        fn disposable(
            resource: &crate::interpreter::Disposable,
            visitor: &mut crate::memory::Visitor,
        ) {
            visitor.value(&resource.value);
            visitor.value(&resource.method);
        }
        fn completion(completion: &DisposeCompletion, visitor: &mut crate::memory::Visitor) {
            match completion {
                DisposeCompletion::Throw(value)
                | DisposeCompletion::SourceReturn(value)
                | DisposeCompletion::ResumeReturn(value) => visitor.value(value),
                DisposeCompletion::Normal
                | DisposeCompletion::BareReturn
                | DisposeCompletion::Jump { .. } => {}
            }
        }

        visitor.chunk(&self.chunk);
        visitor.value(&Value::Obj(self.realm.clone()));
        visitor.value(&self.this_val);
        let mut bytes = self
            .references
            .capacity()
            .saturating_mul(std::mem::size_of::<crate::eval::PreparedReferenceSlot>())
            .saturating_add(
                self.slots
                    .capacity()
                    .saturating_mul(std::mem::size_of::<PackedValue>()),
            )
            .saturating_add(
                self.stack
                    .capacity()
                    .saturating_mul(std::mem::size_of::<PackedValue>()),
            )
            .saturating_add(
                self.handlers
                    .capacity()
                    .saturating_mul(std::mem::size_of::<Handler>()),
            )
            .saturating_add(
                self.disposal_frames
                    .capacity()
                    .saturating_mul(std::mem::size_of::<Vec<crate::interpreter::Disposable>>()),
            )
            .saturating_add(
                self.class_states
                    .capacity()
                    .saturating_mul(std::mem::size_of::<
                        Option<crate::eval::PreparedClassEvaluation>,
                    >()),
            );
        for reference in self.references.iter().flatten() {
            bytes = bytes.saturating_add(reference.scan_retained_memory(visitor));
        }
        for value in self.slots.iter().chain(self.stack.raw_slice()) {
            visitor.value(&value.unpack());
        }
        for frame in &self.disposal_frames {
            bytes = bytes.saturating_add(
                frame
                    .capacity()
                    .saturating_mul(std::mem::size_of::<crate::interpreter::Disposable>()),
            );
            for resource in frame {
                disposable(resource, visitor);
            }
        }
        for state in self.class_states.iter().flatten() {
            bytes = bytes.saturating_add(state.scan_retained_memory(visitor));
        }
        if let Some(delegation) = &self.delegation {
            visitor.value(&delegation.iterator);
            visitor.value(&delegation.next);
        }
        if let Some(close) = &self.async_close {
            visitor.value(&close._iterator);
        }
        if let Some(disposal) = &self.disposal {
            bytes = bytes.saturating_add(
                disposal
                    .resources
                    .capacity()
                    .saturating_mul(std::mem::size_of::<crate::interpreter::Disposable>()),
            );
            for resource in &disposal.resources {
                disposable(resource, visitor);
            }
            if let Some(resource) = &disposal.pending_resource {
                disposable(resource, visitor);
            }
            completion(&disposal.output, visitor);
        }
        // `cap_env` and `env` are registered scope allocations and remain canonical to the
        // collector snapshot even when a suspended continuation is their discoverer.
        bytes
    }

    /// Build an async coroutine for `chunk` with its already-instantiated parameter values, parked
    /// before its first step (run on the first `resume`). `arguments` remains the original call
    /// list, as required for the function's arguments object.
    pub fn new(
        i: &mut Interp,
        chunk: Rc<Chunk>,
        env: Env,
        this_val: Value,
        params: &[Value],
        arguments: &[Value],
    ) -> VmCoro {
        let env = chunk.make_run_env(i, &env, &this_val, params);
        let references = (0..chunk.n_refs)
            .map(|_| crate::eval::PreparedReferenceSlot::default())
            .collect();
        let slots: Vec<PackedValue> = (0..chunk.n_slots)
            .map(|_| PackedValue::pack(Value::Undefined))
            .collect();
        for (k, a) in params.iter().take(chunk.n_params).enumerate() {
            slots.write_value(k, a.clone());
        }
        if let Some(slot) = chunk.arguments_slot {
            slots.write_value(
                slot as usize,
                chunk.arguments_slot_value(i, arguments, &env),
            );
        }
        let class_states = (0..chunk.class_plans.len()).map(|_| None).collect();
        VmCoro {
            chunk,
            realm: i.global.clone(),
            host_job_context: i.host_job_context,
            cap_env: env.clone(),
            env,
            references,
            this_val,
            slots,
            stack: ValueStack::with_capacity(16),
            pc: 0,
            handlers: Vec::new(),
            disposal_frames: Vec::new(),
            class_states,
            is_generator: false,
            is_async_generator: false,
            awaiting_yield_value: false,
            awaiting_return_value: false,
            awaiting_body_return: false,
            delegation: None,
            async_close: None,
            disposal: None,
            done: false,
            started: false,
            frame: None,
        }
    }

    /// Build a synchronous generator continuation, parked in suspended-start without reserving a
    /// native thread stack.
    pub fn new_generator(
        i: &mut Interp,
        chunk: Rc<Chunk>,
        env: Env,
        this_val: Value,
        params: &[Value],
        arguments: &[Value],
    ) -> VmCoro {
        let mut coroutine = Self::new(i, chunk, env, this_val, params, arguments);
        coroutine.is_generator = true;
        coroutine
    }

    /// Build an async-generator continuation. `yield value` first reports `Await(value)` to the
    /// async-generator driver and publishes the settled value as `Yield` on the reaction resume.
    pub fn new_async_generator(
        i: &mut Interp,
        chunk: Rc<Chunk>,
        env: Env,
        this_val: Value,
        params: &[Value],
        arguments: &[Value],
    ) -> VmCoro {
        let mut coroutine = Self::new_generator(i, chunk, env, this_val, params, arguments);
        coroutine.is_async_generator = true;
        coroutine
    }

    /// Drive one step: run to the next `await`/`yield`, completion, or uncaught throw. A resumed
    /// throw is injected at the suspension point so an enclosing VM `try` can catch it.
    pub fn resume(
        &mut self,
        i: &mut Interp,
        signal: crate::coroutine::Resume,
    ) -> crate::coroutine::Suspend {
        // This local owner remains an external GC root while the driver has
        // temporarily removed the continuation from its owner's internal slot.
        let realm = self.realm.clone();
        let frame = self.frame.take();
        let suspend = i.with_suspended_context(&realm, self.host_job_context, |i| {
            i.in_resumed(frame.as_deref(), |i| self.resume_active(i, signal))
        });
        self.frame = frame;
        suspend
    }

    fn resume_active(
        &mut self,
        i: &mut Interp,
        mut signal: crate::coroutine::Resume,
    ) -> crate::coroutine::Suspend {
        use crate::coroutine::{Resume, Suspend};
        if self.done {
            return Suspend::Done(Value::Undefined);
        }
        let mut settled_body_return = None;
        if self.awaiting_body_return {
            self.awaiting_body_return = false;
            let settled = std::mem::replace(&mut signal, Resume::Terminate);
            settled_body_return = Some(match settled {
                Resume::Next(value) | Resume::Return(value) => {
                    PendingCompletion::ResumeReturn(value)
                }
                Resume::Throw(error) => PendingCompletion::Throw(error),
                Resume::Terminate => {
                    self.done = true;
                    return Suspend::Done(Value::Undefined);
                }
            });
        }
        // AsyncGeneratorUnwrapYieldResumption: a return completion received at a suspended yield
        // is awaited before either completing the generator or reaching a `yield*` delegate.
        if settled_body_return.is_none() && self.awaiting_return_value {
            self.awaiting_return_value = false;
            signal = match signal {
                Resume::Next(value) => Resume::Return(value),
                Resume::Throw(error) => Resume::Throw(error),
                Resume::Return(value) => Resume::Return(value),
                Resume::Terminate => Resume::Terminate,
            };
        } else if settled_body_return.is_none() && self.is_async_generator && self.started {
            if let Resume::Return(value) = signal {
                self.awaiting_return_value = true;
                return Suspend::Await(value);
            }
        }
        if self.awaiting_yield_value {
            self.awaiting_yield_value = false;
            signal = match signal {
                Resume::Next(value) => return Suspend::Yield(value),
                other => other,
            };
        }
        let mut resume_directly = false;
        let mut disposal_pending = None;
        loop {
            let pending = if let Some(pending) = settled_body_return.take() {
                Some(pending)
            } else if let Some(pending) = disposal_pending.take() {
                Some(pending)
            } else if self.disposal.is_some() {
                let action = self
                    .disposal
                    .as_mut()
                    .expect("checked above")
                    .resume(i, signal.clone());
                match action {
                    DisposeAction::Suspend(value) => return Suspend::Await(value),
                    DisposeAction::Complete(completion) => {
                        self.disposal = None;
                        let pending = pending_dispose_completion(completion);
                        if pending.is_none() {
                            resume_directly = true;
                        }
                        pending
                    }
                    DisposeAction::Terminate => {
                        self.disposal = None;
                        self.done = true;
                        return Suspend::Done(Value::Undefined);
                    }
                }
            } else if self.async_close.is_some() {
                let action = self
                    .async_close
                    .as_mut()
                    .expect("checked above")
                    .resume(i, signal.clone());
                match action {
                    AsyncCloseAction::Suspend(suspend) => return suspend,
                    AsyncCloseAction::Continue => {
                        self.async_close = None;
                        resume_directly = true;
                        None
                    }
                    AsyncCloseAction::Throw(error) => {
                        self.async_close = None;
                        Some(PendingCompletion::Throw(error))
                    }
                    AsyncCloseAction::Terminate => {
                        self.async_close = None;
                        self.done = true;
                        return Suspend::Done(Value::Undefined);
                    }
                }
            } else if resume_directly {
                resume_directly = false;
                None
            } else if let Some(delegate) = self.delegation.as_mut() {
                match delegate.resume(i, signal.clone()) {
                    DelegateAction::Suspend(suspend) => return suspend,
                    DelegateAction::Continue(value) => {
                        self.delegation = None;
                        self.stack.push(value); // result of the YieldExpression
                        None
                    }
                    DelegateAction::Return(value) => {
                        self.delegation = None;
                        if self.handlers.iter().any(|handler| {
                            matches!(
                                &handler.target,
                                HandlerTarget::Finally { .. } | HandlerTarget::Iterator { .. }
                            )
                        }) {
                            Some(PendingCompletion::ResumeReturn(value))
                        } else {
                            self.done = true;
                            return Suspend::Done(value);
                        }
                    }
                    DelegateAction::Throw(error) => {
                        self.delegation = None;
                        Some(PendingCompletion::Throw(error))
                    }
                    DelegateAction::Terminate => {
                        self.delegation = None;
                        self.done = true;
                        return Suspend::Done(Value::Undefined);
                    }
                }
            } else {
                match signal.clone() {
                    Resume::Next(value) => {
                        if self.started {
                            // Settled await value, or the value of an ordinary `yield` expression.
                            self.stack.push(value);
                        }
                        None
                    }
                    // A rejected await or `throw()` resumption enters the VM at the suspension
                    // point, so its saved try-handler stack gets the first chance to catch it.
                    Resume::Throw(error) if self.started => Some(PendingCompletion::Throw(error)),
                    Resume::Throw(error) => {
                        self.done = true;
                        return Suspend::Throw(error);
                    }
                    Resume::Return(value) if self.started => {
                        if self.handlers.iter().any(|handler| {
                            matches!(
                                &handler.target,
                                HandlerTarget::Finally { .. } | HandlerTarget::Iterator { .. }
                            )
                        }) {
                            Some(PendingCompletion::ResumeReturn(value))
                        } else {
                            self.done = true;
                            return Suspend::Done(value);
                        }
                    }
                    Resume::Return(value) => {
                        self.done = true;
                        return Suspend::Done(value);
                    }
                    Resume::Terminate => {
                        self.done = true;
                        return Suspend::Done(Value::Undefined);
                    }
                }
            };
            self.started = true;
            // GeneratorResume/AsyncFunctionStart reinstates the suspended execution context.
            // In particular, PutValue must use this function code's strictness rather than the
            // host job/script that happened to resume it. Ordinary compiled calls establish this
            // in `run_compiled_chunk`; heap continuations must do the same on every VM slice.
            let effective_strict = if self.class_states.iter().any(Option::is_some) {
                true
            } else {
                self.chunk.strict
            };
            let saved_strict = std::mem::replace(&mut i.strict, effective_strict);
            let step = drive_vm(
                i,
                &self.chunk,
                &mut self.env,
                &self.cap_env,
                &mut self.references,
                &self.slots,
                &mut self.stack,
                &mut self.pc,
                &self.this_val,
                &mut self.handlers,
                &mut self.disposal_frames,
                &mut self.class_states,
                pending,
                self.is_async_generator,
                None,
            );
            i.strict = saved_strict;
            match step {
                Ok(VmStep::Await(awaited)) => return Suspend::Await(awaited),
                Ok(VmStep::AsyncClose {
                    iterator,
                    from_sync,
                    swallow_error,
                }) => {
                    let (state, action) =
                        VmAsyncClose::start(i, iterator, from_sync, swallow_error);
                    self.async_close = state;
                    match action {
                        AsyncCloseAction::Suspend(suspend) => return suspend,
                        AsyncCloseAction::Continue => {
                            self.async_close = None;
                            resume_directly = true;
                        }
                        AsyncCloseAction::Throw(error) => {
                            self.async_close = None;
                            signal = Resume::Throw(error);
                        }
                        AsyncCloseAction::Terminate => {
                            self.async_close = None;
                            self.done = true;
                            return Suspend::Done(Value::Undefined);
                        }
                    }
                    continue;
                }
                Ok(VmStep::Dispose { frame, completion }) => {
                    let mut disposal = VmDispose::new(frame, completion);
                    match disposal.advance(i) {
                        DisposeAction::Suspend(value) => {
                            self.disposal = Some(disposal);
                            return Suspend::Await(value);
                        }
                        DisposeAction::Complete(completion) => {
                            let pending = pending_dispose_completion(completion);
                            if pending.is_none() {
                                resume_directly = true;
                            }
                            disposal_pending = pending;
                        }
                        DisposeAction::Terminate => {
                            self.done = true;
                            return Suspend::Done(Value::Undefined);
                        }
                    }
                    continue;
                }
                Ok(VmStep::Yield(value)) if self.is_async_generator => {
                    self.awaiting_yield_value = true;
                    return Suspend::Await(value);
                }
                Ok(VmStep::Yield(value)) if self.is_generator => return Suspend::Yield(value),
                Ok(VmStep::Yield(_)) => {
                    self.done = true;
                    return Suspend::Throw(
                        i.make_error("SyntaxError", "yield outside a generator"),
                    );
                }
                Ok(VmStep::YieldStar(value)) if self.is_generator => {
                    match VmDelegate::open(i, value, self.is_async_generator) {
                        Ok(delegate) => {
                            self.delegation = Some(delegate);
                            // YieldExpression starts its loop with NormalCompletion(undefined).
                            signal = Resume::Next(Value::Undefined);
                        }
                        Err(Abrupt::Throw(error)) => signal = Resume::Throw(error),
                        Err(Abrupt::Return(value)) => signal = Resume::Return(value),
                        Err(Abrupt::Interrupt(_))
                        | Err(Abrupt::Break(_, _))
                        | Err(Abrupt::Continue(_, _)) => signal = Resume::Terminate,
                    }
                    continue;
                }
                Ok(VmStep::YieldStar(_)) => {
                    self.done = true;
                    return Suspend::Throw(
                        i.make_error("SyntaxError", "yield outside a generator"),
                    );
                }
                Ok(VmStep::Done(value)) => {
                    self.done = true;
                    return Suspend::Done(value);
                }
                Ok(VmStep::Return(value)) if self.is_async_generator => {
                    // ReturnStatement : return Expression awaits its operand in an async
                    // generator before producing the return completion (ECMA-262 §14.10.1).
                    self.awaiting_body_return = true;
                    return Suspend::Await(value);
                }
                Ok(VmStep::Return(value)) => {
                    self.done = true;
                    return Suspend::Done(value);
                }
                Ok(VmStep::ResumeReturn(value)) => {
                    self.done = true;
                    return Suspend::Done(value);
                }
                Ok(VmStep::BareReturn) => {
                    self.done = true;
                    return Suspend::Done(Value::Undefined);
                }
                Ok(VmStep::AbruptJump { .. }) => {
                    unreachable!("drive_vm consumes loop completions")
                }
                Ok(VmStep::FragmentExit(..)) => {
                    unreachable!("language coroutines never contain an AST fragment terminal")
                }
                Err(Abrupt::Throw(error)) => {
                    self.done = true;
                    return Suspend::Throw(error);
                }
                // Return/Break/Continue can't escape a function body; treat defensively as completion.
                Err(_) => {
                    self.done = true;
                    return Suspend::Done(Value::Undefined);
                }
            }
        }
    }
}

/// Shared `++`/`--` tail: ToNumeric the old value, write old±1 back through `set`, and return the
/// value to leave on the stack — old / new / nothing per `kind`.
///
/// ECMA-262 §13.4.2-5 requires PutValue to succeed before either a prefix or postfix expression
/// completes. Accordingly the raw GetValue result is observed before potentially abrupt
/// ToNumeric, while the arithmetic `newValue` is published only after `set` succeeds. Postfix
/// returns the coerced old numeric value; an object that coerces to BigInt therefore stays BigInt.
#[inline]
fn step_value(
    i: &mut Interp,
    feedback: &crate::feedback::FeedbackVector,
    pc: usize,
    kind: UpdKind,
    old: Value,
    set: impl FnOnce(&mut Interp, Value) -> Result<(), Abrupt>,
) -> Result<Option<Value>, Abrupt> {
    let profiling = observe_arithmetic_operand(feedback, pc, &old);
    let inc = matches!(
        kind,
        UpdKind::PreInc | UpdKind::PostInc | UpdKind::IncDiscard
    );
    let old_numeric = i.to_numeric(old)?;
    let new_value = match &old_numeric {
        Value::BigInt(old) => {
            let one = crate::bigint::JsBigInt::from_u64(1);
            Value::BigInt(if inc { old.add(&one) } else { old.sub(&one) })
        }
        Value::Num(old) => Value::Num(if inc { old + 1.0 } else { old - 1.0 }),
        _ => unreachable!("ToNumeric returns only Number or BigInt"),
    };
    set(i, new_value.clone())?;
    observe_arithmetic_result(feedback, pc, profiling, &new_value);
    Ok(match kind {
        UpdKind::PreInc | UpdKind::PreDec => Some(new_value),
        UpdKind::PostInc | UpdKind::PostDec => Some(old_numeric),
        UpdKind::IncDiscard | UpdKind::DecDiscard => None,
    })
}

/// [`step_value`] pushing its result onto the VM's operand stack.
fn step_and_store<S: StoredValue>(
    i: &mut Interp,
    stack: &mut ValueStack<S>,
    feedback: &crate::feedback::FeedbackVector,
    pc: usize,
    kind: UpdKind,
    old: Value,
    set: impl FnOnce(&mut Interp, Value) -> Result<(), Abrupt>,
) -> Result<(), Abrupt> {
    if let Some(v) = step_value(i, feedback, pc, kind, old, set)? {
        stack.push(v);
    }
    Ok(())
}

#[inline]
fn get_named_property(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    base: &Value,
    name: &str,
    cache: &std::cell::Cell<IcState>,
) -> Result<Value, Abrupt> {
    if !chunk.feedback.detailed_enabled() {
        // A String primitive's `length` is its own fixed data property (ECMA-262 §10.4.3.5).
        if let (Value::Str(s), "length") = (base, name) {
            return Ok(Value::Num(i.str_len(s) as f64));
        }
        return i.get_prop_ic(base, name, cache);
    }
    let mut trace = crate::feedback::CurrentPropertyTrace::default();
    let result = i.get_prop_ic_profiled(base, name, cache, &mut trace);
    chunk
        .feedback
        .observe_current_property(pc, &chunk.feedback_shapes, trace);
    result
}

#[inline]
unsafe fn get_named_property_packed(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    base: *const PackedValue,
    name: &str,
    cache: &std::cell::Cell<IcState>,
) -> Result<PackedValue, Abrupt> {
    if !chunk.feedback.detailed_enabled() {
        return unsafe { i.get_prop_ic_packed(base, name, cache) };
    }
    let receiver = unsafe { &*base }.unpack();
    get_named_property(i, chunk, pc, &receiver, name, cache).map(PackedValue::pack)
}

#[inline]
fn set_named_property(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    base: &Value,
    name: &Rc<str>,
    value: Value,
    cache: &std::cell::Cell<IcState>,
) -> Result<(), Abrupt> {
    if !chunk.feedback.detailed_enabled() {
        return i.set_prop_ic(base, name, value, cache);
    }
    let mut trace = crate::feedback::CurrentPropertyTrace::default();
    let result = i.set_prop_ic_profiled(base, name, value, cache, &mut trace);
    chunk
        .feedback
        .observe_current_property(pc, &chunk.feedback_shapes, trace);
    result
}

#[inline]
fn observe_element_trace(
    i: &Interp,
    chunk: &Chunk,
    pc: usize,
    base: &Value,
    key: &str,
    trace: crate::feedback::CurrentPropertyTrace,
) {
    let Some(property_outcome) = trace.outcome else {
        return;
    };
    let receiver = i.element_receiver_kind(base);
    let key_kind = i.element_key_kind(key);
    let outcome = match property_outcome {
        crate::feedback::PropertyOutcome::Data => {
            if trace.depth == 0 {
                crate::feedback::ElementOutcome::OwnData
            } else {
                crate::feedback::ElementOutcome::Prototype
            }
        }
        crate::feedback::PropertyOutcome::Absent => {
            if receiver == crate::feedback::ElementReceiverKind::Array
                && key_kind == crate::feedback::ElementKeyKind::Index
            {
                crate::feedback::ElementOutcome::Hole
            } else {
                crate::feedback::ElementOutcome::Absent
            }
        }
        crate::feedback::PropertyOutcome::Created => crate::feedback::ElementOutcome::Created,
        crate::feedback::PropertyOutcome::Accessor => crate::feedback::ElementOutcome::Accessor,
        crate::feedback::PropertyOutcome::Exotic => crate::feedback::ElementOutcome::Exotic,
        crate::feedback::PropertyOutcome::Rejected => crate::feedback::ElementOutcome::Rejected,
    };
    chunk
        .feedback
        .observe_element(pc, receiver, key_kind, outcome);
}

/// Profile a computed element read after the normal nullish check and `ToPropertyKey` conversion.
/// Diagnostic mode deliberately bypasses dense/temporary IC shortcuts so the one canonical
/// `[[Get]]` operation supplies the semantic outcome without replaying observable work.
#[inline]
fn get_element_profiled(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    base: &Value,
    raw_key: &Value,
) -> Result<Value, Abrupt> {
    if matches!(base, Value::Undefined | Value::Null) {
        crate::value::trace_nullish_property("bytecode-profiled-get-elem", raw_key);
        return Err(i.throw("TypeError", "cannot read property of null or undefined"));
    }
    let key = i.to_property_key(raw_key)?;
    let mut trace = crate::feedback::CurrentPropertyTrace::default();
    let result = i.get_member_profiled(base, key.as_str(), &mut trace);
    observe_element_trace(i, chunk, pc, base, key.as_str(), trace);
    result
}

/// Profile a computed element write after `ToPropertyKey`, retaining the original value/result
/// handling in the caller. The underlying [[Set]] operation is still executed exactly once.
#[inline]
fn set_element_profiled(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    base: &Value,
    raw_key: &Value,
    value: Value,
) -> Result<(), Abrupt> {
    // PutValue performs ToObject before ToPropertyKey (ECMA-262 e28783d5,
    // sec-putvalue). Profiling must preserve the same observable ordering.
    if matches!(base, Value::Undefined | Value::Null) {
        return Err(i.throw("TypeError", "cannot set property of null or undefined"));
    }
    let key = i.to_property_key(raw_key)?;
    let mut trace = crate::feedback::CurrentPropertyTrace::default();
    let result = i.set_member_profiled(base, key.as_str(), value, &mut trace);
    observe_element_trace(i, chunk, pc, base, key.as_str(), trace);
    result
}

#[inline]
fn call_arity_kind(len: usize) -> crate::feedback::CallArityKind {
    match len {
        0 => crate::feedback::CallArityKind::Zero,
        1 => crate::feedback::CallArityKind::One,
        2..=4 => crate::feedback::CallArityKind::Few,
        _ => crate::feedback::CallArityKind::Many,
    }
}

/// Profile one completed `Call` operation. Target metadata is captured before dispatch, and the
/// return value class is published only after [[Call]] succeeds, matching EvaluateCall's ordering.
#[inline]
fn call_profiled(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    callee: Value,
    this: Value,
    args: &[Value],
) -> Result<Value, Abrupt> {
    let target = i.call_target_kind(&callee);
    let environment = i.call_environment_kind(&callee);
    chunk
        .feedback
        .observe_call(pc, target, call_arity_kind(args.len()), environment);
    let result = i.call(callee, this, args);
    if let Ok(value) = &result {
        if let Some(class) = arithmetic_value_class(value) {
            chunk
                .feedback
                .observe_value_class(pc, crate::feedback::ObservationRole::Result, class);
        }
    }
    result
}

/// Profile one completed `Construct` operation. The construct result is necessarily an object on
/// success, but it still flows through the normal ValueClass result slot for a uniform call ABI.
#[inline]
fn construct_profiled(
    i: &mut Interp,
    chunk: &Chunk,
    pc: usize,
    callee: Value,
    args: &[Value],
) -> Result<Value, Abrupt> {
    let target = i.call_target_kind(&callee);
    let environment = i.call_environment_kind(&callee);
    chunk
        .feedback
        .observe_call(pc, target, call_arity_kind(args.len()), environment);
    let result = i.construct(callee, args);
    if let Ok(value) = &result {
        if let Some(class) = arithmetic_value_class(value) {
            chunk
                .feedback
                .observe_value_class(pc, crate::feedback::ObservationRole::Result, class);
        }
    }
    result
}

#[inline]
fn bin_num<S: StoredValue>(
    i: &mut Interp,
    stack: &mut ValueStack<S>,
    feedback: &crate::feedback::FeedbackVector,
    pc: usize,
    op: &'static str,
    f: impl Fn(f64, f64) -> f64,
) -> Result<(), Abrupt> {
    let b = stack.pop().expect("vm stack underflow");
    let a = stack.pop().expect("vm stack underflow");
    let profiling = observe_arithmetic_operands(feedback, pc, &a, &b);
    let v = match i
        .tagged_arithmetic
        .then(|| try_tagged_numeric_binary(&a, &b, &f))
        .flatten()
    {
        Some(value) => value,
        None => match (&a, &b) {
            (Value::Num(x), Value::Num(y)) => Value::Num(f(*x, *y)),
            _ => i.binary(op, a, b)?,
        },
    };
    observe_arithmetic_result(feedback, pc, profiling, &v);
    stack.push(v);
    Ok(())
}

/// Retire only the local owner that the immediately following StoreLocal will overwrite.
/// ECMA-262 assignment evaluation still reads the left value before the RHS, and conversion
/// hooks must still see the binding: callers restrict this to already-primitive strings after
/// the length guard. No JS, coercion, safepoint or recoverable error may occur before the store.
#[inline]
fn release_overwritten_string_local(slot: &mut Value, left: &crate::lstr::LStr) {
    if matches!(slot, Value::Str(current) if crate::lstr::LStr::ptr_eq(current, left)) {
        *slot = Value::Undefined;
    }
}

/// Attempt the immediate-only tagged ABI path. Returning `None` is a deliberate deoptimization:
/// heap values, strings, BigInts, symbols, objects, and the internal Empty marker all continue
/// through the complete interpreter helper, preserving ToPrimitive/ToNumeric ordering and
/// abrupt completion behavior mandated by ECMA-262 §13.15 (Additive Operators).
#[inline(always)]
fn try_tagged_numeric_binary<F>(left: &Value, right: &Value, f: &F) -> Option<Value>
where
    F: Fn(f64, f64) -> f64,
{
    let (Value::Num(left), Value::Num(right)) = (left, right) else {
        return None;
    };
    let frame = crate::tagged::TaggedNumericFrame::new(*left, *right);
    let result = frame.binary(f);
    Some(Value::Num(
        result
            .as_number()
            .expect("tagged numeric result remains a Number"),
    ))
}

/// Attempt the immediate-only tagged ABI path for relational and equality operators. Returning
/// `None` is the same deliberate deoptimization as the arithmetic slice: heap values, strings,
/// BigInts, symbols, and objects all continue through the complete interpreter helper, preserving
/// the abstract-relation/equality ordering and coercion mandated by ECMA-262 §13.11 (Relational
/// Operators) and §13.12 (Equality Operators). Both operands must already be primitive Numbers,
/// where the f64 predicate is exactly the specified comparison (including `-0 == +0` and every
/// NaN case reducing to `false`).
#[inline(always)]
fn try_tagged_numeric_cmp<F>(left: &Value, right: &Value, f: &F) -> Option<Value>
where
    F: Fn(f64, f64) -> bool,
{
    let (Value::Num(left), Value::Num(right)) = (left, right) else {
        return None;
    };
    let frame = crate::tagged::TaggedNumericFrame::new(*left, *right);
    let result = frame.cmp(f);
    Some(Value::Bool(
        result
            .as_boolean()
            .expect("tagged comparison result remains a Boolean"),
    ))
}

/// Attempt the immediate-only tagged ABI path for bitwise and shift operators. Returning `None`
/// keeps the complete `Interp::binary` helper: heap values, strings, BigInts, symbols, and objects
/// preserve ToNumeric ordering and the BigInt mixing check of ECMA-262 §13.7–13.8. Number operands
/// run ToInt32 (§7.1.5) inside the frame on the exact extracted bits, identical to `bin_i32`.
#[inline(always)]
fn try_tagged_numeric_i32<F>(left: &Value, right: &Value, f: &F) -> Option<Value>
where
    F: Fn(i32, i32) -> i32,
{
    let (Value::Num(left), Value::Num(right)) = (left, right) else {
        return None;
    };
    let frame = crate::tagged::TaggedNumericFrame::new(*left, *right);
    let result = frame.bitwise(f);
    Some(Value::Num(
        result
            .as_number()
            .expect("tagged bitwise result remains a Number"),
    ))
}

/// Attempt the immediate-only tagged ABI path for unary numeric operators. Returning `None` keeps
/// the complete `eval_unary_vm` helper with its ToNumber/ToNumeric ordering and abrupt completions
/// (ECMA-262 §13.5.5–6, §13.5.9). The closure is the same f64 transform the canonical fast path
/// runs, so signed-zero negation, `+` identity, and ToInt32-based bitwise NOT match exactly.
#[inline(always)]
fn try_tagged_numeric_unary<F>(value: &Value, f: F) -> Option<Value>
where
    F: FnOnce(f64) -> f64,
{
    let Value::Num(n) = value else {
        return None;
    };
    let frame = crate::tagged::TaggedNumberFrame::new(*n);
    let result = frame.unary(f);
    Some(Value::Num(
        result
            .as_number()
            .expect("tagged unary result remains a Number"),
    ))
}

/// Attempt the immediate-only tagged ABI path for exponentiation, mirroring the canonical
/// `Interp::binary` fast path's Number::exponentiate guard exactly (NaN exponent, and |base| = 1
/// with an infinite exponent, are NaN even though raw `powf` would round them to 1.0). Returning
/// `None` keeps the complete helper with BigInt mixing and ToNumeric ordering (ECMA-262 §13.9).
#[inline(always)]
fn try_tagged_numeric_pow(left: &Value, right: &Value) -> Option<Value> {
    let (Value::Num(left), Value::Num(right)) = (left, right) else {
        return None;
    };
    let frame = crate::tagged::TaggedNumericFrame::new(*left, *right);
    let result = frame.pow();
    Some(Value::Num(
        result
            .as_number()
            .expect("tagged exponentiation result remains a Number"),
    ))
}

#[inline]
fn bin_i32<S: StoredValue>(
    i: &mut Interp,
    stack: &mut ValueStack<S>,
    feedback: &crate::feedback::FeedbackVector,
    pc: usize,
    op: &'static str,
    f: impl Fn(i32, i32) -> i32,
) -> Result<(), Abrupt> {
    let b = stack.pop().expect("vm stack underflow");
    let a = stack.pop().expect("vm stack underflow");
    let profiling = observe_arithmetic_operands(feedback, pc, &a, &b);
    let v = match i
        .tagged_arithmetic
        .then(|| try_tagged_numeric_i32(&a, &b, &f))
        .flatten()
    {
        Some(value) => value,
        None => {
            if let (Value::Num(x), Value::Num(y)) = (&a, &b) {
                Value::Num(f(crate::eval::to_int32(*x), crate::eval::to_int32(*y)) as f64)
            } else {
                i.binary(op, a, b)?
            }
        }
    };
    observe_arithmetic_result(feedback, pc, profiling, &v);
    stack.push(v);
    Ok(())
}

#[inline]
fn bin_cmp<S: StoredValue>(
    i: &mut Interp,
    stack: &mut ValueStack<S>,
    op: &'static str,
    f: impl Fn(f64, f64) -> bool,
) -> Result<(), Abrupt> {
    let b = stack.pop().expect("vm stack underflow");
    let a = stack.pop().expect("vm stack underflow");
    if let Some(v) = i
        .tagged_arithmetic
        .then(|| try_tagged_numeric_cmp(&a, &b, &f))
        .flatten()
    {
        stack.push(v);
        return Ok(());
    }
    if let (Value::Num(x), Value::Num(y)) = (&a, &b) {
        stack.push(Value::Bool(f(*x, *y)));
        return Ok(());
    }
    let v = i.binary(op, a, b)?;
    stack.push(v);
    Ok(())
}

// ---------------------------------------------------------------------------------------------
// JIT support: Chunk accessors and the runtime helpers the machine-code templates call.
// The generic executor `jit_exec` runs exactly ONE op against a raw operand-stack pointer; the
// templates bake the op index in as an immediate and keep the stack top in a register. Control
// flow never reaches here — jumps, returns and try bookkeeping are real branches in the JIT.
// ---------------------------------------------------------------------------------------------

impl Chunk {
    pub(crate) fn jit_ops(&self) -> &[Op] {
        &self.ops
    }
    /// A borrowed sloppy ordinary activation may expose slot-backed formals through its
    /// parked legacy arguments map. Fresh compiled entries keep their established contract.
    pub(crate) fn jit_borrowed_parameter_aliases(&self) -> bool {
        self.borrowed_parameter_aliases
    }
    pub(crate) fn jit_detailed_feedback_enabled(&self) -> bool {
        self.feedback.detailed_enabled()
    }
    /// Leading slot names, for debug identification of a chunk (`TRUST_JS_JIT_DUMP`).
    pub(crate) fn jit_slot_names(&self) -> &[Rc<str>] {
        &self.slot_names
    }
    /// Source start offset and length of the function this chunk was compiled from.
    pub(crate) fn jit_debug_origin(&self) -> (u32, u32) {
        self.debug_origin
    }
    /// Guard data for a speculative-inline site (`Op::InlineGuard`'s first operand).
    pub(crate) fn jit_inline_target(&self, t: u32) -> &InlineTarget {
        &self.inline_targets[t as usize]
    }

    /// O(1) invocation selection; this never changes an active frame or its canonical PCs.
    pub(crate) fn inline_realm_compatible(&self, genv: usize) -> bool {
        self.inline_planning_genv == 0 || self.inline_planning_genv == genv
    }

    /// The [[Environment]] of an inline target's pinned function. `LoadNameIn` sites are
    /// dominated by that target's identity guard, so the function (and therefore this
    /// environment) is alive whenever they run; `None` only for a dead pin.
    pub(crate) fn inline_target_env(&self, t: u32) -> Option<Env> {
        let object = self.inline_targets[t as usize].pin.upgrade()?;
        let object = object.borrow();
        match &object.call {
            crate::value::Callable::User(user) => Some(user.env.clone()),
            _ => None,
        }
    }

    /// `LoadNameIn`/`LoadNameForCallIn`: ResolveBinding from the inline target's environment.
    fn load_name_in(
        &self,
        i: &mut Interp,
        n: u32,
        c: u32,
        t: u32,
        for_call: bool,
    ) -> Result<(Value, Value), Abrupt> {
        let env = self
            .inline_target_env(t)
            .expect("an inline name read runs only after its target's identity guard");
        if !for_call {
            return Ok((Value::Undefined, self.load_name_ic(i, &env, n, c)?));
        }
        // As for LoadNameForCall: a cache hit/fill never resolves through a `with` object.
        if let Some(v) = self
            .name_ic_hit(i, &env, c)
            .or_else(|| self.name_ic_fill(i, &env, n, c))
        {
            return Ok((Value::Undefined, v));
        }
        let (callee, with_this) = i.get_var_with(&self.names[n as usize], &env)?;
        Ok((with_this.unwrap_or(Value::Undefined), callee))
    }

    /// The interned name a property op refers to (the emitter gates array-receiver inlining on
    /// whether it could be an element key).
    pub(crate) fn jit_name(&self, n: u32) -> &str {
        &self.names[n as usize]
    }
    /// The stable address of inline-cache site `idx`'s `Cell<IcState>`. The `caches` `Vec` is
    /// fixed once compilation finishes (never reallocated), and the `Chunk` outlives its own JIT
    /// code, so the JIT bakes this address as an immediate to read the live cache from machine
    /// code. `None` if the emitter cannot use it (the address must be reachable — always is here).
    pub(crate) fn jit_cache_ptr(&self, idx: u32) -> usize {
        self.caches.as_ptr() as usize
            + idx as usize * std::mem::size_of::<std::cell::Cell<IcState>>()
    }
    /// The hottest property-cache way observed during bytecode warmup. A compact JIT site may
    /// bake this state behind full shape/prototype guards and route misses to the checked helper.
    pub(crate) fn jit_cache_preferred(&self, idx: u32) -> Option<IcState> {
        let st = self.caches[idx as usize].get();
        // A compact template bakes one shape. It is a win only for a truly monomorphic site;
        // choosing way 0 at a polymorphic virtual-method call makes every other stable way fall
        // through to Rust. Seeded second-stage chunks preserve all hot ways, so keep their full
        // native probe whenever warmup observed more than one receiver shape.
        let mono =
            (1..PROP_IC_WAYS).all(|way| self.caches[idx as usize + way].get().depth == IC_EMPTY);
        (st.has_cacheable_shapes() && mono).then_some(st)
    }
    /// The stable address of call site `idx`'s way-1 `Cell<CallIc>` (same contract as
    /// [`Chunk::jit_cache_ptr`]: `call_caches` is fixed once compilation finishes and the Chunk
    /// outlives its JIT code).
    pub(crate) fn jit_call_cache_ptr(&self, idx: u32) -> usize {
        self.call_caches[idx as usize].entries.as_ptr() as usize
    }
    #[cfg(test)]
    pub(crate) fn cached_call_for(&self, callee: usize) -> Option<CallIc> {
        self.call_caches
            .iter()
            .flat_map(|site| site.entries.iter())
            .map(std::cell::Cell::get)
            .find(|entry| entry.callee == callee)
    }
    #[cfg(test)]
    pub(crate) fn cached_construct_for(&self, callee: usize) -> bool {
        self.ops.iter().any(|op| match op {
            Op::New(_, site) => self.construct_cache(*site).call.callee == callee,
            _ => false,
        })
    }
    /// The stable address of name-cache site `idx`'s `Cell<NameIc>` (same contract as
    /// [`Chunk::jit_cache_ptr`]).
    pub(crate) fn jit_name_cache_ptr(&self, idx: u32) -> usize {
        self.name_caches.as_ptr() as usize
            + idx as usize * std::mem::size_of::<std::cell::Cell<NameIc>>()
    }
    /// Stable address of the captured-binding cache for interned name `idx`.
    pub(crate) fn jit_cap_cache_ptr(&self, idx: u32) -> usize {
        self.cap_caches.as_ptr() as usize
            + idx as usize * std::mem::size_of::<std::cell::Cell<NameIc>>()
    }
    /// Numeric value observed at this name site before second-stage compilation. Generated code
    /// compares the live binding/property bits before taking the specialized decode path.
    pub(crate) fn jit_name_number(&self, idx: u32) -> Option<u64> {
        self.name_num_valid[idx as usize]
            .get()
            .then(|| self.name_num_bits[idx as usize].get())
    }
    /// Name-cache hit check (see [`NameIc`] for the validation story): a pointer compare, a
    /// generation compare, and a value clone. `None` = miss (including TDZ — the slow path
    /// throws the proper error).
    #[inline]
    fn name_ic_hit(&self, i: &Interp, env: &Env, c: u32) -> Option<Value> {
        let ic = self.name_caches[c as usize].get();
        if ic.env == FIXED_NAME_IC {
            let scope = env.borrow();
            if scope.with_obj.is_some() || ic.gen == 0 || scope.vars.layout_id() != ic.gen {
                return None;
            }
            let binding = scope.vars.fixed_binding_at(ic.binding as usize)?;
            return (binding.initialized && binding.import_ref.is_none())
                .then(|| binding.value.clone());
        }
        if ic.env == lexical_cache::DEEP_NAME_IC {
            return self.deep_name_ic_hit(i, env, c);
        }
        let raw = Env::as_ptr(env) as usize;
        if ic.env == raw {
            let b = env.borrow();
            if !b.vars.matches_generation(ic.gen) {
                return None;
            }
            // The unchanged generation proves the map is structurally untouched since the fill:
            // the pointer is live and the resolution unchanged (see NameIc). The value and TDZ
            // flag are read live — in-place writes flow through.
            let bd = unsafe { &*(ic.binding as usize as *const crate::interpreter::Binding) };
            return if bd.initialized && bd.import_ref.is_none() {
                Some(bd.value.clone())
            } else {
                None
            };
        }
        if ic.env == raw | 1 {
            // Global-object mode (see NameIc): scope still empty of this name (generation),
            // global layout unchanged (shape) → the cached slot is still the resolution.
            if !env.borrow().vars.matches_generation(ic.gen) {
                return None;
            }
            let g = i.global.borrow();
            if !matches!(g.exotic, crate::value::Exotic::None)
                || g.props.shape() != (ic.binding >> 32) as u32
            {
                return None;
            }
            let p = g.props.property_at(ic.binding as u32 as usize)?;
            if p.accessor() {
                return None;
            }
            return Some(p.value());
        }
        if ic.env & 2 != 0 {
            // Depth-1 mode: the current scope's key-set proof establishes absence
            // here. The live parent identity and generation still prove the
            // binding pointer's lifetime and resolution; values and TDZ are live.
            let b = env.borrow();
            if !ic.matches_activation(&b.vars) {
                return None;
            }
            let p = b.parent.as_ref()?;
            if Env::as_ptr(p) as usize != ic.env & !7 {
                return None;
            }
            let pb = p.borrow();
            if !pb.vars.matches_generation(ic.gen) {
                return None;
            }
            let bd = unsafe { &*(ic.binding as usize as *const crate::interpreter::Binding) };
            return if bd.initialized && bd.import_ref.is_none() {
                Some(bd.value.clone())
            } else {
                None
            };
        }
        None
    }
    /// Depth-0 cache fill: the name resolves directly in `env` as a plain initialized binding —
    /// no `with` object on the scope, no live import redirect. When `env` *is* the global scope
    /// and misses, an own data property of the ordinary global object fills the global mode
    /// instead. Returns the value on success; `None` = not cacheable at this site (the caller
    /// runs the interpreter's full walk, uncached).
    fn name_ic_fill(&self, i: &Interp, env: &Env, n: u32, c: u32) -> Option<Value> {
        {
            let b = env.borrow();
            if b.with_obj.is_some() || b.vars.generation() == u32::MAX {
                return None;
            }
            if let Some(bd) = b.vars.get(&self.names[n as usize]) {
                if !bd.initialized || bd.import_ref.is_some() {
                    return None;
                }
                let v = bd.value.clone();
                self.record_name_number(c as usize, &v);
                let previous = self.name_caches[c as usize].get();
                let layout_id = b.vars.layout_id();
                // Preserve the shorter identity path for a monomorphic environment.
                // A second instance with the same layout establishes useful sharing.
                if layout_name_ics_enabled()
                    && layout_id != 0
                    && previous.env > FIXED_NAME_IC
                    && previous.env & 7 == 0
                    && previous.env != Env::as_ptr(env) as usize
                    && previous.act_gen == layout_id
                {
                    if let Some(slot) = b.vars.binding_slot(&self.names[n as usize]) {
                        self.name_caches[c as usize].set(NameIc {
                            env: FIXED_NAME_IC,
                            binding: slot as u64,
                            gen: layout_id,
                            act_gen: 0,
                        });
                        drop(b);
                        self.name_pins.borrow_mut()[c as usize] = None;
                        return Some(v);
                    }
                }
                self.name_caches[c as usize].set(NameIc {
                    env: Env::as_ptr(env) as usize,
                    binding: bd as *const _ as usize as u64,
                    gen: b.vars.generation(),
                    act_gen: layout_id,
                });
                drop(b);
                // Pin the scope allocation so the raw `env` compare stays ABA-safe.
                self.name_pins.borrow_mut()[c as usize] = Some(Env::downgrade(env));
                return Some(v);
            }
            // A published binding-layout identity proves the same key set even
            // when this chunk runs directly in a different creator's fresh
            // activation. Generation alone cannot prove that: two unrelated
            // scopes can have equal generations but different binding names.
            // The older own-activation mode remains valid without a layout ID.
            let layout_id = b.vars.layout_id();
            if layout_id != 0 || self.makes_env() {
                if let Some(p) = &b.parent {
                    let pb = p.borrow();
                    if pb.with_obj.is_none()
                        && pb.vars.layout_id() == 0
                        && pb.vars.generation() != u32::MAX
                    {
                        if let Some(bd) = pb.vars.get(&self.names[n as usize]) {
                            if bd.initialized && bd.import_ref.is_none() {
                                let v = bd.value.clone();
                                self.record_name_number(c as usize, &v);
                                self.name_caches[c as usize].set(NameIc {
                                    env: Env::as_ptr(p) as usize
                                        | if layout_id != 0 { 6 } else { 2 },
                                    binding: bd as *const _ as usize as u64,
                                    gen: pb.vars.generation(),
                                    act_gen: if layout_id != 0 {
                                        layout_id
                                    } else {
                                        b.vars.generation()
                                    },
                                });
                                let pin = Env::downgrade(p);
                                drop(pb);
                                drop(b);
                                // Pin the PARENT: that's the raw pointer the hit compares.
                                self.name_pins.borrow_mut()[c as usize] = Some(pin);
                                return Some(v);
                            }
                        }
                    }
                }
            }
        }
        // Global mode: only when there are no intermediate scopes whose later mutation could
        // re-route the name — i.e. the chunk runs directly under the global scope.
        if !Env::ptr_eq(env, &i.global_env)
            || !i.ordinary_get_ptr(crate::value::Gc::as_ptr(&i.global) as usize)
        {
            return self.deep_name_ic_fill(i, env, n, c);
        }
        let g = i.global.borrow();
        if !matches!(g.exotic, crate::value::Exotic::None)
            || !crate::value::is_cacheable_shape(g.props.shape())
        {
            return None;
        }
        let slot = g.props.slot_of(&self.names[n as usize])?;
        let p = g.props.property_at(slot)?;
        if p.accessor() {
            return None;
        }
        let v = p.value();
        self.record_name_number(c as usize, &v);
        self.name_caches[c as usize].set(NameIc {
            env: Env::as_ptr(env) as usize | 1,
            binding: ((g.props.shape() as u64) << 32) | slot as u64,
            gen: env.borrow().vars.generation(),
            act_gen: 0,
        });
        drop(g);
        self.name_pins.borrow_mut()[c as usize] = Some(Env::downgrade(env));
        Some(v)
    }
    /// Cached free-name read: hit, else depth-0 refill, else the interpreter's full walk
    /// (deeper resolutions, `with`, module imports, TDZ, globals — uncached every time).
    pub(crate) fn load_name_ic(
        &self,
        i: &mut Interp,
        env: &Env,
        n: u32,
        c: u32,
    ) -> Result<Value, Abrupt> {
        if let Some(v) = self.name_ic_hit(i, env, c) {
            return Ok(v);
        }
        if let Some(v) = self.name_ic_fill(i, env, n, c) {
            return Ok(v);
        }
        crate::workload_metrics::uncached_name(env, &self.names[n as usize]);
        i.get_var(&self.names[n as usize], env)
    }

    /// Resolve a captured binding in the current activation and cache its stable map-entry
    /// address. Structural `VarMap` mutations bump `generation`; the weak scope pin prevents an
    /// activation allocation from being recycled while its raw pointer remains cached.
    fn cap_binding_ptr(&self, env: &Env, n: u32) -> *mut crate::interpreter::Binding {
        let index = n as usize;
        let raw = Env::as_ptr(env) as usize;
        let ic = self.cap_caches[index].get();
        {
            let b = env.borrow();
            if ic.env == FIXED_NAME_IC
                && ic.gen != 0
                && b.with_obj.is_none()
                && b.vars.layout_id() == ic.gen
            {
                if let Some(binding) = b.vars.fixed_binding_at(ic.binding as usize) {
                    return binding as *const _ as *mut crate::interpreter::Binding;
                }
            }
            if ic.env == raw && b.vars.matches_generation(ic.gen) {
                return ic.binding as usize as *mut crate::interpreter::Binding;
            }
        }
        let name = &self.names[index];
        let (binding, generation, layout_id, slot) = {
            let mut b = env.borrow_mut();
            let generation = b.vars.generation();
            let layout_id = b.vars.layout_id();
            let slot = (layout_name_ics_enabled()
                && layout_id != 0
                && ic.env > FIXED_NAME_IC
                && ic.env & 7 == 0
                && ic.env != raw
                && ic.act_gen == layout_id)
                .then(|| b.vars.binding_slot(name))
                .flatten();
            let binding = b.vars.get_mut(name).expect("captured binding missing")
                as *mut crate::interpreter::Binding;
            (binding, generation, layout_id, slot)
        };
        if let Some(slot) = slot {
            self.cap_caches[index].set(NameIc {
                env: FIXED_NAME_IC,
                binding: slot as u64,
                gen: layout_id,
                act_gen: 0,
            });
            self.cap_pins.borrow_mut()[index] = None;
        } else if generation != u32::MAX {
            self.cap_caches[index].set(NameIc {
                env: raw,
                binding: binding as usize as u64,
                gen: generation,
                act_gen: layout_id,
            });
            self.cap_pins.borrow_mut()[index] = Some(Env::downgrade(env));
        } else {
            self.cap_caches[index].set(NameIc::EMPTY);
            self.cap_pins.borrow_mut()[index] = None;
        }
        binding
    }

    pub(crate) fn load_cap_ic(&self, i: &mut Interp, env: &Env, n: u32) -> Result<Value, Abrupt> {
        let binding = unsafe { &*self.cap_binding_ptr(env, n) };
        if !binding.initialized {
            return Err(i.throw(
                "ReferenceError",
                format!(
                    "cannot access '{}' before initialization",
                    self.names[n as usize]
                ),
            ));
        }
        Ok(binding.value.clone())
    }

    pub(crate) fn store_cap_ic(
        &self,
        i: &mut Interp,
        env: &Env,
        n: u32,
        value: Value,
        initialize: bool,
    ) -> Result<(), Abrupt> {
        let binding = unsafe { &mut *self.cap_binding_ptr(env, n) };
        if !initialize && !binding.initialized {
            return Err(i.throw(
                "ReferenceError",
                format!(
                    "cannot access '{}' before initialization",
                    self.names[n as usize]
                ),
            ));
        }
        binding.value = value;
        if initialize {
            binding.initialized = true;
        }
        Ok(())
    }

    /// The captured-cell equivalent of the adjacent Add/StoreLocal ownership handoff.
    /// Only initialized mutable declarative cells qualify; name resolution, globals, imports,
    /// TDZ and immutable stores retain their ordinary paths (ECMA-262 SetMutableBinding).
    fn release_overwritten_captured_string(&self, env: &Env, n: u32, left: &crate::lstr::LStr) {
        let binding = unsafe { &mut *self.cap_binding_ptr(env, n) };
        if binding.initialized && binding.mutable && binding.import_ref.is_none() {
            release_overwritten_string_local(&mut binding.value, left);
        }
    }

    /// Reject PutValue to a compiler-proven immutable captured binding without cloning its old
    /// value. DeclarativeEnvironmentRecord.SetMutableBinding checks initialization before
    /// immutability (ECMA-262 §9.1.1.1.5), so a store into a TDZ remains a ReferenceError.
    fn reject_const_cap_store(&self, i: &mut Interp, env: &Env, n: u32) -> Result<(), Abrupt> {
        let binding = unsafe { &*self.cap_binding_ptr(env, n) };
        if !binding.initialized {
            return Err(i.throw(
                "ReferenceError",
                format!(
                    "cannot access '{}' before initialization",
                    self.names[n as usize]
                ),
            ));
        }
        Err(i.throw(
            "TypeError",
            format!(
                "assignment to constant variable '{}'",
                self.names[n as usize]
            ),
        ))
    }

    /// Cached free-name write. A cache hit validates the same resolution proof as a read and
    /// updates a live mutable binding/plain writable global property in place. Misses perform the
    /// full PutValue operation, then side-effect-freely seed a cache when the resulting resolution
    /// is cacheable.
    fn store_name_ic(
        &self,
        i: &mut Interp,
        env: &Env,
        n: u32,
        c: u32,
        value: Value,
    ) -> Result<(), Abrupt> {
        let ic = self.name_caches[c as usize].get();
        if ic.env == FIXED_NAME_IC {
            {
                let mut scope = env.borrow_mut();
                if scope.with_obj.is_none() && ic.gen != 0 && scope.vars.layout_id() == ic.gen {
                    if let Some(binding) = scope.vars.fixed_binding_at_mut(ic.binding as usize) {
                        if binding.initialized && binding.mutable && binding.import_ref.is_none() {
                            binding.value = value;
                            return Ok(());
                        }
                    }
                }
            }
            i.assign_free_name(&self.names[n as usize], value, env)?;
            let _ = self.name_ic_fill(i, env, n, c);
            return Ok(());
        }
        if ic.env == lexical_cache::DEEP_NAME_IC {
            let mut pending = Some(value);
            if self.deep_name_ic_store(i, env, c, &mut pending) {
                return Ok(());
            }
            i.assign_free_name(&self.names[n as usize], pending.unwrap(), env)?;
            let _ = self.name_ic_fill(i, env, n, c);
            return Ok(());
        }
        let raw = Env::as_ptr(env) as usize;
        let value = if ic.env == raw {
            let b = env.borrow_mut();
            if b.vars.matches_generation(ic.gen) {
                let bd = unsafe { &mut *(ic.binding as usize as *mut crate::interpreter::Binding) };
                if bd.initialized && bd.mutable && bd.import_ref.is_none() {
                    bd.value = value;
                    return Ok(());
                }
            }
            value
        } else if ic.env == raw | 1 {
            if env.borrow().vars.matches_generation(ic.gen) {
                let mut g = i.global.borrow_mut();
                if matches!(g.exotic, crate::value::Exotic::None)
                    && g.props.shape() == (ic.binding >> 32) as u32
                {
                    if let Some((_, p)) = g.props.entry_at(ic.binding as u32 as usize) {
                        if !p.accessor() && p.writable() {
                            g.props.set_value_at(ic.binding as u32 as usize, value);
                            return Ok(());
                        }
                    }
                }
            }
            value
        } else if ic.env & 2 != 0 {
            let parent = {
                let b = env.borrow();
                ic.matches_activation(&b.vars)
                    .then(|| b.parent.clone())
                    .flatten()
            };
            if let Some(parent) = parent {
                if Env::as_ptr(&parent) as usize == ic.env & !7 {
                    let pb = parent.borrow_mut();
                    if pb.vars.matches_generation(ic.gen) {
                        let bd = unsafe {
                            &mut *(ic.binding as usize as *mut crate::interpreter::Binding)
                        };
                        if bd.initialized && bd.mutable && bd.import_ref.is_none() {
                            bd.value = value;
                            return Ok(());
                        }
                    }
                }
            }
            value
        } else {
            value
        };
        i.assign_free_name(&self.names[n as usize], value, env)?;
        let _ = self.name_ic_fill(i, env, n, c);
        Ok(())
    }
    pub(crate) fn jit_frame(&self) -> (usize, usize) {
        (self.n_params, self.n_slots)
    }
    pub(crate) fn jit_arguments_slot(&self) -> Option<u16> {
        self.arguments_slot
    }

    /// The initial value of `arguments_slot`: the arguments object, or for a
    /// [`Chunk::lazy_arguments`] body the plain Array of actual arguments standing in for it
    /// (for a [`Chunk::arguments_count`] body, their number).
    pub(crate) fn arguments_slot_value(
        &self,
        i: &mut Interp,
        args: &[Value],
        scope: &Env,
    ) -> Value {
        if self.arguments_count {
            Value::Num(args.len() as f64)
        } else if self.lazy_arguments {
            i.make_array(args.to_vec())
        } else {
            Value::Obj(i.make_compiled_arguments_object(args, scope))
        }
    }
    /// Recognize the Prototype.js-style forwarding constructor
    /// `this.<initializer>.apply(this, arguments);`.
    ///
    /// The construct fast path can execute this exact, branch-free body without materializing
    /// the otherwise short-lived `arguments` exotic. Property and builtin-identity guards remain
    /// live there; any accessor, proxy, `apply` override, or other body shape runs normally.
    #[inline]
    pub(crate) fn jit_arguments_apply_forwarder(
        &self,
    ) -> Option<(&str, &std::cell::Cell<IcState>, &std::cell::Cell<IcState>)> {
        let plan = self.arguments_forwarder.get_or_init(|| {
            let [Op::GetPropThis(initializer, initializer_cache), Op::GetMethod(apply, apply_cache), Op::LoadThis, Op::LoadLocal(arguments), Op::CallWithThis(2, _), Op::Pop, Op::ReturnUndef] =
                self.ops.as_slice()
            else {
                return None;
            };
            (self.arguments_slot == Some(*arguments) && &*self.names[*apply as usize] == "apply")
                .then_some(ArgumentsForwarder {
                    initializer: *initializer,
                    initializer_cache: *initializer_cache,
                    apply_cache: *apply_cache,
                })
        });
        let plan = plan.as_ref()?;
        Some((
            &self.names[plan.initializer as usize],
            &self.caches[plan.initializer_cache as usize],
            &self.caches[plan.apply_cache as usize],
        ))
    }

    pub(crate) fn jit_forwarder_runtime(
        &self,
        initializer: &crate::value::Gc,
        apply: usize,
    ) -> Option<Rc<Chunk>> {
        let initializer_ptr = crate::value::Gc::as_ptr(initializer) as usize;
        self.arguments_forwarder_runtime
            .borrow()
            .as_ref()
            .filter(|runtime| {
                runtime.initializer == initializer_ptr
                    && runtime.apply == apply
                    && runtime.pin.as_ptr() == crate::value::Gc::as_ptr(initializer)
            })
            .map(|runtime| runtime.chunk.clone())
    }

    pub(crate) fn cache_jit_forwarder_runtime(
        &self,
        initializer: &crate::value::Gc,
        apply: usize,
        runtime_chunk: Rc<Chunk>,
    ) {
        let initializer_ptr = crate::value::Gc::as_ptr(initializer) as usize;
        *self.arguments_forwarder_runtime.borrow_mut() = Some(ForwarderRuntime {
            initializer: initializer_ptr,
            apply,
            pin: crate::value::Gc::downgrade(initializer),
            chunk: runtime_chunk,
        });
    }

    fn parse_initializer_plan(&self) -> Option<InitializerPlan> {
        if self.arguments_slot.is_some()
            || self.needs_env()
            || self.n_params > 128
            || !matches!(self.ops.last(), Some(Op::ReturnUndef))
        {
            return None;
        }

        let finish = |fields: Vec<InitializerField>| {
            let mut used = 0u128;
            if fields.is_empty()
                || fields.len() > 8
                || fields.iter().any(|field| {
                    if field.slot as usize >= self.n_params {
                        return true;
                    }
                    let bit = 1u128 << field.slot;
                    let duplicate = used & bit != 0;
                    used |= bit;
                    duplicate
                })
            {
                None
            } else {
                Some(InitializerPlan {
                    fields,
                    shapes: std::cell::Cell::new(InitializerShapes::default()),
                })
            }
        };

        // `this.x = arg ? arg : constant`, repeated, then implicit return.
        let mut pc = 0usize;
        let mut fields = Vec::new();
        while let Some(
            [Op::LoadLocal(test), Op::JumpIfFalse(on_false), Op::LoadLocal(value), Op::Jump(done), Op::Const(default), Op::SetPropThisDrop(name, cache)],
        ) = self.ops.get(pc..pc + 6)
        {
            if test != value || *on_false as usize != pc + 4 || *done as usize != pc + 5 {
                break;
            }
            fields.push(InitializerField {
                slot: *test,
                default: Some(*default),
                name: *name,
                cache: *cache,
            });
            pc += 6;
        }
        if pc + 1 == self.ops.len() && matches!(self.ops[pc], Op::ReturnUndef) {
            return finish(fields);
        }

        // `if (!arg) arg = constant` prefixes followed by direct `this.x = arg` stores.
        let mut defaults = [None; 128];
        pc = 0;
        while let Some(
            [Op::LoadLocal(test), Op::Not, Op::JumpIfFalse(done), Op::Const(default), Op::StoreLocal(store)],
        ) = self.ops.get(pc..pc + 5)
        {
            if test != store
                || *test as usize >= self.n_params
                || *done as usize != pc + 5
                || defaults[*test as usize].is_some()
            {
                break;
            }
            defaults[*test as usize] = Some(*default);
            pc += 5;
        }
        fields = Vec::new();
        while let Some([Op::LoadLocal(slot), Op::SetPropThisDrop(name, cache)]) =
            self.ops.get(pc..pc + 2)
        {
            fields.push(InitializerField {
                slot: *slot,
                default: defaults.get(*slot as usize).copied().flatten(),
                name: *name,
                cache: *cache,
            });
            pc += 2;
        }
        if pc + 1 == self.ops.len() && matches!(self.ops[pc], Op::ReturnUndef) {
            return finish(fields);
        }
        None
    }

    pub(crate) fn jit_initializer_plan(&self) -> Option<&InitializerPlan> {
        self.initializer_plan
            .get_or_init(|| self.parse_initializer_plan())
            .as_ref()
    }

    #[inline(always)]
    pub(crate) fn jit_initializer_field(
        &self,
        plan: &InitializerPlan,
        index: usize,
    ) -> (usize, Option<&Value>, &Rc<str>, &std::cell::Cell<IcState>) {
        let field = &plan.fields[index];
        (
            field.slot as usize,
            field
                .default
                .map(|constant| &self.consts[constant as usize]),
            &self.names[field.name as usize],
            &self.caches[field.cache as usize],
        )
    }

    /// Exact straight-line field constructor recognized without function or benchmark identity.
    /// Unique parameter slots let the construct path move owned values directly into the fresh
    /// object. Any computed value, control flow, duplicate parameter use, or materialized
    /// `arguments` object declines to ordinary execution.
    pub(crate) fn jit_simple_constructor(&self) -> Option<SimpleConstructor<'_>> {
        let fields = self
            .simple_constructor_plan
            .get_or_init(|| {
                if self.ops.len() < 3
                    || self.ops.len() > 17
                    || self.ops.len() & 1 == 0
                    || !matches!(self.ops.last(), Some(Op::ReturnUndef))
                    || self.arguments_slot.is_some()
                    || self.n_params > 128
                {
                    return None;
                }
                let count = self.ops.len() / 2;
                let mut fields = Vec::with_capacity(count);
                let mut used = 0u128;
                for pair_index in 0..count {
                    let start = pair_index * 2;
                    let pair = &self.ops[start..start + 2];
                    let [Op::LoadLocal(slot), Op::SetPropThisDrop(name, cache)] = pair else {
                        return None;
                    };
                    if *slot as usize >= self.n_params {
                        return None;
                    }
                    let bit = 1u128 << *slot;
                    if used & bit != 0 {
                        return None;
                    }
                    used |= bit;
                    fields.push(InitializerField {
                        slot: *slot,
                        default: None,
                        name: *name,
                        cache: *cache,
                    });
                }
                Some(fields)
            })
            .as_deref()?;
        Some(SimpleConstructor {
            chunk: self,
            fields,
        })
    }

    /// Whether calls run without an activation environment (nothing captured, no lexical
    /// `this`) — the precondition for the JIT→JIT fast call's moved-argument entry.
    pub(crate) fn jit_no_activation(&self) -> bool {
        !self.resumable && !self.needs_env()
    }
    pub(crate) fn jit_is_resumable(&self) -> bool {
        self.resumable
    }
    pub(crate) fn jit_is_strict(&self) -> bool {
        self.strict
    }
    /// Byte offset of `inline_attempted` within `Chunk` (self-probed; every Chunk shares the
    /// monomorphized layout, so the caller's offset is the callee's too).
    pub(crate) fn jit_inline_attempted_off(&self) -> usize {
        &self.inline_attempted as *const _ as usize - self as *const Chunk as usize
    }
    pub(crate) fn jit_runs_off(&self) -> usize {
        &self.jit_runs as *const _ as usize - self as *const Chunk as usize
    }
    pub(crate) fn jit_inline_retry_at_off(&self) -> usize {
        &self.inline_retry_at as *const _ as usize - self as *const Chunk as usize
    }
    pub(crate) fn inline_retry_due(&self, runs: u32) -> bool {
        let at = self.inline_retry_at.get();
        at != 0 && runs >= at
    }
    /// Four exponentially spaced feedback checkpoints bound compilation work. Empty early
    /// profiles can mature, but unchanged profiles never rerun the planner. Only identities
    /// and immutable compile states enter this signature; no user property reads are needed.
    pub(crate) fn advance_inline_feedback(&self) -> bool {
        use std::hash::{Hash, Hasher};
        let checks = self.inline_checks.get().saturating_add(1);
        self.inline_checks.set(checks);
        self.inline_retry_at.set(if checks >= 4 {
            0
        } else {
            self.jit_runs.get().saturating_add(
                inline_recompile_at()
                    .max(1)
                    .saturating_mul(4u32.pow(checks as u32)),
            )
        });
        let mut fingerprint = std::collections::hash_map::DefaultHasher::new();
        for site in &self.call_caches {
            for entry in &site.entries {
                let ic = entry.get();
                ic.callee.hash(&mut fingerprint);
                ic.func.hash(&mut fingerprint);
                ic.chunk_raw.hash(&mut fingerprint);
                ic.env.hash(&mut fingerprint);
                ic.epoch.hash(&mut fingerprint);
            }
        }
        let next = fingerprint.finish();
        let first = !self.inline_attempted.replace(true);
        let changed = self.inline_feedback.replace(next) != next;
        first || changed
    }
    /// [`CallIc::direct`] gates for this chunk (see its docs).
    ///
    /// A chunk that materializes a native activation for its bridge operations (see
    /// [`Chunk::jit_needs_activation_state`]) is eligible: the direct sequence runs it on a
    /// pooled record of its own, exactly like `run_moved`, the activation is created lazily from
    /// that record's closure environment, and the finish stub hands any materialized
    /// activation to `jit_direct_finish`, whose record release drops it.
    pub(crate) fn jit_direct_flags(&self, code: &crate::jit::JitCode) -> u8 {
        // The machine-code sequence seeds positional parameters only; a rest parameter's Array
        // is built by the Rust frame entries.
        if self.resumable || !direct_shared_context_enabled() || self.rest_slot.is_some() {
            return 0;
        }
        #[allow(unused_mut)] // Only the ARM64 shared-call backend adds frame flags.
        let mut f = 1u8;
        #[cfg(all(
            target_arch = "aarch64",
            any(target_os = "macos", target_os = "linux", target_os = "windows")
        ))]
        {
            if code.needs_global {
                f |= 2;
            }
            // The direct sequence carves [slots|operand stack] from one fixed-size pooled
            // buffer, exactly like run_moved's fast path — a frame that doesn't fit must take
            // the layered path (run_moved falls back to growable Vecs there).
            let (_, n_slots) = self.jit_frame();
            if n_slots + code.max_stack <= crate::jit::FRAME_BUF {
                f |= 8;
            }
        }
        #[cfg(not(all(
            target_arch = "aarch64",
            any(target_os = "macos", target_os = "linux", target_os = "windows")
        )))]
        let _ = code;
        f
    }

    pub(crate) fn jit_needs_activation_state(&self) -> bool {
        self.jit_needs_activation_state
    }
    /// Whether const `k` is a trivially-copyable value the JIT may materialize inline.
    pub(crate) fn jit_const_copyable(&self, k: u32) -> bool {
        matches!(
            self.consts[k as usize],
            Value::Undefined | Value::Null | Value::Bool(_) | Value::Num(_)
        )
    }
    /// One-word execution encoding for an immediate constant; heap constants need ownership
    /// cloning and are deliberately excluded. All Number NaNs use the canonical packed bits.
    pub(crate) fn jit_const_packed_bits(&self, k: u32) -> Option<u64> {
        PackedValue::scalar_bits(&self.consts[k as usize])
    }
    /// Stable address of const `k` (the chunk is pinned by any code that runs it): the JIT's
    /// string-const template copies the Value and bumps its refcount inline.
    pub(crate) fn jit_const_ptr(&self, k: u32) -> *const Value {
        &self.consts[k as usize] as *const Value
    }
    /// Whether const `k` is a string (payload strong count at offset 0 — the template's bump).
    pub(crate) fn jit_const_is_str(&self, k: u32) -> bool {
        matches!(self.consts[k as usize], Value::Str(_))
    }
    /// The f64 bits of a Num const (for the JIT's register-chain emitter).
    pub(crate) fn jit_const_num(&self, k: u32) -> Option<u64> {
        match &self.consts[k as usize] {
            Value::Num(n) => Some(n.to_bits()),
            _ => None,
        }
    }
    /// The first 16 bytes of a copyable const as two words, for inline materialization.
    /// repr(u8) puts each payload at its own alignment: Bool's byte sits in word0 at offset 1,
    /// Num's f64 fills word1 (offset 8).
    pub(crate) fn jit_const_bits(&self, k: u32) -> (u64, u64) {
        match &self.consts[k as usize] {
            Value::Undefined => (0, 0),
            Value::Null => (2, 0),
            Value::Bool(b) => (3 | ((*b as u64) << 8), 0),
            Value::Num(n) => (4, n.to_bits()),
            _ => unreachable!("non-copyable const in jit_const_bits"),
        }
    }
    pub(crate) fn jit_make_run_env(
        &self,
        i: &mut Interp,
        env: &Env,
        this_val: &Value,
        args: &[Value],
    ) -> Env {
        self.make_run_env(i, env, this_val, args)
    }

    /// Seed captured owners directly from the still-live caller operand list. The ordinary
    /// frame subsequently consumes those words; the environment owns only its captured copies.
    pub(crate) fn jit_make_run_env_packed(
        &self,
        i: &mut Interp,
        env: &Env,
        this_val: &Value,
        args: &[PackedValue],
    ) -> Env {
        self.make_run_env_from(i, env, this_val, CallArgs::Packed(args))
    }
    /// (pops, pushes) of the op at `pc`, for the static stack-depth analysis. `None` = an op the
    /// JIT can't account for (which refuses compilation).
    pub(crate) fn jit_stack_effect(&self, pc: usize) -> Option<(usize, usize)> {
        self.jit_stack_effect_for_entry(pc, false)
    }

    /// A borrowed synchronous activation already owns disposal frames and completion state.
    /// Its native slice can return disposal operations to the canonical VM driver without
    /// pretending the language-level function is resumable or admitting a fresh-call entry.
    pub(crate) fn jit_borrowed_stack_effect(&self, pc: usize) -> Option<(usize, usize)> {
        self.jit_stack_effect_for_entry(pc, true)
    }

    fn jit_stack_effect_for_entry(&self, pc: usize, borrowed: bool) -> Option<(usize, usize)> {
        if matches!(self.ops[pc], Op::FragmentExit(_)) && !borrowed {
            return None;
        }
        // AssignTarget enters the normative tree-walker with a projected Environment Record.
        // Keep that uncommon bridge in the bytecode VM: re-entering arbitrary evaluator code
        // from a packed ARM64 frame is both unnecessary for coroutine conversion and unsafe for
        // JIT ownership assumptions. The rest of the function still avoids the tree-walker and,
        // crucially, coroutine bodies remain heap-owned rather than native-thread-backed.
        if matches!(
            self.ops[pc],
            Op::AssignTarget(_)
                | Op::EvalExpr(_)
                | Op::PushWith
                | Op::PushLex(_)
                | Op::PushCatchLex(_)
                | Op::CloneLex(_)
                | Op::InitLex(_)
                | Op::PopEnv
                | Op::ResolveNameRef(..)
                | Op::LoadRef(_)
                | Op::StoreRef(_)
                | Op::PushDisposeFrame
                | Op::AddDisposable(_)
                | Op::DisposeNormal
                | Op::DisposeThrow
                | Op::DisposeReturn
                | Op::DisposeBareReturn
                | Op::DisposeResumeReturn
                | Op::DisposeJump
                | Op::StoreConstLocal(..)
                | Op::StoreConstCap(_)
                | Op::UpdateConst(..)
                | Op::RequireObject
                | Op::DestructureStepL(..)
                | Op::DestructureRestL(..)
                | Op::IterCloseIfNotDoneL(..)
                | Op::IterAbortIfNotDoneL(..)
                | Op::ObjectRest(_)
                | Op::AsyncIterStepL(..)
                | Op::AsyncIterCloseL(..)
                | Op::NewArray
                | Op::ArrayPush
                | Op::ArrayHole
                | Op::ArraySpread
                | Op::CallArgsArray
                | Op::CallArgsArrayThis
                | Op::EvalCallArgsArray
                | Op::TailEvalCallArgsArray
                | Op::NewArgsArray
                | Op::ImportMeta
                | Op::DynamicImport(..)
                | Op::UpdatePrivate(..)
                | Op::SuperCallStart
                | Op::SuperCallArgsArray
                | Op::LoadLexicalThis
                | Op::SuperThis
                | Op::SuperBase
                | Op::SuperGet
                | Op::SuperGetKeep
                | Op::SuperGetMethod
                | Op::SuperSet
                | Op::SuperUpdate(_)
                | Op::TemplateObject(_)
                | Op::RequireCallable
                | Op::ClassStart(..)
                | Op::ClassHeritage(..)
                | Op::ClassKey(..)
                | Op::ClassDecorator(..)
                | Op::ClassFinish(_)
                | Op::ClassAbort(_)
        ) && !jit_bridge_op(&self.ops[pc])
            && !(self.resumable && jit_slice_exit_op(&self.ops[pc]))
            && !(borrowed
                && matches!(
                    self.ops[pc],
                    Op::DisposeNormal
                        | Op::DisposeThrow
                        | Op::DisposeReturn
                        | Op::DisposeBareReturn
                        | Op::DisposeResumeReturn
                        | Op::DisposeJump
                ))
        {
            return None;
        }
        let upd = |k: &UpdKind| match k {
            UpdKind::IncDiscard | UpdKind::DecDiscard => 0,
            _ => 1,
        };
        Some(match &self.ops[pc] {
            Op::FragmentExit(_) => (1, 0),
            Op::AnnexBSync(_) => (0, 0),
            Op::Const(_)
            | Op::Undef
            | Op::LoadLocal(_)
            | Op::LoadCap(_)
            | Op::LoadName(..)
            | Op::LoadNameIn(..)
            | Op::LoadThis
            | Op::LoadLexicalThis
            | Op::MakeClosure(..) => (0, 1),
            Op::Dup => (1, 2),
            Op::Dup2 => (2, 4),
            Op::Pop
            | Op::StoreLocal(_)
            | Op::StoreCap(_)
            | Op::StoreCapInit(_)
            | Op::StoreName(_)
            | Op::StoreGlobalName(_)
            | Op::StoreNameCached(..)
            | Op::StoreConstLocal(..)
            | Op::StoreConstCap(_)
            | Op::UpdateConst(..) => (1, 0),
            Op::UpdateLocal(_, k) | Op::UpdateCap(_, k) | Op::UpdateName(_, k) => (0, upd(k)),
            Op::UpdateNameCached(_, _, k) => (0, upd(k)),
            Op::UpdateProp(_, _, k) => (1, upd(k)),
            Op::UpdateElem(k) => (2, upd(k)),
            Op::Tdz(_) => (0, 0),
            Op::GetProp(..) | Op::RequireObject => (1, 1),
            Op::GetPropThis(..) => (0, 1),
            Op::GetPropLocal(..) => (0, 1),
            Op::SetProp(..) => (2, 1),
            Op::SetPropDrop(..) => (2, 0),
            Op::SetPropThisDrop(..) => (1, 0),
            Op::SetPropLocalDrop(..) => (1, 0),
            Op::GetElem => (2, 1),
            Op::SetElem => (3, 1),
            Op::SetElemDrop => (3, 0),
            Op::AppendProp(..) => (3, 0),
            Op::DestructureGuard => (1, 1),
            Op::DestructureArr(n) => (1, *n as usize),
            Op::TryArrayBinding(..) => (1, 2),
            Op::ArrayBindingStep(..) => (0, 1),
            Op::AssignTarget(_) => (1, 0),
            Op::EvalExpr(_) => (0, 1),
            Op::ClassStart(_, count) => (*count as usize * 2, 0),
            Op::ClassAbort(_) => (0, 0),
            Op::ClassHeritage(_, present) => (usize::from(*present), 0),
            Op::ClassKey(..) => (1, 0),
            Op::ClassDecorator(..) => (2, 0),
            Op::ClassFinish(_) => (0, 1),
            Op::ResolveNameRef(..) => (0, 0),
            Op::LoadRef(_) => (0, 1),
            Op::StoreRef(_) => (1, 0),
            Op::PushWith => (1, 0),
            Op::PushLex(_) | Op::PushCatchLex(_) | Op::CloneLex(_) => (0, 0),
            Op::InitLex(_) => (1, 0),
            Op::PopEnv => (0, 0),
            Op::PushDisposeFrame | Op::DisposeNormal => (0, 0),
            Op::AddDisposable(_) => (1, 1),
            Op::DisposeThrow | Op::DisposeReturn | Op::DisposeResumeReturn => (1, 0),
            Op::DisposeBareReturn => (0, 0),
            Op::DisposeJump => (2, 0),
            Op::ObjectRest(count) => (*count as usize + 1, 1),
            Op::DeleteProp(..) => (1, 1),
            Op::DeleteElem(_) => (2, 1),
            Op::DeleteName(_) => (0, 1),
            Op::DeleteSuper => (0, 0),
            Op::CallSpread(argc) => (*argc as usize + 1, 1),
            Op::CallSpreadThis(argc) => (*argc as usize + 2, 1),
            Op::CallArgsArray => (2, 1),
            Op::CallArgsArrayThis => (3, 1),
            Op::EvalCallArgsArray | Op::TailEvalCallArgsArray => (3, 1),
            Op::TailDeep => (0, 1),
            Op::TailCall(mode, with_this) => {
                let count = match mode {
                    CallArgsMode::Fixed(count) | CallArgsMode::FinalSpread(count) => {
                        *count as usize
                    }
                    CallArgsMode::Array => 1,
                };
                (count + 1 + usize::from(*with_this), 1)
            }
            Op::ToStr => (1, 1),
            Op::GetIter => (1, 2),
            Op::GetAsyncIter => (1, 3),
            Op::ForInKeys => (1, 1),
            Op::ForInStepL(..) => (0, 2),
            Op::IterStepL(..) => (0, 2),
            Op::IterCloseL(_) => (0, 0),
            Op::IterAbortL(_) => (1, 0),
            Op::DestructureStepL(..) | Op::DestructureRestL(..) => (0, 1),
            Op::IterCloseIfNotDoneL(..) => (0, 0),
            Op::IterAbortIfNotDoneL(..) => (1, 0),
            Op::AsyncIterStepL(..) => (0, 1),
            Op::AsyncIterResumeL(..) => (1, 2),
            Op::AsyncIterCloseL(..) => (0, 0),
            Op::GetElemLocal(_) | Op::ArgElem(_) => (1, 1),
            Op::SetElemLocal(_) => (2, 1),
            Op::SetElemLocalDrop(_) => (2, 0),
            Op::ToPropKey => (2, 2),
            Op::ToPropKeyLocal(_) => (1, 1),
            Op::GetMethod(..) => (1, 2),
            Op::GetMethodElem => (2, 2),
            Op::Add
            | Op::Sub
            | Op::Mul
            | Op::Div
            | Op::Mod
            | Op::BitAnd
            | Op::BitOr
            | Op::BitXor
            | Op::Shl
            | Op::Shr
            | Op::UShr
            | Op::Lt
            | Op::Gt
            | Op::Le
            | Op::Ge
            | Op::EqEq
            | Op::NotEq
            | Op::StrictEq
            | Op::StrictNotEq
            | Op::InstanceOf(_)
            | Op::In
            | Op::GenBin(_) => (2, 1),
            Op::Neg
            | Op::Plus
            | Op::Not
            | Op::BitNot
            | Op::Typeof
            | Op::TypeofIs(..)
            | Op::Void => (1, 1),
            Op::TypeofName(_) => (0, 1),
            Op::Jump(_) | Op::AbruptJump(..) => (0, 0),
            Op::InlineGuard(..) => (0, 0),
            Op::ResetSlots(..) => (0, 0),
            Op::JumpIfFalse(_) => (1, 0),
            Op::JumpIfFalsePeek(_) | Op::JumpIfTruePeek(_) | Op::JumpIfNotNullishPeek(_) => (1, 1),
            Op::Call(argc, _) => (*argc as usize + 1, 1),
            Op::LoadNameForCall(..) | Op::LoadNameForCallIn(..) => (0, 2),
            Op::CallWithThis(argc, _) => (*argc as usize + 2, 1),
            Op::New(argc, _) => (*argc as usize + 1, 1),
            Op::NewArgsArray => (2, 1),
            Op::MakeRegExp(..) => (0, 1),
            Op::MakeArray(n) => (*n as usize, 1),
            Op::NewArray => (0, 1),
            Op::ArrayPush | Op::ArraySpread => (2, 1),
            Op::ArrayHole => (1, 1),
            Op::MakeObject(_, count, _) => (*count as usize, 1),
            Op::NewObject => (0, 1),
            Op::ObjectData(_) => (3, 1),
            Op::ObjectSpread | Op::ObjectProto | Op::ObjectMethod(..) | Op::ObjectDataName(..) => {
                (2, 1)
            }
            Op::ObjectMethodName(..) => (1, 1),
            Op::Abstract(op) => op.stack_effect(),
            Op::ImportMeta | Op::NewTarget | Op::TemplateObject(_) => (0, 1),
            Op::DynamicImport(_, has_options) => (usize::from(*has_options) + 1, 1),
            Op::PrivateIn(..) => (1, 1),
            Op::GetPrivate(..) => (1, 1),
            Op::GetPrivateKeep(..) | Op::GetPrivateMethod(..) => (1, 2),
            Op::SetPrivate(..) => (2, 1),
            Op::UpdatePrivate(_, kind) => (1, upd(kind)),
            Op::SuperCallStart => (0, 2),
            Op::SuperCallArgsArray => (3, 1),
            Op::SuperThis | Op::SuperBase => (0, 1),
            Op::SuperGet => (3, 1),
            Op::SuperGetKeep => (3, 4),
            Op::SuperGetMethod => (3, 2),
            Op::SuperSet => (4, 1),
            Op::SuperUpdate(kind) => (3, upd(kind)),
            Op::RequireCallable => (0, 0),
            Op::Throw | Op::Return | Op::ResumeReturn => (1, 0),
            Op::ResumeJump => (2, 0),
            Op::ReturnBare | Op::ReturnUndef => (0, 0),
            Op::Await | Op::Yield | Op::YieldStar => (1, 1),
            Op::PushHandler(_) | Op::PushFinally(..) | Op::PushIterator(..) | Op::PopHandler => {
                (0, 0)
            }
        })
    }
}

/// Execute the single (non-control-flow) op at `pc` against the raw operand stack `sp`. Returns
/// the updated stack top (reflecting any operands consumed *even on a throw* — the unwinder's
/// cleanup must never re-drop moved-out slots) plus a flag: 1 = threw (stored in `ctx.error`).
///
/// # Safety
/// Called from JIT code with `ctx` pointing at the live `JitCtx` for this activation and `sp`
/// inside its stack buffer, whose capacity covers the chunk's statically-computed maximum depth.
/// Owned state for uncommon synchronous operations in an otherwise native activation.
pub(crate) struct NativeActivation {
    chunk: *const Chunk,
    env: Env,
    cap_env: Env,
    stack: ValueStack<PackedValue>,
    references: Vec<crate::eval::PreparedReferenceSlot>,
    disposal_frames: Vec<Vec<crate::interpreter::Disposable>>,
    class_states: Vec<Option<crate::eval::PreparedClassEvaluation>>,
}

/// A borrow of the authoritative VmCoro state, valid only for one native slice. No machine
/// stack address or code address is retained by the suspended continuation. The operand Vec
/// lends its allocation to generated code (length zero), then regains the initialized prefix
/// at every checked operation or exit. Locals already use the same owned-word representation.
pub(crate) struct NativeContinuation {
    pub(crate) chunk: *const Chunk,
    pub(crate) env: *mut Env,
    pub(crate) cap_env: *const Env,
    pub(crate) references: *mut [crate::eval::PreparedReferenceSlot],
    pub(crate) stack: *mut ValueStack<PackedValue>,
    pub(crate) disposal_frames: *mut Vec<Vec<crate::interpreter::Disposable>>,
    pub(crate) class_states: *mut [Option<crate::eval::PreparedClassEvaluation>],
}

/// Instructions whose exact Completion/suspension must return to the shared driver. They are
/// full materialization barriers: no register or borrowed owner can survive an Await/Yield.
pub(crate) fn jit_slice_exit_op(op: &Op) -> bool {
    matches!(
        op,
        Op::Await
            | Op::FragmentExit(_)
            | Op::Yield
            | Op::YieldStar
            | Op::AsyncIterStepL(..)
            | Op::AsyncIterCloseL(..)
            | Op::DisposeNormal
            | Op::DisposeThrow
            | Op::DisposeReturn
            | Op::DisposeBareReturn
            | Op::DisposeResumeReturn
            | Op::DisposeJump
            | Op::Return
            | Op::ReturnBare
            | Op::ReturnUndef
            | Op::ResumeReturn
            | Op::Throw
            | Op::AbruptJump(..)
            | Op::ResumeJump
            | Op::IterAbortL(_)
            | Op::IterAbortIfNotDoneL(..)
    )
}

/// A normally resumed suspension adds one value for Await/Yield/iterator stepping, but no
/// value for asynchronous cleanup. This is separate from normal CFG edges and dominance.
pub(crate) fn jit_resume_after(op: &Op) -> bool {
    matches!(
        op,
        Op::Await
            | Op::Yield
            | Op::YieldStar
            | Op::AsyncIterStepL(..)
            | Op::AsyncIterCloseL(..)
            | Op::DisposeNormal
    )
}

fn jit_bridge_op(op: &Op) -> bool {
    matches!(
        op,
        Op::AnnexBSync(_)
            | Op::AssignTarget(_)
            | Op::EvalExpr(_)
            | Op::PushWith
            | Op::PushLex(_)
            | Op::PushCatchLex(_)
            | Op::CloneLex(_)
            | Op::InitLex(_)
            | Op::PopEnv
            | Op::ResolveNameRef(..)
            | Op::LoadRef(_)
            | Op::StoreRef(_)
            | Op::StoreConstLocal(..)
            | Op::StoreConstCap(_)
            | Op::UpdateConst(..)
            | Op::RequireObject
            | Op::DestructureStepL(..)
            | Op::DestructureRestL(..)
            | Op::IterCloseIfNotDoneL(..)
            | Op::IterAbortIfNotDoneL(..)
            | Op::ObjectRest(_)
            | Op::NewArray
            | Op::ArrayPush
            | Op::ArrayHole
            | Op::ArraySpread
            | Op::CallArgsArray
            | Op::CallArgsArrayThis
            | Op::EvalCallArgsArray
            | Op::NewArgsArray
            | Op::ImportMeta
            | Op::DynamicImport(..)
            | Op::UpdatePrivate(..)
            | Op::SuperCallStart
            | Op::SuperCallArgsArray
            | Op::LoadLexicalThis
            | Op::SuperThis
            | Op::SuperBase
            | Op::SuperGet
            | Op::SuperGetKeep
            | Op::SuperGetMethod
            | Op::SuperSet
            | Op::SuperUpdate(_)
            | Op::TemplateObject(_)
            | Op::RequireCallable
            | Op::ClassStart(..)
            | Op::ClassHeritage(..)
            | Op::ClassKey(..)
            | Op::ClassDecorator(..)
            | Op::ClassFinish(_)
            | Op::ClassAbort(_)
            | Op::PushDisposeFrame
            | Op::AddDisposable(_)
            | Op::GetAsyncIter
            | Op::AsyncIterResumeL(..)
    )
}

/// Run one checked operation against the canonical borrowed continuation, not an activation
/// copy. A nested ordinary direct callee has another chunk and must not use this view.
unsafe fn jit_continuation_operation(
    ctx: &mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
    exits: bool,
) -> crate::jit::SpFlag {
    let state = &mut *ctx.resume_activation;
    debug_assert_eq!(state.chunk, ctx.chunk);
    let chunk = &*ctx.chunk;
    let stack = &mut *state.stack;
    debug_assert!(stack.is_empty());
    debug_assert_eq!(stack.as_mut_ptr(), ctx.stack_base);
    stack.set_len(sp.offset_from(ctx.stack_base) as usize);
    let mut next = pc as usize;
    let result = if next == chunk.ops.len() {
        Ok(VmStep::Done(Value::Undefined))
    } else {
        run_vm(
            &mut *ctx.interp,
            chunk,
            &mut *state.env,
            &*state.cap_env,
            &mut *state.references,
            std::slice::from_raw_parts(ctx.slots, ctx.n_slots),
            stack,
            &mut next,
            &ctx.this_val,
            &mut ctx.handlers,
            &mut *state.disposal_frames,
            &mut *state.class_states,
            Some(pc as usize + 1),
            None,
        )
        .map(VmRunExit::single_operation)
    };
    // CFG capacity covers every settled depth and the helper's temporary operand suffix.
    // Helpers must never replace the borrowed allocation under the machine stack pointer.
    assert_eq!(
        stack.as_mut_ptr(),
        ctx.stack_base,
        "native continuation stack reallocated"
    );
    let sp = ctx.stack_base.add(stack.len());
    stack.set_len(0);
    ctx.env_raw = Env::as_ptr(&*state.env) as *const u8;
    ctx.env_parent_raw = (*state.env)
        .borrow()
        .parent
        .as_ref()
        .map_or(std::ptr::null(), |parent| Env::as_ptr(parent) as *const u8);
    if exits {
        ctx.resume_pc = next;
    }
    match result {
        Ok(VmStep::Done(_))
            if (pc as usize) < chunk.ops.len()
                && !matches!(chunk.ops[pc as usize], Op::ReturnUndef) =>
        {
            crate::jit::SpFlag { sp, flag: 0 }
        }
        Ok(step) if exits => {
            ctx.resume_step = Some(step);
            crate::jit::SpFlag { sp, flag: 0 }
        }
        Ok(_) => unreachable!("only slice exit operations may suspend or return"),
        Err(error) => {
            ctx.throw_at(pc, error);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

pub(crate) unsafe extern "C" fn jit_slice_op(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    jit_continuation_operation(&mut *ctx, pc, sp, true)
}

unsafe fn new_native_activation(ctx: &crate::jit::JitCtx) -> Box<NativeActivation> {
    let chunk = &*ctx.chunk;
    let borrowed = std::mem::ManuallyDrop::new(crate::interpreter::Env::from_raw(
        ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
    ));
    let env = crate::interpreter::Env::clone(&borrowed);
    Box::new(NativeActivation {
        chunk: ctx.chunk,
        cap_env: env.clone(),
        env,
        stack: ValueStack::default(),
        references: (0..chunk.n_refs)
            .map(|_| crate::eval::PreparedReferenceSlot::default())
            .collect(),
        disposal_frames: Vec::new(),
        class_states: (0..chunk.class_plans.len()).map(|_| None).collect(),
    })
}

unsafe fn ensure_native_activation(ctx: &mut crate::jit::JitCtx) {
    if ctx.activation.is_none() {
        ctx.activation = Some(new_native_activation(ctx));
    }
    let activation = ctx
        .activation
        .as_mut()
        .expect("native activation initialized");
    debug_assert_eq!(
        activation.chunk, ctx.chunk,
        "stateful callees must use separate contexts"
    );
    ctx.references_raw = activation.references.as_mut_ptr();
}

#[cfg(test)]
thread_local! {
    pub(crate) static TEST_REFERENCE_HELPERS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// Dedicated Reference slow path: operates directly on canonical owners, without copying the
/// operand stack into a one-operation VM or replaying resolution after an effect.
pub(crate) unsafe extern "C" fn jit_reference_op(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    #[cfg(test)]
    TEST_REFERENCE_HELPERS.with(|count| count.set(count.get() + 1));
    let ctx = &mut *ctx;
    let chunk = &*ctx.chunk;
    if !ctx.resume_activation.is_null() && (*ctx.resume_activation).chunk == ctx.chunk {
        ctx.references_raw = (&mut *(*ctx.resume_activation).references).as_mut_ptr();
    } else {
        ensure_native_activation(ctx);
    }
    jit_opstat(ctx, pc);
    let i = &mut *ctx.interp;
    let result = match chunk.ops[pc as usize] {
        Op::ResolveNameRef(name, reference) => {
            let env = std::mem::ManuallyDrop::new(crate::interpreter::Env::from_raw(
                ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
            ));
            chunk.resolve_name_reference(i, &env, name).map(|value| {
                (*ctx.references_raw.add(reference as usize)).set(value);
            })
        }
        Op::LoadRef(reference) => {
            let reference = (*ctx.references_raw.add(reference as usize))
                .as_mut()
                .expect("prepared Reference resolved before GetValue");
            i.read_prepared_reference(reference).map(|value| {
                sp.write(PackedValue::pack(value));
                sp = sp.add(1);
            })
        }
        Op::StoreRef(reference) => {
            sp = sp.sub(1);
            let value = sp.read().into_value();
            let reference = (*ctx.references_raw.add(reference as usize))
                .as_mut()
                .expect("prepared Reference resolved before PutValue");
            i.write_prepared_reference(reference, value)
        }
        _ => unreachable!("Reference helper operation"),
    };
    match result {
        Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
        Err(error) => {
            ctx.throw_at(pc, error);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

/// BlockDeclarationInstantiation (ECMA-262 §14.2.3) of a compiler-planned lexical scope, or a
/// `catch` parameter environment (§14.15.2): a new declarative record whose bindings start
/// uninitialized, pushed as the running LexicalEnvironment.
fn push_lexical_scope(chunk: &Chunk, env: &mut Env, scope: u32, catch: bool) {
    let scope = &chunk.lexical_scopes[scope as usize];
    let bindings = scope
        .bindings
        .iter()
        .map(|binding| {
            (
                binding.name.clone(),
                crate::interpreter::Binding {
                    value: Value::Undefined,
                    mutable: !binding.is_const,
                    strict_immutable: binding.is_const,
                    initialized: false,
                    import_ref: None,
                    imported: false,
                    deletable: false,
                },
            )
        })
        .collect();
    let next = if catch {
        crate::interpreter::new_catch_scope(env.clone())
    } else {
        crate::interpreter::new_scope(Some(env.clone()))
    };
    // A block record is never a VariableEnvironment, so it records no `lexical_names` (only
    // EvalDeclarationInstantiation's variable-environment check reads them; it tests block
    // records through HasBinding).
    install_lexical_bindings(&next, scope, bindings);
    *env = next;
}

/// Give a fresh block/loop record `scope`'s complete ordered key set and publish its identity.
fn install_lexical_bindings(
    record: &Env,
    scope: &LexicalScope,
    bindings: Vec<(Rc<str>, crate::interpreter::Binding)>,
) {
    let mut record = record.borrow_mut();
    record.vars = crate::interpreter::VarMap::from_fixed_bindings(bindings, scope.index.as_ref());
    record.vars.publish_layout(scope.layout_id);
}

/// CreatePerIterationEnvironment (ECMA-262 §14.7.4.4): a sibling record copying each
/// per-iteration binding's current value and state.
fn clone_lexical_scope(chunk: &Chunk, env: &mut Env, scope: u32) {
    let scope = &chunk.lexical_scopes[scope as usize];
    let parent = env
        .borrow()
        .parent
        .clone()
        .expect("per-iteration lexical environment has a parent");
    let next = crate::interpreter::new_scope(Some(parent));
    let bindings = {
        let current = env.borrow();
        // A record this chunk created holds the scope's bindings in order; a borrowed first
        // iteration (a loop fragment's tree-walker record) is read by name.
        let ordered = scope.layout_id != 0 && current.vars.layout_id() == scope.layout_id;
        scope
            .bindings
            .iter()
            .enumerate()
            .map(|(slot, binding)| {
                let previous = if ordered {
                    current.vars.fixed_binding_at(slot)
                } else {
                    current.vars.get(&binding.name)
                }
                .expect("per-iteration binding missing");
                (
                    binding.name.clone(),
                    crate::interpreter::Binding {
                        value: previous.value.clone(),
                        mutable: previous.mutable,
                        strict_immutable: previous.strict_immutable,
                        initialized: previous.initialized,
                        import_ref: None,
                        imported: false,
                        deletable: false,
                    },
                )
            })
            .collect()
    };
    install_lexical_bindings(&next, scope, bindings);
    *env = next;
}

/// InitializeBinding (ECMA-262 §9.1.1.1.4) of an own lexical binding of the running scope.
fn initialize_lexical_binding(chunk: &Chunk, env: &Env, name: u32, value: Value) {
    let name = &chunk.names[name as usize];
    let mut record = env.borrow_mut();
    let binding = record
        .vars
        .get_mut(name)
        .expect("lexical initialization requires an own binding");
    binding.value = value;
    binding.initialized = true;
}

/// Restore the running LexicalEnvironment to the outer record of a compiled scope.
fn pop_lexical_scope(env: &mut Env) {
    let parent = env
        .borrow()
        .parent
        .clone()
        .expect("compiled environment scope has a parent");
    *env = parent;
}

fn jit_scope_operation(op: &Op) -> bool {
    matches!(
        op,
        Op::PushLex(_) | Op::PushCatchLex(_) | Op::CloneLex(_) | Op::InitLex(_) | Op::PopEnv
    )
}

/// Dedicated lexical-environment slow path: the same Environment Record operations as the VM,
/// applied directly to the native activation's canonical LexicalEnvironment, without copying
/// the operand stack into a one-operation VM. None of them can run author code or throw.
unsafe fn jit_scope_op(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    if !ctx.resume_activation.is_null() && (*ctx.resume_activation).chunk == ctx.chunk {
        return jit_vm_operation(ctx, pc, sp);
    }
    let chunk = &*ctx.chunk;
    jit_opstat(ctx, pc);
    ensure_native_activation(ctx);
    let activation = ctx
        .activation
        .as_mut()
        .expect("native activation initialized");
    match chunk.ops[pc as usize] {
        Op::PushLex(scope) => push_lexical_scope(chunk, &mut activation.env, scope, false),
        Op::PushCatchLex(scope) => push_lexical_scope(chunk, &mut activation.env, scope, true),
        Op::CloneLex(scope) => clone_lexical_scope(chunk, &mut activation.env, scope),
        Op::InitLex(name) => {
            sp = sp.sub(1);
            let value = sp.read().into_value();
            initialize_lexical_binding(chunk, &activation.env, name, value);
        }
        Op::PopEnv => pop_lexical_scope(&mut activation.env),
        _ => unreachable!("lexical environment helper operation"),
    }
    ctx.env_raw = Env::as_ptr(&activation.env) as *const u8;
    ctx.env_parent_raw = activation
        .env
        .borrow()
        .parent
        .as_ref()
        .map_or(std::ptr::null(), |parent| Env::as_ptr(parent) as *const u8);
    crate::jit::SpFlag { sp, flag: 0 }
}

unsafe fn jit_vm_operation(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    let chunk = &*ctx.chunk;
    if !ctx.resume_activation.is_null() && (*ctx.resume_activation).chunk == ctx.chunk {
        return jit_continuation_operation(ctx, pc, sp, false);
    }
    jit_opstat(ctx, pc);
    ensure_native_activation(ctx);
    let activation = ctx
        .activation
        .as_mut()
        .expect("native activation initialized");
    let depth = sp.offset_from(ctx.stack_base) as usize;
    debug_assert!(activation.stack.is_empty());
    activation.stack.reserve(depth);
    std::ptr::copy_nonoverlapping(ctx.stack_base, activation.stack.as_mut_ptr(), depth);
    activation.stack.set_len(depth);
    let mut next = pc as usize;
    let result = run_vm(
        &mut *ctx.interp,
        chunk,
        &mut activation.env,
        &activation.cap_env,
        &mut activation.references,
        std::slice::from_raw_parts(ctx.slots, ctx.n_slots),
        &mut activation.stack,
        &mut next,
        &ctx.this_val,
        &mut ctx.handlers,
        &mut activation.disposal_frames,
        &mut activation.class_states,
        Some(pc as usize + 1),
        None,
    )
    .map(VmRunExit::single_operation);
    // Transfer the live suffix back even on error. The native unwinder must never
    // observe moved-out inputs or omit values produced before a later abrupt step.
    let depth = activation.stack.len();
    std::ptr::copy_nonoverlapping(activation.stack.as_ptr(), ctx.stack_base, depth);
    activation.stack.set_len(0);
    ctx.env_raw = Env::as_ptr(&activation.env) as *const u8;
    ctx.env_parent_raw = activation
        .env
        .borrow()
        .parent
        .as_ref()
        .map_or(std::ptr::null(), |parent| Env::as_ptr(parent) as *const u8);
    let sp = ctx.stack_base.add(depth);
    match result {
        Ok(VmStep::Done(_)) => crate::jit::SpFlag { sp, flag: 0 },
        Err(error) => {
            ctx.throw_at(pc, error);
            crate::jit::SpFlag { sp, flag: 1 }
        }
        _ => unreachable!("native one-op bridge cannot suspend or return"),
    }
}

/// Private-name operations from machine code, without the generic operation decoder. The
/// Private Name resolves from the running environment: a materialized activation's (which
/// follows the block/class scopes its bridge operations push), else the frame's.
unsafe fn jit_private_op_inner(
    ctx: &mut crate::jit::JitCtx,
    pc: u32,
    sp: &mut *mut PackedValue,
) -> Result<(), Abrupt> {
    let i = &mut *ctx.interp;
    let chunk = &*ctx.chunk;
    // As in `jit_exec_inner`: the swapped `env_raw` names this activation's environment.
    let env_h = std::mem::ManuallyDrop::new(unsafe {
        crate::interpreter::Env::from_raw(
            ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
        )
    });
    let private_env: &Env = match ctx.activation.as_ref() {
        Some(activation) if activation.chunk == ctx.chunk => &activation.env,
        _ if !ctx.resume_activation.is_null() && (*ctx.resume_activation).chunk == ctx.chunk => {
            &*(*ctx.resume_activation).env
        }
        _ => &env_h,
    };
    let op = chunk.ops[pc as usize];
    let (Op::PrivateIn(name, site)
    | Op::GetPrivate(name, site)
    | Op::GetPrivateKeep(name, site)
    | Op::GetPrivateMethod(name, site)
    | Op::SetPrivate(name, site)) = op
    else {
        unreachable!("private-name operation helper");
    };
    let name = &chunk.names[name as usize];
    let site = Some(&chunk.private_sites[site as usize]);
    macro_rules! pop {
        () => {{
            *sp = sp.sub(1);
            sp.read().into_value()
        }};
    }
    macro_rules! push {
        ($v:expr) => {{
            let v = $v;
            sp.write(PackedValue::pack(v));
            *sp = sp.add(1);
        }};
    }
    match op {
        Op::PrivateIn(..) => {
            let value = pop!();
            let result = i.private_in_vm(name, value, private_env, site)?;
            push!(result);
        }
        Op::GetPrivate(..) => {
            let base = pop!();
            let value = i.private_get_vm(name, &base, private_env, site)?;
            push!(value);
        }
        Op::GetPrivateKeep(..) | Op::GetPrivateMethod(..) => {
            let base = pop!();
            let value = i.private_get_vm(name, &base, private_env, site)?;
            push!(base);
            push!(value);
        }
        _ => {
            let value = pop!();
            let base = pop!();
            i.private_set_vm(name, &base, value.clone(), private_env, site)?;
            push!(value);
        }
    }
    Ok(())
}

pub(crate) unsafe extern "C" fn jit_exec(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let chunk = &*(*ctx).chunk;
    let _inline_position = ImplicitCallPosition::enter((*ctx).interp, chunk, pc as usize);
    if matches!(
        chunk.ops[pc as usize],
        Op::PrivateIn(..)
            | Op::GetPrivate(..)
            | Op::GetPrivateKeep(..)
            | Op::GetPrivateMethod(..)
            | Op::SetPrivate(..)
    ) {
        let ctx = &mut *ctx;
        jit_opstat(ctx, pc);
        return match jit_private_op_inner(ctx, pc, &mut sp) {
            Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
            Err(error) => {
                ctx.throw_at(pc, error);
                crate::jit::SpFlag { sp, flag: 1 }
            }
        };
    }
    if matches!(
        chunk.ops[pc as usize],
        Op::ResolveNameRef(..) | Op::LoadRef(_) | Op::StoreRef(_)
    ) {
        return jit_reference_op(ctx, pc, sp);
    }
    if jit_scope_operation(&chunk.ops[pc as usize]) {
        return jit_scope_op(ctx, pc, sp);
    }
    if jit_object_literal_operation(&chunk.ops[pc as usize]) {
        return jit_object_literal(ctx, pc, sp);
    }
    if jit_bridge_op(&chunk.ops[pc as usize]) {
        return jit_vm_operation(ctx, pc, sp);
    }
    #[cfg(test)]
    if matches!(chunk.ops[pc as usize], Op::Tdz(_) | Op::ResetSlots(..)) {
        TEST_JIT_LOCAL_RESET_HELPERS.with(|count| count.set(count.get() + 1));
    }
    #[cfg(test)]
    if matches!(
        unsafe { &(&(*(*ctx).chunk).ops)[pc as usize] },
        Op::GetElem
            | Op::GetElemLocal(_)
            | Op::SetElem
            | Op::SetElemDrop
            | Op::SetElemLocal(_)
            | Op::SetElemLocalDrop(_)
    ) {
        TEST_JIT_EXEC_ELEMENT_HELPERS.with(|count| count.set(count.get() + 1));
    }
    #[cfg(test)]
    if matches!(
        unsafe { &(&(*(*ctx).chunk).ops)[pc as usize] },
        Op::UpdateElem(_)
    ) {
        TEST_JIT_UPDATE_ELEM_HELPERS.with(|count| count.set(count.get() + 1));
    }
    let ctx = &mut *ctx;
    jit_opstat(ctx, pc);
    let result = if makes_explicit_call(&chunk.ops[pc as usize]) {
        let i = &mut *ctx.interp;
        explicit_call(i, call_op_position(chunk, pc as usize), |_| {
            jit_exec_inner(ctx, pc, &mut sp)
        })
    } else {
        jit_exec_inner(ctx, pc, &mut sp)
    };
    match result {
        Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
        Err(ab) => {
            ctx.throw_at(pc, ab);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

/// Drop one wide boundary Value (`this`, return or hardware-saved state), never an execution
/// word. Generated packed local/operand/property drops use `jit_drop_packed_at` explicitly.
pub(crate) unsafe extern "C" fn jit_drop_at(
    _ctx: *mut crate::jit::JitCtx,
    _imm: u32,
    sp: *mut Value,
) -> *mut Value {
    std::ptr::drop_in_place(sp);
    sp
}

/// Drop one NaN-boxed execution or property owner at `word`. Generated stores use this only
/// after all observable guards pass; packed destruction cannot execute JavaScript.
pub(crate) unsafe extern "C" fn jit_drop_packed_at(
    _ctx: *mut crate::jit::JitCtx,
    _imm: u32,
    word: *mut PackedValue,
) -> *mut PackedValue {
    unsafe { crate::value::PackedValue::drop_raw(word.cast::<u64>()) };
    word
}

/// Strict equality fallback for cases intentionally left out of the generated fast path:
/// equal-length string content, BigInts, and operands whose last owner must run a destructor.
/// This operation cannot throw, so it can bypass the generic bytecode decoder and stack/slot
/// adaptation while retaining ordinary `Value` ownership semantics.
pub(crate) unsafe extern "C" fn jit_strict_eq(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = unsafe { &mut *ctx };
    let chunk = unsafe { &*ctx.chunk };
    let op = &chunk.ops[pc as usize];
    debug_assert!(matches!(op, Op::StrictEq | Op::StrictNotEq));
    let base = unsafe { sp.sub(2) };
    let left = unsafe { base.read().into_value() };
    let right = unsafe { base.add(1).read().into_value() };
    let mut equal = unsafe { (&*ctx.interp).strict_equals(&left, &right) };
    if matches!(op, Op::StrictNotEq) {
        equal = !equal;
    }
    unsafe { base.write(PackedValue::pack(Value::Bool(equal))) };
    crate::jit::SpFlag {
        sp: unsafe { base.add(1) },
        flag: 0,
    }
}

/// Allocate a fresh RegExp literal wrapper from the chunk's per-site compiled matcher.
pub(crate) unsafe extern "C" fn jit_make_regexp(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = unsafe { &mut *ctx };
    let chunk = unsafe { &*ctx.chunk };
    let Op::MakeRegExp(body, flags) = chunk.ops[pc as usize] else {
        return unsafe { jit_exec(ctx, pc, sp) };
    };
    match chunk.make_regexp_literal(unsafe { &mut *ctx.interp }, pc as usize, body, flags) {
        Ok(value) => {
            observe_allocation(
                &chunk.feedback,
                pc as usize,
                crate::feedback::AllocationObjectKind::RegExp,
                chunk.names[body as usize]
                    .len()
                    .saturating_add(chunk.names[flags as usize].len()),
            );
            unsafe { sp.write(PackedValue::pack(value)) };
            crate::jit::SpFlag {
                sp: unsafe { sp.add(1) },
                flag: 0,
            }
        }
        Err(abrupt) => {
            ctx.throw_at(pc, abrupt);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

/// Fast `String + String` after the generated-code tag guards. Moving the left operand out of
/// the stack lets a temporary concatenation grow in place; otherwise the replacement reserves
/// spare capacity so a following concatenation can do so. This is the ordinary string-add
/// operation, independent of source or benchmark identity.
pub(crate) unsafe extern "C" fn jit_add_strings(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let base = unsafe { sp.sub(2) };
    if !matches!(unsafe { &(*base).unpack() }, Value::Str(_))
        || !matches!(unsafe { &(*base.add(1)).unpack() }, Value::Str(_))
    {
        return unsafe { jit_exec(ctx, pc, sp) };
    }

    let Value::Str(left) = (unsafe { base.read().into_value() }) else {
        unreachable!()
    };
    let Value::Str(right) = (unsafe { base.add(1).read().into_value() }) else {
        unreachable!()
    };
    if left.len().saturating_add(right.len()) > crate::interpreter::MAX_STR_LEN {
        let ctx = unsafe { &mut *ctx };
        let i = unsafe { &mut *ctx.interp };
        let error = i.throw("RangeError", "Invalid string length");
        unsafe { ctx.throw_at(pc, error) };
        return crate::jit::SpFlag { sp: base, flag: 1 };
    }

    let ctx = unsafe { &mut *ctx };
    let chunk = unsafe { &*ctx.chunk };
    if let Some(Op::StoreLocal(slot)) = chunk.ops.get(pc as usize + 1) {
        // Inspect/retire this one packed owner. The operand `left` keeps it alive here.
        let word = unsafe { ctx.slots.cast::<u64>().add(*slot as usize) };
        let current = unsafe { crate::value::PackedValue::clone_raw(word) };
        let same =
            matches!(&current, Value::Str(current) if crate::lstr::LStr::ptr_eq(current, &left));
        drop(current);
        if same {
            unsafe { crate::value::PackedValue::replace_raw(word, Value::Undefined) };
        }
    } else if let Some(Op::StoreCap(name)) = chunk.ops.get(pc as usize + 1) {
        // As in jit_exec_inner, env_raw is the running environment swapped for this native
        // frame, not a borrowed pointer to the caller's environment. Its existing owner outlives
        // the call. The captured binding lives in the body's activation record, which env_raw
        // leaves inside a block or `with` scope.
        let env = std::mem::ManuallyDrop::new(unsafe {
            crate::interpreter::Env::from_raw(
                ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
            )
        });
        let cap_env = unsafe { jit_cap_env(ctx, &env) };
        chunk.release_overwritten_captured_string(cap_env, *name, &left);
    }

    unsafe { base.write(PackedValue::pack(Value::Str(left.concat_owned(&right)))) };
    crate::jit::SpFlag {
        sp: unsafe { base.add(1) },
        flag: 0,
    }
}

#[cfg(test)]
thread_local! {
    pub(crate) static TEST_JIT_CODE_POINT_INTRINSICS: std::cell::Cell<usize> = const {
        std::cell::Cell::new(0)
    };
}

/// Hot native intrinsics after the machine-code call IC has already proved builtin identity.
/// Emitted guards keep string/property intrinsics on non-coercing cases. Function#apply performs
/// its own dense-list guards; Array push/pop transfer ownership directly between the operand
/// stack and dense storage. Every guard miss invokes the exact builtin implementation.
/// [`jit_intrinsic_inner`] as the explicit call it is: the callee records the call's position.
pub(crate) unsafe extern "C" fn jit_intrinsic(
    ctx: *mut crate::jit::JitCtx,
    packed: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let site = (packed & 0xFFFF) as usize;
    let i = unsafe { &mut *(*ctx).interp };
    let position = call_op_position(unsafe { &*(*ctx).chunk }, site);
    explicit_call(i, position, |_| unsafe {
        jit_intrinsic_inner(ctx, packed, sp)
    })
}

unsafe fn jit_intrinsic_inner(
    ctx: *mut crate::jit::JitCtx,
    packed: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    let i = &mut *ctx.interp;
    let intrinsic = (packed >> 16) as u8;
    let call_argc = (packed >> 24) as usize;
    let _pc = (packed & 0xffff) as usize;
    let width = match intrinsic {
        INTRINSIC_CHAR_AT | INTRINSIC_CODE_POINT_AT => 3, // [receiver, callee, index]
        INTRINSIC_CHAR_CODE_AT | INTRINSIC_FROM_CHAR_CODE => 3, // [receiver, callee, Number]
        INTRINSIC_ARRAY_PUSH => 3,                        // [receiver, callee, arg]
        INTRINSIC_ARRAY_POP => 2,                         // [receiver, callee]
        INTRINSIC_FUNCTION_CALL => call_argc + 2,
        INTRINSIC_REGEXP_EXEC_DISCARD => 3,
        INTRINSIC_STRING_SPLIT_DISCARD => 3,
        _ => 4, // [receiver, callee, arg0, arg1]
    };
    let base = sp.sub(width);
    if intrinsic == INTRINSIC_CHAR_CODE_AT || intrinsic == INTRINSIC_FROM_CHAR_CODE {
        // [receiver, callee, Number]. String.prototype.charCodeAt on a String receiver and
        // String.fromCharCode (ECMA-262 §22.1.3.2, §22.1.2.1) run no author code for a Number
        // argument and only read or intern a string, so they need none of the native-call
        // boundary below. The template proved the operand types.
        // Move the three owners out; each is released exactly once below.
        let receiver = base.read().into_value();
        let callee = base.add(1).read();
        let Value::Num(n) = base.add(2).read().into_value() else {
            unreachable!("Number argument guard")
        };
        let value = if intrinsic == INTRINSIC_CHAR_CODE_AT {
            let Value::Str(s) = &receiver else {
                unreachable!("charCodeAt receiver guard")
            };
            let idx = if n.is_nan() { 0.0 } else { n.trunc() };
            let unit = if idx < 0.0 || !idx.is_finite() {
                None
            } else {
                i.unit_at(s, idx as usize)
            };
            Value::Num(unit.map_or(f64::NAN, f64::from))
        } else {
            Value::Str(crate::jstr::unit_lstr(crate::builtins::uint16_of_number(n)))
        };
        drop(callee);
        drop(receiver);
        base.write(PackedValue::pack(value));
        return crate::jit::SpFlag {
            sp: base.add(1),
            flag: 0,
        };
    }
    if intrinsic == INTRINSIC_ARRAY_PUSH {
        // [receiver, callee, value]. A guarded dense append runs no author code, so it needs
        // none of the native-call boundary below (depth, safepoint, new.target bookkeeping).
        if let Value::Obj(receiver) = (*base).unpack() {
            let value = base.add(2).read();
            match crate::builtins::array_push_dense_packed(i, &receiver, value) {
                Ok(length) => {
                    drop(receiver);
                    std::ptr::drop_in_place(base);
                    std::ptr::drop_in_place(base.add(1));
                    base.write(PackedValue::pack(Value::Num(length as f64)));
                    return crate::jit::SpFlag {
                        sp: base.add(1),
                        flag: 0,
                    };
                }
                // Nothing changed: restore the moved owner for the general path.
                Err(value) => base.add(2).write(value),
            }
        }
    }
    let mut this_moved = false;
    let mut push_arg_moved = false;
    let mut call_args_moved = 0usize;
    i.depth += 1;
    let exhausted = crate::interpreter::execution_stack_exhausted(i.depth);
    let r: Result<Value, Abrupt> = if exhausted {
        Err(i.throw("RangeError", "Maximum call stack size exceeded"))
    } else {
        crate::interpreter::with_execution_stack(i.depth, || {
            i.gc_check_amortized().and_then(|()| {
                // Match `call_native_committed`: native code and any observable fallback it invokes
                // run outside a pending construction. Dense push/pop themselves cannot observe
                // these fields, but a prototype setter or unusual array-like on the miss path can.
                let saved_ctor = std::mem::replace(&mut i.constructing, false);
                let saved_nt = std::mem::replace(&mut i.new_target, Value::Undefined);
                let r = match intrinsic {
                    INTRINSIC_CHAR_AT => {
                        let Value::Str(s) = &(*base).unpack() else {
                            unreachable!("charAt intrinsic receiver guard")
                        };
                        let Value::Num(n) = &(*base.add(2)).unpack() else {
                            unreachable!("charAt intrinsic index guard")
                        };
                        let idx = if n.is_nan() { 0.0 } else { n.trunc() };
                        Ok(if idx < 0.0 || !idx.is_finite() {
                            Value::lstr("")
                        } else {
                            match i.unit_at(s, idx as usize) {
                                Some(unit) => Value::Str(crate::jstr::unit_lstr(unit)),
                                None => Value::lstr(""),
                            }
                        })
                    }
                    INTRINSIC_CODE_POINT_AT => {
                        #[cfg(test)]
                        TEST_JIT_CODE_POINT_INTRINSICS.with(|count| count.set(count.get() + 1));
                        let Value::Str(s) = &(*base).unpack() else {
                            unreachable!("codePointAt intrinsic receiver guard")
                        };
                        let Value::Num(n) = &(*base.add(2)).unpack() else {
                            unreachable!("codePointAt intrinsic index guard")
                        };
                        let idx = if n.is_nan() { 0.0 } else { n.trunc() };
                        Ok(if idx < 0.0 || !idx.is_finite() {
                            Value::Undefined
                        } else {
                            i.code_point_at(s, idx as usize)
                                .map_or(Value::Undefined, |point| Value::Num(point as f64))
                        })
                    }
                    INTRINSIC_STRING_SLICE => {
                        let Value::Str(s) = &(*base).unpack() else {
                            unreachable!("slice intrinsic receiver guard")
                        };
                        let Value::Num(start) = &(*base.add(2)).unpack() else {
                            unreachable!("slice intrinsic start guard")
                        };
                        let Value::Num(end) = &(*base.add(3)).unpack() else {
                            unreachable!("slice intrinsic end guard")
                        };
                        debug_assert!(s.ascii_hint());
                        let len = s.len() as i64;
                        let norm = |n: f64| {
                            if n.is_nan() {
                                return 0;
                            }
                            let n = if n.is_infinite() {
                                if n > 0.0 {
                                    len
                                } else {
                                    -len - 1
                                }
                            } else {
                                n as i64
                            };
                            if n < 0 {
                                (len + n).max(0)
                            } else {
                                n.min(len)
                            }
                        };
                        let (start, end) = (norm(*start), norm(*end));
                        Ok(if start < end {
                            Value::Str(s.slice_bytes(start as usize, end as usize))
                        } else {
                            Value::lstr("")
                        })
                    }
                    INTRINSIC_OBJECT_HAS_OWN => {
                        let object @ Value::Obj(_) = &(*base.add(2)).unpack() else {
                            unreachable!("hasOwn intrinsic object guard")
                        };
                        let Value::Str(key) = &(*base.add(3)).unpack() else {
                            unreachable!("hasOwn intrinsic key guard")
                        };
                        crate::builtins::has_own_property_trapped(
                            i,
                            object,
                            &crate::value::encode_string_key(key),
                        )
                        .map(Value::Bool)
                        .map_err(Abrupt::Throw)
                    }
                    INTRINSIC_FUNCTION_CALL => {
                        // `target.call(thisArg, arg)`: transfer thisArg + the single forwarded argument
                        // directly into a compiled target frame. A failed applicability probe has no
                        // side effects, so proxies, native targets, and unusual closures invoke the
                        // exact Function.prototype.call builtin.
                        debug_assert!(call_argc >= 1);
                        let forwarded = call_argc - 1;
                        match i.call_jit_fast(
                            &(*base).unpack(),
                            base.add(2),
                            base.add(3),
                            forwarded,
                            None,
                        ) {
                            Some(r) => {
                                this_moved = true;
                                call_args_moved = forwarded;
                                r
                            }
                            None => crate::builtins::nf_function_call(
                                i,
                                (*base).unpack(),
                                &DecodedArgs::new(std::slice::from_raw_parts(
                                    base.add(2),
                                    call_argc,
                                )),
                            )
                            .map_err(Abrupt::Throw),
                        }
                    }
                    INTRINSIC_FUNCTION_APPLY => {
                        // The dominant `initialize.apply(this, arguments)` shape has an unmapped,
                        // own-dense arguments object. Clone its entries once, then move them straight
                        // into an already-JIT-compiled target frame. No observable operation occurs
                        // before every list guard has passed; unusual array-likes and non-JIT targets
                        // execute the named builtin unchanged.
                        let dense = match (&(*base).unpack(), &(*base.add(3)).unpack()) {
                            (Value::Obj(_), Value::Obj(list))
                                if i.ordinary_get_ptr(crate::value::Gc::as_ptr(list) as usize)
                                    && !i.mapped_arguments.contains_key(
                                        &(crate::value::Gc::as_ptr(list) as usize),
                                    ) =>
                            {
                                let b = list.borrow();
                                let len = match b.props.get("length") {
                                    Some(p) if !p.accessor() => match p.value() {
                                        Value::Num(n)
                                            if n >= 0.0
                                                && n.is_finite()
                                                && n.fract() == 0.0
                                                && n <= crate::interpreter::MAX_ARGUMENTS_LEN
                                                    as f64 =>
                                        {
                                            Some(n as usize)
                                        }
                                        _ => None,
                                    },
                                    _ => None,
                                };
                                len.and_then(|len| {
                                    let mut values = Vec::with_capacity(len);
                                    for k in 0..len {
                                        let value = b
                                            .props
                                            .get_index(k as u32)
                                            .filter(|p| !p.accessor())
                                            .map(|p| p.value())?;
                                        values.push(PackedValue::pack(value));
                                    }
                                    Some(values)
                                })
                            }
                            _ => None,
                        };
                        if let Some(mut values) = dense {
                            match i.call_jit_fast(
                                &(*base).unpack(),
                                base.add(2),
                                values.as_mut_ptr(),
                                values.len(),
                                None,
                            ) {
                                Some(r) => {
                                    // `call_jit_fast` moved every Vec element and the original thisArg.
                                    values.set_len(0);
                                    this_moved = true;
                                    r
                                }
                                None => crate::builtins::nf_function_apply(
                                    i,
                                    (*base).unpack(),
                                    &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 2)),
                                )
                                .map_err(Abrupt::Throw),
                            }
                        } else {
                            crate::builtins::nf_function_apply(
                                i,
                                (*base).unpack(),
                                &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 2)),
                            )
                            .map_err(Abrupt::Throw)
                        }
                    }
                    INTRINSIC_ARRAY_PUSH => {
                        let Value::Obj(o) = &(*base).unpack() else {
                            unreachable!("push intrinsic receiver guard")
                        };
                        let arg = base.add(2).read().into_value();
                        push_arg_moved = true;
                        match crate::builtins::jit_array_push_one(i, o, arg) {
                            Ok(v) => Ok(v),
                            Err(arg) => {
                                // The transfer helper promises a guard miss has no side effects and
                                // returns the original owner, so the generic builtin sees the exact
                                // operand stack it would have seen without specialization.
                                base.add(2).write(PackedValue::pack(arg));
                                push_arg_moved = false;
                                crate::builtins::nf_array_push(
                                    i,
                                    (*base).unpack(),
                                    &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 1)),
                                )
                                .map_err(Abrupt::Throw)
                            }
                        }
                    }
                    INTRINSIC_ARRAY_POP => {
                        let Value::Obj(o) = &(*base).unpack() else {
                            unreachable!("pop intrinsic receiver guard")
                        };
                        match crate::builtins::jit_array_pop(i, o) {
                            Some(v) => Ok(v),
                            None => crate::builtins::nf_array_pop(i, (*base).unpack(), &[])
                                .map_err(Abrupt::Throw),
                        }
                    }
                    INTRINSIC_REGEXP_EXEC_DISCARD => {
                        let (Value::Obj(_), Value::Str(input)) =
                            (&(*base).unpack(), &(*base.add(2)).unpack())
                        else {
                            unreachable!("regexp exec intrinsic guards")
                        };
                        match crate::builtins::regexp_exec_discard_fast(i, &(*base).unpack(), input)
                        {
                            Some(r) => {
                                i.interrupt_poll_force()?;
                                r.map(|_| Value::Undefined).map_err(Abrupt::Throw)
                            }
                            None => crate::builtins::regexp_exec(
                                i,
                                (*base).unpack(),
                                &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 1)),
                            )
                            .map_err(Abrupt::Throw),
                        }
                    }
                    INTRINSIC_STRING_REPLACE_DISCARD => {
                        match crate::builtins::string_replace_discard_fast(
                            i,
                            &(*base).unpack(),
                            &(*base.add(2)).unpack(),
                            &(*base.add(3)).unpack(),
                        ) {
                            Some(r) => {
                                i.interrupt_poll_force()?;
                                r.map_err(Abrupt::Throw)
                            }
                            None => crate::builtins::nf_string_replace(
                                i,
                                (*base).unpack(),
                                &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 2)),
                            )
                            .map_err(Abrupt::Throw),
                        }
                    }
                    INTRINSIC_STRING_SPLIT_DISCARD => {
                        match crate::builtins::string_split_discard_fast(
                            i,
                            &(*base).unpack(),
                            &(*base.add(2)).unpack(),
                            &Value::Undefined,
                        ) {
                            Some(r) => r.map_err(Abrupt::Throw),
                            None => crate::builtins::nf_string_split(
                                i,
                                (*base).unpack(),
                                &DecodedArgs::new(std::slice::from_raw_parts(base.add(2), 1)),
                            )
                            .map_err(Abrupt::Throw),
                        }
                    }
                    _ => unreachable!("unknown JIT intrinsic"),
                };
                i.constructing = saved_ctor;
                i.new_target = saved_nt;
                r
            })
        })
    };
    i.depth -= 1;
    // Every operand is still owned by the caller stack. Drop after the result has finished
    // borrowing any receiver/key storage, then reuse the receiver slot.
    for k in 0..width {
        if (!this_moved || k != 2)
            && (!push_arg_moved || k != 2)
            && (call_args_moved == 0 || k < 3 || k >= 3 + call_args_moved)
        {
            std::ptr::drop_in_place(base.add(k));
        }
    }
    match r {
        Ok(v) => {
            base.write(PackedValue::pack(v));
            crate::jit::SpFlag {
                sp: base.add(1),
                flag: 0,
            }
        }
        Err(ab) => {
            ctx.throw_at(packed & 0xFFFF, ab);
            crate::jit::SpFlag { sp: base, flag: 1 }
        }
    }
}

/// Teardown for a direct JIT→JIT call, the slow path of the generated finish stub. The callee
/// ran on its own pooled record ([`crate::jit::JitFrame`]); this drops whatever it left (operand
/// stack range and slots), moves its completion (return value or error) into the caller's
/// context, returns the record to the pool, pops the FnFrame (including a materialized `extra`),
/// drains a pending tail call and decrements the recursion depth. The caller's generated code
/// then pushes `caller.ret` or unwinds with `caller.error`.
/// Returns 0 = ok (`caller.ret` valid) / 1 = threw (`caller.error` set).
///
/// # Safety
/// `callee` must be the finished record the direct-call sequence popped for this call, and
/// `caller` the live context of the calling frame.
pub(crate) unsafe extern "C" fn jit_direct_finish(
    caller: *mut crate::jit::JitCtx,
    callee: *mut crate::jit::JitCtx,
    threw: u32,
) -> u64 {
    let caller = &mut *caller;
    let record = std::ptr::NonNull::new_unchecked(callee.cast::<crate::jit::JitFrame>());
    let callee = &mut *callee;
    let i = &mut *callee.interp;
    // Leftover operand stack (only on throw; clean returns leave it empty).
    let mut p = callee.stack_base;
    while p < callee.final_sp {
        std::ptr::drop_in_place(p);
        p = p.add(1);
    }
    // Exact packed-owner destruction; numeric words require no heap operation.
    for k in 0..callee.n_slots {
        std::ptr::drop_in_place(callee.slots.add(k));
    }
    let mut threw = threw != 0;
    if threw {
        caller.error = Some(
            callee
                .error
                .take()
                .unwrap_or(Abrupt::Throw(Value::Undefined)),
        );
    } else {
        caller.ret = callee.take_ret();
    }
    // Returning from inside a try bypasses the lexical PopHandler; `release` also discards the
    // callee's own handler records (ECMA-262 14.10.1 and 14.15.3) and its `this` binding.
    crate::jit::JitFrame::release(i, record);
    // FnFrame pop (the asm pushed it; a materialized `extra` drops here). The caller's direct
    // call never set `call_site`, so no explicit call is in progress once it returns.
    if let Some(f) = i.fn_frames.pop() {
        drop(f.extra);
    }
    i.call_site = crate::stack_trace::NO_POSITION;
    // Proper-tail-call trampoline, exactly like the layered paths.
    if !threw {
        while let Some(bx) = i.pending_tail.take() {
            let (f, t, a) = *bx;
            let r = i.gc_check_amortized().and_then(|()| i.call_tail(f, t, &a));
            match r {
                Ok(v) => caller.ret = PackedValue::pack(v),
                Err(e) => {
                    caller.error = Some(e);
                    threw = true;
                    break;
                }
            }
        }
    }
    i.depth -= 1;
    threw as u64
}

/// The call template's inline-probe HIT entry: the emitted code already validated one way
/// (callee identity + epoch + realm — the way index rides in bits 16.. of `pc`, the pc itself
/// in the low 16), so this skips the probe loop — it re-reads that entry (nothing ran between
/// the machine-code compare and this call), bumps the recompile counter, and enters the
/// committed path directly. Same contract as [`jit_exec`].
/// `Reflect.apply(target, thisArg, list)` from a proven call-cache hit, when `target` is an
/// operand-only native in this Realm and `list` is an ordinary array-like whose length and
/// elements are own data properties (CreateListFromArrayLike then observes nothing). Calls the
/// target directly and consumes the call's operands; `None` (nothing consumed) otherwise.
///
/// # Safety
/// As for [`jit_call_hit`]: `sp` is the live operand top of a `CallWithThis(3)`/`Call(3)` site.
unsafe fn jit_reflect_apply_operand_only(
    ctx: &mut crate::jit::JitCtx,
    sp: *mut PackedValue,
    with_this: bool,
) -> Option<crate::jit::SpFlag> {
    let i = &mut *ctx.interp;
    let args_ptr = sp.sub(3);
    let target = (*args_ptr).unpack();
    let Value::Obj(target_object) = &target else {
        return None;
    };
    let nf = {
        let object = target_object.borrow();
        match &object.call {
            crate::value::Callable::Native(nf)
                if object.ic_plain.get() && i.native_call_in_current_realm(target_object) =>
            {
                *nf
            }
            _ => return None,
        }
    };
    let list = (*args_ptr.add(2)).unpack();
    let numeric = crate::builtins::is_numeric_only_native(nf);
    if !crate::builtins::is_operand_only_native(nf) && !numeric {
        return None;
    }
    let values = dense_own_list(i, &list)?;
    if numeric && !values.iter().all(|value| matches!(value, Value::Num(_))) {
        return None;
    }
    drop((target, list));
    let this_arg = args_ptr.add(1).read().into_value();
    let r = nf(i, this_arg, &values);
    // Release the target, the list, the Reflect.apply function and its receiver.
    drop(args_ptr.read());
    drop(args_ptr.add(2).read());
    let mut base = args_ptr.sub(1);
    drop(base.read());
    if with_this {
        base = base.sub(1);
        drop(base.read());
    }
    Some(match r {
        Ok(v) => {
            base.write(PackedValue::pack(v));
            crate::jit::SpFlag {
                sp: base.add(1),
                flag: 0,
            }
        }
        Err(error) => {
            ctx.error = Some(Abrupt::Throw(error));
            crate::jit::SpFlag { sp: base, flag: 1 }
        }
    })
}

/// The elements of an ordinary array-like whose `length` and indices `0..length` are all own
/// data properties: CreateListFromArrayLike's Gets then run no author code.
fn dense_own_list(i: &Interp, list: &Value) -> Option<Vec<Value>> {
    let Value::Obj(list) = list else {
        return None;
    };
    if !i.ordinary_get_ptr(crate::value::Gc::as_ptr(list) as usize)
        || i.mapped_arguments
            .contains_key(&(crate::value::Gc::as_ptr(list) as usize))
    {
        return None;
    }
    let b = list.borrow();
    let len = match b.props.get("length") {
        Some(p) if !p.accessor() => match p.value() {
            Value::Num(n) if n >= 0.0 && n.fract() == 0.0 && n <= 64.0 => n as usize,
            _ => return None,
        },
        _ => return None,
    };
    let mut values = Vec::with_capacity(len);
    for k in 0..len {
        let value = b
            .props
            .get_index(k as u32)
            .filter(|p| !p.accessor())
            .map(|p| p.value())?;
        values.push(value);
    }
    Some(values)
}

/// [`jit_call_hit_inner`] as the explicit call it is: the callee records the call's position.
pub(crate) unsafe extern "C" fn jit_call_hit(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let site = (pc & 0xFFFF) as usize;
    let i = unsafe { &mut *(*ctx).interp };
    let position = call_op_position(unsafe { &*(*ctx).chunk }, site);
    explicit_call(i, position, |_| unsafe { jit_call_hit_inner(ctx, pc, sp) })
}

unsafe fn jit_call_hit_inner(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    let way = (pc >> 16) as usize & (CALL_IC_WAYS - 1);
    let pc = pc & 0xFFFF;
    jit_opstat(ctx, pc);
    let i = &mut *ctx.interp;
    let chunk = &*ctx.chunk;
    // Detailed profiling disables the inline probe at compile time, but keep this helper
    // semantically complete if a previously emitted chunk reaches it after instrumentation is
    // enabled. The profiled path must observe before dispatch and must not consume moved slots.
    if chunk.feedback.detailed_enabled() {
        return match jit_call_inner(ctx, pc, &mut sp) {
            Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
            Err(ab) => {
                ctx.error = Some(ab);
                crate::jit::SpFlag { sp, flag: 1 }
            }
        };
    }
    let (argc, c, with_this) = match chunk.ops[pc as usize] {
        Op::CallWithThis(argc, c) => (argc as usize, c, true),
        Op::Call(argc, c) => (argc as usize, c, false),
        _ => unreachable!("jit_call_hit emitted only for call ops"),
    };
    let entry = &chunk.call_caches[c as usize].entries[way];
    // A native entry needs two words of the way: read them in place. Copying the whole entry
    // first (a dozen words through vector stores) made every native call wait for the copy.
    let (native, intrinsic) = {
        // SAFETY: the Cell holds plain-old-data and nothing writes it during this read.
        let entry = unsafe { &*entry.as_ptr() };
        (entry.native, entry.intrinsic)
    };
    if native != 0 {
        return jit_call_hit_native(ctx, sp, argc, with_this, native, intrinsic, entry);
    }
    let mut ic = entry.get();
    // A code-keyed probe hit (see `jit::emit_call_code_probe`) matched another closure of this
    // way's function. PrepareForOrdinaryCall's F is the LIVE closure: run the shared code with
    // its identity and [[Environment]], never the filling closure's (a local copy; the way is
    // unchanged, like `Interp::resolve_cached_call`'s code-sharing retry).
    // The callee's operand remains an owner through the whole committed call.
    // This observer-free inspection therefore needs no unpack/clone/drop round trip.
    let _ = (*sp.sub(argc + 1)).with_object(|callee| {
        let key = crate::value::Gc::as_ptr(callee) as usize;
        if key != ic.callee {
            if let crate::value::Callable::User(user) = &callee.borrow().call {
                debug_assert_eq!(Rc::as_ptr(&user.func), ic.func);
                ic.callee = key;
                ic.env = Env::as_ptr(&user.env);
            }
        }
    });
    // The emitted probe already validated this epoch. Acquire before inline
    // recompilation, which may now reclaim other inactive native code.
    let code = crate::jit::cache::lease_raw(ic.code);
    jit_callstat(i, ctx, &ic, argc, with_this, sp);
    let chunk_ref = &*ic.chunk;
    let runs = chunk_ref.jit_runs.get().saturating_add(1);
    chunk_ref.jit_runs.set(runs);
    if chunk_ref.inline_retry_due(runs) {
        i.try_inline_recompile(ic.func, chunk_ref, ic.realm, ic.global_env);
    }
    let args_ptr = sp.sub(argc);
    let mut undef = std::mem::ManuallyDrop::new(PackedValue::pack(Value::Undefined));
    let this_slot: *const PackedValue = if with_this {
        sp.sub(argc + 2)
    } else {
        &raw mut *undef as *const PackedValue
    };
    let r = i.call_jit_committed(&ic, &code, this_slot, args_ptr, argc);
    // Arguments and `this` were moved; pop them virtually and drop only the callee slot
    // (same ownership story as jit_call_inner's Some arm).
    sp = args_ptr.sub(1);
    match sp.read().into_value() {
        Value::Obj(o) => crate::value::Gc::release(o),
        other => drop(other),
    }
    if with_this {
        sp = sp.sub(1); // `this` was consumed (moved) by the callee — skip, don't drop
    }
    match r {
        Ok(v) => {
            sp.write(PackedValue::pack(v));
            crate::jit::SpFlag {
                sp: sp.add(1),
                flag: 0,
            }
        }
        Err(ab) => {
            ctx.error = Some(ab);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

/// [`jit_call_hit_inner`]'s native-entry arm: the emitted probe proved the callee is the
/// way's builtin `native` (identity, epoch and realm). Consumes the callee, receiver and
/// arguments exactly like the user-function arm.
#[inline(always)]
unsafe fn jit_call_hit_native(
    ctx: &mut crate::jit::JitCtx,
    mut sp: *mut PackedValue,
    argc: usize,
    with_this: bool,
    native: usize,
    intrinsic: u8,
    entry: &std::cell::Cell<CallIc>,
) -> crate::jit::SpFlag {
    let i = &mut *ctx.interp;
    if ctx.callstat_enabled {
        jit_callstat(i, ctx, &entry.get(), argc, with_this, sp);
    }
    let operand_only = match intrinsic {
        INTRINSIC_OPERAND_ONLY => true,
        INTRINSIC_NUMERIC_ONLY | INTRINSIC_MATH_FIRST..=INTRINSIC_MATH_LAST => {
            (0..argc).all(|k| (*sp.sub(argc).add(k)).number().is_some())
        }
        INTRINSIC_DATAVIEW_GET | INTRINSIC_DATAVIEW_SET => {
            let checked = if intrinsic == INTRINSIC_DATAVIEW_SET {
                2
            } else {
                1
            };
            (0..argc.min(checked)).all(|k| (*sp.sub(argc).add(k)).is_primitive())
        }
        _ => false,
    };
    if intrinsic == INTRINSIC_REFLECT_APPLY && argc == 3 {
        if let Some(flag) = jit_reflect_apply_operand_only(ctx, sp, with_this) {
            return flag;
        }
    }
    let nf: crate::value::NativeFn = std::mem::transmute(native);
    let args_ptr = sp.sub(argc);
    let r = if operand_only {
        // The exact builtin is proven and runs no author code for these operands: move the
        // receiver and arguments into it directly, without an arbitrary native's call boundary.
        let this = if with_this {
            sp.sub(argc + 2).read().into_value()
        } else {
            Value::Undefined
        };
        crate::execution_storage::with_moved_values(args_ptr, argc, |args| nf(i, this, args))
            .map_err(Abrupt::Throw)
    } else {
        let mut undef = std::mem::ManuallyDrop::new(PackedValue::pack(Value::Undefined));
        let this_slot: *const PackedValue = if with_this {
            sp.sub(argc + 2)
        } else {
            &raw mut *undef as *const PackedValue
        };
        i.call_native_committed(nf, this_slot, args_ptr, argc)
    };
    // Arguments and `this` were moved; pop them virtually and drop only the callee slot.
    sp = args_ptr.sub(1);
    match sp.read().into_value() {
        Value::Obj(o) => crate::value::Gc::release(o),
        other => drop(other),
    }
    if with_this {
        sp = sp.sub(1); // `this` was consumed (moved) by the callee — skip, don't drop
    }
    match r {
        Ok(v) => {
            sp.write(PackedValue::pack(v));
            crate::jit::SpFlag {
                sp: sp.add(1),
                flag: 0,
            }
        }
        Err(ab) => {
            ctx.error = Some(ab);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

/// PropertyDefinitionEvaluation of `PropertyName : AssignmentExpression` into an object literal
/// under construction (ECMA-262 §13.2.5.5): NamedEvaluation's SetFunctionName for an anonymous
/// function definition, then CreateDataPropertyOrThrow, which cannot fail on the fresh,
/// extensible ordinary object. Runs no author code.
fn literal_define_data<K: AsRef<str> + crate::value::IntoPropKey>(
    i: &mut Interp,
    object: &crate::value::Gc,
    key: K,
    value: Value,
    anonymous: bool,
) {
    if anonymous {
        let name = i.fn_name_for_key(key.as_ref());
        i.set_fn_name(&value, &name);
    }
    object
        .borrow_mut()
        .props
        .insert(key, crate::value::Property::plain(value));
}

/// MethodDefinitionEvaluation (`kind` 0: DefineMethod, SetFunctionName, DefineMethodProperty) or
/// an accessor definition (1: getter, 2: setter; SetFunctionName with its "get"/"set" prefix,
/// then that half of the accessor) into an object literal under construction, closing over the
/// running LexicalEnvironment `env`. MakeMethod binds the literal as [[HomeObject]] only for a
/// method that can observe it (see `Function::observes_home_object`). Runs no author code and
/// cannot fail.
fn literal_define_method<K: AsRef<str> + crate::value::IntoPropKey>(
    i: &mut Interp,
    object: &crate::value::Gc,
    env: &Env,
    func: &Rc<Function>,
    key: K,
    kind: u8,
) {
    let method_env = if func.observes_home_object() {
        let home_env = crate::interpreter::new_scope(Some(env.clone()));
        crate::eval::bind(&home_env, "%homeobject%", Value::Obj(object.clone()));
        home_env
    } else {
        env.clone()
    };
    let value = i.make_function(func.clone(), method_env);
    let name = i.fn_name_for_key(key.as_ref());
    match kind {
        0 => {
            i.set_fn_name(&value, &name);
            object
                .borrow_mut()
                .props
                .insert(key, crate::value::Property::plain(value));
        }
        1 => {
            i.set_fn_name(&value, &format!("get {name}"));
            i.define_accessor(object, key.as_ref(), Some(value), None);
        }
        2 => {
            i.set_fn_name(&value, &format!("set {name}"));
            i.define_accessor(object, key.as_ref(), None, Some(value));
        }
        _ => unreachable!("object method kind is compiler-internal"),
    }
}

/// Whether `op` builds an object literal incrementally (see [`jit_object_literal`]).
fn jit_object_literal_operation(op: &Op) -> bool {
    matches!(
        op,
        Op::NewObject
            | Op::ObjectData(_)
            | Op::ObjectDataName(..)
            | Op::ObjectProto
            | Op::ObjectSpread
            | Op::ObjectMethod(..)
            | Op::ObjectMethodName(..)
    )
}

/// Dedicated incremental ObjectLiteral entry (same contract as [`jit_exec`]): the builder ops
/// operate on the native operand stack and the frame's current environment directly, without
/// the generic operation dispatch or a one-operation VM. The fresh object stays owned by the
/// operand stack while ToPropertyKey, getters and Proxy traps (CopyDataProperties) run.
pub(crate) unsafe extern "C" fn jit_object_literal(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    jit_opstat(ctx, pc);
    let _inline_position = ImplicitCallPosition::enter(ctx.interp, &*ctx.chunk, pc as usize);
    match jit_object_literal_inner(ctx, pc, &mut sp) {
        Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
        Err(ab) => {
            ctx.throw_at(pc, ab);
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

unsafe fn jit_object_literal_inner(
    ctx: &mut crate::jit::JitCtx,
    pc: u32,
    sp: &mut *mut PackedValue,
) -> Result<(), Abrupt> {
    let i = &mut *ctx.interp;
    let chunk = &*ctx.chunk;
    macro_rules! pop {
        () => {{
            *sp = sp.sub(1);
            sp.read().into_value()
        }};
    }
    // The builder object under construction, borrowed from the operand stack (which keeps it
    // alive and owned across any fallible step).
    macro_rules! builder {
        () => {{
            let Value::Obj(object) = (*sp.sub(1)).unpack() else {
                unreachable!("object literal builder retains an Object")
            };
            object
        }};
    }
    match chunk.ops[pc as usize] {
        Op::NewObject => {
            let value = Value::Obj(i.new_object());
            observe_allocation(
                &chunk.feedback,
                pc as usize,
                crate::feedback::AllocationObjectKind::Object,
                0,
            );
            sp.write(PackedValue::pack(value));
            *sp = sp.add(1);
        }
        Op::ObjectData(name_anonymous) => {
            // pop! updates the unwind boundary before any fallible work; moved key/value
            // owners are dropped by Rust on an abrupt completion, never again by the JIT.
            let value = pop!();
            let key = pop!();
            let key = i.to_property_key(&key)?;
            literal_define_data(i, &builder!(), key.as_str(), value, name_anonymous);
        }
        Op::ObjectDataName(name, name_anonymous) => {
            let value = pop!();
            let key = chunk.names[name as usize].clone();
            literal_define_data(i, &builder!(), key, value, name_anonymous);
        }
        Op::ObjectProto => {
            let prototype = pop!();
            // A fresh, unexposed ordinary object, not an author-visible __proto__ assignment.
            // Primitive values other than null are ignored.
            let object = builder!();
            match prototype {
                Value::Obj(prototype) => object.borrow_mut().proto = Some(prototype),
                Value::Null => object.borrow_mut().proto = None,
                _ => {}
            }
        }
        Op::ObjectSpread => {
            // ECMA-262 CopyDataProperties: consume the source before any fallible operation so
            // unwind cannot drop it twice.
            let source = pop!();
            i.copy_data_properties_into(&builder!(), &source, &[])?;
        }
        Op::ObjectMethod(function, kind) | Op::ObjectMethodName(function, kind, _) => {
            let key = match chunk.ops[pc as usize] {
                Op::ObjectMethodName(_, _, name) => {
                    crate::value::PropertyKey::stored(chunk.names[name as usize].to_string())
                }
                _ => {
                    let key = pop!();
                    i.to_property_key(&key)?
                }
            };
            let env = std::mem::ManuallyDrop::new(crate::interpreter::Env::from_raw(
                ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
            ));
            let func = &chunk.funcs[function as usize];
            literal_define_method(i, &builder!(), &env, func, key.as_str(), kind);
        }
        _ => unreachable!("jit_object_literal emitted only for object literal builder ops"),
    }
    Ok(())
}

/// Dedicated `Op::MakeClosure` entry (same contract as [`jit_exec`]): InstantiateOrdinaryFunction
/// Expression / ArrowFunction evaluation (OrdinaryFunctionCreate over the running execution
/// context's LexicalEnvironment, plus NamedEvaluation's name) without the generic operation
/// dispatch. The environment is the frame's current one, exactly as `jit_exec_inner` derives it;
/// creating a closure runs no author code and cannot throw.
pub(crate) unsafe extern "C" fn jit_make_closure(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    jit_opstat(ctx, pc);
    let i = &mut *ctx.interp;
    let chunk = &*ctx.chunk;
    let Op::MakeClosure(function, name) = chunk.ops[pc as usize] else {
        unreachable!("jit_make_closure emitted only for MakeClosure");
    };
    // Borrowed, like `jit_exec_inner`: the frame keeps its current environment alive.
    let env = std::mem::ManuallyDrop::new(crate::interpreter::Env::from_raw(
        ctx.env_raw as *const std::cell::RefCell<crate::interpreter::Scope>,
    ));
    let name = (name != u32::MAX).then(|| &chunk.names[name as usize]);
    let closure =
        i.make_function_named(chunk.funcs[function as usize].clone(), (*env).clone(), name);
    observe_allocation(
        &chunk.feedback,
        pc as usize,
        crate::feedback::AllocationObjectKind::Function,
        0,
    );
    sp.write(PackedValue::pack(closure));
    crate::jit::SpFlag {
        sp: sp.add(1),
        flag: 0,
    }
}

/// Dedicated `Op::MakeObject` entry (same contract as [`jit_exec`]): clones the site's
/// pre-shaped map and moves the values straight off the operand stack — no generic op
/// dispatch, no intermediate `Vec`.
pub(crate) unsafe extern "C" fn jit_make_object(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = &mut *ctx;
    jit_opstat(ctx, pc);
    let i = &mut *ctx.interp;
    let chunk = &*ctx.chunk;
    let Op::MakeObject(start, count, tidx) = chunk.ops[pc as usize] else {
        unreachable!("jit_make_object emitted only for MakeObject");
    };
    let count = count as usize;
    let base = sp.sub(count);
    let keys = &chunk.names[start as usize..start as usize + count];
    let v = if tidx != u32::MAX {
        i.make_plain_object_templated_from(&chunk.obj_maps[tidx as usize], keys, base, count)
    } else {
        let mut values = Vec::with_capacity(count);
        for k in 0..count {
            values.push(base.add(k).read().into_value());
        }
        i.make_plain_object_vm(keys, values)
    };
    observe_allocation(
        &chunk.feedback,
        pc as usize,
        crate::feedback::AllocationObjectKind::Object,
        count,
    );
    sp = base;
    sp.write(PackedValue::pack(v));
    crate::jit::SpFlag {
        sp: sp.add(1),
        flag: 0,
    }
}

/// Dedicated `Op::MakeArray` entry: moves the operand values directly into the fresh array's
/// dense property storage, avoiding both generic opcode dispatch and an intermediate `Vec`.
pub(crate) unsafe extern "C" fn jit_make_array(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = unsafe { &mut *ctx };
    jit_opstat(ctx, pc);
    let chunk = unsafe { &*ctx.chunk };
    let Op::MakeArray(count) = chunk.ops[pc as usize] else {
        unreachable!("jit_make_array emitted only for MakeArray");
    };
    let base = unsafe { sp.sub(count as usize) };
    let value = unsafe { (&*ctx.interp).make_array_from_raw(base, count as usize) };
    observe_allocation(
        &chunk.feedback,
        pc as usize,
        crate::feedback::AllocationObjectKind::Array,
        count as usize,
    );
    sp = base;
    unsafe { sp.write(PackedValue::pack(value)) };
    crate::jit::SpFlag {
        sp: unsafe { sp.add(1) },
        flag: 0,
    }
}

/// `Op::TryArrayBinding`: retain the source and its `next` method in the two hidden slots when
/// the closed Array prefix applies.
fn open_array_binding<S: StoredValue>(
    i: &mut Interp,
    slots: &[S],
    source: Value,
    iterator: u16,
    next: u16,
    count: u16,
) -> Result<bool, Abrupt> {
    let old_source = slots.read_value(iterator as usize);
    let old_next = slots.read_value(next as usize);
    let captured = i.try_array_binding(&source, count as usize, &old_source, &old_next)?;
    let matched = captured.is_some();
    if let Some(captured) = captured {
        slots.write_value(next as usize, captured);
        slots.write_value(iterator as usize, source);
    }
    Ok(matched)
}

/// Dedicated iterator-protocol entry for array destructuring and `for…of` steps: the same
/// operations as `jit_exec`, without the generic decoder in front of their intrinsic
/// Array/Map/Set fast paths.
pub(crate) unsafe extern "C" fn jit_iteration(
    ctx: *mut crate::jit::JitCtx,
    pc: u32,
    mut sp: *mut PackedValue,
) -> crate::jit::SpFlag {
    let ctx = unsafe { &mut *ctx };
    jit_opstat(ctx, pc);
    let chunk = unsafe { &*ctx.chunk };
    let _inline_position = unsafe { ImplicitCallPosition::enter(ctx.interp, chunk, pc as usize) };
    let i = unsafe { &mut *ctx.interp };
    let push = |sp: &mut *mut PackedValue, value: Value| unsafe {
        sp.write(PackedValue::pack(value));
        *sp = sp.add(1);
    };
    let result = match chunk.ops[pc as usize] {
        Op::DestructureArr(count) => {
            sp = unsafe { sp.sub(1) };
            let source = unsafe { sp.read() }.into_value();
            match i.destructure_array_prefix(&source, count as usize, |value| push(&mut sp, value))
            {
                Some(result) => result,
                None => {
                    // The proof failed before any effect: the generic operation runs instead.
                    push(&mut sp, source);
                    return unsafe { jit_exec(ctx, pc, sp) };
                }
            }
        }
        Op::TryArrayBinding(iterator, next, count) => {
            let slots = unsafe { std::slice::from_raw_parts(ctx.slots, ctx.n_slots) };
            let source = unsafe { &*sp.sub(1) }.clone_value();
            open_array_binding(i, slots, source, iterator, next, count).map(|matched| {
                #[cfg(test)]
                if matched {
                    crate::array_binding::TEST_JIT_ARRAY_BINDING_OPENS
                        .with(|count| count.set(count.get() + 1));
                }
                push(&mut sp, Value::Bool(matched));
            })
        }
        Op::ArrayBindingStep(iterator, _, index) => {
            let slots = unsafe { std::slice::from_raw_parts(ctx.slots, ctx.n_slots) };
            let source = slots.read_value(iterator as usize);
            i.array_binding_step(&source, index as usize)
                .map(|value| push(&mut sp, value))
        }
        Op::IterStepL(iterator, next) => {
            let slots = unsafe { std::slice::from_raw_parts(ctx.slots, ctx.n_slots) };
            let iterator = slots.read_value(iterator as usize);
            let next = slots.read_value(next as usize);
            i.iterator_step(&iterator, &next).map(|step| {
                let more = step.is_some();
                push(&mut sp, step.unwrap_or(Value::Undefined));
                push(&mut sp, Value::Bool(more));
            })
        }
        _ => return unsafe { jit_exec(ctx, pc, sp) },
    };
    match result {
        Ok(()) => crate::jit::SpFlag { sp, flag: 0 },
        Err(error) => {
            unsafe { ctx.throw_at(pc, error) };
            crate::jit::SpFlag { sp, flag: 1 }
        }
    }
}

